const ROOT = dirname(fileURLToPath(import.meta.url));

/* Зоны первого мира и ВСЕ зоны всех миров. Прежний единственный `ZONES`
   отвечал на два разных вопроса сразу — в каком порядке зоны идут по забегу и
   у каждой ли зоны полная палитра, — и со вторым миром эти вопросы
   разъезжаются: порядок спрашивают у мира, контракт палитры — у каждой зоны,
   в каком бы мире она ни лежала. Поэтому имён два, и они названы по смыслу. */
const ZONES = zonesOf('hills');
const ZONES_ALL = Object.keys(THEME);


let failed = 0;
let passed = 0;
function check(name, cond, detail = '') {
  if (cond) { passed++; return; }
  failed++;
  console.error(`  ПРОВАЛ  ${name}${detail ? '\n          ' + detail : ''}`);
}
function group(name, fn) { console.log(name); return fn(); }

/* ───────────────── поддельный холст ─────────────────

   Порядок заливок и их геометрия — это и есть половина дефектов вида: кольцо
   поверх плиты, тень дальнего кольца поверх ближнего, обочина поверх стены.
   Проверять их можно только по НАСТОЯЩЕМУ вызову отрисовки, поэтому вместо
   Canvas подставляется вот это: оно не рисует, а записывает.

   Два среза одного и того же. `fills` — только цвета по порядку, им проверяют
   «что чем накрыто» и считают бюджет кадра. `shapes` — то же плюс рамка каждой
   фигуры, и этим отличают дальнее кольцо от ближнего: цвет у них один, разный
   только размер.

   Был он здесь в четырёх почти одинаковых копиях, и каждая умела чуть своё.
   Разные копии расходятся молча: проверка начинает мерить не то, что рисует
   соседняя, и спорят в итоге не код с кодом, а два теста между собой. */
function painter() {
  const fills = [];
  const shapes = [];
  const images = [];
  let style = null;
  let pts = [];
  const add = (x, y) => pts.push([x, y]);
  const done = () => {
    fills.push(style);
    const xs = pts.map((q) => q[0]);
    const ys = pts.map((q) => q[1]);
    shapes.push({
      style,
      minX: Math.min(...xs), maxX: Math.max(...xs),
      minY: Math.min(...ys), maxY: Math.max(...ys),
      w: Math.max(...xs) - Math.min(...xs),
      h: Math.max(...ys) - Math.min(...ys),
    });
  };
  const ctx = {
    get fillStyle() { return style; },
    set fillStyle(v) { style = v; },
    beginPath() { pts = []; },
    closePath() {},
    moveTo: add,
    lineTo: add,
    ellipse(x, y) { add(x, y); },
    quadraticCurveTo(x1, y1, x2, y2) { add(x1, y1); add(x2, y2); },
    drawImage(im) { images.push(im); },
    /* Пустышки преобразований. Нужны с тех пор, как вторая копия растра неба
       кладётся зеркально: без них отрисовка падает в node, то есть набор
       перестаёт видеть кадр целиком. Геометрию они не трогают — экранные
       координаты растра не меряет ни одна проверка, его кладёт drawImage. */
    save() {}, restore() {}, translate() {}, scale() {},
    fill() { done(); },
    fillRect(x, y, w, h) { pts = [[x, y], [x + w, y + h]]; done(); },
  };
  return { canvas: { width: 0, height: 0, getContext: () => ctx }, fills, shapes, images };
}

/** Один кадр поддельным холстом. Умолчания — пустая сцена без ничего. */
function paintFrame(patch = {}) {
  const p = painter();
  createView(p.canvas, patch.backdrops ? { backdrops: patch.backdrops } : {})
    .render({
      u: 0, v: 0, travel: 0, elapsed: 0, stars: [], obstacles: [], decor: [], ...patch,
    });
  return p;
}

/* Случайность с посевом. Генераторы уровня, звёзд и декораций принимают rng
   снаружи именно для этого: тест прогоняет тысячу РАЗНЫХ уровней, а не один и
   тот же, и при этом каждый прогон повторяем. */
function seeded(seed) {
  let s = seed;
  return () => { s = (s * 1103515245 + 12345) & 0x7fffffff; return s / 0x7fffffff; };
}

// ───────────────────── синтетический скелет ─────────────────────

/* Стоящий человек в нормализованных координатах кадра: x вправо, y вниз.
   Параметрами двигаем то, что нас интересует: смещение вбок, присед, подход
   к камере, поворот боком. */
function pose({
  x = 0.5, y = 0.45, scale = 0.2, crouch = 0, profile = 1, vis = 0.9, lean = 0,
  aspect = 1,
} = {}) {
  const lm = new Float32Array(33 * 4);
  const put = (i, px, py, v = vis) => {
    lm[i * 4] = px; lm[i * 4 + 1] = py; lm[i * 4 + 2] = 0; lm[i * 4 + 3] = v;
  };
  /* Горизонтальные размеры делятся на отношение сторон, потому что MediaPipe
     нормирует x по ШИРИНЕ кадра: одна и та же ширина плеч в широком кадре
     занимает меньшую его долю. Без этого деления синтетика физически неверна
     при любом кадре кроме 1:1 — отношение плеч к торсу росло с формой кадра
     (1.10 при 1:1, 1.96 при 16:9), а geometry() умножает x на aspect и
     получал бы не те плечи. Та же договорённость, что в группе «единицы
     кадра»: строим в физических длинах, делим x на ширину кадра.

     Умолчание 1 оставлено нарочно: при нём синтетика ровно та же, что была,
     и ни одна прежняя проверка не меняет смысла. */
  const halfShoulder = 0.11 * scale / 0.2 * profile / aspect;
  const halfHip = 0.08 * scale / 0.2 * profile / aspect;
  /* Присед: плечи и бёдра идут вниз.

     `lean` отдельно укорачивает ПРОЕКЦИЮ торса, не трогая ширину плеч. Это не
     украшение синтетики, а то, что настоящий присед делает с кадром: ребёнок
     наклоняется вперёд, торс разворачивается к камере и в кадре становится
     короче, а ширина плеч при повороте вокруг горизонтальной оси сохраняется.
     Пока этого параметра здесь не было, синтетика утверждала обратное («торс
     не укорачивается»), и ни одна проверка не могла увидеть, что присед
     выбивает ребёнка в паузу по нижней границе. В журнале 7 октября торс
     ронялся с 0.30 до 0.11 на каждом из одиннадцати приседов. */
  const shoulderY = y + crouch * scale;
  const hipY = shoulderY + scale * (1 - lean);
  put(11, x - halfShoulder, shoulderY);
  put(12, x + halfShoulder, shoulderY);
  put(23, x - halfHip, hipY);
  put(24, x + halfHip, hipY);
  // Колени и ступни: в приседе колено сгибается.
  const kneeY = hipY + scale * (crouch > 0.2 ? 0.35 : 0.7);
  const kneeX = crouch > 0.2 ? 0.06 * scale / 0.2 : 0;
  put(25, x - halfHip - kneeX, kneeY);
  put(26, x + halfHip + kneeX, kneeY);
  put(27, x - halfHip, hipY + scale * 1.4);
  put(28, x + halfHip, hipY + scale * 1.4);
  return lm;
}

/** Прогнать серию поз через трекер с шагом dt мс. */
function run(tracker, frames, { dt = 50, t0 = 0 } = {}) {
  const out = [];
  let t = t0;
  for (const f of frames) {
    out.push(tracker.push({ lm: f, t }));
    t += dt;
  }
  return out;
}

const steady = (opts, n) => Array.from({ length: n }, () => pose(opts));

/**
 * Подход к телефону и отход от него — ПОСТЕПЕННО, как у настоящего ребёнка.
 *
 * Мгновенная телепортация торса физически невозможна: по сырым отсчётам всех
 * журналов длина торса меняется не больше чем в 1.78 раза за 100 мс, и теперь
 * `presence` скачок больше `scaleJumpMax` не принимает — иначе мусорная поза
 * MediaPipe выдаёт ложное «ты слишком близко» (журнал 14 октября: торс 1.79
 * при 0.25 за секунду до и 0.26 через секунду после).
 *
 * Поэтому проверки «подошёл / отошёл» обязаны вести ребёнка через
 * промежуточные расстояния. Шаг 1.5 раза за отсчёт — вдвое грубее того, что
 * бывает у живого ребёнка, и втрое мягче порога: ни одна проверка здесь не
 * опирается на точный путь, только на то, чем он КОНЧИЛСЯ.
 */
const ramp = (from, to, opts = {}, step = 1.5) => {
  const frames = [];
  let s = from;
  while (to > s * step) { s *= step; frames.push(pose({ ...opts, scale: s })); }
  while (to < s / step) { s /= step; frames.push(pose({ ...opts, scale: s })); }
  return frames;
};

// ─────────────────────────── геометрия ───────────────────────────

group('единицы кадра', () => {
  /* Самая дорогая ошибка этапа, найденная на живом ребёнке.

     MediaPipe нормирует x по ширине кадра, а y по высоте. Длина торса
     считается через hypot, то есть смешивает их — и при кадре 16:9
     горизонтальные расстояния выходят вдвое меньше настоящих. Отношение
     ширины плеч к торсу получалось 0.48 при пороге 0.45: ребёнок, стоящий
     строго лицом, висел на волосок от «повернись к телевизору» и однажды там
     застрял насовсем.

     Проверяется физическая величина: у человека лицом к камере плечи
     составляют примерно 0.86 торса, и это не должно зависеть от формы кадра. */
  const реальный = (plechi, torso, w, h) => {
    const aspect = w / h;
    const Hm = 2.0, Wm = Hm * aspect;
    // Точки в нормированных координатах, как их отдаёт MediaPipe.
    const lm = new Float32Array(33 * 4);
    const put = (i, x, y) => { lm[i * 4] = x; lm[i * 4 + 1] = y; lm[i * 4 + 3] = 0.9; };
    put(11, 0.5 - plechi / 2 / Wm, 0.4);
    put(12, 0.5 + plechi / 2 / Wm, 0.4);
    put(23, 0.5 - plechi / 3 / Wm, 0.4 + torso / Hm);
    put(24, 0.5 + plechi / 3 / Wm, 0.4 + torso / Hm);
    return geometry(lm, aspect);
  };

  for (const [w, h, name] of [[640, 360, '16:9'], [640, 480, '4:3'], [360, 640, 'портрет']]) {
    const g = реальный(0.30, 0.35, w, h);
    check(`${name}: плечи к торсу около 0.86`, Math.abs(g.shoulderRatio - 0.30 / 0.35) < 0.02,
      `получилось ${g.shoulderRatio.toFixed(2)}`);
    check(`${name}: стоящий лицом не читается как повёрнутый`, g.shoulderRatio > S.profileRatio,
      `${g.shoulderRatio.toFixed(2)} против порога ${S.profileRatio}`);
  }

  // И смещение в длинах торса тоже не должно зависеть от формы кадра:
  // полшага вбок — это полшага вбок при любой камере.
  const смещение = (w, h) => {
    const aspect = w / h;
    const Hm = 2.0, Wm = Hm * aspect;
    const tr = makeTracker({}, { aspect });
    const кадр = (dx) => {
      const lm = new Float32Array(33 * 4);
      const put = (i, x, y) => { lm[i * 4] = x; lm[i * 4 + 1] = y; lm[i * 4 + 3] = 0.9; };
      const c = 0.5 + dx / Wm;
      put(11, c - 0.15 / Wm, 0.4); put(12, c + 0.15 / Wm, 0.4);
      put(23, c - 0.10 / Wm, 0.4 + 0.35 / Hm); put(24, c + 0.10 / Wm, 0.4 + 0.35 / Hm);
      put(25, c - 0.10 / Wm, 0.4 + 0.6 / Hm); put(26, c + 0.10 / Wm, 0.4 + 0.6 / Hm);
      put(27, c - 0.10 / Wm, 0.4 + 0.9 / Hm); put(28, c + 0.10 / Wm, 0.4 + 0.9 / Hm);
      return lm;
    };
    let t = 0, rec;
    for (let i = 0; i < 5; i++) rec = tr.push({ lm: кадр(0), t: t += 50 });
    for (let i = 0; i < 5; i++) rec = tr.push({ lm: кадр(0.175), t: t += 50 });
    return rec.uRaw;
  };
  const широкий = смещение(640, 360);
  const узкий = смещение(640, 480);
  check('смещение не зависит от формы кадра', Math.abs(широкий - узкий) < 0.05,
    `16:9 дало ${широкий.toFixed(2)}, 4:3 дало ${узкий.toFixed(2)}`);
  check('полторса вбок читается как полторса', Math.abs(Math.abs(широкий) - 0.5) < 0.05,
    `получилось ${Math.abs(широкий).toFixed(2)}`);
});

group('отношение сторон берётся у кадра', () => {
  /* Второй забег 8 октября: ребёнок не смог начать игру вовсе.

     Камера открылась через 91 мс после поворота экрана, и `getSettings()`
     отдал 360×640 — портрет, — тогда как кадры шли по-прежнему 640×360.
     Отношение сторон бралось один раз и именно оттуда, поэтому горизонталь
     сжалась в 3.2 раза: размах калибровки вышел 0.51/0.43 вместо 1.5/0.93, а
     ширина плеч к торсу — 0.27 вместо 0.86, то есть ниже порога `profileRatio`
     НАВСЕГДА. Игра встала на «повернись к телевизору», и ни одна поза её
     оттуда не выводила: тело тут не при чём, число было чужое.

     Что отчёт `getSettings()` врал, а не камера повернулась, видно по длине
     торса: она меряется по высоте кадра и от этой путаницы не зависит — S0
     вышла 0.38 против 0.35 в первом забеге. Будь кадр и правда портретным,
     вертикальное поле зрения стало бы почти вдвое шире, и торс упал бы к 0.2.

     Поэтому истина — КАДР. Он и есть то, по чему нормирует MediaPipe. */
  /* Порядок достоверности: кадр позы → <video> → getSettings(). Соврать может
     только последний, и именно поэтому он последний. */
  check('кадр позы сильнее всего',
    frameAspect({
      sample: { w: 640, h: 360 },
      video: { videoWidth: 360, videoHeight: 640 },
      settings: { width: 360, height: 640 },
    }) === 640 / 360);
  check('кадр сильнее getSettings',
    frameAspect({ video: { videoWidth: 640, videoHeight: 360 }, settings: { width: 360, height: 640 } })
    === 640 / 360);
  check('поза без размера (конвейер на главном потоке) отдаёт ход видео',
    frameAspect({ sample: { w: null, h: null }, video: { videoWidth: 640, videoHeight: 360 } })
    === 640 / 360);
  check('без кадра берётся getSettings',
    frameAspect({ settings: { width: 640, height: 480 } }) === 640 / 480);
  check('кадр без размеров кадром не считается',
    frameAspect({ video: { videoWidth: 0, videoHeight: 0 }, settings: { width: 640, height: 360 } })
    === 640 / 360);
  check('не известно ничего — 16:9', frameAspect({}) === 16 / 9);

  /* А вот и сам ущерб, числами журнала: кадр 16:9, судим его портретным. */
  const лицом = (judged) => {
    const tr = makeTracker({}, { aspect: judged });
    run(tr, steady({ aspect: 16 / 9 }, 5));
    return run(tr, steady({ aspect: 16 / 9 }, 3)).pop().why;
  };
  check('перевёрнутое отношение сторон читается как поворот боком',
    лицом(360 / 640) === 'profile', `получилось «${лицом(360 / 640)}»`);
  check('верное отношение сторон не мешает стоять лицом',
    лицом(640 / 360) === null, `получилось «${лицом(640 / 360)}»`);

  /* Починка обязана доезжать до УЖЕ ЖИВОГО трекера: отношение сторон
     выясняется не раньше первых кадров, а пересоздать трекер посреди забега
     значит потерять нейтраль и защёлкнутую дорожку. */
  const живой = makeTracker({}, { aspect: 360 / 640 });
  run(живой, steady({ aspect: 16 / 9 }, 5));
  check('пока отношение чужое — пауза',
    run(живой, steady({ aspect: 16 / 9 }, 3)).pop().why === 'profile');
  живой.setAspect(640 / 360);
  const спасён = run(живой, steady({ aspect: 16 / 9 }, 3)).pop();
  check('setAspect спасает живой трекер', спасён.why === null);

  /* И спасает ПО-НАСТОЯЩЕМУ, а не только по присутствию.

     Нейтраль хранится в `cxh`, то есть x, УЖЕ умноженный на отношение сторон.
     Поменять делитель и не тронуть её — значит вычитать единицы из других
     единиц: у стоящего в середине `u` уезжает к −2 при пороге дорожки 0.34,
     дорожка защёлкивается и разащёлкнуться не может (|u| никогда не падает
     ниже `uExit`), а дрейф нейтрали её не вылечит — он сам разрешён только при
     нулевой дорожке. Снаружи это панорама, прижатая к стене до конца забега.
     Поэтому `setAspect` пересчитывает всё горизонтальное: величины линейны по
     отношению сторон, и перевод точный. */
  /* Проверяется на расхождении 4:3 → 16:9, а не портретном: портретное так
     сжимает плечи, что presence возвращает 'profile' и `push` уходит ДО
     записи нейтрали — нейтрали в старых единицах просто не возникает, и
     дефект прячется. А 4:3 против 16:9 даёт плечи 0.65 при пороге 0.45, то
     есть поза проходит, нейтраль пишется, и вот тогда смена единиц бьёт. */
  const кадр169 = () => steady({ x: 0.5, scale: 0.3, aspect: 16 / 9 }, 6);
  const почти = makeTracker({}, { aspect: 4 / 3 });
  const доПравки = run(почти, кадр169()).pop();
  check('мягкое расхождение присутствию не мешает — и потому опасно',
    доПравки.why === null && доПравки.lane === 0, `${доПравки.why} / ${доПравки.lane}`);
  почти.setAspect(16 / 9);
  const послеПравки = run(почти, кадр169()).pop();
  check('нейтраль переведена в новые единицы, а не оставлена в старых',
    Math.abs(послеПравки.uRaw) < 0.1, `u вышло ${послеПравки.uRaw?.toFixed(2)}`);
  check('дорожка не защёлкнулась от смены единиц', послеПравки.lane === 0,
    `дорожка ${послеПравки.lane}`);

  /* Та же ловушка у калибровки, и там она тише: стадии идут дальше, а размах
     меряется от сдвинутой нейтрали — один бок насыщается сразу, другой не
     набирается никогда, и забег уходит с молча испорченным `panSpan`. */
  const зонаЦели = (born, fix) => {
    const cal = makeCalibration({ aspect: born });
    let t = 0, last = null;
    // Нейтраль набирается целиком (5000 мс), иначе менять единицы нечему.
    for (let i = 0; i < 120; i++) {
      if (i === 120 - 40 && fix) cal.setAspect(fix);
      last = cal.push(pose({ x: 0.5, scale: 0.3, aspect: 16 / 9 }), t += 50);
    }
    return { stage: last.stage?.id, x: last.target?.x, half: last.target?.half };
  };
  const правильная = зонаЦели(16 / 9, null);
  const переведённая = зонаЦели(4 / 3, 16 / 9);
  check('калибровка дошла до боковой стадии — иначе проверять нечего',
    правильная.stage === 'left' && typeof правильная.x === 'number', JSON.stringify(правильная));
  check('набранное калибровкой тоже переводится, а не смешивается',
    Math.abs(переведённая.x - правильная.x) < 0.01
    && Math.abs(переведённая.half - правильная.half) < 0.01,
    `${JSON.stringify(переведённая)} против ${JSON.stringify(правильная)}`);

  /* То же у калибровки: она начинается раньше, чем кадры успевают прийти.
     Сверяется с той, что родилась с верным числом: совпасть обязано всё —
     и набранная нейтраль, и зона-цель, которую рисует окошко камеры. */
  const прогон = (cal) => {
    let last = null, t = 0;
    for (let i = 0; i < 80; i++) last = cal.push(pose({ x: 0.5, scale: 0.3, aspect: 16 / 9 }), t += 50);
    return JSON.stringify({ stage: last.stage?.id, target: last.target });
  };
  const верная = makeCalibration({ aspect: 16 / 9 });
  const переучённая = makeCalibration({ aspect: 360 / 640 });
  переучённая.setAspect(16 / 9);
  check('калибровка тоже умеет переучиваться', прогон(верная) === прогон(переучённая),
    `${прогон(makeCalibration({ aspect: 16 / 9 }))} против ${прогон(makeCalibration({ aspect: 360 / 640 }))}`);
});

group('геометрия', () => {
  const g = geometry(pose({ x: 0.5, scale: 0.2 }));
  check('длина торса положительна', g.S > 0);
  check('длина торса равна масштабу', Math.abs(g.S - 0.2) < 1e-6, `получилось ${g.S}`);
  check('центр тела по X найден', Math.abs(g.cx - 0.5) < 1e-6);

  // Ширина плеч схлопывается в профиль — именно поэтому она детектор
  // поворота, а не единица масштаба.
  const front = geometry(pose({ profile: 1 }));
  const side = geometry(pose({ profile: 0.2 }));
  check('масштаб не зависит от поворота', Math.abs(front.S - side.S) < 1e-6);
  check('поворот виден по отношению плеч к торсу', side.shoulderRatio < front.shoulderRatio / 3);

  // Та же поза вдвое дальше: все производные величины обязаны совпасть.
  const near = geometry(pose({ scale: 0.3 }));
  const far = geometry(pose({ scale: 0.15 }));
  check('отношение плеч к торсу не зависит от расстояния',
    Math.abs(near.shoulderRatio - far.shoulderRatio) < 1e-6);
});

// ──────────────────────── знак и расстояние ────────────────────────

group('знак и расстояние', () => {
  // Самая важная проверка файла. Задняя камера смотрит на ребёнка, повёрнутого
  // к ней лицом: когда он шагает в свою левую сторону, в кадре он уезжает
  // вправо. Перепутанный знак делает игру неиграбельной, и ловится он только
  // так — на живом ребёнке это выглядит как «игра сошла с ума».
  const tr = makeTracker();
  run(tr, steady({ x: 0.5 }, 5));
  const left = run(tr, steady({ x: 0.62 }, 5)).pop();
  check('шаг ребёнка влево даёт отрицательный u', left.uRaw < 0,
    `uRaw = ${left.uRaw?.toFixed(3)}; в кадре он смещается вправо`);

  const tr2 = makeTracker();
  run(tr2, steady({ x: 0.5 }, 5));
  const right = run(tr2, steady({ x: 0.38 }, 5)).pop();
  check('шаг ребёнка вправо даёт положительный u', right.uRaw > 0);

  // Одно и то же смещение «в долях тела» с разных дистанций должно читаться
  // одинаково: ради этого всё и меряется в длинах торса.
  const far = makeTracker();
  run(far, steady({ x: 0.5, scale: 0.15 }, 5));
  const farStep = run(far, steady({ x: 0.5 + 0.09, scale: 0.15 }, 5)).pop();
  const near = makeTracker();
  run(near, steady({ x: 0.5, scale: 0.30 }, 5));
  const nearStep = run(near, steady({ x: 0.5 + 0.18, scale: 0.30 }, 5)).pop();
  check('одинаковый шаг в долях тела читается одинаково с разных дистанций',
    Math.abs(farStep.uRaw - nearStep.uRaw) < 0.02,
    `далеко ${farStep.uRaw.toFixed(3)}, близко ${nearStep.uRaw.toFixed(3)}`);
});

// ─────────────────────────── One-Euro ───────────────────────────

group('One-Euro', () => {
  const f = makeOneEuro(S.oneEuro);
  for (let i = 0; i < 20; i++) f.push(0, 0.05);
  const first = f.push(1, 0.05);
  check('скачок не проходит мгновенно', first < 0.9, `сразу дало ${first.toFixed(3)}`);
  let last = first;
  for (let i = 0; i < 20; i++) last = f.push(1, 0.05);
  check('за 20 отсчётов догоняет', last > 0.95, `догнало до ${last.toFixed(3)}`);

  // Фильтр обязан шагать настоящим dt. Если подставлять ожидаемые 50 мс,
  // адаптация врёт ровно тогда, когда конвейер запнулся, — то есть когда она
  // и нужна.
  const a = makeOneEuro(S.oneEuro);
  const b = makeOneEuro(S.oneEuro);
  a.push(0, 0.05); b.push(0, 0.05);
  const fast = a.push(1, 0.01);
  const slow = b.push(1, 0.20);
  check('результат зависит от реального dt', Math.abs(fast - slow) > 0.05,
    `при dt=10мс ${fast.toFixed(3)}, при dt=200мс ${slow.toFixed(3)}`);

  const z = makeOneEuro(S.oneEuro);
  check('нулевой dt не ломает фильтр', Number.isFinite(z.push(0.5, 0)));
});

// ───────────────────────── дорожка ─────────────────────────

group('дорожка', () => {
  const tr = makeTracker();
  run(tr, steady({ x: 0.5 }, 10));
  check('в покое дорожка центральная', tr.lane === 0);

  run(tr, steady({ x: 0.5 - 0.16 }, 20)); // ребёнок ушёл вправо (в кадре влево)
  check('уверенное смещение переключает дорожку', tr.lane === 1, `lane = ${tr.lane}`);

  run(tr, steady({ x: 0.5 }, 20));
  check('возврат в центр возвращает дорожку', tr.lane === 0);

  // Дребезг ровно на пороге: стоять на границе и не метаться — требование не
  // косметическое, иначе персонаж трясётся между дорожками.
  const edge = makeTracker();
  run(edge, steady({ x: 0.5 }, 10));
  const onThreshold = 0.5 - S.uEnter * 0.2 * 1.0; // u ≈ uEnter
  let flips = 0;
  let prev = edge.lane;
  for (let i = 0; i < 60; i++) {
    const jitter = (i % 2 ? 1 : -1) * 0.0015;
    edge.push({ lm: pose({ x: onThreshold + jitter }), t: 1000 + i * 50 });
    if (edge.lane !== prev) { flips++; prev = edge.lane; }
  }
  check('на пороге дорожка не дребезжит', flips <= 1, `переключений: ${flips}`);
});

// ───────────────────────── присед ─────────────────────────

group('присед', () => {
  const tr = makeTracker();
  run(tr, steady({}, 10));
  check('стоя приседа нет', tr.crouch === false);

  run(tr, steady({ crouch: 0.5 }, 10));
  check('присед распознан', tr.crouch === true);

  // Минимальное удержание: короткий нырок не должен мигать.
  const held = run(tr, steady({ crouch: 0 }, 4)).pop();
  check('присед держится минимальное время', tr.crouch === true,
    `отпустило через ${held.t - 0} мс`);
  run(tr, steady({ crouch: 0 }, 20));
  check('потом отпускает', tr.crouch === false);

  // Главная ложная тревога: ребёнок подошёл к камере. Он стал крупнее, плечи
  // в кадре опустились — но это не присед.
  const near = makeTracker();
  run(near, steady({ scale: 0.20 }, 10));
  const approach = run(near, steady({ scale: 0.32, y: 0.50 }, 12)).pop();
  check('приближение к камере не читается как присед', near.crouch === false,
    `голоса: ${JSON.stringify(approach.votes)}, защита: ${approach.scaleGuardOk}`);

  // Колени голосуют только когда их видно: молчание не считается за «да».
  const noKnees = pose({ crouch: 0.5 });
  noKnees[25 * 4 + 3] = 0.1;
  noKnees[26 * 4 + 3] = 0.1;
  const g = geometry(noKnees);
  check('невидимые колени не голосуют', g.kneeVis < 0.5);
});

// ───────────────────────── дрейф ─────────────────────────

group('переиспользованная калибровка не врёт о росте', () => {
  /* Третий забег 8 октября шёл по калибровке первого, и жалоба была дословно:
     «меня воспринимали на 10–20 см выше, чем я был». В журнале это то же
     число: `v` держалось −0.2…−0.47 длины торса, а торс взрослого около 50 см,
     то есть 10–23 см. И приседать стало тяжелее ровно настолько же — порог
     `vEnter` 0.45 отсчитывается от нейтрали, а она съехала на 0.3, значит
     плечи надо было опустить на 0.75 торса, на две трети глубже, чем просили.

     Нейтраль по вертикали — это АБСОЛЮТНАЯ высота плеч в кадре, то есть не
     про тело, а про то, где человек стоял и как держался. На калибровке торс
     вышел 0.51, в забеге 0.32–0.40: возятся у телефона, пригнувшись к нему, а
     бежать отходят и выпрямляются. `isStale` такую разницу пропускает
     намеренно (допуск 45% для этого и поднят), но пропускать её можно только
     ПОРОГАМ.

     Высота плеч задаётся здесь параметром `y`, а не выводится из `scale`:
     синтетика масштабирует тело на месте и выразить «плечи оказались ниже в
     кадре» иначе не умеет. Разница 0.11 высоты кадра при торсе 0.34 — это
     треть торса, ровно середина замеренной полосы. */
  const вЗабеге = { scale: 0.34, y: 0.45, aspect: 16 / 9 };
  const наКалибровке = { scale: 0.51, y: 0.56, aspect: 16 / 9 };

  const g0 = geometry(pose(наКалибровке), 16 / 9);
  const близкая = {
    neutralX: g0.cxh, neutralShoulderY: g0.shoulderY, neutralHipY: g0.hipY, S0: g0.S,
    uEnter: 0.32, vEnter: 0.45,
    excursion: { left: 1.26, right: 0.92, crouch: 1.81 },
  };

  check('такую калибровку isStale ещё пропускает',
    !isStale(близкая, geometry(pose(вЗабеге), 16 / 9)),
    'иначе дефекта бы не было, но и переиспользования тоже');

  const стоя = (cal) => {
    const tr = makeTracker(cal, { aspect: 16 / 9 });
    let rec = null, t = 0;
    for (let i = 0; i < 8; i++) rec = tr.push({ lm: pose(вЗабеге), t: t += 50 });
    return rec;
  };

  const какБыло = стоя(близкая);
  check('прямо так нейтраль по вертикали врёт', Math.abs(какБыло.vRaw) > 0.2,
    `v вышло ${какБыло.vRaw?.toFixed(2)} — это и есть «воспринимали выше»`);
  check('и врёт в ту же сторону, что в журнале (плечи «выше» нейтрали)',
    какБыло.vRaw < 0, `v вышло ${какБыло.vRaw?.toFixed(2)}`);

  const какНадо = стоя(forReuse(близкая));
  check('а с пересеянной нейтралью стоящий ровно читается как стоящий',
    Math.abs(какНадо.vRaw) < 0.05, `v вышло ${какНадо.vRaw?.toFixed(2)}`);

  /* Пороги при этом обязаны остаться: они и есть то, ради чего калибровку
     переиспользуют, — двадцать секунд на каждый забег ребёнок ждать не
     станет. */
  const сохранены = forReuse(близкая);
  check('пороги переиспользуются', сохранены.uEnter === 0.32 && сохранены.vEnter === 0.45);
  check('и размах игрока тоже', сохранены.excursion.left === 1.26);
  check('и измеренная S0 — по ней судится «слишком близко»', сохранены.S0 === g0.S);
  check('а нейтраль обнулена вся, и горизонтальная тоже',
    сохранены.neutralShoulderY === null && сохранены.neutralHipY === null
    && сохранены.neutralX === null);

  /* Нейтраль с живой позы берётся с ОДНОГО кадра, и этот кадр может быть
     снят на середине шага: забег к этому моменту уже идёт, а первая
     достоверная поза приходит, когда взрослый разворачивается и идёт к
     телевизору. Один такой кадр уводит нейтраль на 0.1–0.2 длины торса, то
     есть ровно на столько, из-за чего `forReuse` и появился, — поэтому первую
     секунду её быстро уточняет дрейф. */
  const кривойЗасев = (мс) => {
    const tr = makeTracker(forReuse(близкая), { aspect: 16 / 9 });
    let t = 0, rec = null;
    // Первый кадр — на середине шага: плечи на 0.05 кадра ниже обычного.
    rec = tr.push({ lm: pose({ ...вЗабеге, y: вЗабеге.y + 0.05 }), t: t += 50 });
    while (t < мс) rec = tr.push({ lm: pose(вЗабеге), t: t += 50 });
    return rec;
  };
  check('сразу после кривого засева нейтраль ещё врёт',
    Math.abs(кривойЗасев(100).vRaw) > 0.1, `v ${кривойЗасев(100).vRaw?.toFixed(2)}`);
  check('а через секунду стояния на месте выправляется',
    Math.abs(кривойЗасев(1200).vRaw) < 0.03, `v ${кривойЗасев(1200).vRaw?.toFixed(2)}`);

  /* И быстрый дрейф обязан иметь те же ворота, что обычный: шаг вбок,
     сделанный сразу после старта, впитываться НЕ должен — иначе игра решит,
     что ребёнок там и стоял, и шаг перестанет быть шагом. */
  const шагСразу = () => {
    const tr = makeTracker(forReuse(близкая), { aspect: 16 / 9 });
    let t = 0, rec = null;
    rec = tr.push({ lm: pose(вЗабеге), t: t += 50 });
    const вбок = { ...вЗабеге, x: 0.5 + 0.8 * вЗабеге.scale / (16 / 9) };
    while (t < 1200) rec = tr.push({ lm: pose(вбок), t: t += 50 });
    return rec;
  };
  check('шаг вбок сразу после старта в нейтраль не впитывается',
    Math.abs(шагСразу().u) > 0.5, `u ${шагСразу().u?.toFixed(2)}`);

  /* Присед обязан срабатывать там, где просили, а не на две трети глубже.
     Приседаем ровно на порог с небольшим запасом — и со сложенным торсом, как
     в жизни. */
  const присед = (cal) => {
    const tr = makeTracker(cal, { aspect: 16 / 9 });
    let t = 0, rec = null;
    for (let i = 0; i < 8; i++) rec = tr.push({ lm: pose(вЗабеге), t: t += 50 });
    for (let i = 0; i < 10; i++) {
      rec = tr.push({ lm: pose({ ...вЗабеге, crouch: 0.6, lean: 0.3 }), t: t += 50 });
    }
    return rec;
  };
  const сПересевом = присед(forReuse(близкая));
  check('присед на пересеянной нейтрали распознаётся', сПересевом.crouch === true,
    `v вышло ${сПересевом.vRaw?.toFixed(2)} при пороге 0.45`);
  const соСтарой = присед(близкая);
  check('а на съехавшей тот же присед недобирает порога', соСтарой.crouch === false,
    `v вышло ${соСтарой.vRaw?.toFixed(2)} — вот во что обошлась съехавшая нейтраль`);
});

group('дрейф', () => {
  // Медленный уход по комнате должен впитаться: ребёнок не виноват, что
  // сместился за минуту, и игра не должна считать это вечным наклоном.
  //
  // Обещание конструкции здесь двойное, и проверяются обе половины: во время
  // ухода дорожка не должна сработать, а после остановки смещение должно
  // рассосаться само. Требовать, чтобы u оставалось крошечным прямо во время
  // ухода, нельзя — интегратор по определению отстаёт.
  const slow = makeTracker();
  run(slow, steady({ x: 0.5 }, 40)); // 2 секунды в центре — интегратор включился
  const sliding = [];
  for (let i = 0; i < 200; i++) sliding.push(pose({ x: 0.5 + 0.06 * (i / 200) })); // 10 с
  const during = run(slow, sliding, { t0: 2000 });
  check('во время медленного ухода дорожка не срабатывает',
    during.every((r) => r.lane === 0), 'иначе дрейф читается как намеренный шаг');
  check('дрейф действительно применялся', during.some((r) => r.driftApplied));

  // Ребёнок остановился на новом месте — за десять секунд это становится его
  // новой нейтралью.
  const after = run(slow, steady({ x: 0.56 }, 400), { t0: 12000 }).pop();
  check('после остановки смещение рассасывается', Math.abs(after.u) < S.uDeadband,
    `u = ${after.u.toFixed(3)}`);

  // А резкий шаг — нет.
  const step = makeTracker();
  run(step, steady({ x: 0.5 }, 40));
  const jumped = run(step, steady({ x: 0.5 - 0.16 }, 10)).pop();
  check('резкий шаг не впитан', Math.abs(jumped.u) > S.uEnter * 0.8,
    `u = ${jumped.u.toFixed(3)}`);
});

// ───────────────────── присутствие и пауза ─────────────────────

group('присутствие', () => {
  const why = (opts) => {
    const tr = makeTracker();
    run(tr, steady({}, 5));
    // Через промежуточные расстояния: мгновенный скачок торса presence больше
    // не принимает, и правильно — см. ramp().
    run(tr, ramp(0.2, opts.scale ?? 0.2, opts));
    return run(tr, steady(opts, 3)).pop().why;
  };
  check('низкая видимость опознана', why({ vis: 0.2 }) === 'lowvis');
  check('уход к краю кадра опознан', why({ x: 0.03 }) === 'edge');
  check('поворот боком опознан', why({ profile: 0.15 }) === 'profile');
  check('слишком близко к камере опознано', why({ scale: 0.95 }) === 'scale');
  check('слишком далеко опознано', why({ scale: 0.05 }) === 'scale');

  /* А рабочий диапазон отвергаться не должен. Числа из журнала с телефона:
     весь забег длина торса держалась 0.35–0.45, и прежний потолок 0.45
     проходил ровно по нему — игра встала посреди игры с «отойди назад». */
  for (const scale of [0.35, 0.40, 0.45, 0.50, 0.65]) {
    check(`длина торса ${scale} — рабочая, не повод для паузы`, why({ scale }) === null,
      `получилось «${why({ scale })}»`);
  }

  /* Верхняя граница — от своего роста, а не от абсолютной доли кадра.

     Абсолютный потолок 0.80 для взрослого 173 см работает: подошёл к
     телефону, торс дошёл до 1.07, пауза сработала. Для ребёнка 100–130 см
     торс в кадре короче почти вдвое, и 0.80 недостижим вовсе — ребёнок
     упирается в телефон, а игра молчит, потому что формально он в рабочем
     диапазоне. Числа S0 ниже — из журнала и из пересчёта на детский рост. */
  const whyFor = (cal, opts) => {
    const tr = makeTracker(cal);
    run(tr, steady({ scale: cal.S0 }, 5));
    run(tr, ramp(cal.S0, opts.scale ?? cal.S0, opts));
    return run(tr, steady(opts, 3)).pop().why;
  };
  check('ребёнок, подошедший к телефону, опознан',
    whyFor({ S0: 0.28 }, { scale: 0.60 }) === 'scale',
    'абсолютный потолок 0.80 этого не поймал бы');
  check('ребёнку его рабочая дистанция паузой не считается',
    whyFor({ S0: 0.28 }, { scale: 0.30 }) === null);
  check('взрослый, подошедший к телефону, опознан',
    whyFor({ S0: 0.53 }, { scale: 1.07 }) === 'scale');
  check('взрослому отход к старту паузой не считается',
    whyFor({ S0: 0.53 }, { scale: 0.40 }) === null,
    'торс на калибровке систематически больше, чем в забеге: 0.53 против 0.40');

  /* А догадка по первому кадру потолок задавать не вправе: на стадии
     установки штатива длина торса была 2.1, и привязка к ней выдала бы либо
     ничего, либо ложную паузу за шаг вперёд. */
  check('без пройденной калибровки потолок остаётся абсолютным',
    why({ scale: 0.65 }) === null && why({ scale: 0.95 }) === 'scale');

  /* Вырожденная калибровка не имеет права перевернуть границы. Стадия
     нейтрали сдаётся после трёх попыток и всё равно доходит до finish(),
     приняв сколько успела, — так в хранилище попадает крошечная S0. При
     S0 < scaleMin / scaleRelMax потолок оказался бы НИЖЕ пола, и presence
     возвращал бы 'scale' на любой позе: забег встал бы навсегда с «ты слишком
     близко», пока ребёнок на самом деле слишком далеко, и снять это можно
     было бы только сбросом калибровки во взрослом меню. */
  for (const S0 of [0.001, 0.02, 0.05]) {
    check(`вырожденная калибровка S0=${S0} не запирает забег`,
      whyFor({ S0 }, { scale: 0.40 }) === null,
      `получилось «${whyFor({ S0 }, { scale: 0.40 })}» — границы перевернулись`);
  }

  const none = makeTracker();
  run(none, steady({}, 5));
  const lost = none.push({ lm: null, t: 1000 });
  check('отсутствие позы опознано', lost.why === 'none' && lost.ok === false);

  // Граница ухода в паузу: 700 мс. Проверяем обе стороны, потому что ошибка
  // здесь означает либо паузу от каждого моргания распознавания, либо
  // ребёнка, который ушёл, а игра бежит дальше.
  const tr = makeTracker();
  run(tr, steady({}, 5));
  const before = tr.push({ lm: null, t: 1000 });
  const atEdge = tr.push({ lm: null, t: 1000 + S.lostMs - 1 });
  const past = tr.push({ lm: null, t: 1000 + S.lostMs + 1 });
  check('до порога ещё не потерян', atEdge.lostMs < S.lostMs, `${atEdge.lostMs}`);
  check('за порогом потерян', past.lostMs > S.lostMs, `${past.lostMs}`);
  check('отсчёт потери идёт от первого пропавшего кадра', before.lostMs === 0);

  // Подмена субъекта: в кадр вошёл второй ребёнок, и модель перескочила.
  const jump = makeTracker();
  run(jump, steady({ x: 0.5 }, 5));
  const swapped = jump.push({ lm: pose({ x: 0.5 + S.jumpMax + 0.05 }), t: 9999 });
  check('скачок центра опознан как подмена', swapped.why === 'jump');
});

/* ─────────── чужое тело у объектива, а не ребёнок подошёл ───────────

   14 октября забег встал на 0.74 секунде с «ты слишком близко к телефону».
   Ребёнок стоял на месте: торс 0.25 за секунду до паузы, 1.79 в самой паузе,
   0.26 через секунду после. Объяснил это заказчик: он в тот момент нажимал
   кнопку запуска, и камера приняла за детское тело ЕГО РУКУ у объектива.

   Числа сходятся с объяснением: торс 1.79 ВЫСОТЫ КАДРА при ширине плеч 0.76
   ширины кадра — это настоящее тело в двадцати сантиметрах от стекла, а не
   бессмыслица модели. Доля принятых отсчётов в той секунде 0.22–0.30: модель
   металась между двумя телами.

   Причина «кто-то ещё в кадре» в проекте была и подсказка к ней говорила ровно
   то, что нужно взрослому. Но стояла она ПОСЛЕДНЕЙ, после потолка расстояния,
   и потолок, честно сработав на чужом теле, забрал приговор себе. */
group('чужое тело опознаётся прежде расстояния', () => {
  // Числа ровно из журнала.
  const стоя = 0.25;
  const чужое = 1.79;

  const прогон = (кадры) => {
    const tr = makeTracker();
    run(tr, steady({ scale: стоя }, 5));
    return run(tr, кадры);
  };

  check('рука у объектива названа вторым телом, а не расстоянием',
    прогон([pose({ scale: чужое })]).pop().why === 'jump',
    `получилось «${прогон([pose({ scale: чужое })]).pop().why}» — ` +
    'прежде здесь стояло «scale», то есть ложное «отойди назад»');

  check('и чужой торс точкой отсчёта не становится',
    прогон([pose({ scale: чужое }), pose({ scale: 0.26 })]).pop().why === null,
    'иначе вернувшийся настоящий ребёнок сам оказался бы подменой');

  /* ГЛАВНОЕ: паузы в этом случае не случается вовсе. Отсчёты перемешаны — в той
     секунде журнала принята каждая третья поза, — а `lostMs` считает только
     НЕПРЕРЫВНЫЙ отказ. Настоящая поза обнуляет счёт, и 3.9 секунды забега,
     потерянные в журнале, не теряются. */
  const вперемешку = прогон(Array.from({ length: 30 }, (_, i) => pose({
    scale: i % 3 === 2 ? стоя : чужое,
  })));
  check('перемешанные тела паузы не дают',
    Math.max(...вперемешку.map((r) => r.lostMs ?? 0)) < S.lostMs,
    `худший непрерывный отказ ${Math.max(...вперемешку.map((r) => r.lostMs ?? 0))} мс ` +
    `при пороге ${S.lostMs}`);
  check('а чужие отсчёты при этом отвергаются все',
    вперемешку.filter((r) => r.why === 'jump').length === 20,
    'иначе часть чужого тела прошла бы как настоящее расстояние');

  /* А тот, кто ПРАВДА подошёл к телефону, своё «отойди» получает. Спорить с
     камерой дольше, чем пауза ждёт возвращения, мы не вправе: за `lostMs`
     точка отсчёта берётся заново, и дальше судит потолок, как судил всегда. */
  const плотно = прогон(Array.from({ length: 30 }, () => pose({ scale: чужое })));
  check('тело, оставшееся в кадре, после lostMs судится потолком',
    плотно.at(-1).why === 'scale',
    `получилось «${плотно.at(-1).why}»: иначе «ты слишком близко» перестало бы ` +
    'ловиться вовсе, а это единственная защита от короткой S0');
  check('и до этого срока оно остаётся чужим',
    плотно[0].why === 'jump' && плотно[2].why === 'jump');

  /* Скачок размера ловится ТОЛЬКО вверх: чужое тело попадает в кадр, когда к
     телефону подходят, то есть оказывается ближе ребёнка и крупнее его. */
  check('обвал торса вниз по-прежнему «слишком далеко», а не подмена',
    прогон([pose({ scale: 0.01 })]).pop().why === 'scale',
    'вырожденный скелет обязан опознаваться, и присед сюда не попадает');

  // И настоящий подход, через промежуточные расстояния, подменой не считается.
  check('постепенный подход к телефону подменой не считается',
    ramp(стоя, 0.6).length > 0
    && прогон(ramp(стоя, 0.6)).every((r) => r.why !== 'jump'),
    'иначе каждый шаг ребёнка к штативу читался бы вторым телом');

  /* Порог взят замером, а не на глаз, и запас обязан остаться с двух сторон:
     сверху его держит самое быстрое НАСТОЯЩЕЕ изменение торса (1.78 раза за
     100 мс по сырым отсчётам всех журналов), снизу — скачок на чужое тело 7.2. */
  check('порог лежит выше самого быстрого настоящего изменения торса',
    S.scaleJumpMax > 1.78,
    `${S.scaleJumpMax} против измеренного максимума 1.78`);
  check('и ниже скачка на чужое тело из журнала',
    S.scaleJumpMax < чужое / стоя,
    `${S.scaleJumpMax} против ${(чужое / стоя).toFixed(1)}`);

  /* И порядок приговоров проверяется НА ПРИГОВОРЕ, а не на чтении кода: когда
     чужое тело одновременно и слишком близко, и повёрнуто боком, ответ обязан
     быть про тело. Иначе подсказка снова пошлёт ребёнка отходить назад. */
  check('опознание тела сильнее и потолка, и поворота',
    прогон([pose({ scale: чужое, profile: 0.1 })]).pop().why === 'jump',
    'расстояние и поворот — свойства ТОГО тела, за которым следим');
});

group('короткая S0 не отнимает забег', () => {
  const whyFor = (cal, opts) => {
    const tr = makeTracker(cal);
    run(tr, steady({ scale: cal.S0 }, 5));
    run(tr, ramp(cal.S0, opts.scale ?? cal.S0, opts));
    return run(tr, steady(opts, 3)).pop().why;
  };

  // Ровно те длины торса, на которых журнал ставил паузу.
  for (const scale of [0.36, 0.37, 0.38, 0.40, 0.43]) {
    check(`при S0=0.20 торс ${scale} — не повод для паузы`,
      whyFor({ S0: 0.20 }, { scale }) === null,
      `получилось «${whyFor({ S0: 0.20 }, { scale })}»: порог встал ниже стоящего игрока`);
  }

  // Но потолок обязан остаться потолком: подход к телефону ловится и с короткой S0.
  check('и при короткой S0 подход к телефону всё равно опознан',
    whyFor({ S0: 0.20 }, { scale: 0.90 }) === 'scale');

  /* Пол выбран по замерам, а не на глаз, и обе его границы важны. Сверху —
     самый длинный торс, замеренный у СТОЯЩЕГО и играющего человека (0.43,
     журнал 9 октября). Снизу — самый короткий, замеренный у подошедшего к
     телефону (0.60 у ребёнка, журнал 6 октября). Пол между ними: выше первого
     — ложных пауз нет, ниже второго — настоящие ловятся. */
  check('пол потолка выше любого замеренного стоячего торса', S.scaleCeilMin > 0.43,
    `scaleCeilMin = ${S.scaleCeilMin}, а стоя замерено до 0.43`);
  check('и ниже любого замеренного подхода к телефону', S.scaleCeilMin < 0.60,
    `scaleCeilMin = ${S.scaleCeilMin}, а подход к телефону замерен с 0.60`);
  /* И ниже абсолютного потолка — иначе пол его перевешивал бы, то есть
     «защита от бессмыслицы» оказалась бы отменена защитой от короткой S0.
     Сейчас это верно с запасом, но держится только на том, что scaleMax ≥ 0.60;
     проверка нужна, чтобы правка scaleMax не отменила его молча. */
  check('пол не перевешивает абсолютный потолок', S.scaleCeilMin < S.scaleMax,
    `scaleCeilMin = ${S.scaleCeilMin}, scaleMax = ${S.scaleMax}`);

  // Прежние случаи не сдвинулись: пол лежит ниже детского потолка.
  check('детский потолок остался относительным',
    whyFor({ S0: 0.28 }, { scale: 0.60 }) === 'scale' &&
    whyFor({ S0: 0.28 }, { scale: 0.30 }) === null);
  check('взрослый потолок остался относительным',
    whyFor({ S0: 0.53 }, { scale: 1.07 }) === 'scale' &&
    whyFor({ S0: 0.53 }, { scale: 0.40 }) === null);
});

// ─────────────────── присед против границы потери ───────────────────

/* Группа появилась из журнала 7 октября — второго сеанса ребёнка.

   Нижняя граница присутствия абсолютная (SIGNALS.scaleMin 0.10) и мерила
   длину торса. У ребёнка торс стоя даёт S около 0.30, и КАЖДЫЙ из одиннадцати
   приседов ронял его до 0.11–0.24: присед — это наклон вперёд, проекция торса
   укорачивается. Дважды провал задержался ниже порога дольше lostMs (702 и
   766 мс при пороге 700), и игра встала с «ты слишком далеко» ровно в тот
   момент, когда ребёнок делал то, что от него требовали. Видимость при этом
   была 1 — ребёнок никуда не уходил.

   Цена видна в том же журнале: ложная пауза в 144.0 с кончилась возвратом в
   147.7 с, а в 148.3 с пришло препятствие на присед — crouch:false,
   единственное задетое препятствие за весь забег.

   У взрослого этого не видно по построению: стоя торс 0.40, в приседе около
   0.20 — вдвое выше порога. Ровно та же ловушка «абсолютный порог против
   ребёнка», что уже закрыта для ВЕРХНЕЙ границы.

   Абсолютный порог здесь переподобрать нельзя: у ребёнка «присел» (0.11) и
   «ушёл в другой конец комнаты» по длине торса перекрываются. Поэтому нижняя
   граница меряется тем, что наклон не укорачивает, — шириной плеч. */
group('присед не выбивает в паузу', () => {
  // Числа ровно из журнала: стоя 0.30, в приседе 0.11.
  const childStand = 0.30;
  const leanTo = (s) => 1 - s / childStand;

  const whyAfter = (opts, { cal = {}, base = { scale: childStand } } = {}) => {
    const tr = makeTracker(cal);
    run(tr, steady(base, 5));
    return run(tr, [pose({ ...base, ...opts })]).pop().why;
  };

  check('торс в приседе действительно укорачивается в кадре',
    Math.abs(geometry(pose({ scale: childStand, lean: leanTo(0.11) })).S - 0.11) < 0.005,
    'иначе синтетика описывает не тот присед, который дал журнал');
  check('а ширина плеч в приседе не меняется',
    Math.abs(geometry(pose({ scale: childStand, lean: leanTo(0.11) })).shoulderWidth
      - geometry(pose({ scale: childStand })).shoulderWidth) < 1e-9,
    'на этом и держится вся группа: мерить надо тем, что присед не портит');

  /* Проверяем ПЕРВЫЙ же присевший кадр, а не серию. Ждать подтверждения
     нельзя: пока presence отвечает 'scale', push возвращает управление рано,
     жесты не считаются, и защёлкнуть присед, чтобы на него сослаться, уже
     нечем. Поэтому решение обязано приниматься по самой позе. */
  /* В журнале самый глубокий снимок — 0.11, но это медиана секундного окна:
     мгновенное значение уходило ниже 0.10, иначе пауза не набрала бы своих
     702 мс. Поэтому проверяется вся полоса, включая 0.11 — он проходит и до
     правки, и ровно этим показывает, насколько тонок был запас. */
  for (const s of [0.11, 0.09, 0.07, 0.05]) {
    check(`присед ребёнка до торса ${s} паузой не считается`,
      whyAfter({ crouch: 0.6, lean: leanTo(s) }) === null,
      `получилось «${whyAfter({ crouch: 0.6, lean: leanTo(s) })}»`);
  }
  check('глубокий присед — тем более не пауза',
    whyAfter({ crouch: 0.9, lean: leanTo(0.03) }) === null);

  /* ─── ПЛЕЧИ НИЖЕ БЁДЕР: присед, в котором ломаются ВСЕ меры сразу ───

     Заказчик 11 октября вечером: «во время приседания плечи опускались ниже
     уровня бедер и игра становилась на паузу… ещё он пытался ползти в бок во
     время препятствия сверху, на что распознавание посчитало, что он стоит
     боком».

     Журнал подтвердил дословно. Пять пауз `profile` за 180 секунд, и в каждой:
     падение плеч `v` 2.0–3.4 длины торса (это и есть «ниже бёдер»), торс в
     проекции 0.07–0.12 против 0.26 стоя, ширина плеч `shW` 0.00–0.04, то есть
     В НОЛЬ — плечи проецируются в одну точку, как и бывает, когда ложишься на
     бок. Отношение «плечи к торсу» вышло 0.02–0.23 при пороге 0.45.

     Суть не в пороге. В такой позе отношение не значит НИЧЕГО, как не значила
     длина торса для нижней границы, — и починка та же по форме: мера, которую
     присед портит, в приседе не применяется. Нижнюю границу это задевает
     заодно: она мерит ширину плеч, а у лежащего на боку ширины нет. */
  const лёжа = { crouch: 2.5, lean: leanTo(0.09), profile: 0.05 };
  const гЛёжа = geometry(pose({ scale: childStand, ...лёжа }));
  /* Числа журнала: `shW` 0.00–0.04, торс 0.07–0.12 против 0.26 стоя,
     отношение 0.02–0.23. Синтетика обязана попасть в эти полосы, иначе
     проверка мерила бы другой случай. */
  check('поза из журнала воспроизведена: плечи почти в ноль, торс вчетверо короче',
    гЛёжа.shoulderWidth <= 0.04 && гЛёжа.S >= 0.07 && гЛёжа.S <= 0.12
    && гЛёжа.shoulderRatio <= 0.23,
    JSON.stringify({
      shW: +гЛёжа.shoulderWidth.toFixed(3),
      S: +гЛёжа.S.toFixed(3),
      ratio: +гЛёжа.shoulderRatio.toFixed(3),
    }));
  check('и отношение плеч к торсу в ней ниже порога поворота',
    гЛёжа.shoulderRatio < S.profileRatio,
    `${гЛёжа.shoulderRatio.toFixed(3)} против порога ${S.profileRatio}`);
  check('глубокий присед с плечами в ноль паузой НЕ считается',
    whyAfter(лёжа) === null,
    `получилось «${whyAfter(лёжа)}» — ребёнок делал ровно то, что просили`);
  check('и на трёх формах кадра тоже',
    [1, 4 / 3, 16 / 9].every((a) => whyAfter({ ...лёжа, aspect: a },
      { base: { scale: childStand, aspect: a } }) === null),
    'отношение плеч к торсу зависит от формы кадра — на 1:1 дефект спрятался бы');

  /* А то, ради чего проверка поворота стоит, обязано сохраниться: СТОЯ поворот
     корпусом по-прежнему пауза. Сняв её совсем, мы потеряли бы единственный
     сигнал «повернись к телевизору». */
  check('поворот корпусом СТОЯ по-прежнему пауза',
    whyAfter({ profile: 0.08 }) === 'profile',
    'суспензия обязана держаться на приседе, а не на ширине плеч');
  check('и неглубокий наклон поворота не прощает',
    whyAfter({ crouch: 0.2, profile: 0.08 }) === 'profile',
    'иначе достаточно чуть присесть, чтобы отключить проверку совсем');

  /* И то, ради чего нижняя граница стоит, обязано сохраниться. */
  check('ребёнок, ушедший от камеры, по-прежнему опознан',
    whyAfter({ scale: 0.05 }) === 'scale',
    'уход уменьшает и плечи тоже — в отличие от приседа');
  check('вырожденный скелет по-прежнему опознан',
    whyAfter({ scale: 0.01 }) === 'scale');
  check('присед в другом конце комнаты — всё ещё слишком далеко',
    whyAfter({ scale: 0.05, crouch: 0.6, lean: leanTo(0.11) }) === 'scale',
    'послабление даёт присед, а не любой короткий торс');

  /* Верхняя граница не ослабляется вовсе: её мерит торс, как и раньше. Иначе
     синтетическое отношение плеч к торсу (1.1) против измеренного на ребёнке
     (0.86) сдвинуло бы потолок на 28% и выдало ложное «ты слишком близко». */
  check('ребёнок, подошедший к телефону, по-прежнему опознан',
    whyAfter({ scale: 0.60 }, { cal: { S0: 0.28 }, base: { scale: 0.28 } }) === 'scale');
  check('взрослый, подошедший к телефону, по-прежнему опознан',
    whyAfter({ scale: 1.07 }, { cal: { S0: 0.53 }, base: { scale: 0.53 } }) === 'scale');

  /* А вот чего послабление делать не вправе: пускать сложившийся торс в ту
     арифметику, что меряется В ДОЛЯХ ТОРСА.

     Всё смещение здесь делится на длину торса, и при S = 0.05 вместо 0.30 оно
     раздувается шестикратно: остаток в 0.07 длины торса — пятая часть порога
     жеста — превращается в 0.4 и защёлкивает дорожку по пути «начало
     движения». Панорама уезжает к краю, и выглядит это фантомным шагом вбок на
     каждом приседе: та самая тряска, от которой ребёнка укачивало.

     Раньше этого не могло быть по случайности: нижняя граница отбрасывала
     такие кадры целиком. Снимая её, надо назвать по имени и то, что она
     держала заодно.

     ЗДЕСЬ СТОЯЛО «боковое положение НЕ обновляется, пока торс сложен или
     присед защёлкнут», и это отменено 18 октября: заморозка стоила скачка
     панорамы на 29 приседах из 43. Чинит раздувание теперь ДЕЛИТЕЛЬ — в
     приседе боковое делится на торс СТОЯ, — а шум снимает догоняющий фильтр
     `crouchLateralTauMs`. Разбор у `lateralHeld` в js/signals.js.

     Утверждения проверки от этого не ослабли, и это главное: раздуваться
     смещению больше нечем, поэтому `|u| < onsetU` держится теперь ПО СУЩЕСТВУ,
     а не потому, что значение заморожено. Остаток 0.07 торса читается как
     0.07 (был 0.21), остаток 0.15 — как 0.15 (был 0.45).

     Присед и боковой наклон одновременно физически невозможны — на этом же
     стоит правило запретного окна `starGuardS`, — поэтому дорожка в приседе
     по-прежнему не защёлкивается: её держит признак `lateralHeld`, а не
     величина смещения.

     Проверяется на ТРЁХ формах кадра, и это принципиально: смещение считается
     из величин в долях ширины, а порог — в долях торса. Прежняя версия этой
     проверки шла на кадре 1:1 и дефект прятала — на настоящем 16:9 дорожка
     защёлкивалась, а при остатке в 0.15 торса брался даже порог `uEnter`. */
  const приседВбоку = (aspect, offTorso) => {
    const tr = makeTracker({}, { aspect });
    const стоя = { scale: childStand, aspect };
    run(tr, steady(стоя, 10));
    /* Остаток задаётся в ДОЛЯХ ТОРСА, а не в долях кадра: доля кадра при
       разной форме значит разное расстояние, и сравнивать было бы нечего. */
    const dx = offTorso * childStand / aspect;
    return run(tr, Array.from({ length: 8 }, () => pose({
      ...стоя, x: 0.5 - dx, crouch: 0.6, lean: leanTo(0.05),
    })));
  };

  for (const [aspect, name] of [[1, '1:1'], [4 / 3, '4:3'], [16 / 9, '16:9']]) {
    for (const off of [0.07, 0.15]) {
      const r = приседВбоку(aspect, off);
      /* ЧЕСТНЫЙ ДЕЛИТЕЛЬ, и это сердце правки. Остаток задан в долях торса
         СТОЯ, значит в приседе он обязан читаться тем же числом, каким задан.
         До правки делитель брался с текущего кадра (торс 0.05 при зажиме
         0.10), и 0.07 читалось как 0.21 — втрое. Допуск 0.01 — на то, что
         синтетическая поза складывает торс не идеально. */
      check(`кадр ${name}, остаток ${off} торса: в приседе делитель — торс стоя`,
        Math.abs(r.at(-1).uRaw - off) < 0.01,
        `uRaw = ${r.at(-1).uRaw.toFixed(3)}, задано ${off}`);
      check(`кадр ${name}, остаток ${off} торса: дорожка не защёлкивается`,
        r.every((x) => x.lane === 0),
        'дорожки: ' + r.map((x) => x.lane).join(''));
      check(`кадр ${name}, остаток ${off} торса: смещение не раздувается`,
        r.every((x) => Math.abs(x.u) < S.onsetU),
        'u: ' + r.map((x) => x.u.toFixed(2)).join(','));
      check(`кадр ${name}, остаток ${off} торса: присед распознан`,
        r.at(-1).crouch === true,
        'заморозка бокового не должна выключить то, ради чего всё это делалось');
    }
  }

  /* Настоящее смещение, сделанное ДО приседа, заморозка отменять не вправе:
     ребёнок, ушедший в сторону и там присевший, остаётся ушедшим. */
  const ушёлПотомПрисел = (() => {
    const aspect = 16 / 9;
    const tr = makeTracker({}, { aspect });
    const стоя = { scale: childStand, aspect };
    run(tr, steady(стоя, 10));
    const dx = 0.8 * childStand / aspect;      // уверенный шаг вбок, стоя
    run(tr, steady({ ...стоя, x: 0.5 - dx }, 10));
    return run(tr, Array.from({ length: 6 }, () => pose({
      ...стоя, x: 0.5 - dx, crouch: 0.6, lean: leanTo(0.05),
    })));
  })();
  check('шаг вбок, сделанный до приседа, в приседе не теряется',
    Math.abs(ушёлПотомПрисел.at(-1).u) > S.uEnter
    && ушёлПотомПрисел.at(-1).lane !== 0,
    `u = ${ушёлПотомПрисел.at(-1).u.toFixed(2)}, дорожка ${ушёлПотомПрисел.at(-1).lane}`);

  /* НЕПРЕРЫВНОСТЬ НА ВЫХОДЕ ИЗ ПРИСЕДА — та дыра, из-за которой дефект и жил.
     Проверялось «заморозка не залипает» (признак вернулся в false) и «шаг до
     приседа не теряется», а вот сценария «присел в центре → сместился ЛЁЖА →
     встал» не проверял никто, то есть величина шага `u` на кадре вставания не
     была ограничена ничем. В журналах 18 октября она доходила до 2.4 ширины
     поля за секунду: 29 приседов из 43 кончались боковым жестом в первые
     0.3 с, максимум |u| = 2.51.

     Смещение здесь ползучее, а не мгновенное: ребёнок в приседе переставляет
     ноги, а не телепортируется. Вставание тоже постепенное — тем же пандусом,
     каким пользуется проверка «согнутая поза нейтралью не становится». */
  const сместилсяЛёжаИВстал = (() => {
    const aspect = 16 / 9;
    const стоя = { scale: childStand, aspect };
    const цель = 0.6 * childStand / aspect;    // 0.6 торса — больше onsetU, меньше uEnter
    const присед = (x, lean = 0.05) => pose({ ...стоя, x, crouch: 0.6, lean: leanTo(lean) });
    /* Весь сценарий ОДНИМ прогоном, и это не стиль: `run` начинает время с
       нуля при каждом вызове, а отпускание приседа судится по `crouchMinHoldMs`
       — то есть по прошедшему времени. Разбитый на четыре вызова, этот
       сценарий показывал присед, который не отпускается никогда. */
    const кадры = [
      ...steady(стоя, 12),
      ...Array.from({ length: 6 }, () => присед(0.5)),
      // Ползком в сторону: 16 кадров, 0.8 с.
      ...Array.from({ length: 16 }, (_, i) => присед(0.5 - цель * ((i + 1) / 16))),
      // Выпрямление: торс в кадре растёт постепенно, как у живого ребёнка.
      ...[[0.08, 0.45], [0.13, 0.30], [0.20, 0.12]].map(
        ([s, c]) => pose({ ...стоя, x: 0.5 - цель, crouch: c, lean: leanTo(s) })),
      ...steady({ ...стоя, x: 0.5 - цель }, 14),
    ];
    const r = run(makeTracker({}, { aspect }), кадры);
    return { ползком: r.slice(18, 34), встаёт: r.slice(34, 37), встал: r.slice(37) };
  })();
  {
    const все = [...сместилсяЛёжаИВстал.ползком, ...сместилсяЛёжаИВстал.встаёт,
      ...сместилсяЛёжаИВстал.встал].filter((r) => r.ok);
    let шаг = 0;
    for (let i = 1; i < все.length; i++) шаг = Math.max(шаг, Math.abs(все[i].u - все[i - 1].u));
    /* Потолок назван не на глаз: `onsetSpeed` 1.2 длины торса в секунду — это
       порог, по которому игра считает движение НАЧАТЫМ, а кадр здесь 50 мс.
       То есть требуется, чтобы ни один кадр возврата не выглядел началом
       быстрого шага. Настоящего движения в этом сценарии после вставания нет
       вовсе — ребёнок уже стоит там, где стоит. */
    check('сместился в приседе и встал — панорама не прыгает',
      шаг < S.onsetSpeed * 0.05,
      `худший шаг за кадр ${шаг.toFixed(3)} при потолке ${(S.onsetSpeed * 0.05).toFixed(3)}`);
    /* Сверяется с СОБСТВЕННЫМ сырым чтением, а не с заданными 0.6: синтетика
       складывает торс неидеально, и 0.6 на входе даёт чуть другое число на
       выходе. Утверждение здесь не «ровно 0.6», а «панорама догнала тело». */
    const п = сместилсяЛёжаИВстал.встал.at(-1);
    check('и в итоге панорама приезжает туда, где ребёнок',
      Math.abs(п.u - п.uRaw) < 0.02,
      `u = ${п.u.toFixed(3)}, сырое ${п.uRaw.toFixed(3)}`);
    /* Дорожка защёлкивается, и это правильно: ребёнок ПРАВДА ушёл в сторону.
       Правка отменяет скачок, а не само смещение. */
    check('смещение, сделанное в приседе, после вставания не потеряно',
      сместилсяЛёжаИВстал.встал.at(-1).lane !== 0,
      'дорожка 0 означала бы, что игра не заметила ухода вовсе');
    check('в самом приседе дорожка всё ещё не защёлкивается',
      сместилсяЛёжаИВстал.ползком.every((r) => r.lane === 0),
      'дорожки: ' + сместилсяЛёжаИВстал.ползком.map((r) => r.lane).join(''));
  }

  /* ГЛУБОКИЙ ПРИСЕД НЕ СЧИТАЕТСЯ «ТЕЛА НЕ ВИДНО», и проверка эта поставлена по
     живому случаю: первая версия правки писала `hardHold = g.S < lo` без
     приписки `!crouch`, и заморозка вернулась ровно в самые глубокие приседы —
     там торс в кадре складывается НИЖЕ границы присутствия (в синтетике 0.05
     при `scaleMin` 0.10). Набор это поймал тем, что `u` остался нулём при
     ненулевом `uRaw`. */
  {
    const r = приседВбоку(16 / 9, 0.15);
    check('в глубоком приседе боковое всё-таки идёт',
      Math.abs(r.at(-1).u) > 0.02,
      `u = ${r.at(-1).u.toFixed(3)} при uRaw ${r.at(-1).uRaw.toFixed(3)}`);
  }

  /* А ЖЁСТКАЯ ЗАМОРОЗКА ЖИВА, и она про другое: короткий торс БЕЗ приседа —
     это «тела не видно», и обновлять по такому кадру действительно нечем.
     Отличается от приседа тем, что голоса за присед не собраны. */
  {
    const aspect = 16 / 9;
    const стоя = { scale: childStand, aspect };
    // Торс схлопнулся, а приседа нет: ни наклона плеч, ни согнутых колен.
    const r = run(makeTracker({}, { aspect }), [
      ...steady(стоя, 13),
      ...Array.from({ length: 6 }, () => pose({ ...стоя, x: 0.2, lean: leanTo(0.05) })),
    ]);
    const было = r[12].u;
    const потеряли = r.slice(13);
    check('короткий торс без приседа боковое по-прежнему морозит',
      потеряли.every((x) => !x.ok || x.u === было),
      'u: ' + потеряли.map((x) => (x.ok ? x.u.toFixed(3) : x.why)).join(','));
  }

  /* Нейтраль со СЛОЖЕННОГО торса не берётся. Раньше такой кадр отбрасывала
     нижняя граница, и нейтралью он стать не мог; теперь он проходит — а
     взрослый, нагнувшийся к штативу, задал бы согнутую нейтраль, после чего
     `v` уже не дотянулся бы до порога и присед перестал бы распознаваться
     вовсе. Мерить от такой позы нечего, и кадр честно считается непригодным. */
  const согнутыйСразу = (() => {
    const tr = makeTracker();
    const кадры = run(tr, Array.from({ length: 6 }, () => pose({
      scale: childStand, crouch: 0.6, lean: leanTo(0.05),
    })));
    /* А теперь он выпрямился — и вот с этой позы нейтраль брать можно.
       Выпрямляется ПОСТЕПЕННО: торс в кадре растёт с 0.05 до 0.30, и
       мгновенный скачок presence больше не принимает (см. ramp()). Живой
       ребёнок и не выпрямляется мгновенно — по журналам торс меняется не
       больше чем в 1.78 раза за 100 мс. */
    for (const [s, c] of [[0.08, 0.45], [0.13, 0.30], [0.20, 0.12]]) {
      run(tr, [pose({ scale: childStand, crouch: c, lean: leanTo(s) })]);
    }
    const стоя = run(tr, steady({ scale: childStand }, 4));
    const присел = run(tr, Array.from({ length: 4 }, () => pose({
      scale: childStand, crouch: 0.6, lean: leanTo(0.05),
    })));
    return { кадры, стоя, присел };
  })();
  check('согнутая поза нейтралью не становится',
    согнутыйСразу.кадры.every((r) => r.ok === false && r.why === 'scale'),
    JSON.stringify(согнутыйСразу.кадры.map((r) => r.why)));
  check('выпрямился — нейтраль взята',
    согнутыйСразу.стоя.at(-1).ok === true);
  check('и присед после этого распознаётся',
    согнутыйСразу.присел.at(-1).crouch === true,
    'если бы нейтраль села согнутой, v не дотянулся бы до порога никогда');

  /* Присед на калибровке судится тем же правилом. Своей S0 на стадии приседа
     ещё нет, и послабление не имеет права её требовать: иначе стадия, на
     которой ребёнка просят присесть, отвергала бы каждый присевший кадр. */
  check('присед без пройденной калибровки тоже не пауза',
    whyAfter({ crouch: 0.6, lean: leanTo(0.11) }, { cal: {} }) === null);
});

// ───────────────────── предсказание панорамы ─────────────────────

group('панорама', () => {
  /* Эта группа появилась после жалобы ребёнка: при смещении вбок дрожали пол
     и стены, резало глаза, укачивало. Причина была в коде — панорама между
     отсчётами достраивалась экстраполяцией `u + скорость × возраст отсчёта`,
     а приход нового отсчёта сбрасывал возраст в ноль. Вид уезжал вперёд и
     дёргался назад двадцать раз в секунду.

     Поэтому проверяется не «похоже на правду», а само свойство, которого не
     хватало: монотонность. Пока тело едет в одну сторону, взгляд не имеет
     права ни разу повернуть обратно. */
  const follow = makeFollower(VIEW.followMs);
  const dtFrame = 1 / 60;
  const out = [];
  let target = 0;
  for (let frame = 0; frame < 180; frame++) {
    // Отсчёты приходят 20 Гц, кадры рисуются 60 — то есть один новый отсчёт
    // на каждые три кадра. Ровно тот случай, где и ломалось.
    if (frame % 3 === 0) target = frame / 180;
    out.push(follow.step(target, dtFrame));
  }
  let reversals = 0;
  for (let i = 2; i < out.length; i++) {
    if (out[i] - out[i - 1] < -1e-12) reversals++;
  }
  check('взгляд не дёргается назад при движении вперёд', reversals === 0,
    `разворотов: ${reversals} — это и есть та самая тряска`);

  const f2 = makeFollower(VIEW.followMs);
  for (let i = 0; i < 300; i++) f2.step(1, dtFrame);
  check('за несколько периодов догоняет цель', Math.abs(f2.value - 1) < 0.01,
    `дошло до ${f2.value.toFixed(3)}`);

  const f3 = makeFollower(VIEW.followMs);
  f3.step(0, dtFrame);
  const oneFrame = f3.step(1, dtFrame);
  check('за один кадр не прыгает целиком', oneFrame < 0.3,
    `за кадр прошло ${oneFrame.toFixed(3)} — резкий скачок читается как рывок`);

  // Просадка частоты кадров не должна менять ощущение: доля пути считается
  // от настоящего dt.
  const slow = makeFollower(VIEW.followMs);
  slow.step(0, dtFrame);
  const bigStep = slow.step(1, 3 * dtFrame);
  check('при редких кадрах догоняет быстрее за кадр', bigStep > oneFrame);

  /* Та же проверка, но на настоящей цепочке: сценарий «ходьбы» → трекер →
     One-Euro → слежение → поворот взгляда. Браузером это мерить бесполезно —
     граница пола и так ходит на сотни пикселей, и рывок в ней не разглядеть.
     Здесь же видно сам сигнал.

     Тело качается синусоидой 0.3 Гц: за четыре секунды это чуть больше
     одного периода, то есть законных разворотов два-три. Всё сверх этого —
     дрожание. */
  {
    const tr = makeTracker();
    const f = makeFollower(VIEW.followMs);
    const yaws = [];
    let tMs = 0;
    let target = 0;
    for (let frame = 0; frame < 240; frame++) {
      // Позы приходят 20 Гц, кадры рисуются 60.
      if (frame % 3 === 0) {
        const p = SCRIPTS.walk(tMs / 1000);
        const rec = tr.push({ lm: fakeLandmarks({ x: 0.5, ...p }), t: tMs });
        if (rec.ok) target = rec.u;
      }
      // Следим за краем стены в среднем поле: именно он теперь несёт движение.
      yaws.push(project(-VIEW.corridorWidth / 2, 0, 3, camera(f.step(target, 1 / 60), 0)).sx);
      tMs += 1000 / 60;
    }
    let turns = 0;
    let dir = 0;
    for (let i = 1; i < yaws.length; i++) {
      const d = yaws[i] - yaws[i - 1];
      if (Math.abs(d) < 1e-9) continue;
      const s2 = Math.sign(d);
      if (dir && s2 !== dir) turns++;
      dir = s2;
    }
    check('на плавной ходьбе взгляд не дрожит', turns <= 3,
      `разворотов направления: ${turns}; у синусоиды 0.3 Гц за 4 с их должно быть 2–3`);
    check('и при этом действительно двигается',
      Math.max(...yaws) - Math.min(...yaws) > 40,
      'иначе «не дрожит» означало бы просто «не шевелится»');
  }

  // Мёртвая зона: в покое дрожание распознавания не шевелит стены.
  check('дрожание в покое не двигает вид',
    camera(VIEW.viewDeadband * 0.9, 0).x === 0,
    'иначе у неподвижного ребёнка мелко трясутся стены');
  check('а заметное смещение двигает', camera(0.5, 0).x !== 0);
});

// ───────────────────────── геометрия вида ─────────────────────────

group('вид', () => {
  // Эти проверки появились после измерения: сначала панорама двигала картинку
  // на 14 пикселей из 1280 при полном смещении тела — на телевизоре это
  // незаметно, то есть единственной обратной связи в игре не было вовсе.
  const centre = camera(0, 0);
  const left = camera(-1, 0);
  const right = camera(1, 0);

  // Поворота взгляда нет — точка схода стоит на месте. Движение несёт
  // параллакс: стены и пол едут мимо. Мерить его надо там, куда ребёнок
  // смотрит, — в среднем поле, а не у горизонта, где боковой сдвиг камеры по
  // построению почти ничего не меняет. На этом я один раз уже ошибся и сделал
  // неверный вывод, что обратной связи нет.
  const wallAt = (z, cam) => project(-VIEW.corridorWidth / 2, 0, z, cam).sx;

  check('смещение влево двигает стену', wallAt(3, left) !== wallAt(3, centre));
  check('стороны противоположны',
    Math.sign(wallAt(3, left) - wallAt(3, centre)) === -Math.sign(wallAt(3, right) - wallAt(3, centre)));

  const swing = Math.abs(wallAt(3, left) - wallAt(3, right));
  check('движение заметно на телевизоре', swing > VIEW.width * 0.15,
    `${Math.round(swing)} пикселей из ${VIEW.width} на трёх метрах — меньше 15% не читается после сжатия`);

  check('точка схода неподвижна', vanishX(left) === vanishX(right),
    'поворот взгляда убран намеренно: от него укачивает сильнее, чем от поступательного движения');

  // Крена нет по построению: две точки на одной высоте и одной глубине дают
  // одинаковый y при любом состоянии тела. Наклон горизонта — главный
  // источник укачивания, и проверяется он тут, а не на ребёнке.
  for (const cam of [centre, left, right, camera(1, 0.6), camera(-1, 0.3)]) {
    const a = project(-1, 0, 5, cam);
    const b = project(1, 0, 5, cam);
    check('горизонт не наклоняется', Math.abs(a.sy - b.sy) < 1e-9);
  }

  const crouched = camera(0, 0.6);
  check('присед опускает глаза', crouched.y < centre.y);
  check('присед поднимает горизонт в кадре', horizonY(crouched) > horizonY(centre),
    `стоя ${horizonY(centre).toFixed(0)}, присед ${horizonY(crouched).toFixed(0)}`);

  // Сбор звёзд обязан считаться по тому же числу, по которому рисуется кадр.
  check('положение глаз одно на отрисовку и на сбор', cameraX(0.7) === camera(0.7, 0).x);

  // Дальше крайних значений вид не уезжает: иначе на дрожании распознавания
  // картинку швыряло бы за пределы коридора.
  // Зажим: дальше крайнего значения вид не уезжает, иначе дрожание
  // распознавания швыряло бы картинку за пределы коридора. Оба значения
  // заведомо за зажимом — мёртвая зона вычитается до него.
  check('панорама зажата по величине', camera(5, 0).x === camera(3, 0).x);
});

group('расстановка звёзд', () => {
  /* Проверка появилась после замера на ребёнке: две звезды подряд на разных
     сторонах оказались физически недостижимы — перейти из левого положения в
     правое за отведённое время он не успевал.

     Поэтому проверяется не «похоже на правду», а само физическое условие: на
     смену стороны всегда даётся больше времени, чем на звезду, за которой
     идти никуда не надо. Прогон на тысяче раскладок, а не на одной. */
  const rng = seeded(777);

  let худшийПереход = Infinity;
  let худшийОбычный = Infinity;
  let подрядОдна = 0;
  let всего = 0;

  for (let k = 0; k < 1000; k++) {
    const st = makeStars({ durationS: 120, rng });
    всего += st.length;
    let run = 0;
    for (let i = 1; i < st.length; i++) {
      const dt = st[i].at - st[i - 1].at;
      const переход = st[i].side && st[i - 1].side && st[i].side !== st[i - 1].side;
      if (переход) худшийПереход = Math.min(худшийПереход, dt);
      else худшийОбычный = Math.min(худшийОбычный, dt);
      if (st[i].side && st[i].side === st[i - 1].side) { run++; подрядОдна = Math.max(подрядОдна, run); }
      else run = 0;
    }
  }

  check('на смену стороны даётся не меньше заявленного',
    худшийПереход >= VIEW.starSwitchS - 1e-9,
    `минимум ${худшийПереход.toFixed(2)} с при заявленных ${VIEW.starSwitchS}`);
  check('переход дороже обычного промежутка', VIEW.starSwitchS > VIEW.starGapS,
    'иначе смена стороны ничего не стоит, а она стоит времени');
  check('обычный промежуток не меньше заявленного',
    худшийОбычный >= VIEW.starGapS - 1e-9, `${худшийОбычный.toFixed(2)} с`);
  check('подряд на одной стороне не больше двух', подрядОдна <= 1,
    `встретилось ${подрядОдна + 1} подряд; смысл игры в том, что ребёнок двигается`);
  check('звёзд не слишком густо', всего / 1000 / 120 < 0.55,
    `${(всего / 1000 / 120).toFixed(2)} звезды в секунду`);

  // Время прихода и расстояние обязаны совпадать: звезда на z приезжает к
  // игроку через z/скорость, и расходиться эти две величины не должны.
  const st = makeStars({ durationS: 60, rng });
  check('расстояние соответствует времени',
    st.every((s) => Math.abs(s.z - s.at * VIEW.speed) < 1e-9));
});

group('звёзды', () => {
  // Вся ценность игры в том, что ребёнок двигается. Если боковую звезду можно
  // собрать стоя столбом, игра превращается в заставку — и именно это и
  // обнаружилось при первом прогоне: допуск был шире, чем ход панорамы.
  const stars = makeStars();
  const side = stars.find((s) => s.x > 0).x;
  const middle = stars.find((s) => s.x === 0).x;

  check('боковую звезду стоя посередине не достать', !canReach(side, 0),
    `звезда на ${side.toFixed(2)} м, взгляд на ${cameraX(0).toFixed(2)} м`);
  check('сместившись — достать', canReach(side, 1),
    `взгляд уходит на ${cameraX(1).toFixed(2)} м`);
  check('в другую сторону — не достать', !canReach(side, -1));

  check('центральную звезду достать стоя посередине', canReach(middle, 0));
  check('а сместившись — уже нет', !canReach(middle, 1),
    'иначе можно висеть в одном положении и собирать всё подряд');
});

// ──────────────────── окошко камеры и поле ────────────────────

/* ───────────── фразы колец ─────────────

   Прежде сторона каждого кольца была отдельным броском: ряд получался без
   замысла, собирать приходилось то, что попалось. Теперь стороны набираются
   фразами — «двойка на одной стороне», «слалом», «через середину», — и ряд
   читается как сделанный.

   Чего фраза НЕ делает, и это главное, что здесь проверяется: она не меняет ни
   геометрию, ни плотность, ни число колец. Узор, который хотелось нарисовать
   сначала (дуга, цепочка через коридор), физически невозможен — смена стороны
   стоит 3.0 с измеренного времени перехода ребёнка, положений по x ровно три, а
   глубина жёстко связана со временем. Фраза живёт на той же решётке. */
group('фразы колец', () => {
  const ПОСЕВОВ = 100;
  const РАЗРЕШЁННЫЕ_X = [-1, 0, 1].map((s) => s * CORRIDOR_HALF * VIEW.starX);

  /* Прежнее правило сторон, воспроизведённое ровно как было — чтобы число
     колец сравнивалось с ЗАМЕРОМ, а не с числом из комментария.

     ЧИСЛА ЗДЕСЬ СВОИ, А НЕ ИЗ КОНФИГА, и это исправление самой проверки.
     Воспроизведение читало живые `VIEW.starGapS`, `starSwitchS` и живой
     `starAllowed` — то есть эталон ехал вместе с правкой, и проверка
     сравнивала новое правило с самим собой. Поймано 11 октября, когда шаг ряда
     пришлось менять ради сохранения потолка колец: подвинь его — и «прежнее
     правило» подвинулось бы следом, а разница осталась бы нулевой при любой
     поломке. Эталон обязан быть неподвижным: это шаг 2.0 с, переход 3.0 с и
     единственное окно 1.6 с на любую сторону — те числа, НА КОТОРЫХ снят
     замер 101 кольца за 300 секунд. */
  const П = { gap: 2.0, switch: 3.0, guard: 1.6 };
  const прежнееРазрешено = (t, side, obstacles) => obstacles.every((ob) => {
    if (Math.abs(t - ob.at) > П.guard) return true;
    return ob.kind !== 'duck' && side === -ob.side;
  });
  const прежние = (durationS, rng, obstacles) => {
    const sides = [];
    const n = Math.ceil(durationS / П.gap) + 2;
    let sameRun = 0;
    for (let i = 0; i < n; i++) {
      let side = rng() < 0.3 ? 0 : (rng() < 0.5 ? -1 : 1);
      if (side !== 0 && side === sides[i - 1] && sameRun >= 1) side = -side;
      sameRun = side !== 0 && side === sides[i - 1] ? sameRun + 1 : 0;
      sides.push(side);
    }
    // Расстановка по времени — та же, что в makeStars: нас интересует только
    // число колец, и считать его надо по тем же правилам промежутков.
    let t = VIEW.starFirstS;
    let count = 0;
    for (let i = 0; i < sides.length && t < durationS; i++) {
      if (!прежнееРазрешено(t, sides[i], obstacles)) {
        t = obstacles
          .filter((ob) => Math.abs(t - ob.at) <= П.guard)
          .reduce((max, ob) => Math.max(max, ob.at + П.guard + 0.05), t);
        if (t >= durationS) break;
      }
      count++;
      const next = sides[i + 1];
      const переход = next !== undefined && next !== 0 && sides[i] !== 0 && next !== sides[i];
      t += переход ? П.switch : П.gap;
    }
    return count;
  };

  const вПередышке = (t, ob) => {
    let prev = null;
    for (const o of ob) {
      if (o.at > t) return prev === null ? true : o.at - prev >= O.breatherS;
      prev = o.at;
    }
    return true;
  };

  let колец = 0;
  let прежнихКолец = 0;
  let свободных = 0;
  let чужихX = 0;
  let подрядХудший = 1;
  let сменВСерии = 0;
  let всегоВСерии = 0;
  let сменВПередышке = 0;
  let всегоВПередышке = 0;
  let тесныхПар = 0;

  for (let seed = 1; seed <= ПОСЕВОВ; seed++) {
    const ob = makeLevel({ durationS: 300, rng: seeded(seed * 7919) });
    const st = makeStars({ durationS: 300, obstacles: ob, rng: seeded(seed * 104729) });
    колец += st.length;
    прежнихКолец += прежние(300, seeded(seed * 104729), ob);
    свободных += makeStars({ durationS: 300, rng: seeded(seed * 104729) }).length;

    let подряд = 1;
    for (let i = 0; i < st.length; i++) {
      if (!РАЗРЕШЁННЫЕ_X.some((x) => Math.abs(st[i].x - x) < 1e-9)) чужихX++;
      if (i === 0) continue;
      const шаг = st[i].at - st[i - 1].at;
      const смена = st[i].side !== 0 && st[i - 1].side !== 0 && st[i].side !== st[i - 1].side;
      // Промежуток обязан быть не меньше заявленного: смена стороны дороже.
      if (шаг < (смена ? VIEW.starSwitchS : VIEW.starGapS) - 1e-9) тесныхПар++;
      if (st[i].side !== 0 && st[i].side === st[i - 1].side) подряд++; else подряд = 1;
      подрядХудший = Math.max(подрядХудший, подряд);
      if (вПередышке(st[i].at, ob)) {
        всегоВПередышке++;
        if (смена) сменВПередышке++;
      } else {
        всегоВСерии++;
        if (смена) сменВСерии++;
      }
    }
  }

  // ── решётка не тронута ──
  check('все кольца стоят в трёх разрешённых положениях', чужихX === 0,
    `${чужихX} колец встали мимо решётки — промежуточное x может оказаться достижимым стоя`);
  check('промежутки не короче заявленных', тесныхПар === 0,
    `${тесныхПар} пар теснее нормы: смена стороны стоит ${VIEW.starSwitchS} с измеренного времени`);
  check('подряд на одной стороне не больше двух', подрядХудший <= 2, `${подрядХудший} подряд`);

  // ── число колец не поехало ──
  const было = прежнихКолец / ПОСЕВОВ;
  const стало = колец / ПОСЕВОВ;
  check('число колец за забег осталось прежним', Math.abs(стало - было) / было < 0.05,
    `${стало.toFixed(1)} против ${было.toFixed(1)} у прежнего правила`);
  check('ряд колец не выродился', стало > (свободных / ПОСЕВОВ) * 0.7,
    `${стало.toFixed(1)} против ${(свободных / ПОСЕВОВ).toFixed(1)} без препятствий`);

  /* ── согласование с волнами ──

     Здесь и живёт ощущение ритма, и это единственное, что фразы добавляют
     поверх прежнего поведения: в серии препятствий ребёнок занят уклонением, и
     требовать от него слалом поверх серии значило бы два дела разом. */
  const вСерии = сменВСерии / всегоВСерии;
  const вПередышкеДоля = сменВПередышке / всегоВПередышке;
  check('в серии препятствий кольца требуют меньше переходов',
    вПередышкеДоля > вСерии * 1.2,
    `серия ${(вСерии * 100).toFixed(1)}%, передышка ${(вПередышкеДоля * 100).toFixed(1)}%`);
  check('но переходы не исчезают и в серии', вСерии > 0.1,
    `${(вСерии * 100).toFixed(1)}% — иначе ребёнок стоит на месте всю серию`);

  /* ─── большие кольца ───

     Редкие, дорогие и только боковые. Боковые — потому что большое обязано
     требовать полного размаха: центральное большое было бы наградой за
     неподвижность. */
  let большихВсего = 0;
  let большихЦентральных = 0;
  let безВеса = 0;
  let минРазносБольших = Infinity;
  for (let seed = 1; seed <= ПОСЕВОВ; seed++) {
    const st = makeStars({
      durationS: 300,
      obstacles: makeLevel({ durationS: 300, rng: seeded(seed * 7919) }),
      rng: seeded(seed * 104729),
    });
    for (const r of st) if (!(Number.isFinite(r.worth) && r.worth >= 1)) безВеса++;
    const большие = st.filter((r) => r.worth > 1);
    большихВсего += большие.length;
    большихЦентральных += большие.filter((r) => r.side === 0).length;
    for (let i = 1; i < большие.length; i++) {
      минРазносБольших = Math.min(минРазносБольших, большие[i].at - большие[i - 1].at);
    }
  }
  check('вес есть у каждого кольца', безВеса === 0,
    `${безВеса} колец без веса — undefined ушёл бы прямо в счёт очков`);
  check('большие кольца встречаются', большихВсего / ПОСЕВОВ > 1,
    `${(большихВсего / ПОСЕВОВ).toFixed(1)} за забег`);
  check('но остаются редкими', большихВсего / колец < 0.1,
    `${((большихВсего / колец) * 100).toFixed(1)}% колец — при большей доле «редкое» перестаёт быть редким`);
  check('большое кольцо никогда не центральное', большихЦентральных === 0,
    `${большихЦентральных} больших встали в середине — это награда за неподвижность`);
  /* Период обязан быть ПЕРИОДОМ. Сначала здесь стояла вероятность, выведенная
     из плотности ряда, и она врала втрое: заявленные 45 секунд давали сто. */
  check('период между большими соблюдён',
    минРазносБольших >= VIEW.bigStarEveryS * 0.75 - 1e-9,
    `минимум ${минРазносБольших.toFixed(1)} с при заявленных ${VIEW.bigStarEveryS} × 0.75`);

  /* И СРЕДНИЙ период обязан попадать в заявленную полосу разброса — на каждой
     ступени. Минимума для этого мало: он держит только нижний конец, а уехать
     период может вверх, и уезжал. Большое кольцо не бывает центральным, значит
     оно ждёт бокового, а на ступени 0 боковые живут только в передышках: при
     отсчёте срока от МЕСТА предыдущего ожидание копилось, и замеренный период
     вырастал с 45 до 55.5 с. Чинится это тем, что срок считается от СРОКА, а
     не от места; остаток (50.2 с на нулевой) — честная цена спокойного ряда, и
     он внутри полосы 33.75…56.25. */
  for (let step = 0; step <= STEP_MAX; step++) {
    const tune = tuneFor(step);
    const зазоры = [];
    for (let seed = 1; seed <= 40; seed++) {
      const ob = makeLevel({ durationS: 300, crouch: true, rng: seeded(seed * 7919), tune });
      const st = makeStars({ durationS: 300, obstacles: ob, rng: seeded(seed * 104729), tune });
      const б = st.filter((x) => x.worth > 1).map((x) => x.at);
      for (let i = 1; i < б.length; i++) зазоры.push(б[i] - б[i - 1]);
    }
    const ср = зазоры.reduce((a, b) => a + b, 0) / зазоры.length;
    check(`ступень ${step}: средний период большого кольца в полосе разброса`,
      ср >= VIEW.bigStarEveryS * 0.75 && ср <= VIEW.bigStarEveryS * 1.25,
      `${ср.toFixed(1)} с при заявленных ${VIEW.bigStarEveryS} (полоса ${(VIEW.bigStarEveryS * 0.75).toFixed(1)}…${(VIEW.bigStarEveryS * 1.25).toFixed(1)})`);
  }

  /* И главное: вес не трогает правило дотягивания. Большое кольцо нарисовано
     крупнее, но собрать его можно с того же размаха — иначе «крупнее» тихо
     означало бы «легче», а выглядело бы наоборот. */
  const боковое = CORRIDOR_HALF * VIEW.starX;
  check('вес не меняет правило дотягивания',
    canReach(боковое, 0) === false && canReach(боковое, 1) === true,
    'правило смотрит на x и u, и веса не знает вовсе');

  /* Раскладка БЕЗ аргументов обязана давать и боковое кольцо, и центральное:
     на этом стоят проверки достижимости, и они индексируют `find(...)` — то
     есть упали бы с TypeError, а не осмысленным провалом. */
  const голая = makeStars();
  check('без аргументов есть боковое кольцо', голая.some((s) => s.x > 0));
  check('и центральное', голая.some((s) => s.x === 0),
    'иначе проверки достижимости падают с TypeError вместо внятного провала');
});

group('игровое поле', () => {
  // Полоса показывает ребёнку край пространства, которое видит камера.
  // Зеркалит: камера смотрит спереди, и без зеркала шаг влево уезжал бы на
  // полосе вправо — подсказка, поставленная ради понимания, путала бы.
  const mid = fieldPosition(0.5);
  check('центр кадра — центр полосы', Math.abs(mid.x - 0.5) < 1e-9);
  check('в центре край не грозит', !mid.nearEdge && !mid.outside);

  const childLeft = fieldPosition(0.75);  // ребёнок шагнул влево → в кадре вправо
  check('шаг ребёнка влево двигает отметку влево', childLeft.x < 0.5,
    `отметка на ${childLeft.x.toFixed(2)}`);
  const childRight = fieldPosition(0.25);
  check('шаг вправо — вправо', childRight.x > 0.5);

  const edge = fieldPosition(0.04);
  check('у самого края — «вышел»', edge.outside);
  const near = fieldPosition(0.12);
  check('на подходе к краю — предупреждение', near.nearEdge && !near.outside,
    'предупредить надо до того, как игра встанет на паузу, а не вместе с ней');

  check('без позы поле считает, что ребёнка нет', fieldPosition(null).outside);
});

// ──────────────────── препятствия и телеграф ────────────────────

/* ─────────── пауза не вправе съедать телеграф ───────────

   Журнал 11 октября вечером, по секундам: телеграф на присед прозвучал на
   203.9; на 208.4 игра встала на паузу — ребёнок приседал, и поза потерялась
   целиком; отсчёт кончился на 213.0, препятствие пришло на 213.9. На
   исполнение осталось 0.94 с при измеренном времени ответа 3.5 с.

   И ребёнок всё сделал правильно: на 210.1 в журнале `crouchIn` с голосами —
   он присел по услышанному телеграфу, только во время отсчёта, и к возврату
   успел встать. Приговор «задето» он получил за то, чего игра ему не
   показала. */
group('пауза не съедает телеграф', () => {
  const ob = (at, passed = false) => ({ at, kind: 'duck', side: 0, passed });

  check('случай из журнала: долг равен недостающему телеграфу',
    Math.abs(telegraphDebt([ob(60.6)], 59.66) - (O.signalS - 0.94)) < 1e-9,
    `${telegraphDebt([ob(60.6)], 59.66).toFixed(2)} с при окне ${O.signalS}`);
  check('полный телеграф долга не создаёт',
    telegraphDebt([ob(60)], 55) === 0,
    'ровно signalS — значит ничего не съедено');
  check('и дальний телеграф тоже',
    telegraphDebt([ob(90)], 55) === 0);
  check('впереди нет препятствий — долга нет',
    telegraphDebt([], 55) === 0 && telegraphDebt([ob(10, true)], 55) === 0,
    'пройденные и пустой список не считаются');

  /* Уже пришедшее, но не закрытое препятствие (оно в окне прощения) долга не
     создаёт: его приговор вот-вот выставится, и отматывать к нему значило бы
     выставить его дважды. */
  check('пришедшее препятствие в счёт не идёт',
    telegraphDebt([ob(55)], 55) === 0 && telegraphDebt([ob(54.9)], 55) === 0);

  check('отмотать больше, чем прошло, нельзя',
    telegraphDebt([ob(1.5)], 1.0) === 1.0,
    'в начале забега возвращать нечего, кроме самого начала');

  /* И отмотка обязана быть ВИДНА в разборе: она меняет длину забега, то есть
     без неё «забег 180 с» перестанет сходиться с временем журнала, и объяснить
     это будет нечем. Та же причина, по которой исход починки офлайн-кэша
     пишется событием, а не только просьбой. */
  const сОтмоткой = report(сессия([
    { t: 1000, type: 'run.start', durationS: 180, obstacles: 26, stars: 60 },
    { t: 2000, type: 'pause', why: 'none', vis: 0, S: 0 },
    { t: 3000, type: 'rewind', s: 4.06, at: 60.6, kind: 'duck' },
    { t: 3100, type: 'resume' },
    { t: 5000, type: 'rewind', s: 1.2, at: 90.1, kind: 'side' },
    { t: 9000, type: 'run.finish', stars: 60, score: 60, starsTotal: 60, hits: 0, durationS: 180 },
  ]));
  check('отмотки собраны', сОтмоткой.rewind?.n === 2
    && Math.abs(сОтмоткой.rewind.s - 5.26) < 1e-9,
    JSON.stringify(сОтмоткой.rewind));
  check('и сводка их называет',
    /телеграф возвращён: 2 раза, 5\.3 с/.test(format(сОтмоткой)),
    format(сОтмоткой).split(String.fromCharCode(10)).filter((l) => /телеграф возвращён/.test(l)).join('') || '(строки нет)');
  const безОтмоток = report(сессия([
    { t: 1000, type: 'run.start', durationS: 180, obstacles: 26, stars: 60 },
    { t: 9000, type: 'run.finish', stars: 60, score: 60, starsTotal: 60, hits: 0, durationS: 180 },
  ]));
  check('у журнала без отмоток строки нет',
    !/телеграф возвращён/.test(format(безОтмоток)) && безОтмоток.rewind === null,
    'журналы до правки события не несут, и выдумывать ноль нельзя');

  /* И отмотка не может перешагнуть приход ПРЕДЫДУЩЕГО препятствия — иначе
     выставленный приговор выставится второй раз. Это держится инвариантом
     `minGapS > signalS`, который тут и проверяется на деле, а не на словах. */
  check('долг не перешагивает прошлое препятствие',
    O.minGapS > O.signalS
    && (() => {
      const список = [ob(50, true), ob(50 + O.minGapS)];
      const долг = telegraphDebt(список, 50 + O.minGapS - 0.1);
      return 50 + O.minGapS - 0.1 - долг > 50;
    })(),
    `minGapS ${O.minGapS} против signalS ${O.signalS}`);
});

group('уровень', () => {
  /* Проверяется не «похоже на правду», а инварианты, которые обязаны
     держаться на любом уровне. Непроходимый уровень на глаз не виден — он
     виден ребёнку, который не понимает, почему проиграл. Поэтому тысяча
     разных уровней, а не один. */
  const rng = seeded(12345);

  let minGap = Infinity;
  let sameSideRun = 0;
  let worstSameSide = 0;
  let total = 0;
  let ducks = 0;
  let firstTooEarly = 0;

  /* Прогон идёт по ВСЕМ ступеням сложности: доля приседов и длина серии —
     ручки ступени, и инвариант «приседания встречаются, но не преобладают»
     обязан держаться на каждой, а не только на нулевой. */
  for (let i = 0; i < 1000; i++) {
    const level = makeLevel({ durationS: 180, crouch: true, rng, tune: tuneFor(i % (STEP_MAX + 1)) });
    if (!level.length) continue;
    if (level[0].at < O.firstAtS) firstTooEarly++;

    let prevSide = 0;
    sameSideRun = 0;
    for (let k = 0; k < level.length; k++) {
      total++;
      if (level[k].kind === 'duck') ducks++;
      if (k > 0) minGap = Math.min(minGap, level[k].at - level[k - 1].at);
      if (level[k].kind === 'side') {
        sameSideRun = level[k].side === prevSide ? sameSideRun + 1 : 0;
        worstSameSide = Math.max(worstSameSide, sameSideRun);
        prevSide = level[k].side;
      }
    }
  }

  check('между препятствиями хватает места на телеграф', minGap >= O.minGapS - 1e-9,
    `самый тесный промежуток ${minGap.toFixed(2)} с при телеграфе ${O.signalS} с`);
  check('времени на решение хватает всегда', minGap >= O.minLeadS,
    'иначе ребёнок физически не успевает — и дело не в ловкости');
  check('разминка не прерывается', firstTooEarly === 0);
  check('подряд в одну сторону не больше двух', worstSameSide <= 2,
    `встретилось ${worstSameSide + 1} подряд; смысл игры в том, что ребёнок двигается`);
  check('приседания встречаются, но не преобладают',
    ducks / total > 0.1 && ducks / total < 0.5,
    `их доля ${(ducks / total * 100).toFixed(0)}%`);

  // Выключенные приседания должны убирать их совсем, а не «пореже».
  for (const step of [0, STEP_MAX]) {
    const flat = makeLevel({ durationS: 300, crouch: false, rng, tune: tuneFor(step) });
    check(`без приседаний верхних препятствий нет (ступень ${step})`,
      flat.every((o) => o.kind === 'side'),
      'настройка для взрослого обязана работать буквально — и на любой ступени');
  }
});

/* ───────────── волны ─────────────

   Прежде интервал между препятствиями был равномерным 5.5–8.0 с — за пять
   минут это метроном без единой группировки: «три плотных подряд, потом пауза»
   не случалось почти никогда. Волна даёт забегу форму, которую слышно без
   часов.

   Делается она СВЕРХУ, и это не выбор, а единственная возможность: сгустить
   препятствия нельзя (`minGapS > signalS`, иначе два телеграфа звучат разом;
   `minGapS > 2 * starGuardS`, иначе сдвиг колец перестаёт сходиться), а верхней
   границы на разнос нет вовсе.

   Главное, что здесь проверяется, — что СЛОЖНОСТЬ НЕ ПОЕХАЛА: средний разнос и
   число препятствий за забег остались прежними. Иначе следующий журнал нельзя
   будет сравнить с седьмым октября, а менять сложность по журналу с дефектами
   в этом проекте запрещено. */
group('волны', () => {
  const ВЕРХ_СЕРИИ = O.minGapS + O.seriesJitterS;   // 6.1
  const СЕРИЙ = 400;

  const разносы = (L) => L.slice(1).map((o, i) => o.at - L[i].at);

  let мин = Infinity;
  let макс = 0;
  let всеРазносы = 0;
  let суммаРазносов = 0;
  let препятствий = 0;
  let междуПолос = 0;
  let пустых = 0;
  let безСерии = 0;
  let худшаяСерия = 0;

  /* Прежнее правило воспроизведено здесь ровно как было — `minGapS + rng()*2.5`
     — чтобы сравнение шло с ЗАМЕРОМ, а не с числом из комментария: число в
     комментарии однажды разойдётся с кодом, и проверка начнёт сверять правку
     саму с собой. */
  const прежнее = (durationS, rng) => {
    const out = [];
    let t = O.firstAtS;
    while (t < durationS) { out.push(t); t += O.minGapS + rng() * 2.5; }
    return out;
  };
  let прежнихПрепятствий = 0;

  for (let seed = 1; seed <= СЕРИЙ; seed++) {
    const L = makeLevel({ durationS: 300, rng: seeded(seed) });
    прежнихПрепятствий += прежнее(300, seeded(seed)).length;
    if (!L.length) { пустых++; continue; }
    препятствий += L.length;

    const g = разносы(L);
    for (const d of g) {
      мин = Math.min(мин, d);
      макс = Math.max(макс, d);
      суммаРазносов += d;
      всеРазносы++;
      // Разнос обязан лежать в одной из двух полос, а не между ними.
      if (d > ВЕРХ_СЕРИИ + 1e-9 && d < O.breatherS - 1e-9) междуПолос++;
    }
    /* Серия обязана случаться — и обязана укладываться в потолок. Считается
       она по ПРЕПЯТСТВИЯМ, а не по разносам: три препятствия подряд дают два
       плотных разноса, и путать одно с другим значило бы сдвинуть потолок на
       единицу. */
    let подряд = 1;
    let лучшая = 1;
    for (const d of g) {
      подряд = d <= ВЕРХ_СЕРИИ + 1e-9 ? подряд + 1 : 1;
      лучшая = Math.max(лучшая, подряд);
    }
    if (лучшая < O.seriesMin) безСерии++;
    худшаяСерия = Math.max(худшаяСерия, лучшая);
  }

  check('пустых уровней нет', пустых === 0, `${пустых} из ${СЕРИЙ}`);
  check('пол разноса соблюдён', мин >= O.minGapS - 1e-9, `минимум ${мин.toFixed(2)}`);
  check('и он не ниже длины телеграфа', O.minGapS > O.signalS,
    'иначе два телеграфа звучат разом и теряются оба');

  /* Полосы не пересекаются — это и есть «волну слышно без часов». Если
     разносы размазаны между 6.1 и 8.8, группировки на слух нет, и вся правка
     сводится к другому генератору случайных чисел. */
  check('каждый разнос попал в свою полосу', междуПолос === 0,
    `${междуПолос} разносов повисли между полосами (серия ≤ ${ВЕРХ_СЕРИИ}, передышка ≥ ${O.breatherS})`);
  check('передышка заметно длиннее серии', O.breatherS / ВЕРХ_СЕРИИ >= 1.4,
    `${(O.breatherS / ВЕРХ_СЕРИИ).toFixed(2)}× — при меньшем отношении волна не читается`);
  check('серия случается на каждом уровне', безСерии === 0, `${безСерии} уровней без серии`);

  /* И НЕ ДЛИННЕЕ заявленной. Проверялось только то, что серия случается, — а
     хвост забега рос мимо потолка: когда до финиша не влезала передышка,
     генератор продлевал серию по одному и делал это до самого конца. Замерено
     на четырёхстах посевах: 56 серий по шесть и 12 по семь при потолке пять.
     Конфиг этот случай прямо отвергает («шесть подряд без паузы — вопрос о
     выносливости семилетки»), то есть код противоречил своему же решению, и
     увидеть это было нечем. */
  check('серия не длиннее заявленного потолка', худшаяСерия <= O.seriesMax,
    `${худшаяСерия} подряд при потолке ${O.seriesMax} — хвост забега растёт мимо потолка`);
  check('передышка не длиннее заявленной', макс <= O.breatherS + O.breatherJitterS + 1e-9,
    `максимум ${макс.toFixed(2)}`);

  /* ─── сложность не поехала ───

     Два числа, и оба нужны: среднее разнесение говорит про ритм, число
     препятствий — про то, сколько решений ребёнок принял за забег. Именно по
     второму следующий журнал будет сравниваться с седьмым октября. */
  const средний = суммаРазносов / всеРазносы;
  const было = прежнихПрепятствий / СЕРИЙ;
  const стало = препятствий / СЕРИЙ;
  check('средний разнос остался прежним', Math.abs(средний - 6.75) / 6.75 < 0.03,
    `${средний.toFixed(2)} против 6.75`);
  check('число препятствий за забег осталось прежним', Math.abs(стало - было) / было < 0.03,
    `${стало.toFixed(2)} против ${было.toFixed(2)} у прежнего правила`);

  /* Короткий забег. Передышка не имеет права съесть его конец: ровно поэтому в
     генераторе остаток сравнивается с её длиной. */
  for (const durationS of [180, 300, 480, 720]) {
    const L = makeLevel({ durationS, rng: seeded(durationS) });
    check(`забег ${durationS} с не пустой`, L.length > 0);
    check(`забег ${durationS} с начинается с разминки`, L[0].at >= O.firstAtS,
      `первое на ${L[0].at}`);
    check(`в забеге ${durationS} с нет препятствий после конца`,
      L.every((o) => o.at < durationS), `последнее на ${L[L.length - 1].at}`);
  }
  // Отладочный забег на двадцать секунд — тоже забег, и пустым он быть не должен.
  check('отладочный забег на 20 с не пустой',
    makeLevel({ durationS: 20, rng: seeded(5) }).length > 0,
    'иначе ?run=20 перестаёт показывать препятствия вовсе');

  check('расписание строго по возрастанию', (() => {
    const L = makeLevel({ durationS: 300, rng: seeded(99) });
    return L.every((o, i) => i === 0 || o.at > L[i - 1].at);
  })(), 'stepObstacles делает ранний break: неупорядоченный список молча перестанет показываться');
});

group('телеграф', () => {
  // Порядок отметок — это и есть механика. Ошибка в нём не видна на глаз, но
  // ломает игру: ребёнок узнаёт о препятствии позже, чем может среагировать.
  const order = [O.signalS, O.visibleS, O.railS, O.lastCallS];
  check('отметки идут по убыванию', order.every((x, i) => i === 0 || x < order[i - 1]),
    JSON.stringify(order));
  check('сигнал раньше, чем препятствие видно', O.signalS > O.visibleS,
    'звук опережает картинку намеренно: у динамика телефона задержки нет');
  check('времени на решение не меньше заявленного', O.minLeadS <= O.visibleS);

  // Окно далёкой метки удлинено до двух секунд (signalS 5.0 против visibleS
  // 3.0) после жалобы «плохо видно предупреждение»: при метке в одну секунду
  // мерцание 1 Гц успевает показать один цикл, то есть не читается вовсе.
  const far = telegraph(6);
  check('за шесть секунд ещё ничего не показано', !far.signal && !far.visible);
  const sig = telegraph(4.5);
  check('за 4.5 с идёт только сигнал', sig.signal && !sig.visible && !sig.rail);
  const sig2 = telegraph(3.5);
  check('за 3.5 с сигнал ещё идёт — окно метки двухсекундное',
    sig2.signal && !sig2.visible, 'иначе медленному мерцанию негде показаться');
  check('метка не накладывается на соседнее препятствие', O.minGapS > O.signalS,
    `minGapS ${O.minGapS} против signalS ${O.signalS}`);
  const vis = telegraph(2.5);
  check('за 2.5 с препятствие видно, рельса ещё нет', vis.visible && !vis.rail);
  const rail = telegraph(1.5);
  check('за 1.5 с идёт рельс', rail.rail && !rail.lastCall);
  const last = telegraph(0.5);
  check('за полсекунды — последний зов', last.lastCall && !last.arrived);
  check('ноль — это приход', telegraph(0).arrived);

  // Пока открыто окно прощения, ребёнок ещё может уйти — и обязан видеть,
  // куда. Поэтому вплотную препятствие перестаёт рисоваться: иначе оно
  // закрывает проём именно в эти миллисекунды.
  const forgiveS = O.lateForgiveMs / 1000;
  /* Считается от момента, когда плита исчезает ЦЕЛИКОМ, то есть от
     `drawNear − thickness`: прежняя проверка делила на скорость сам
     `drawNearM` и потому мерила не то, что называла. И гоняется она теперь
     по ВСЕМ скоростям уровней: в метрах это число при каждой своё, во
     времени обязано остаться не меньше окна прощения — иначе ребёнок
     получает приговор, глядя на закрытый проём. */
  check('препятствие исчезает не раньше окна прощения при скорости 2.0',
    (drawNear(2.0) - O.thickness) / 2.0 >= forgiveS - 1e-9,
    `исчезает за ${((drawNear(2.0) - O.thickness) / 2.0).toFixed(2)} с, окно ${forgiveS} с`);
  check('и не слишком рано', (drawNear(2.0) - O.thickness) / 2.0 < 1.0,
    'иначе препятствие пропадает, когда решение ещё не принято');
  check('при скорости 2.0 это ровно прежние 1.4 метра', drawNear(2.0) === 1.4,
    `${drawNear(2.0)} — перевод во время обязан был сохранить число`);
});

/* ───────────── перекраска не достаёт до игры ─────────────

   Препятствий два вида по ДЕЙСТВИЮ — шаг в сторону и присед, — и больше их не
   станет: у ребёнка ровно две оси управления. А вот внешностей теперь по две
   на каждое: `bat`/`ceiling` у приседа, `plate`/`gate` у бокового. Пять минут
   одного и того же силуэта приедаются, и это единственное, что перекраска
   лечит.

   Вся группа проверяет одно: что `look` не значит НИЧЕГО. Перекраска,
   дотянувшаяся до приговора, дала бы препятствие, которое выглядит как одно, а
   судится как другое, — дефект, невидимый на глаз и видимый только ребёнку,
   который не понял, почему проиграл. Поэтому проверяется не «нарисовалось
   красиво», а что приговор, метка телеграфа и звук от вида не зависят. */
group('перекраска не достаёт до игры', () => {
  const edge = obstacleEdge();

  // Приговор. Перебираются все внешности против всех положений тела.
  for (const kind of Object.keys(LOOKS)) {
    for (const side of kind === 'duck' ? [0] : [-1, 1]) {
      const verdicts = LOOKS[kind].map((look) => {
        const ob = { at: 10, kind, look, side };
        return [-1, -edge - 0.01, 0, edge + 0.01, 1]
          .flatMap((camX) => [true, false].map((crouching) => isSafe(ob, { camX, crouching })))
          .join(',');
      });
      check(`приговор у ${kind} одинаков при любой внешности`,
        new Set(verdicts).size === 1,
        LOOKS[kind].map((l, i) => `${l}: ${verdicts[i]}`).join(' | '));
    }
  }

  // Звук. Мотив сообщает, ЧТО делать, и перекраска не вправе его менять:
  // мотивы различаются числом нот, и новый мотив означал бы новое действие.
  for (const kind of Object.keys(LOOKS)) {
    const motifs = LOOKS[kind].map((look) => motifFor({ at: 10, kind, look, side: 1 }));
    check(`мотив у ${kind} одинаков при любой внешности`,
      new Set(motifs).size === 1, motifs.join(' / '));
  }

  // Расписание телеграфа — тоже по действию, а не по внешности.
  for (const kind of Object.keys(LOOKS)) {
    const plans = LOOKS[kind].map((look) => JSON.stringify(telegraph({ at: 10, kind, look, side: 1 }, 6)));
    check(`телеграф у ${kind} одинаков при любой внешности`, new Set(plans).size === 1);
  }

  /* Зубья висят ВНУТРИ щели, в которую ребёнок проходит приседая. Приговор от
     их длины не зависит (присед судится флагом), но ребёнок видит картинку, а
     не приговор: длинные зубья учили бы приседать глубже, чем просят. */
  check('зубья не съедают щель для приседа', O.teethM < O.duckHeight * 0.25,
    `зубья ${O.teethM} при щели ${O.duckHeight}`);

  // Генератор: внешности из таблицы, обе встречаются, полос нет.
  const level = makeLevel({ durationS: 300, rng: seeded(11) });
  check('внешность есть у каждого препятствия', level.every((o) => typeof o.look === 'string'));
  check('внешности только из таблицы',
    level.every((o) => LOOKS[o.kind].includes(o.look)),
    [...new Set(level.map((o) => `${o.kind}/${o.look}`))].join(', '));

  /* ПАРА У КАЖДОГО МИРА СВОЯ, и проверяется это по всем миру × действию.
     Стояло здесь «у kind за забег встречаются ОБЕ внешности», жёстко
     `seen.size === 2`, и пока таблица была плоской, этого хватало. С парами
     по мирам такая проверка молча мерила бы один мир умолчания: забег в
     «Подводной долине» мог бы идти створками с шипами, и набор этого не
     заметил бы. */
  for (const мир of Object.keys(WORLDS)) {
    const L = makeLevel({ durationS: 300, rng: seeded(11), world: мир });
    for (const kind of Object.keys(LOOKS)) {
      const пара = looksFor(мир, kind);
      check(`мир ${мир}: пара на ${kind} это общая плюс своя`,
        пара.length === 2 && пара[0] === looksFor('ice', kind)[0] && пара[1] !== пара[0],
        пара.join(', '));
      const seen = new Set(L.filter((o) => o.kind === kind).map((o) => o.look));
      check(`мир ${мир}: за забег у ${kind} встречаются обе внешности пары`,
        seen.size === 2 && [...seen].every((l) => пара.includes(l)),
        [...seen].join(', ') || '(ни одного препятствия этого вида)');
    }
  }
  /* И обратная сторона того же: КАЖДАЯ внешность перечня кому-то принадлежит.
     Иначе фигура, отрисованная и забытая в таблице миров, не выпадала бы
     никогда — и отличить это от замысла было бы нечем. */
  for (const kind of Object.keys(LOOKS)) {
    const розданы = new Set(Object.keys(WORLDS).flatMap((w) => looksFor(w, kind)));
    check(`у ${kind} каждая внешность перечня кому-то досталась`,
      LOOKS[kind].every((l) => розданы.has(l)),
      LOOKS[kind].filter((l) => !розданы.has(l)).join(', ') || 'все розданы');
  }

  /* Подряд не больше двух одинаковых. Чистая случайность даёт полосы по
     пять-шесть штук, и перекраска внутри такой полосы не видна вовсе — то
     есть не делает того единственного, ради чего сделана. */
  let worstRun = 1;
  let runLen = 1;
  for (let i = 1; i < level.length; i++) {
    const same = level[i].kind === level[i - 1].kind && level[i].look === level[i - 1].look;
    runLen = same ? runLen + 1 : 1;
    worstRun = Math.max(worstRun, runLen);
  }
  check('подряд не больше двух одинаковых препятствий', worstRun <= 2, `${worstRun} подряд`);

  check('один посев даёт тот же набор внешностей',
    JSON.stringify(makeLevel({ durationS: 300, rng: seeded(11) }).map((o) => o.look))
    === JSON.stringify(level.map((o) => o.look)));

  /* И наконец — что перекраска вообще РИСУЕТСЯ по-другому. Без этой проверки
     все предыдущие выполнялись бы и у поля, которое никто не читает. */
  const recorder = painter;   // общий поддельный холст, см. выше
  const paint = (ob) => {
    const { canvas, fills } = recorder();
    createView(canvas).render({
      u: 0, v: 0, travel: 0, elapsed: 10 - 1.5, obstacles: [ob], stars: [],
    });
    return fills;
  };
  const C = THEME.greenHill;
  const teeth = (look) => paint({ at: 10, kind: 'duck', look, side: 0 })
    .filter((f) => f === C.spike).length;
  check('у внешности ceiling зубья есть', teeth('ceiling') > 0);
  check('а у bat их нет', teeth('bat') === 0,
    'иначе внешности не отличаются, и перекраска существует только в поле');
  /* И обратную сторону того же: у зверя есть то, чего нет у зубьев. Без этой
     проверки `bat` мог бы оказаться голой плитой — то есть прежней `beam`,
     которую заказчик назвал скучной красной стеной, только под новым именем. */
  const duckPaint = (look) => paint({ at: 10, kind: 'duck', look, side: 0 });
  check('у bat есть тело', duckPaint('bat').includes(C.badnik));
  check('и глаза', duckPaint('bat').includes(THEME.greenHill.badnikEye));
  check('а у ceiling ни того, ни другого', !duckPaint('ceiling').includes(C.badnik),
    'иначе верхние внешности различаются только полем, которое никто не читает');
  /* Незнакомая внешность не рисуется НИЧЕМ — то же правило, что у декораций:
     ветка `else` однажды сделала бы любое новое имя тотемом с глазом. */
  check('незнакомая внешность приседа не рисует ни зверя, ни зубьев',
    teeth('beam') === 0 && !duckPaint('beam').includes(C.badnik),
    'имя beam снято с оборота — и не должно рисовать остатки прежней внешности');

  const sidePaint = (look) => paint({ at: 10, kind: 'side', look, side: 1 });
  check('у внешности gate бадника нет', !sidePaint('gate').includes(C.badnik),
    'живое существо рядом с механической створкой читается как два препятствия');
  check('а у plate он есть', sidePaint('plate').includes(C.badnik));
  /* И обратную сторону: шипы с 11 октября — признак СТВОРКИ, а не всякого
     бокового препятствия. У бадника заказчик велел их убрать («смотрят в центр
     бегового поля»), и тело выросло на освободившееся место. Проверять это
     надо здесь же, рядом с зубьями приседа: вызов `drawSpikes` стоит теперь
     внутри одной ветки, и обратная правка молча вернула бы гребень обеим
     внешностям — то есть снова отняла бы у бадника плиту. */
  const spikes = (look) => sidePaint(look).filter((f) => f === C.spike).length;
  check('у внешности gate шипы есть', spikes('gate') > 0);
  check('а у plate их нет', spikes('plate') === 0,
    'шипы смотрели в центр поля и съедали ту плиту, на которой живёт бадник');

  /* ВСЕ ВНЕШНОСТИ ОДНОГО ДЕЙСТВИЯ ОТЛИЧАЮТСЯ ДРУГ ОТ ДРУГА, попарно и по
     составу заливок. Шесть проверок «у медузы есть щупальца» ловили бы каждая
     свою фигуру, но не ловили бы главного: двух фигур, которые нарисованы
     по-разному в коде и одинаково на экране. А ребёнок видит экран.

     Подпись — это сколько заливок какого цвета. Цвета берутся из палитры зоны,
     то есть подпись заодно требует, чтобы фигура пользовалась цветами, которые
     в палитре есть: `undefined` Canvas проглатывает молча. */
  for (const [kind, side] of [['duck', 0], ['side', 1]]) {
    const подпись = (look) => {
      const счёт = {};
      for (const f of paint({ at: 10, kind, look, side })) счёт[f] = (счёт[f] || 0) + 1;
      return JSON.stringify(Object.entries(счёт).sort());
    };
    const пустая = подпись('beam');
    const подписи = new Map();
    for (const look of LOOKS[kind]) {
      const п = подпись(look);
      check(`внешность ${look} вообще что-то рисует`, п !== пустая,
        'иначе это прежняя beam под новым именем — «скучная красная стена»');
      const близнец = [...подписи.entries()].find(([, v]) => v === п);
      check(`внешность ${look} отличается от остальных на экране`,
        !близнец, близнец ? `совпадает с ${близнец[0]}` : '');
      подписи.set(look, п);
    }
  }
  /* И незнакомое имя на БОКОВОМ препятствии тоже не рисует ничего. Проверялось
     это только у приседа, потому что у бокового стоял `else`: плита со зверем
     была «всё остальное». С шестью внешностями такой `else` означал бы, что
     опечатка рисует зверя под водой и в космосе — молча. */
  check('незнакомая внешность бокового не рисует ни зверя, ни шипов',
    !sidePaint('beam').includes(C.badnik) && spikes('beam') === 0,
    'имя beam снято с оборота и не должно рисовать остатки прежней внешности');

  /* ЦЕНА ВНЕШНОСТИ В ЗАЛИВКАХ, и мерится она настоящей отрисовкой, а не
     таблицей. Таблица здесь уже была и уже разошлась с кодом — та самая
     третья копия одного числа, о которой предупреждает корень.

     Считается ВКЛАД: кадр с этой внешностью минус кадр с внешностью, которая
     не рисует ничего (`beam` снята с оборота ровно для этого). И считается по
     всему циклу анимации — фигура, у которой число заливок зависит от фазы,
     мигала бы в бюджете, и худший кадр ходил бы от посева к посеву. */
  const цена = (kind, look, side) => {
    const ряд = new Set();
    for (let t = 0; t < 3.1; t += 0.1) {
      const кадр = (l) => {
        const { canvas, fills } = recorder();
        createView(canvas).render({
          u: 0, v: 0, travel: 0, elapsed: t, obstacles: [{ at: t + 1.5, kind, look: l, side }], stars: [],
        });
        return fills.length;
      };
      ряд.add(кадр(look) - кадр('beam'));
    }
    return [...ряд];
  };
  for (const [kind, side] of [['duck', 0], ['side', 1]]) {
    const эталон = Math.max(...цена(kind, kind === 'duck' ? 'ceiling' : 'gate', side));
    for (const look of LOOKS[kind]) {
      const ряд = цена(kind, look, side);
      check(`внешность ${look} стоит одно и то же при любой фазе`,
        ряд.length === 1, `заливок по фазам: ${ряд.join(', ')}`);
      /* Эталон — САМАЯ ДОРОГАЯ из прежних двух внешностей этого действия
         (зубья у приседа, створка у бокового). Новая фигура дороже эталона
         означала бы, что мир покупается за бюджет кадра, а в этом проекте
         размен идёт только вниз. */
      check(`внешность ${look} не дороже прежней самой дорогой`,
        Math.max(...ряд) <= эталон,
        `${look}: ${Math.max(...ряд)} заливок при эталоне ${эталон}`);
    }
  }
});

/* ───────────── звёздная дорога читается ─────────────

   Жалоба заказчика 19 октября, после трёх забегов: боковое препятствие мира
   «Звёздная дорога» — «статичная тёмная бесформенная клякса с тремя пятнами»,
   а верхнее — «статичный камень с хвостом, всё направлено в левую сторону».

   Обе жалобы верны, и обе про ОДНО: про то, чего прежние фигуры не сообщали.
   Клякса не сообщала формы — тело и кратеры были двумя тёмными цветами рядом,
   и после сжатия Miracast разницы между ними не оставалось вовсе. Хвост
   кометы не сообщал действия: горизонтальная фигура с дышащей длиной читается
   как «летит вбок», то есть подсказывает ШАГ, а комета висит над щелью, в
   которую надо ПРИСЕСТЬ. Хуже этого в проекте только приговор за то, чего игра
   не показала: ребёнок видит подсказку одного действия и делает другое.

   Поэтому проверяется здесь не «похоже ли на ракету» — это проверяется
   ребёнком, — а ровно те два свойства, отсутствие которых заказчик и назвал:
   у верхнего препятствия КАЖДАЯ фигура вытянута вниз, а не вбок, и у бокового
   есть светлая точка, по которой тёмный силуэт опознаётся как предмет.

   Числа фигур тут нет намеренно: сколько клиньев у факела и сколько метеоров в
   дожде — дело отрисовки, и проверка числа запретила бы её менять. Цену в
   заливках мерит группа выше, настоящей отрисовкой. */
group('звёздная дорога читается', () => {
  const recorder = painter;
  /* ЗОНА — звёздной дороги, а не холмов умолчанием. Это не придирка к чистоте:
     жалоба пришла именно из этих палитр, и только в них `badnik` и `blockDeep`
     оказываются соседями по светлоте (0.046 / 0.030 / 0.027 против 0.024).
     Группа, рисующая космические фигуры зеленью холмов, проверяла бы цвета,
     которых у этих внешностей в игре не бывает. Поймано ревью. */
  const ZONE = 'nebula';
  const C = THEME[ZONE];
  /* Фаза и РАССТОЯНИЕ разведены: `at` едет вместе с `elapsed`, так что кадр за
     кадром меняется только фаза анимации, а препятствие остаётся на той же
     глубине. Иначе перебор фаз незаметно превращался бы в наезд камеры, и
     габариты в пикселях ходили бы от расстояния, а не от фигуры.

     Глубина 3.0 с выбрана потому, что при ней плита видна ЦЕЛИКОМ. Вблизи её
     верх уходит за кадр — у пустой плиты габарит выходил y −58…373, — и
     проверка «фигура внутри плиты» становилась пустой: сравнивать было не с
     чем. Поймано попыткой уронить проверку нарочно: удлинённый вдвое шлейф
     её не уронил. */
  const DT = 3.0;
  const кадр = (kind, look, side, elapsed = 1.5) => {
    const { canvas, fills, shapes } = recorder();
    createView(canvas).render({
      u: 0, v: 0, travel: 0, elapsed, zone: ZONE,
      obstacles: [{ at: elapsed + DT, kind, look, side }], stars: [],
    });
    return { fills, shapes };
  };

  /* ФИГУРЫ САМОЙ ВНЕШНОСТИ, а не всего кадра. Берутся вычитанием кадра с
     внешностью, которая не рисует ничего (`beam` снята с оборота ровно для
     этого): что осталось — и есть вклад фигуры. Тот же приём, которым группа
     выше меряет цену в заливках; фильтр по цветам здесь не годится — небо,
     обрывы и стены пользуются теми же тёмными цветами. */
  const одинаковы = (a, b) => a.style === b.style
    && a.minX === b.minX && a.maxX === b.maxX && a.minY === b.minY && a.maxY === b.maxY;
  const своё = (kind, look, side, elapsed) => {
    const a = кадр(kind, 'beam', side, elapsed).shapes;
    const b = кадр(kind, look, side, elapsed).shapes;
    let i = 0;
    while (i < a.length && i < b.length && одинаковы(a[i], b[i])) i++;
    let j = 0;
    while (j < a.length - i && j < b.length - i
           && одинаковы(a[a.length - 1 - j], b[b.length - 1 - j])) j++;
    return b.slice(i, b.length - j);
  };

  /* ВЕРТИКАЛЬНОСТЬ ДОЖДЯ — машинная формулировка жалобы «нарисовано
     двигающимся в бок». Мерится отношение сторон габарита, и это проверка
     ИМЕННО ДОЖДЯ, а не всей семьи приседа: у зубьев габарит каждого зуба
     шире, чем выше (51×23), потому что их тринадцать в ряд на всю ширину
     коридора. Здесь сначала стояло «каждая фигура верхнего препятствия», и
     звучало это как правило для всех внешностей приседа — неправда, которую
     поймало ревью. */
  const дождь = своё('duck', 'comet', 0);
  check('у метеорного дождя фигуры есть', дождь.length > 0);
  const вбок = дождь.filter((s) => s.w > s.h);
  check('каждая фигура метеорного дождя вытянута ВНИЗ, а не вбок',
    вбок.length === 0,
    `вбок смотрят ${вбок.length} из ${дождь.length}: `
    + вбок.map((s) => `${s.w.toFixed(0)}×${s.h.toFixed(0)}`).join(', '));

  /* И ПО ВСЕМУ ЦИКЛУ, а не в одной фазе: метеор растёт и сходит в точку, то
     есть его габарит меняется, и отношение сторон обязано пережить это
     целиком. Фаза берётся из `elapsed`, как в игре. */
  {
    const плохие = [];
    for (let e = 0.1; e < 3.2; e += 0.1) {
      for (const ф of своё('duck', 'comet', 0, e)) {
        if (ф.w > ф.h) плохие.push(`${e.toFixed(1)}с ${ф.w.toFixed(0)}×${ф.h.toFixed(0)}`);
      }
    }
    check('и в любой фазе цикла', плохие.length === 0, плохие.slice(0, 4).join(', '));
  }

  /* ДОЖДЬ НЕ ДОСТАЁТ ДО КРОМОК ПЛИТЫ НИ В ОДНОЙ ФАЗЕ. Прежде это было обещано
     комментарием в `js/view.js` — и обещание было ложным: зажим `Math.min`
     срабатывал, и один шлейф выходил короче прочих. Комментарий, которому
     нельзя верить, хуже отсутствующего, поэтому обещание переехало сюда.

     Верх плиты сторожится, потому что срезанная фигура теряет форму; низ —
     потому что за кромку приговора свисают только зубья, и дождь, полезший в
     щель, обещал бы проход там, где он есть. */
  {
    const пусто = кадр('duck', 'beam', 0).shapes.filter((f) => f.style === C.block);
    const плита = пусто.reduce((m, f) => (f.w * f.h > m.w * m.h ? f : m), пусто[0]);
    check('плита видна целиком, иначе проверка ниже пустая',
      плита.minY > 0, `верх плиты на ${плита.minY.toFixed(0)}`);
    const вышли = [];
    for (let e = 0.1; e < 3.2; e += 0.1) {
      for (const ф of своё('duck', 'comet', 0, e)) {
        if (ф.minY < плита.minY - 0.5 || ф.maxY > плита.maxY + 0.5) {
          вышли.push(`${e.toFixed(1)}с ${ф.minY.toFixed(0)}…${ф.maxY.toFixed(0)}`);
        }
      }
    }
    check('дождь не достаёт до кромок плиты ни в одной фазе',
      вышли.length === 0,
      `плита ${плита.minY.toFixed(0)}…${плита.maxY.toFixed(0)}, вышли: `
      + вышли.slice(0, 4).join(', '));
  }

  /* ДОЖДЬ НЕ ДЁРГАЕТСЯ МЕЖДУ СОСЕДНИМИ КАДРАМИ. Это главная проверка группы,
     и поставлена она по находке ревью.

     Падение задано пилой, у которой есть момент возврата. Пока метеор был
     постоянного размера, возврат приходился на середину плиты: ядро
     прыгало вверх на четверть её высоты, трижды в секунду при четырёх
     столбцах. Мерцание на лице препятствия — тот самый сигнал, которым в этой
     игре говорит ТЕЛЕГРАФ, и никакая проверка его не видела: все они мерят
     один кадр, а дефект живёт на стыке двух.

     Мерится ВИДИМЫЙ сдвиг: середина фигуры по площади, взвешенная тем,
     насколько фигура вообще видна (её площадь против наибольшей за цикл).
     Вес обязателен — метеор нарочно сходит в точку перед возвратом, и точка,
     перескочившая через всю плиту, на экране не видна. Наивная мера по
     габариту это не различает: она даёт 96 пикселей и у ПОЧИНЕННОЙ версии,
     то есть запрещает единственный известный способ сделать падение без
     разрыва. Замерено: 15.5 пикселя у нынешней отрисовки против 69.8 у той,
     что мерцала. */
  {
    const шаг = 1 / 30;
    const слой = (e) => {
      const m = new Map();
      for (const ф of своё('duck', 'comet', 0, e)) {
        const k = Math.round((ф.minX + ф.maxX) / 2 / 20);   // столбец
        const a = ф.w * ф.h;
        const v = m.get(k) || { a: 0, s: 0 };
        v.a += a; v.s += a * (ф.minY + ф.maxY) / 2;
        m.set(k, v);
      }
      for (const v of m.values()) v.cy = v.a ? v.s / v.a : 0;
      return m;
    };
    const слои = [];
    for (let e = 0.1; e < 3.2; e += шаг) слои.push(слой(e));
    const максА = new Map();
    for (const l of слои) for (const [k, v] of l) максА.set(k, Math.max(максА.get(k) || 0, v.a));
    let худший = 0;
    let когда = 0;
    for (let i = 0; i + 1 < слои.length; i++) {
      for (const [k, va] of слои[i]) {
        const vb = слои[i + 1].get(k);
        if (!vb) continue;
        const вес = Math.min(va.a, vb.a) / (максА.get(k) || 1);
        const d = вес * Math.abs(vb.cy - va.cy);
        if (d > худший) { худший = d; когда = 0.1 + i * шаг; }
      }
    }
    check('дождь не дёргается между соседними кадрами', худший < 30,
      `видимый сдвиг ${худший.toFixed(1)} px за кадр на ${когда.toFixed(2)} с — `
      + 'это мерцание, а мерцанием в этой игре говорит телеграф');
  }

  /* И никакого светлого: светлота в этой игре сообщает решение, а самое
     светлое место кадра — щель под плитой, куда присесть. Белое пятно на лице
     плиты заказчик 19 октября и назвал — «что за белый квадрат в метеоритном
     дожде». */
  check('у метеорного дождя светлых точек нет',
    !кадр('duck', 'comet', 0).fills.includes(C.badnikEye),
    'светлое на закрытой плите тянет взгляд туда, куда идти нельзя');

  /* ОПОЗНАВАЕМОСТЬ БОКОВОГО. Тёмный силуэт на красной плите — это только
     силуэт; предметом он становится от одной светлой точки, по тому же
     правилу, по которому у створки светлые ровно два болта, а у зверя глаз.
     Ровно этой точки кляксе и не хватало. */
  const ракета = кадр('side', 'asteroid', 1);
  const светлых = ракета.fills.filter((f) => f === C.badnikEye).length;
  check('у ракеты есть светлая точка', светлых > 0,
    'без неё тёмная фигура остаётся кляксой');
  check('и она одна', светлых === 1,
    `${светлых} светлых пятен — светлота сообщает решение, её нельзя тратить на декор`);

  /* Потолок светлого — ДОЛЯ ПЛОЩАДИ ПЛИТЫ, тем же числом 0.015, которым он
     уже стоит у глаз бадника и висящего зверя. Здесь сначала стоял мой
     собственный порог «не больше 16 пикселей по стороне», потом «не крупнее,
     чем у принятых внешностей» — оба негодны, и по одной причине: пиксели
     зависят от глубины, а доля нет, и «не крупнее принятых» вдобавок
     поднимает само себя, стоит кому-нибудь увеличить глаз зверя. Один
     цвет — один потолок, и он уже выбран. Поймано ревью. */
  {
    const пусто = кадр('side', 'beam', 1).shapes.filter((f) => f.style === C.block);
    const плита = пусто.reduce((m, f) => (f.w * f.h > m.w * m.h ? f : m), пусто[0]);
    const точки = ракета.shapes.filter((f) => f.style === C.badnikEye);
    const доля = точки.reduce((a, f) => a + f.w * f.h, 0) / (плита.w * плита.h);
    check('иллюминатор остаётся пятном, а не окном', доля < 0.015,
      `${(доля * 100).toFixed(2)}% площади плиты, а он ярче проёма`);
  }
});

/* ───────────── силуэт препятствия ─────────────

   Заказчик после забега 10 октября: «каждое препятствие залито красным, так и
   должно быть? бадник — мелкое существо, позади которого красная стена во всю
   высоту, и из-за неё самого препятствия почти не видно». Плюс: шипы
   недостаточно шипастые, а створка выглядит просто красной стеной.

   Жалоба верна, и ответ на неё — не «убрать красное». Красная область и есть
   приговор: по её краю судит `isSafe()`, её светлота против почти белого
   проёма — единственное, что переживает сжатие Miracast. Менять в ней нельзя
   ничего. А вот `look` — наклейка поверх приговора, он не значит ничего, и ему
   ничто не мешает вырасти до размера плиты.

   Поэтому здесь проверяется ровно эта развязка: приговор на месте (это
   соседняя группа), а внешность занимает плиту, а не висит на ней маркой.
   Доли нарочно грубые — вопрос «крупно или мелко», а не «красиво». */
group('силуэт препятствия', () => {
  const C = THEME.greenHill;
  const at = 10;
  const paint = (ob, dt = 1.5) => paintFrame({ elapsed: at - dt, obstacles: [ob] }).shapes;
  const plateOf = (shapes) => shapes.find((f) => f.style === C.block);
  const side = (look) => ({ at, kind: 'side', look, side: 1 });

  /* ─── НИ ОДНА ФИГУРА НЕ ВЫЕЗЖАЕТ ЗА ПЛИТУ, И НИ В ОДНОЙ ФАЗЕ ───

     Проверка общая на все внешности, и общей она сделана нарочно. Поимённые
     проверки ниже ловят каждая свою фигуру в ОДНОЙ фазе, а своих внешностей у
     миров шесть, и у четырёх из них есть движение: медуза всплывает, блик
     ползёт, кратеры едут, хвост дышит. Фигура, которая в фазе 0.0 внутри
     плиты, а в фазе 0.7 вылезла в проём, обещала бы проход там, где его нет —
     и ровно этого на глаз не видно.

     Горизонталь требуется у всех: по краю плиты судит `isSafe()`. Вертикаль —
     только у боковых, потому что у приседа фигура ОБЯЗАНА свисать ниже плиты,
     в ту самую щель; её глубину сторожит отдельная проверка в пикселях ниже.

     Цвета фигуры вычисляются, а не перечисляются: это те, которых нет в кадре
     с `beam` (внешность, не рисующая ничего). Перечень руками разошёлся бы с
     отрисовкой — третья копия одного знания. */
  for (const [kind, sideV] of [['duck', 0], ['side', 1]]) {
    const своиЦвета = (look) => {
      const было = new Set(paint({ at, kind, look: 'beam', side: sideV }).map((f) => f.style));
      return new Set(paint({ at, kind, look, side: sideV })
        .map((f) => f.style).filter((st) => !было.has(st)));
    };
    for (const look of LOOKS[kind]) {
      const цвета = своиЦвета(look);
      let вышла = null;
      /* Фаза меняется СДВИГОМ МЕТКИ препятствия, а не расстоянием: анимации
         считают фазу от `elapsed` и `ob.at` сразу, и двигать расстояние
         значило бы менять заодно стадию телеграфа — то есть мерить не то. При
         сдвиге метки и `elapsed` на одно и то же расстояние постоянно. */
      for (let ph = 0; ph < 3.0 && !вышла; ph += 0.1) {
        const метка = at + ph;
        const shapes = paintFrame({
          elapsed: метка - 1.5, obstacles: [{ at: метка, kind, look, side: sideV }],
        }).shapes;
        const plate = plateOf(shapes);
        if (!plate) continue;
        for (const f of shapes) {
          if (!цвета.has(f.style)) continue;
          if (f.minX < plate.minX - 1 || f.maxX > plate.maxX + 1) {
            вышла = `по горизонтали в фазе ${ph.toFixed(2)}`;
          } else if (kind === 'side' && (f.minY < plate.minY - 1 || f.maxY > plate.maxY + 1)) {
            вышла = `по вертикали в фазе ${ph.toFixed(2)}`;
          }
          if (вышла) break;
        }
      }
      check(`внешность ${look} держится внутри плиты во всех фазах`, !вышла, вышла ?? '');
    }
  }

  // ─── бадник занимает плиту, а не висит на ней ───
  {
    const shapes = paint(side('plate'));
    const plate = plateOf(shapes);
    const body = shapes.find((f) => f.style === C.badnik);
    check('плита нарисована', !!plate);
    check('бадник нарисован', !!body);
    /* Тело снова МЕЛКОЕ, и плиту занимает его движение.

       Это разворот решения от 10 октября, когда тело растили до размера плиты
       ради жалобы «мелкое существо, позади которого красная стена». Заказчик
       11 октября сказал обратное: «растянутый по высоте монстр выглядит плохо,
       сделай его маленьким, как он был, и добавь анимацию прыжка». Обе жалобы
       верны, и примиряет их прыжок: тело занимает пятнадцать процентов высоты,
       а за полтора прыжка проходит три четверти плиты.

       Поэтому здесь ДВА потолка сразу: тело не вправе быть большим, и прыжок
       обязан быть высоким. Один без другого вернул бы одну из двух жалоб. */
    const doleH = body ? body.h / plate.h : 0;
    const doleW = body ? body.w / plate.w : 0;
    check('бадник мелкий по высоте', doleH < 0.25,
      `${(doleH * 100).toFixed(0)}% высоты плиты — «растянутый монстр выглядит плохо»`);
    /* А по ШИРИНЕ — во всю плиту, и это заказ от 11 октября: шипы с этой
       внешности убраны, и на их месте осталась бы пустота. Потолок здесь не
       формальность: тело вплотную к кромке читается продолжением плиты, то
       есть приговор и картинка опять начинают спорить, только в другую
       сторону. */
    check('но во всю ширину плиты', doleW > 0.85 && doleW < 0.98,
      `${(doleW * 100).toFixed(0)}% ширины — «растянуть монстра на всю ширину красного поля»`);
    check('но не вылезает за плиту',
      body && body.minX >= plate.minX - 1 && body.maxX <= plate.maxX + 1,
      'приговор судит по краю плиты, и фигура не вправе обещать проход там, где его нет');
    check('у бадника есть рот', shapes.some((f) => f.style === C.badnikMouth),
      'заказчик описал его как существо с анимацией рта — её не было вовсе');

    /* ─── и светлое пятно на враге осталось пятном ───

       `badnikEye` светлее проёма (0.96 против 0.954) и не входит ни в один
       набор ролей — исключён нарочно, со словами «занимает несколько пикселей
       и на светлоту кадра не влияет». Когда тело выросло до размера плиты,
       глаз поехал вместе с ним, и условие исключения молча перестало
       выполняться: на плите появилось окно ярче проёма. Поймано глазами на
       первом же кадре закатной зоны, а не тестом, — поэтому тест теперь есть.

       Порог в долях площади ПЛИТЫ, а не в пикселях: пиксели зависят от
       глубины, а доля — нет. */
    /* Глаз теперь ДВА, и площадь считается по обоим сразу. Проверка на
       `find` мерила бы половину того, что ограничивает, — ровно тот недосмотр,
       про который написано абзацем выше: правка пропорций молча отменяет
       условие, на котором держалось исключение из правила. */
    const eyes = shapes.filter((f) => f.style === C.badnikEye);
    check('глаза бадника нарисованы', eyes.length === 2, `${eyes.length} шт.`);
    const доля = eyes.length
      ? eyes.reduce((s, f) => s + f.w * f.h, 0) / (plate.w * plate.h) : 1;
    check('но остаются мелкими пятнами, а не окном', доля < 0.015,
      `${(доля * 100).toFixed(1)}% площади плиты, а он ярче проёма: `
      + 'именно поэтому он и не входит ни в один набор ролей');
  }

  /* ─── у висящего зверя глаза под тем же потолком ───

     `badnikEye` (0.96) светлее проёма (0.954) и не входит ни в один набор
     ролей ИМЕННО потому, что занимает несколько пикселей. Это исключение
     действует ровно до тех пор, пока оно правда. У бадника оно однажды
     перестало быть правдой молча, когда тело выросло; у зверя такого случая
     ещё не было — и потолок ставится до него, а не после.

     Проверяется по всему взмаху: крылья ходят, и пропорции глаз от фазы
     зависеть не должны вовсе — а если однажды начнут, это и будет видно. */
  {
    for (const dt of [1.5, 1.8, 2.1, 2.4]) {
      const shapes = paint({ at, kind: 'duck', look: 'bat', side: 0 }, dt);
      const plate = plateOf(shapes);
      const eyes = shapes.filter((f) => f.style === C.badnikEye);
      check(`глаза зверя нарисованы (dt=${dt})`, eyes.length === 2, `${eyes.length} шт.`);
      const доля = eyes.reduce((s, f) => s + f.w * f.h, 0) / (plate.w * plate.h);
      check(`и остаются мелкими пятнами (dt=${dt})`, доля < 0.015,
        `${(доля * 100).toFixed(2)}% площади плиты, а они ярче проёма`);
    }
  }

  // Рот живёт, и живёт функцией времени, без состояния: видно это из node.
  {
    const рты = [0, 0.2, 0.4, 0.6, 0.8].map((d) => {
      const m = paint(side('plate'), 2.4 - d).find((f) => f.style === C.badnikMouth);
      return m ? Math.round(m.h) : -1;
    });
    check('рот открывается и закрывается', new Set(рты).size > 1, рты.join(' / '));
  }

  /* ─── прыжок доходит до 70-80% высоты плиты и возвращается на землю ───

     Заказанная высота — «70-80% высоты препятствия», и проверяется она по
     ВСЕМУ циклу, а не в одной фазе: прыжок фазовый, и единственный снимок
     поймал бы его в случайном месте. Шаг взят так, чтобы при 0.8 Гц перекрыть
     полный период с запасом.

     Доли экранные, а не мировые, и это законно: `sy` линеен по `y` при
     постоянной глубине, значит доля высоты плиты на экране равна доле в метрах.
     Но глубина внутри прогона меняется вместе с `dt`, поэтому каждая выборка
     делится на СВОЮ плиту, а не на первую. */
  {
    const высоты = [];
    const низы = [];
    for (let dt = 1.3; dt <= 2.6; dt += 0.05) {
      const shapes = paint(side('plate'), dt);
      const plate = plateOf(shapes);
      const body = shapes.find((f) => f.style === C.badnik);
      if (!plate || !body) continue;
      высоты.push((plate.maxY - body.minY) / plate.h);
      низы.push((plate.maxY - body.maxY) / plate.h);
    }
    const верх = Math.max(...высоты);
    const низ = Math.min(...низы);
    check('бадник прыгает до 70-80% высоты плиты', верх >= 0.70 && верх <= 0.82,
      `апогей на ${(верх * 100).toFixed(0)}% — заказано «до 70-80% высоты препятствия»`);
    check('и возвращается на землю', низ < 0.10,
      `ниже всего поднимался на ${(низ * 100).toFixed(0)}% — существо, висящее в воздухе, не прыгает`);
    check('прыжок вообще размахивает', верх - низ > 0.5,
      `размах ${((верх - низ) * 100).toFixed(0)}% высоты плиты`);
  }

  /* ─── дорожка и пыль занимают плиту, но не выходят за неё ───

     Это ответ на жалобу 10 октября, которую мелкое тело вернуло: за существом
     снова оказалось ровное красное поле. Занимать его обязано что-то статичное,
     иначе плита «пустеет» ровно в те полсекунды, когда бадник в апогее.

     Пыль проверяется по всему циклу: она функция фазы, и ровно так полоска
     колёсика однажды выехала на пол — размах подняли, высоту не тронули. */
  {
    for (let dt = 1.3; dt <= 2.6; dt += 0.1) {
      const shapes = paint(side('plate'), dt);
      const plate = plateOf(shapes);
      /* `earthDeep` носит ещё и глубина обрыва, причём она же рисуется первой
         и уходит за кадр. Дорожку поэтому ищем ВНУТРИ плиты, а не по цвету:
         иначе проверка меряет обрыв и проходит/падает не о том. */
      const дорожка = shapes.find((f) => f.style === C.earthDeep
        && f.minX >= plate.minX - 1 && f.maxX <= plate.maxX + 1
        && f.minY >= plate.minY - 1 && f.maxY <= plate.maxY + 1);
      const пыль = shapes.filter((f) => f.style === C.shade);
      if (!plate) continue;
      check(`дорожка нарисована (dt=${dt.toFixed(2)})`, !!дорожка);
      if (дорожка) {
        check(`дорожка идёт во всю ширину плиты (dt=${dt.toFixed(2)})`,
          дорожка.w / plate.w > 0.95, `${((дорожка.w / plate.w) * 100).toFixed(0)}%`);
        check(`и не выезжает ниже плиты (dt=${dt.toFixed(2)})`,
          дорожка.maxY <= plate.maxY + 0.5,
          `низ ${дорожка.maxY.toFixed(1)} при полу плиты ${plate.maxY.toFixed(1)}`);
      }
      check(`пыль не выходит за плиту (dt=${dt.toFixed(2)})`,
        пыль.every((f) => f.minX >= plate.minX - 1 && f.maxX <= plate.maxX + 1
          && f.maxY <= plate.maxY + 0.5),
        'светлое или тёмное ПЕРЕД препятствием обещает пол там, где плита');
      /* И пыль не ложится НА существо. Пока тело было узким, облачка стояли
         по бокам от него и этот вопрос не возникал; у тела во всю плиту
         «рядом» означает «за кромкой», поэтому они ушли под него — и в
         момент отрыва, когда облачко самое широкое, рисовались поверх нижних
         углов тела двумя тёмными выемками. То есть ровно тогда, ради чего
         пыль и нарисована, она переставала быть пылью. Поймано ревью. */
      const тело = shapes.find((f) => f.style === C.badnik);
      if (тело) {
        check(`и не ложится на тело (dt=${dt.toFixed(2)})`,
          пыль.every((f) => f.minY >= тело.maxY - 0.5),
          'пыль рисуется после тела, и поднявшись выше, она красит его углы');
      }
    }
  }

  /* ─── вскрывшийся бадник остаётся внутри плиты ───

     Награда за правильное положение: на последней отметке телеграфа существо
     разъезжается надвое и из него выскакивает зверёк. Половинки разъезжались
     на ЦЕЛУЮ ширину тела, и пока тело было узким (23% плиты), это умещалось
     само. У тела во всю плиту тот же разъезд вынес бы половинку в проём —
     то есть фигура пообещала бы проход уже, чем он есть, ровно как зуб,
     залезший за кромку. Поэтому разъезд считается долей тела, и проверяется
     это по всему раскрытию, а не в одной фазе. */
  for (const s of [1, -1]) {
    let вскрылся = 0;
    let зверёк = false;
    for (let dt = O.lastCallS; dt > 0; dt -= 0.1) {
      const shapes = paintFrame({
        u: s > 0 ? -0.9 : 0.9,
        elapsed: at - dt,
        obstacles: [{ at, kind: 'side', look: 'plate', side: s }],
      }).shapes;
      const plate = plateOf(shapes);
      const половинки = shapes.filter((f) => f.style === C.badnik);
      if (!plate || !половинки.length) continue;
      вскрылся = Math.max(вскрылся, половинки.length);
      зверёк = зверёк || shapes.some((f) => f.style === C.critter);
      check(`половинки бадника не выходят за плиту (сторона ${s}, dt=${dt.toFixed(1)})`,
        половинки.every((f) => f.minX >= plate.minX - 1 && f.maxX <= plate.maxX + 1),
        'по кромке плиты судит isSafe(), и фигура не вправе обещать проход уже, чем он есть');
    }
    /* И проверка обязана ДОЙТИ до вскрытия: без этого она мерила бы обычное
       цельное тело и проходила бы при любом разъезде половинок. */
    check(`бадник действительно вскрылся (сторона ${s})`, вскрылся >= 2,
      `${вскрылся} фигур тела — награда за правильное положение не показана`);
    check(`и зверёк выскочил (сторона ${s})`, зверёк,
      'талисман игры — единственное, ради чего бадник вскрывается');

    /* НИЖНИЙ конец раскрытия: в сам момент вскрытия ширина не прыгает.

       Верхнюю границу (половинки внутри плиты) проверка выше ловит, а нижнюю
       не ловила вовсе — и ровно там завёлся дефект: при `hw = bw · 0.25`
       половинки при `open = 0` занимали ВДВОЕ меньше цельного тела, то есть
       существо на кадр сжималось и только потом расходилось. Поймано ревью.
       Меряется доля плиты, а не пиксели: глубина у двух выборок разная. */
    const размах = (dt) => {
      const shapes = paintFrame({
        u: s > 0 ? -0.9 : 0.9,
        elapsed: at - dt,
        obstacles: [{ at, kind: 'side', look: 'plate', side: s }],
      }).shapes;
      const plate = plateOf(shapes);
      const тело = shapes.filter((f) => f.style === C.badnik);
      if (!plate || !тело.length) return null;
      return (Math.max(...тело.map((f) => f.maxX)) - Math.min(...тело.map((f) => f.minX)))
        / plate.w;
    };
    const до = размах(O.lastCallS + 0.02);
    const после = размах(O.lastCallS - 0.02);
    check(`ширина бадника не прыгает в момент вскрытия (сторона ${s})`,
      до !== null && после !== null && Math.abs(до - после) < 0.05,
      `${((до ?? 0) * 100).toFixed(0)}% ширины плиты до и ${((после ?? 0) * 100).toFixed(0)}% после`);
  }

  /* ─── шипы переживают створку ───

     Шипы рисовались ДО внешности, а стойки створки идут от пола до самой
     кромки — и закрашивали корни крайних зубьев. Те два снова читались
     колпаками на кромке, то есть ровно тем, ради чего корни и уводили внутрь
     плиты. С бадником это не всплывало: его тело кончается ниже корней, и
     порядок случайно оказывался верным. */
  {
    /* Шип опознаётся формой, а не цветом: `spike` носят ещё болты створки, и
       счёт по одному цвету сравнивал бы разные наборы фигур. Шип — фигура,
       которая КАСАЕТСЯ внутренней кромки плиты; болты сидят по её центру.

       Внутренняя кромка у правой плиты — левый край на экране: плита занимает
       [edge, HALF], и меньшему `x` отвечает меньший `sx`. */
    const шипы = (shapes) => {
      const plate = plateOf(shapes);
      return shapes.filter((f) => f.style === C.spike && f.minX <= plate.minX + 1);
    };
    const gate = шипы(paint(side('gate'))).length;
    const plate = шипы(paint(side('plate'))).length;
    /* Порядок проверяется теперь только у створки — у бадника шипов нет вовсе
       (заказ 11 октября). Но проверка эта и была ПРО СТВОРКУ: закрашивали корни
       её стойки, и обратная правка порядка внутри ветки `gate` снова оставила
       бы крайние зубья колпаками на кромке. */
    check('у створки шипов больше трёх', gate > 3,
      `${gate}: стойки створки закрашивали их корни, когда шипы шли первыми`);
    check('а у бадника ни одного', plate === 0,
      `${plate}: шипы смотрели в центр поля и съедали плиту, на которой он живёт`);
    /* И сам ПОРЯДОК. Счёт фигур его не ловит и не ловил: поддельный холст
       записывает каждый вызов независимо от перекрытия, а геометрия шипов от
       створки не зависит — перестановка двух вызовов оставила бы те же семь
       шипов и ту же проверку зелёной. Поймано ревью. Порядок виден только по
       индексу в списке заливок: детали створки обязаны лечь ДО шипов, иначе
       стойки закрасят корни крайних зубьев. */
    const фигуры = paint(side('gate'));
    const полотно = plateOf(фигуры);
    const последняяДеталь = фигуры.reduce(
      (i, f, k) => (f.style === C.blockDeep ? k : i), -1,
    );
    const первыйШип = фигуры.findIndex((f) => f.style === C.spike
      && f.minX <= полотно.minX + 1);
    check('шипы ложатся ПОСЛЕ деталей створки',
      последняяДеталь >= 0 && первыйШип > последняяДеталь,
      `деталь ${последняяДеталь}, шип ${первыйШип}: стойка идёт от пола до кромки `
      + 'и, нарисованная второй, оставляет крайние зубья колпаками');
  }

  // ─── створка тоже на всю плиту ───
  {
    const shapes = paint(side('gate'));
    const plate = plateOf(shapes);
    const детали = shapes.filter((f) => f.style === C.blockDeep);
    check('у створки есть детали', детали.length >= 5,
      `${детали.length} — три полоски посередине заказчик и назвал красной стеной`);
    /* И детали обязаны быть ВИДНЫ. В `blockDark` их не было видно вовсе:
       0.080 против 0.160 у лица плиты — после сжатия Miracast ноль. Разница
       вчетверо и больше переживёт и его. */
    check('детали заметно темнее лица плиты',
      luminance(C.block) / luminance(C.blockDeep) > 4,
      `${luminance(C.block).toFixed(3)} против ${luminance(C.blockDeep).toFixed(3)}`);
    check('но не светлее его', luminance(C.blockDeep) < luminance(C.block),
      'светлое пятно на лице плиты начинает спорить с проёмом');
    const высоко = детали.some((f) => f.minY < plate.minY + plate.h * 0.25);
    const низко = детали.some((f) => f.maxY > plate.minY + plate.h * 0.75);
    check('детали идут по всей высоте плиты', высоко && низко,
      'иначе верх и низ створки остаются той же заливкой');
    const широко = Math.max(...детали.map((f) => f.w)) / plate.w;
    check('и по всей её ширине', широко > 0.8, `${(широко * 100).toFixed(0)}% ширины`);
  }

  /* ─── шипы смотрят в коридор, а не в небо ───

     Росли они с верхней кромки вверх, и заказчик сказал про это прямо: шипы
     должны грозить туда, куда бежит ребёнок. Проверяются обе стороны коридора
     — направление выводится из `x0`/`x1`, и зеркальная ошибка здесь дала бы
     зубья, растущие ВНУТРЬ плиты и не видные вовсе. */
  for (const s of [1, -1]) {
    const shapes = paint({ at, kind: 'side', look: 'gate', side: s });
    const plate = plateOf(shapes);
    // Внутренняя кромка: у правой плиты левый край экрана, у левой — правый.
    const внутрь = s > 0 ? plate.minX : plate.maxX;
    const spikes = shapes.filter((f) => f.style === C.spike
      && Math.min(Math.abs(f.minX - внутрь), Math.abs(f.maxX - внутрь)) < 1);
    check(`шипов больше трёх (сторона ${s})`, spikes.length > 3, `${spikes.length}`);
    const длины = spikes.map((f) => f.w);
    check(`шипы неровные (сторона ${s})`, new Set(длины.map((h) => Math.round(h))).size > 1,
      `длины ${длины.map((h) => h.toFixed(0)).join(', ')} — ровный гребень и был скучным`);
    /* Главное ограничение: остриё доходит до кромки и НЕ переходит её. По этой
       линии судит `isSafe()`, и зуб в проёме пообещал бы проход уже, чем
       приговор, — тот же класс дефекта, из-за которого край препятствия берётся
       из одного места. Вверх шипы вылезали безнаказанно: выше `WALL` не
       судится ничего. */
    check(`ни один шип не залезает в проём (сторона ${s})`,
      spikes.every((f) => (s > 0 ? f.minX >= plate.minX - 1 : f.maxX <= plate.maxX + 1)),
      'приговор судит по кромке плиты, и зуб не вправе обещать проход уже, чем он есть');
    check(`корень шипа внутри плиты (сторона ${s})`,
      spikes.every((f) => (s > 0 ? f.maxX < plate.maxX : f.minX > plate.minX)),
      'корни на самой кромке читаются колпаками, а не гребнем');
  }
  {
    const shapes = paint(side('gate'));
    const plate = plateOf(shapes);
    const spikes = shapes.filter((f) => f.style === C.spike && f.minX <= plate.minX + 1);
    check('шипы раскладываются по высоте плиты',
      Math.max(...spikes.map((f) => f.maxY)) - Math.min(...spikes.map((f) => f.minY))
        > plate.h * 0.8,
      'иначе гребень собрался в одном месте, а не идёт по всей кромке');
  }

  /* Неровность обязана быть ФУНКЦИЕЙ, а не случайностью: дрожащий от кадра к
     кадру гребень — это рябь, а не шипы. По тому же правилу сделаны все
     анимации проекта. */
  {
    const гребень = (ob, dt) => paint(ob, dt).filter((f) => f.style === C.spike)
      .map((f) => f.w.toFixed(3)).join(',');
    check('гребень не дрожит от кадра к кадру',
      гребень(side('gate'), 1.5) === гребень(side('gate'), 1.5));
    check('а у соседнего препятствия он другой',
      гребень(side('gate'), 1.5)
      !== paintFrame({ elapsed: at + 0.7 - 1.5, obstacles: [{ at: at + 0.7, kind: 'side', look: 'gate', side: 1 }] })
        .shapes.filter((f) => f.style === C.spike).map((f) => f.w.toFixed(3)).join(','),
      'иначе все препятствия забега носят один и тот же гребень');
  }

  /* ─── зубья приседа: неровные, но НЕ длиннее ───

     Зубья висят внутри щели, в которую ребёнок проходит. Приговор от их длины
     не зависит — присед судится флагом, — но ребёнок видит картинку, а не
     приговор: длинные зубья учили бы приседать глубже, чем просят. Поэтому
     неровность им разрешена, а рост — нет, и потолок мерится в пикселях
     кадра, а не в доверии к формуле. */
  {
    const z = 1.5 * VIEW.speed;
    const cam = camera(0, 0);
    const потолок = Math.abs(project(0, O.duckHeight - O.teethM, z, cam).sy
      - project(0, O.duckHeight, z, cam).sy);
    const зубья = paint({ at, kind: 'duck', look: 'ceiling', side: 0 })
      .filter((f) => f.style === C.spike);
    check('зубьев больше прежних семи', зубья.length > 7, `${зубья.length}`);
    check('зубья неровные', new Set(зубья.map((f) => Math.round(f.h))).size > 1,
      зубья.map((f) => f.h.toFixed(0)).join(', '));
    const самый = Math.max(...зубья.map((f) => f.h));
    check('но ни один не длиннее teethM', самый <= потолок + 0.5,
      `самый длинный ${самый.toFixed(1)} px при потолке ${потолок.toFixed(1)}`);
  }
});

/* ───────────── большое кольцо видно, а не только слышно ─────────────

   Заказчик: «кольцо с большим количеством очков визуально не отличается от
   остальных, только другой звук». Это и значит, что о его ценности ребёнок
   узнаёт ПОСЛЕ сбора, то есть редкое событие перестаёт быть событием.

   Размером отличать больше нечем: рим большого кольца 0.256 м против окна
   сбора 0.26 — запас двенадцать миллиметров, и он уже выбран. Поэтому цвет, и
   цвет РЕШЕНИЯ: общий на все зоны, как и у обычного кольца, иначе зона
   перекрасила бы язык игры посреди забега. */
group('большое кольцо', () => {
  const C = THEME.greenHill;
  const ring = (worth) => paintFrame({ stars: [{ x: 0, z: 4, worth }] }).shapes;

  const обычное = ring(1);
  const большое = ring(3);
  check('обычное кольцо золотое', обычное.some((f) => f.style === C.star));
  check('большое кольцо другого цвета', большое.some((f) => f.style === C.starBig),
    'иначе о цене ребёнок узнаёт только задним числом, по звуку');
  check('и золотым оно не рисуется', !большое.some((f) => f.style === C.star),
    'два цвета на одном кольце читаются как два кольца');
  check('у обычного кольца нового цвета нет', !обычное.some((f) => f.style === C.starBig),
    'иначе отличать нечем снова');
  check('у большого есть лучи',
    большое.filter((f) => f.style === C.starBig).length
    > обычное.filter((f) => f.style === C.star).length,
    'один только цвет после сжатия Miracast различается хуже, чем цвет плюс форма');

  // Цвета большого кольца — решения, а не фона: общие на все зоны и под
  // проверкой светлоты. Неотнесённый цвет не проверяется ничем.
  check('starBig отнесён к цветам решения', DECISION_KEYS.includes('starBig'));
  check('starBigDim тоже', DECISION_KEYS.includes('starBigDim'));
  for (const z of ZONES_ALL) {
    check(`${z}: большое кольцо того же цвета, что в первой зоне`,
      THEME[z].starBig === THEME.greenHill.starBig
      && THEME[z].starBigDim === THEME.greenHill.starBigDim,
      'язык игры ребёнок учит в первые полминуты, и зона не вправе его перекрасить');
    check(`${z}: большое кольцо отличается от обычного по светлоте`,
      Math.abs(luminance(THEME[z].starBig) - luminance(THEME[z].star)) > 0.05,
      `${luminance(THEME[z].starBig).toFixed(3)} против ${luminance(THEME[z].star).toFixed(3)}: `
      + 'цветность Miracast режет сильнее светлоты, и отличие обязано быть в ней');
  }

  // Размер по-прежнему зажат окном сбора: нарисованное крупнее собираемого —
  // это обещание, которого игра не держит.
  check('рим большого кольца внутри окна сбора',
    VIEW.starDrawR * VIEW.bigStarScale < VIEW.starReach,
    `${(VIEW.starDrawR * VIEW.bigStarScale).toFixed(3)} против ${VIEW.starReach}`);
});

/* ───────────── небо меняется вместе с зоной ─────────────

   Заказчик после забега 10 октября: «смена цветового оформления во время
   забега работает хорошо, но небо и дальний план остаются без изменений».

   Так и было, и не по недосмотру, а по построению: растр один на весь забег и
   кладётся во ВЕСЬ кадр (1024×576 на 1280×720 даёт dy = 0, dh = 720 — это
   посчитано в соседней группе). То есть `COLORS.sky` зоны закрашивался
   картинкой целиком, и зона могла перекрасить всё, кроме верхней половины
   кадра, — ровно той, которая и называется «небо и дальний план».

   Проверяется здесь не красота картинок, а развязка: у каждой зоны свой
   растр, а зона без растра уходит на векторный путь СВОИХ цветов, не утаскивая
   за собой ни палитру, ни игру. */
/* ───────────── потолок светлоты фонового растра ─────────────

   Зажим светлоты при сборке арта был копией без владельца: 0.704 стояло
   числом в README и в строке запуска `tools/frame.html`, а выводится оно из
   `GAP_GUARD`. Изменился бы порог палитры — конвейер арта молча остался бы на
   старом зажиме, и разошлись бы они так же, как разошёлся худший кадр. */
group('потолок светлоты растра', () => {
  for (const zone of ['greenHill', 'sunsetDunes']) {
    check(`${zone}: потолок следует за GAP_GUARD`,
      Math.abs(skyClamp(zone) - (luminance(THEME[zone].gap) - GAP_GUARD)) < 1e-12,
      `${skyClamp(zone)} против ${luminance(THEME[zone].gap) - GAP_GUARD}`);
  }

  /* Ночной — исключение, и оно обязано оставаться исключением: выводить его
     из палитры нечем, такого правила проект не формулировал. Проверяется не
     значение, а смысл — что он заметно ниже дневного. */
  check('у ночной зоны потолок ниже дневного',
    skyClamp('nightHills') < skyClamp('greenHill') - 0.2,
    `ночь ${skyClamp('nightHills')}, день ${skyClamp('greenHill')}`);
  check('и он не ноль', skyClamp('nightHills') > 0.1, `${skyClamp('nightHills')}`);

  /* README называет то же число. Сверка та же, что у худшего кадра: проза,
     повторяющая число, обязана отвечать за него перед кодом. */
  const readme = readFileSync(join(ROOT, 'README.md'), 'utf8');
  const сказано = readme.match(/от проёма [(]сейчас ([0-9.]+)[)]/);
  check('README называет дневной потолок в ожидаемой форме', сказано != null,
    'строка «от проёма (сейчас N)» в README.md не найдена');
  if (сказано) {
    check('и это тот же потолок, что в теме',
      Number(сказано[1]) === Math.round(skyClamp('greenHill') * 1000) / 1000,
      `README говорит ${сказано[1]}, тема даёт ${skyClamp('greenHill')}`);
  }

  /* Потолок берётся у ПОЛЯ зоны, а не по её имени. Имя работало, пока тёмная
     зона была одна; со вторым миром «ночь с сиянием» молча получила бы дневной
     потолок 0.704, и белое сияние читалось бы дырой в ночном небе — ровно тот
     отказ, от которого зажим и ставился. */
  check('ночной потолок задан полем зоны, а не её именем',
    THEME.nightHills.skyClampTo === skyClamp('nightHills'),
    `поле ${THEME.nightHills.skyClampTo}, функция ${skyClamp('nightHills')}`);
  check('и в коде не осталось сравнения с именем зоны',
    !readFileSync(join(ROOT, 'js/theme.js'), 'utf8').includes("zone === 'nightHills'"),
    'вторая тёмная зона потребовала бы второго if, и его забыли бы');
  /* У зоны без поля потолок по-прежнему выводится из проёма. */
  check('у дневной зоны поля нет', THEME.greenHill.skyClampTo === undefined);

  /* У СНЕЖНОГО поля потолок свой и с запасом, хотя зона дневная.

     Причина не в палитре, а в площади: её собственное небо стоит на 0.693 при
     потолке 0.704, то есть запаса 0.011, а WebP выталкивает пиксели обратно
     вверх — замерено на ночном растре +0.047 при заданных 0.30. У прочих зон
     светлое занимает отдельные облака, здесь — половину кадра, и зажим
     впервые работает по всей площади. Без запаса проём перестал бы быть самым
     светлым местом кадра в самой светлой зоне нового мира.

     Проверить это набором нельзя: декодировщика WebP в node нет. Поэтому
     сторожится не растр, а ЗАПАС, с которым он собран. Поймано ревью. */
  check('у снежного поля потолок растра с запасом', skyClamp('snowField') <= 0.65,
    `${skyClamp('snowField')} — при 0.704 плюс выталкивание WebP проём перестаёт быть ярчайшим`);

  /* ── Мотив неба у КАЖДОЙ зоны, и полоса умеет каждый ──

     Здесь стояла пара проверок про булев `skyAurora`: «у ночи с сиянием
     поднят флаг» и «полоса умеет его рисовать». Обе проходили, и обе
     пропустили настоящий дефект — потому что сторожили ДОБАВКУ к шаблону, а
     не сам шаблон. Шаблонов было два («звёзды» и «облака со стволами»), и
     умолчанием служил второй: заросли ламинарии получили облака с пальмами,
     а светящаяся бездна — то самое сияние и луну ПОД ВОДОЙ, потому что
     другого способа сказать «тёмное небо, но не ночь» не было.

     Теперь сторожится композиция целиком: у зоны обязан быть мотив, и
     генератор полосы обязан его знать. Умолчания нет — зона без мотива
     роняет сборку, а не получает пальмы. */
  const полоса = readFileSync(join(ROOT, 'tools', 'frame.html'), 'utf8');
  const мотивыПолосы = new Set(
    [...полоса.matchAll(/^\s{6}([A-Za-z]+): \(\) => \{/gm)].map((m) => m[1]));
  check('генератор полосы называет свои мотивы', мотивыПолосы.size >= 9,
    [...мотивыПолосы].join(', '));
  for (const z of Object.keys(THEME)) {
    const м = THEME[z].skyMotif;
    check(`у зоны ${z} есть мотив неба`, typeof м === 'string' && м.length > 0, `${м}`);
    check(`и полоса умеет рисовать мотив «${м}» зоны ${z}`, мотивыПолосы.has(м),
      'мотив есть, а рисовать его нечем — обещание без исполнения');
  }
  check('сияние осталось ровно у одной зоны',
    Object.keys(THEME).filter((z) => THEME[z].skyMotif === 'aurora').join(',') === 'auroraNight',
    'полярное сияние под водой — ровно та жалоба, из-за которой мотивы и завелись');
  /* И обратная сторона: мотив читает ТОЛЬКО инструмент сборки. Запасной
     векторный путь `drawSky` о нём не знает и знать не должен — он
     существует ради того, чтобы забег шёл вовсе без арта, и сияние стоило бы
     ему заливок. Асимметрия названа, значит и проверена. */
  check('мотив неба не достаёт до игры',
    !/skyMotif/.test(readFileSync(join(ROOT, 'js', 'view.js'), 'utf8')),
    'drawSky не вправе зависеть от мотива: он рисует зону без арта вообще');

  /* README называет и ОСТАЛЬНЫЕ потолки — те, что заданы полем. Дневной он
     сверял с кодом давно, а заданные полем перечислял прозой, не отвечая за
     них ничем. Поймано ревью. */
  for (const [подпись, зона] of [['у четырёх тёмных', 'nebula'],
                                 ['у пояса комет', 'cometBelt'],
                                 ['у зарослей', 'kelpDeep'],
                                 ['у снежного поля', 'snowField']]) {
    const м = readme.match(new RegExp(подпись + ' ([0-9.]+)'));
    check(`README называет потолок ${подпись}`, м != null, подпись);
    if (м) {
      check(`и это тот же потолок, что в теме (${подпись})`,
        Number(м[1]) === skyClamp(зона), `README ${м[1]}, тема ${skyClamp(зона)}`);
    }
  }

  /* И в строке запуска числа больше нет: зажим берётся вызовом. */
  const frame = readFileSync(join(ROOT, 'tools', 'frame.html'), 'utf8');
  /* init-полосу можно сделать для ЛЮБОЙ зоны, а не только первого мира.
     Проверка текстовая, как и соседняя про `skyClamp` в примере сборки: HTML
     в node не исполняется. Без этого арт нового мира нечем начать — и
     выяснилось бы это в середине этапа, с уже написанными палитрами. */
  check('полосу можно снять с любой зоны палитры',
    frame.includes('Object.keys(THEME)') && !frame.includes("const ZONES = zonesOf('hills')"),
    'иначе ?band= знает только зоны первого мира');

  check('пример сборки зовёт skyClamp, а не пишет число',
    frame.includes("skyClamp('sunsetDunes')") && !frame.includes('0.82, 0.704'),
    'в tools/frame.html пример снова вписывает потолок числом');
  check('инструмент отдаёт skyClamp в консоль', frame.includes('window.skyClamp = skyClamp'),
    'без этого skyClamp() из консоли браузера не вызвать');
});

group('небо меняется вместе с зоной', () => {
  const растр = (метка) => ({ width: 1024, height: 576, метка });
  const backdrops = {
    greenHill: растр('утро'),
    sunsetDunes: растр('закат'),
  };
  const кадр = (zone) => paintFrame({ zone, backdrops, travel: 30, elapsed: 30 });

  check('в первой зоне кладётся её растр',
    кадр('greenHill').images.every((i) => i.метка === 'утро'),
    кадр('greenHill').images.map((i) => i.метка).join(', ') || 'ни одного');
  check('во второй — её, а не первой',
    кадр('sunsetDunes').images.length > 0
    && кадр('sunsetDunes').images.every((i) => i.метка === 'закат'),
    'иначе всё оформление зоны меняется, кроме верхней половины кадра');

  /* Зона без растра: картинки нет, но игра идёт, и фон рисуется цветами
     ЭТОЙ зоны. Это и есть та независимость от арта, ради которой запасной
     путь вообще существует. */
  const ночь = кадр('nightHills');
  check('зона без растра обходится без него', ночь.images.length === 0);
  check('и рисуется в своих цветах, а не в чужих',
    ночь.fills.includes(THEME.nightHills.sky)
    && !ночь.fills.includes(THEME.greenHill.sky),
    'запасной путь красится палитрой кадра, и зона обязана доехать до него');

  /* Неизвестная зона не роняет растр. Без памяти о последней известной зоне
     палитра оставалась бы прежней, а небо прыгало бы с картинки на вектор —
     то есть кадр оказался бы наполовину в одной зоне, наполовину в другой. */
  const p = painter();
  const v = createView(p.canvas, { backdrops });
  v.render({ zone: 'sunsetDunes', travel: 30, elapsed: 30, stars: [], obstacles: [], decor: [] });
  const было = p.images.length;
  v.render({ zone: 'чего-то такого нет', travel: 30, elapsed: 30, stars: [], obstacles: [], decor: [] });
  check('неизвестная зона оставляет прежний растр, а не роняет его',
    p.images.length > было && p.images[p.images.length - 1].метка === 'закат');

  // Таблица зона → файл одна на проект: по ней грузит train.js и по ней же
  // собирается список офлайн-кэша.
  check('у каждой зоны назван файл неба',
    ZONES_ALL.every((z) => typeof SKY_FILES[z] === 'string' && SKY_FILES[z].endsWith('.webp')),
    JSON.stringify(SKY_FILES));
  check('файлы разные', new Set(Object.values(SKY_FILES)).size === ZONES_ALL.length,
    'один файл на две зоны вернул бы ровно ту жалобу, с которой всё началось');
});

/* ───────────── ступень сложности ─────────────

   «Тихая адаптация» — последнее несделанное из этапа 5 плана. Ступень живёт у
   игрока, читается один раз на забег и двигается после него на один шаг.

   Проверяется здесь не то, что ступени «работают», а три вещи, каждая из
   которых молча ломается обратной правкой:

   1. ступень не трогает время на решение — это несущая конструкция всей
      затеи, и держится она структурой ответа `tuneFor`, а не обещанием;
   2. ступень 0 — сегодняшняя игра побайтово, иначе все замеры до 11 октября
      перестают быть сравнимыми, а журнал будет говорить «ступень 0» и значить
      другую игру;
   3. ни на одной ступени уклоняемость не сломана, и нарисованное совпадает с
      приговором. */
group('ступень', () => {
  const full = Math.abs(cameraX(1));

  // ── ступень 0 — это сегодняшние числа ──
  {
    const t = tuneFor(0);
    check('ступень 0 повторяет конфиг', t.blockFrac === O.blockFrac
      && t.duckShare === O.duckShare && t.seriesMin === O.seriesMin
      && t.seriesMax === O.seriesMax && t.breatherS === O.breatherS,
      JSON.stringify(t));
    check('и край препятствия на ней прежний',
      obstacleEdge(t.blockFrac) === obstacleEdge(),
      'иначе замеры до тихой адаптации перестают быть сравнимыми');
  }

  /* ── ступени не трогают время на решение ──

     Это главный инвариант, и проверяется он СТРУКТУРОЙ ответа, а не чтением
     кода. Худший ответ ребёнка на телеграф — 4.72 с при окне 5.0, четвёртая
     сессия подряд у границы; `minGapS > signalS` держит плотность. Появление
     любого из этих ключей в «ручках» означало бы, что сложность растёт за
     счёт времени на решение, то есть за счёт того единственного запаса,
     которого у ребёнка нет. */
  {
    /* `speed` из списка ВЫШЕЛ 18 октября: скорость стала ручкой третьего и
       пятого уровней. Запрет на неё обосновывался тем, что расписание задано
       в секундах, — то есть объяснял, почему ручка бесполезна, а не почему
       опасна. Взамен поставлена проверка по сути (ниже): расписание уровня
       с другой скоростью обязано совпасть посекундно. Остальные ключи
       заперты как были. */
    const запрещено = ['signalS', 'visibleS', 'railS', 'lastCallS', 'minGapS',
      'minLeadS', 'lateForgiveMs', 'starX', 'starReach', 'starGuardS'];
    for (let s = 0; s <= STEP_MAX; s++) {
      const ключи = Object.keys(tuneFor(s));
      check(`ступень ${s} не трогает время на решение`,
        ключи.every((k) => !запрещено.includes(k)), ключи.join(', '));
    }
  }

  // ── каждая ступень труднее предыдущей ──
  for (let s = 1; s <= STEP_MAX; s++) {
    const a = tuneFor(s - 1);
    const b = tuneFor(s);
    check(`ступень ${s} не легче ${s - 1}`,
      b.blockFrac >= a.blockFrac && b.duckShare >= a.duckShare
      && b.seriesMin >= a.seriesMin && b.speed >= a.speed
      && (b.seriesMin + b.seriesMax) >= (a.seriesMin + a.seriesMax),
      `${JSON.stringify(a)} → ${JSON.stringify(b)}`);
    check(`и чем-то отличается от неё`,
      JSON.stringify(a) !== JSON.stringify(b),
      'ступень-близнец не видна ни ребёнку, ни журналу');
  }

  /* ── уклоняемость не сломана ни на одной ступени ──

     Сверху ступень ограничена не вкусом, а размахом ребёнка: при `blockFrac`
     0.60 требуемое смещение — 0.61 единицы поля при измеренной медиане
     0.41–0.53 и p95 1.13–1.40. Выше начинается область, где уклониться можно
     только у самой кромки кадра, а это паузы `edge` из журналов 6 октября. */
  for (let s = 0; s <= STEP_MAX; s++) {
    const edge = obstacleEdge(tuneFor(s).blockFrac);
    check(`ступень ${s}: уйти можно`, edge < full,
      `край ${edge.toFixed(3)} при ходе ${full.toFixed(3)}`);
    check(`ступень ${s}: но уйти надо заметно`, edge > full * 0.2);

    /* И кольцо открытой стороны обязано доставаться при МИНИМАЛЬНОМ уходе.

       Это и есть нижняя граница `blockFrac`, и она не умозрительная: уход
       вправо ровно на край даёт `u`, при котором боковое кольцо той же
       стороны должно попасть в окно сбора. Понизь порог ухода — и награда за
       правильное движение станет недостижимой, то есть ребёнок будет уходить
       и терять кольцо за то, что ушёл. */
    const uNeed = edge / full;
    /* Без запасного `|| canReach(starX, 1)`: он не зависел от ступени вовсе и
       делал проверку пустой — она проходила бы при любом `blockFrac`, в том
       числе при таком, где кольцо открытой стороны при минимальном уходе уже
       недостижимо. Поймано ревью. */
    check(`ступень ${s}: кольцо открытой стороны достаётся`,
      canReach(VIEW.starX, uNeed + 0.02),
      `нужно u ≥ ${uNeed.toFixed(2)}, а кольцо на ${VIEW.starX} при окне ${VIEW.starReach}`);
  }

  /* ── ступень доезжает И до приговора, и до картинки ──

     Край препятствия теперь едет В САМОМ препятствии, потому что уровень
     построен на ступени, а конфиг про неё не знает. Две копии этого числа
     расходились бы ровно так, как уже было однажды: ребёнок бьётся о то,
     чего не видит. */
  {
    const tune = tuneFor(STEP_MAX);
    const level = makeLevel({ durationS: 120, rng: seeded(5), tune });
    const edge = obstacleEdge(tune.blockFrac);
    check('у каждого препятствия записан край',
      level.every((o) => o.edge === edge), 'одна ступень — одна кромка на забег');
    const side = level.find((o) => o.kind === 'side');
    check('приговор судит по краю препятствия, а не по конфигу',
      side && !isSafe(side, { camX: side.side > 0 ? -obstacleEdge() : obstacleEdge() }),
      'на верхней ступени прежнего края уже мало, и isSafe обязан это знать');
    /* И то же число обязано быть НАРИСОВАНО. Поддельный холст ловит кромку
       плиты, и она должна совпасть с порогом приговора. */
    const at = 10;
    const ob = { at, kind: 'side', look: 'plate', side: 1, edge };
    const shapes = paintFrame({ elapsed: at - 1.5, obstacles: [ob] }).shapes;
    const plate = shapes.find((f) => f.style === THEME.greenHill.block);
    const z = 1.5 * VIEW.speed;
    const cam = camera(0, 0);
    const ожидалось = project(edge, 0, z, cam).sx;
    check('нарисованная кромка совпадает с приговором',
      plate && Math.abs(plate.minX - ожидалось) < 1.5,
      `нарисовано ${plate?.minX.toFixed(1)}, судится по ${ожидалось.toFixed(1)}`);
  }

  /* ── число решений за забег не поехало ──

     Ступень меняет СОСТАВ решений, а не их число. Средний разнос и число
     препятствий сравниваются со ступенью 0 на нескольких длинах: передышка
     выводится формулой ровно ради этого, и если формула однажды разойдётся с
     генератором, видно будет здесь. */
  for (const durationS of [180, 300, 720]) {
    const среднее = (step) => {
      let gaps = 0;
      let n = 0;
      for (let seed = 1; seed <= 40; seed++) {
        const lv = makeLevel({ durationS, rng: seeded(seed * 7), tune: tuneFor(step) });
        n += lv.length;
        for (let i = 1; i < lv.length; i++) gaps += lv[i].at - lv[i - 1].at;
      }
      return { gap: gaps / (n - 40), n: n / 40 };
    };
    const база = среднее(0);
    const верх = среднее(STEP_MAX);
    check(`на ${durationS} с средний разнос не поехал`,
      Math.abs(верх.gap - база.gap) / база.gap < 0.03,
      `${база.gap.toFixed(2)} с против ${верх.gap.toFixed(2)} с`);
    check(`и число препятствий тоже`,
      Math.abs(верх.n - база.n) / база.n < 0.03,
      `${база.n.toFixed(1)} против ${верх.n.toFixed(1)}`);
  }

  /* ── ЗДЕСЬ БЫЛО ПРАВИЛО ПЕРЕХОДА, и его больше нет ──

     Четырнадцать проверок сторожили `nextStep`: вверх только по безупречному
     забегу, вниз по любому, мусор не двигает. Правило отменено 18 октября по
     требованию заказчика («менять сложность автоматически не надо»), удалено
     из кода целиком, и проверять в нём нечего. Пороги, на которых оно
     стояло, живы — они переехали в разбор журнала и сторожатся в группе
     «разбор журнала».

     На освободившееся место встали проверки того, чем уровни теперь
     различаются. */

  // ── скорость растёт ровно на третьем и пятом ──
  {
    const скорость = (i) => tuneFor(i).speed;
    check('первые два уровня идут базовой скоростью',
      скорость(0) === VIEW.speed && скорость(1) === VIEW.speed,
      `${скорость(0)} и ${скорость(1)} при базовой ${VIEW.speed}`);
    check('третий быстрее второго', скорость(2) > скорость(1),
      `${скорость(1)} → ${скорость(2)}`);
    check('четвёртый идёт скоростью третьего', скорость(3) === скорость(2),
      'заказчик назвал ровно два уровня, где растёт скорость: третий и пятый');
    check('пятый быстрее четвёртого', скорость(4) > скорость(3),
      `${скорость(3)} → ${скорость(4)}`);
  }

  /* ── скорость не трогает время на решение ──

     Это и есть то, чем заменена структурная проверка по именам ключей:
     `speed` из списка запрещённых вышел, и запрет теперь проверяется по
     СУТИ. Расписание задано в секундах, поэтому уровень с другой скоростью
     обязан дать посекундно то же расписание при том же посеве — меняются
     метры, а не секунды. */
  for (let s1 = 1; s1 <= STEP_MAX; s1++) {
    const база = makeLevel({ durationS: 300, rng: seeded(5),
      tune: { ...tuneFor(s1), speed: VIEW.speed } });
    const быстро = makeLevel({ durationS: 300, rng: seeded(5), tune: tuneFor(s1) });
    check(`уровень ${s1 + 1}: скорость не сдвинула расписание`,
      база.length === быстро.length
      && база.every((ob, i) => Math.abs(ob.at - быстро[i].at) < 1e-9),
      'окно решения задано в секундах; скорость меняет метры, а не их');
  }

  /* ── на любой скорости плита исчезает раньше окна прощения ──

     Метры тут при каждой скорости свои, а время обязано остаться не меньше
     окна прощения: иначе ребёнок получает приговор, глядя на закрытый проём,
     — худший класс дефекта проекта. */
  for (let s1 = 0; s1 <= STEP_MAX; s1++) {
    const v = tuneFor(s1).speed;
    check(`уровень ${s1 + 1}: плита исчезает раньше прощения`,
      (drawNear(v) - O.thickness) / v >= O.lateForgiveMs / 1000 - 1e-9,
      `${((drawNear(v) - O.thickness) / v).toFixed(3)} с при окне ${O.lateForgiveMs / 1000} с`);
    check(`уровень ${s1 + 1}: телеграф появляется внутри тумана`,
      O.signalS * v < VIEW.fogDistance * 0.92,
      `${(O.signalS * v).toFixed(1)} м при тумане ${VIEW.fogDistance} м`);
    check(`уровень ${s1 + 1}: окно решения не короче minLeadS`,
      O.signalS >= O.minLeadS,
      'расписание в секундах, значит это тождество — но оно обязано быть проверено');
  }

  /* ── цена перехода не опускается ниже измеренного предела ──

     3.0 с — ИЗМЕРЕННОЕ время перехода ребёнка через коридор, а не настройка.
     Множитель меньше единицы дал бы кольца, за которыми нельзя успеть, и
     написался бы он первым делом при следующей правке «ещё чуть труднее». */
  for (let s1 = 0; s1 <= STEP_MAX; s1++) {
    check(`уровень ${s1 + 1}: переход не дешевле измеренного`,
      tuneFor(s1).starSwitchScale >= 1,
      `${tuneFor(s1).starSwitchScale} — ниже 1.0 кольцо становится недостижимым`);
  }

  // ── у каждого уровня есть имя ──
  check('имён столько же, сколько строк в таблице', LEVELS.length === STEP_MAX + 1,
    `${LEVELS.length} имён на ${STEP_MAX + 1} уровней`);
  LEVELS.forEach((lv, i) => {
    check(`уровень ${i + 1} назван`, !!lv.name && !!lv.hint,
      'уровень без имени — пустая кнопка на экране выбора');
  });

  /* ── чередование видов не перебивает долю приседов ──

     `kindRunMax` подменяет вид, когда полоса одного тянется слишком долго, и
     подменяет его ВСЕГДА на присед. Если ручку взять слишком строгой,
     реализованная доля приседов уедет выше заказанной, то есть ручка молча
     перебьёт `duckShare`. */
  for (let s1 = 0; s1 <= STEP_MAX; s1++) {
    let всего = 0;
    let приседов = 0;
    for (let seed = 1; seed <= 30; seed++) {
      const lv = makeLevel({ durationS: 300, crouch: true, rng: seeded(seed * 13),
        tune: tuneFor(s1) });
      всего += lv.length;
      приседов += lv.filter((ob) => ob.kind === 'duck').length;
    }
    const доля = приседов / всего;
    check(`уровень ${s1 + 1}: доля приседов не убежала`, доля <= 0.45,
      `${доля.toFixed(3)} при заказанных ${tuneFor(s1).duckShare}`);
  }

  /* ── чередование действительно действует ──

     Иначе ручка была бы обещанием: самая длинная полоса одного вида на
     верхнем уровне обязана быть короче, чем на нижнем, где потолка нет. */
  {
    const полоса = (step) => {
      let worst = 0;
      for (let seed = 1; seed <= 30; seed++) {
        const lv = makeLevel({ durationS: 300, crouch: true, rng: seeded(seed * 29),
          tune: tuneFor(step) });
        let run = 0;
        let last = null;
        for (const ob of lv) {
          run = ob.kind === last ? run + 1 : 1;
          last = ob.kind;
          worst = Math.max(worst, run);
        }
      }
      return worst;
    };
    check('на верхнем уровне полоса одного вида короче',
      полоса(STEP_MAX) < полоса(0),
      `${полоса(0)} подряд на первом против ${полоса(STEP_MAX)} на пятом`);
    check('и укладывается в заказанный потолок',
      полоса(STEP_MAX) <= tuneFor(STEP_MAX).kindRunMax,
      `${полоса(STEP_MAX)} при потолке ${tuneFor(STEP_MAX).kindRunMax}`);
  }

  /* ── боковые стороны на верхнем уровне чередуются каждый раз ── */
  {
    let подряд = 0;
    for (let seed = 1; seed <= 30; seed++) {
      const lv = makeLevel({ durationS: 300, crouch: true, rng: seeded(seed * 31),
        tune: tuneFor(STEP_MAX) });
      let last = null;
      let run = 0;
      for (const ob of lv) {
        if (ob.kind !== 'side') continue;
        run = ob.side === last ? run + 1 : 1;
        last = ob.side;
        подряд = Math.max(подряд, run);
      }
    }
    check('на верхнем уровне каждое боковое с другой стороны', подряд === 1,
      `${подряд} подряд с одной стороны при потолке ${tuneFor(STEP_MAX).sameSideMax}`);
  }

  /* ── ряд колец различается по уровням ──

     Три состояния на пять уровней, и каждое обязано быть видно в числах:
     доля боковых колец ВНУТРИ серии растёт от нуля к беговым фразам. */
  {
    const вСерии = (step) => {
      const tune = tuneFor(step);
      let боковых = 0;
      let всего = 0;
      for (let seed = 1; seed <= 20; seed++) {
        const obstacles = makeLevel({ durationS: 300, rng: seeded(seed * 17), tune });
        const stars = makeStars({ durationS: 300, obstacles, rng: seeded(seed * 19), tune });
        /* «В передышке» — тем же определением, что в группе «фразы колец»:
           промежуток до следующего препятствия не короче передышки. Своё,
           более грубое определение («ближе половины передышки») я написал
           первым, и оно дало 19.5% боковых там, где их ноль: внутрь серии
           попадали кольца, стоящие в самой широкой её части. */
        const вПередышке = (t) => {
          let prev = null;
          for (const ob of obstacles) {
            if (ob.at > t) return prev === null ? true : ob.at - prev >= tune.breatherS;
            prev = ob.at;
          }
          return true;
        };
        for (const st of stars) {
          if (вПередышке(st.at)) continue;
          всего++;
          if (st.side !== 0) боковых++;
        }
      }
      return всего ? боковых / всего : 0;
    };
    const спокойный = вСерии(0);
    const средний = вСерии(2);
    const беговой = вСерии(STEP_MAX);
    check('на первом уровне боковых колец в серии нет', спокойный === 0,
      `${(спокойный * 100).toFixed(1)}% — требование заказчика от 11 октября`);
    check('на третьем они появляются', средний > спокойный,
      `${(спокойный * 100).toFixed(1)}% → ${(средний * 100).toFixed(1)}%`);
    check('на пятом их ещё больше', беговой > средний,
      `${(средний * 100).toFixed(1)}% → ${(беговой * 100).toFixed(1)}%`);
  }

  /* ── кольца от ступени не зависят ──

     Таблица рекордов бьётся по длине, а не по ступени, и делить её по
     ступеням нельзя: таблица текущей ступени будет пустой. Значит слабая
     связь принимается — но она обязана остаться слабой, иначе рекорды разных
     ступеней перестанут быть сравнимыми молча. */
  {
    const колец = (step) => {
      let n = 0;
      for (let seed = 1; seed <= 20; seed++) {
        const obstacles = makeLevel({ durationS: 300, rng: seeded(seed * 3), tune: tuneFor(step) });
        n += makeStars({ durationS: 300, obstacles, rng: seeded(seed * 11),
          tune: tuneFor(step) }).length;
      }
      return n / 20;
    };
    const ряд = [];
    for (let step = 0; step <= STEP_MAX; step++) ряд.push(колец(step));
    const низ = Math.min(...ряд);
    const верх = Math.max(...ряд);
    check('колец на всех пяти уровнях столько же',
      (верх - низ) / низ < 0.05,
      `${ряд.map((x) => x.toFixed(1)).join(' / ')} — иначе рекорды уровней несравнимы`);
  }
});

group('уклонение', () => {
  const edge = obstacleEdge();
  const full = Math.abs(cameraX(1));

  // Уйти должно быть можно. Край препятствия выражен долей хода камеры именно
  // поэтому: развязать эти числа значит получить препятствие, от которого
  // нельзя уклониться в принципе, и заметить это только на ребёнке.
  check('от препятствия можно уйти', edge < full,
    `край на ${edge.toFixed(2)} м при ходе камеры ${full.toFixed(2)} м`);
  check('но уйти надо заметно, а не качнуться', edge > full * 0.2,
    'иначе достаточно стоять и чуть шевелиться');

  const right = { kind: 'side', side: 1 };
  check('закрыта правая — спасает левая', isSafe(right, { camX: -full }));
  check('стоять посередине не спасает', !isSafe(right, { camX: 0 }));
  check('уйти в закрытую сторону не спасает', !isSafe(right, { camX: full }));

  const left = { kind: 'side', side: -1 };
  check('и симметрично', isSafe(left, { camX: full }) && !isSafe(left, { camX: -full }));

  const duck = { kind: 'duck', side: 0 };
  check('верхнее проходится приседом', isSafe(duck, { camX: 0, crouching: true }));
  check('а смещением вбок — нет', !isSafe(duck, { camX: full, crouching: false }),
    'иначе присед можно было бы не делать вовсе');
});

/* ───────── «не знаю» не вправе обернуться ударом ─────────

   Журнал 14 октября, 928.7 секунды. Присед защёлкнулся на 12.3 секунды —
   настоящий, глубокий: `v` в нём 1.8–2.7 при пороге 0.35, торс 0.13–0.16
   против 0.31 стоя. В середину этих секунд пришёлся боковой телеграф, и
   исполнить его было НЕЧЕМ: пока присед держится, боковое положение не
   обновляется, потому что в такой позе оно недостоверно. Ребёнок получил
   приговор за то, чего игра не дала сделать, — худший класс дефекта проекта.

   Единственный такой случай за всю историю журналов (0 из 48 и 0 из 16 боковых
   препятствий прошлых сессий пришли в приседе), и он задет: 1 из 1.

   Починка не в заморозке и не в пороге приседа. Снять заморозку нельзя —
   вернётся фантомный шаг вбок и тряска, от которой ребёнка укачивало. Отпускать
   присед по таймеру нельзя — ребёнок правда присевший, и верхнее препятствие
   станет задетым незаслуженно. Поэтому приговор ОТКАЗЫВАЕТСЯ судить о том,
   чего игра не знает. */
group('приговор не судит о том, чего не знает', () => {
  const full = Math.abs(cameraX(1));
  const right = { kind: 'side', side: 1 };
  const duck = { kind: 'duck', side: 0 };

  check('в середине поля боковое препятствие задевает — так было и так осталось',
    !isSafe(right, { camX: 0, lateralKnown: true }));
  check('а при замороженном боковом — не задевает',
    isSafe(right, { camX: 0, lateralKnown: false }),
    'судить по значению, про которое игра сама сказала «не знаю», нельзя');

  check('умолчание осталось прежним',
    !isSafe(right, { camX: 0 }),
    'иначе препятствия из tools/frame.html и наборов стали бы судиться иначе');

  check('а уже заработанный уход заморозка не отменяет',
    isSafe(right, { camX: -full, lateralKnown: false })
    && isSafe(right, { camX: -full, lateralKnown: true }),
    'меняется ровно тот случай, где ответа нет');

  /* Присед НЕ становится универсальным щитом: верхнее препятствие судится
     приседом, и заморозка бокового к нему отношения не имеет. */
  check('верхнее препятствие заморозкой не прощается',
    !isSafe(duck, { camX: 0, crouching: false, lateralKnown: false }),
    'иначе достаточно было бы считаться присевшим, чтобы не приседать');
  check('и проходится по-прежнему приседом',
    isSafe(duck, { camX: 0, crouching: true, lateralKnown: false }));

  /* ─── А теперь то же самое через живой трекер: признак обязан доехать ─── */
  const childStand = 0.30;
  const leanTo = (s) => 1 - s / childStand;
  const tr = makeTracker();
  const стоя = run(tr, steady({ scale: childStand }, 10));
  check('стоя боковое положение известно',
    tr.lateralHeld === false && стоя.at(-1).crouch === false);

  // Глубокий присед из журнала, и держится он ДОЛЬШЕ разноса препятствий.
  const присед = run(tr, Array.from({ length: 160 }, () => pose({
    scale: childStand, crouch: 0.6, lean: leanTo(0.15),
  })));
  check('присед из журнала защёлкнулся', присед.at(-1).crouch === true);
  check('и держится дольше, чем разнос препятствий',
    присед.length * 50 > O.minGapS * 1000,
    `${(присед.length * 50 / 1000).toFixed(1)} с против разноса ${O.minGapS} с — ` +
    'ровно поэтому прежнее «заморозка не может накрыть два препятствия» неверно');
  check('боковое положение в нём не обновляется', tr.lateralHeld === true);
  check('и боковое препятствие в этот момент приговора не выносит',
    isSafe(right, { camX: 0, crouching: tr.crouch, lateralKnown: !tr.lateralHeld }));

  // Выпрямился — и всё вернулось: заморозка не залипает.
  const снова = run(tr, steady({ scale: childStand }, 20));
  check('после приседа боковое снова известно',
    tr.lateralHeld === false && снова.at(-1).crouch === false);
  check('и приговор снова выносится',
    !isSafe(right, { camX: 0, lateralKnown: !tr.lateralHeld }),
    'послабление обязано кончиться вместе с приседом');
});

group('звук', () => {
  // Мотивы различаются числом нот, а не только высотой: высоту съедает
  // телефонный динамик и комнатное эхо, а «два» и «три» слышно всегда.
  const m = describe();
  const need = ['left', 'right', 'duck', 'ready', 'warn', 'clear', 'star', 'hit', 'finish'];
  for (const name of need) check(`мотив «${name}» есть`, m[name]?.length > 0);

  check('присед отличается от боковых числом нот',
    m.duck.length !== m.left.length && m.duck.length !== m.right.length,
    `присед ${m.duck.length}, влево ${m.left.length}, вправо ${m.right.length}`);
  check('подтверждение короче предупреждения', m.ready.length < m.warn.length,
    'подтверждение звучит чаще и не должно надоедать');
  check('финиш — самый длинный',
    m.finish.length >= Math.max(...need.map((n) => m[n].length)));

  // Одинаковое число нот у «влево» и «вправо» — так и задумано, их различает
  // направление хода высоты. Но сами мотивы обязаны отличаться.
  check('влево и вправо — разные мотивы',
    JSON.stringify(m.left) !== JSON.stringify(m.right));
  check('влево идёт вниз', m.left[0][0] > m.left[1][0],
    `${m.left[0][0]} → ${m.left[1][0]}`);
  check('вправо идёт вверх', m.right[0][0] < m.right[1][0]);

  // Ноты не должны накладываться сами на себя: следующая начинается не
  // раньше, чем кончилась предыдущая, иначе мотив превращается в аккорд и
  // ритм, которым они и различаются, пропадает.
  for (const [name, notes] of Object.entries(m)) {
    for (let i = 1; i < notes.length; i++) {
      check(`«${name}»: ноты не наезжают`, notes[i][1] >= notes[i - 1][1],
        `нота ${i} начинается в ${notes[i][1]}, предыдущая в ${notes[i - 1][1]}`);
    }
  }

  /* ── Призы подменяют мотив, а не добавляют новый ──

     Словарь звука дефицитный намеренно: новый мотив означал бы новое
     действие. Поэтому приз обязан звучать тем же событием, и у подмены
     столько же ВСТУПЛЕНИЙ, сколько у базового мотива.

     Для сбора кольца это не стиль, а запрет: `starBig` — ровно три ноты, и
     обычное кольцо в три ноты стало бы неотличимо от большого, то есть
     ребёнок потерял бы единственный признак награды. Поэтому «звонкий сбор»
     работает ДЛИТЕЛЬНОСТЬЮ, а не числом нот. */
  check('у сбора кольца есть вариант приза', !!m.starChime);
  check('и в нём столько же нот, сколько в обычном',
    m.starChime.length === m.star.length,
    `${m.starChime?.length} против ${m.star.length}`);
  check('то есть он не путается с большим кольцом',
    m.starChime.length !== m.starBig.length,
    'три ноты — это «большое кольцо», и занимать их нельзя');
  check('а звонче он послезвучием', m.starChime.at(-1)[2] > m.star.at(-1)[2],
    'последняя нота тянется дольше — это и есть «звонче» без новых нот');

  check('у финиша есть вариант приза', !!m.finishFanfare);
  check('фанфара длиннее обычного финиша', m.finishFanfare.length > m.finish.length,
    `${m.finishFanfare?.length} против ${m.finish.length}`);
  /* Длиннее всех — СЕМЕЙСТВО финиша, а не одна фанфара уровня 4: с этапа 6 у
     вершины своя, и она длиннее. Правило же не про конкретный мотив, а про
     то, что длинный звук позволен только финишу: он терминальный, после него
     не решают ничего. */
  {
    const финишные = ['finish', 'finishFanfare', 'finishGold'];
    const прочие = Object.entries(m).filter(([k]) => !финишные.includes(k));
    check('финишные мотивы длиннее всех прочих',
      Math.min(...финишные.map((k) => m[k].length)) > Math.max(...прочие.map(([, v]) => v.length)),
      'длинный звук позволен только финишу — он терминальный');
  }
  check('фанфара идёт вверх',
    m.finishFanfare.every((n, i, a) => i === 0 || n[0] >= a[i - 1][0]),
    'вниз она читалась бы как проигрыш');

  /* Отбор варианта — чистая функция, и проверяется она без звука: Web Audio в
     node нет вовсе, а правило отбора есть. */
  check('без приза играет базовый мотив', motifNameFor('star', {}) === 'star');
  check('с призом — вариант', motifNameFor('star', { chime: true }) === 'starChime');
  check('финиш так же', motifNameFor('finish', { fanfare: true }) === 'finishFanfare');
  check('у события без вариантов приз ничего не меняет',
    motifNameFor('duck', { chime: true, fanfare: true }) === 'duck');
  /* Приза нет — и варианта нет: `MOTIFS[undefined]` даёт undefined, а `play`
     на этом выходит МОЛЧА, то есть сбор кольца потерял бы звук совсем. */
  check('отбор никогда не отдаёт несуществующее имя',
    Object.keys(m).includes(motifNameFor('star', { chime: false })),
    'иначе play() промолчит, и это неотличимо от выключенного звука');

  /* Фанфара ВЕРШИНЫ. Словарь не растёт: это подмена того же события, что и
     фанфара уровня 4, — у одного события может быть несколько вариантов, и
     выбирается ПЕРВЫЙ открытый. */
  check('у вершины своя фанфара', !!m.finishGold);
  check('она длиннее фанфары уровня 4', m.finishGold.length > m.finishFanfare.length,
    `${m.finishGold?.length} против ${m.finishFanfare.length}`);
  check('и остаётся самым длинным мотивом',
    m.finishGold.length >= Math.max(...Object.values(m).map((v) => v.length)));
  check('вершина сильнее обычной фанфары',
    motifNameFor('finish', { fanfare: true, gold: true }) === 'finishGold',
    'взявший вершину уже взял и четвёртый уровень — звучать должна вершина');
  check('а без вершины звучит обычная',
    motifNameFor('finish', { fanfare: true }) === 'finishFanfare');
  check('ноты вершины не наезжают',
    m.finishGold.every((n, i, a) => i === 0 || n[1] >= a[i - 1][1]));
  check('и фанфара вершины идёт вверх',
    m.finishGold.every((n, i, a) => i === 0 || n[0] >= a[i - 1][0]),
    'вниз она читалась бы как проигрыш');

  /* Выключенный в родительском меню звук СИЛЬНЕЕ любого приза. Из node
     проверить исполнением нельзя — Web Audio здесь нет, — поэтому сторож
     текстовый и смотрит на ПОРЯДОК: проверка `sound` обязана стоять до
     отбора варианта. Иначе приз однажды окажется выше настройки взрослого. */
  const audioSrc = readFileSync(join(ROOT, 'js/audio.js'), 'utf8');
  const телоPlay = audioSrc.slice(audioSrc.indexOf('export function play('));
  check('выключенный звук проверяется до отбора варианта',
    телоPlay.indexOf("settings.get('sound')") < телоPlay.indexOf('motifNameFor('),
    'приз не вправе обойти настройку «Звук: выключен»');

  check('для бокового справа звучит «влево»', motifFor({ kind: 'side', side: 1 }) === 'left',
    'закрыта правая сторона — уходить надо влево, и звук говорит именно это');
  check('для бокового слева звучит «вправо»', motifFor({ kind: 'side', side: -1 }) === 'right');
  check('для верхнего звучит присед', motifFor({ kind: 'duck', side: 0 }) === 'duck');
});

group('финиш', () => {
  // Ворота должны появиться раньше, чем до них можно добежать: иначе они
  // возникают из ниоткуда прямо перед носом.
  check('ворота видно заранее', FINISH.visibleS * VIEW.speed <= VIEW.fogDistance,
    `${(FINISH.visibleS * VIEW.speed).toFixed(0)} м при видимости ${VIEW.fogDistance} м`);
  check('ворота не выше стен', FINISH.gateHeight <= 2.6);
  check('перерыв предлагается не слишком поздно', FINISH.restAfterRuns <= 4,
    'ребёнок сам не остановится, и напоминание нужно взрослому');

  /* Длина забега берётся из родительского меню. Верхняя граница поднята до
     двенадцати минут по просьбе заказчика; нижняя держится, чтобы забег не
     кончался раньше, чем встретится первое препятствие. */
  for (const o of OPTIONS.runLength) {
    check(`длина ${o.label} разумна`, o.value >= 120 && o.value <= 720, `${o.value} с`);
    check(`за ${o.label} успевает встретиться препятствие`, o.value > O.firstAtS + O.minGapS,
      'иначе забег кончится раньше, чем начнётся');
  }
});

// ───────────────────────── калибровка ─────────────────────────

/* Стадии кончаются по удержанию, а не по абсолютному времени, поэтому
   кормить их фиксированным числом миллисекунд ненадёжно: часть уходит на
   переход. Кормим, пока автомат не сообщит о событии. */
function feedUntilEvent(cal, opts, clock, maxMs = 20000) {
  const stop = clock.t + maxMs;
  while (clock.t < stop) {
    const r = cal.push(pose(opts), clock.t);
    clock.t += 50;
    if (r.done || r.advanced || r.retry || r.failed) return r;
  }
  return { timeout: true };
}

group('калибровка', () => {
  const cal = makeCalibration();
  const clock = { t: 0 };

  check('первая стадия — нейтраль', cal.stage.id === 'neutral');
  feedUntilEvent(cal, { x: 0.5 }, clock);
  check('после нейтрали просит шагнуть влево', cal.stage.id === 'left', `сейчас ${cal.stage?.id}`);

  feedUntilEvent(cal, { x: 0.5 + 0.09 }, clock); // влево у ребёнка = вправо в кадре
  check('после левой стадии просит вернуться в середину', cal.stage.id === 'center',
    `сейчас ${cal.stage?.id}`);

  feedUntilEvent(cal, { x: 0.5 }, clock);
  check('после середины просит вправо', cal.stage.id === 'right', `сейчас ${cal.stage?.id}`);

  feedUntilEvent(cal, { x: 0.5 - 0.09 }, clock);
  check('после правой просит присесть', cal.stage.id === 'crouch', `сейчас ${cal.stage?.id}`);

  const done = feedUntilEvent(cal, { crouch: 0.6 }, clock);
  check('калибровка завершилась', done.done === true && !!done.result, JSON.stringify(done));

  const r = done.result;
  check('порог бока в разрешённых границах', r.uEnter >= CLAMP.u[0] && r.uEnter <= CLAMP.u[1],
    `uEnter = ${r?.uEnter}`);
  check('порог приседа в разрешённых границах', r.vEnter >= CLAMP.v[0] && r.vEnter <= CLAMP.v[1],
    `vEnter = ${r?.vEnter}`);
  check('порог выхода ниже порога входа', r.uExit < r.uEnter && r.vExit < r.vEnter);
  check('нейтраль запомнена', r.neutralX > 0 && r.neutralShoulderY > 0 && r.neutralHipY > 0);
  check('длина торса стоя запомнена', r.S0 > 0);

  // Размах вдвое больше обычного не должен сделать жест недостижимым: в азарте
  // ребёнок показывает рекорд, а играть потом будет обычными движениями.
  const wild = makeCalibration();
  const c2 = { t: 0 };
  feedUntilEvent(wild, { x: 0.5 }, c2);
  feedUntilEvent(wild, { x: 0.5 + 0.30 }, c2);
  feedUntilEvent(wild, { x: 0.5 }, c2);
  feedUntilEvent(wild, { x: 0.5 - 0.30 }, c2);
  const wildDone = feedUntilEvent(wild, { crouch: 1.5 }, c2);
  check('огромный размах зажимается сверху',
    wildDone.result && wildDone.result.uEnter <= CLAMP.u[1] && wildDone.result.vEnter <= CLAMP.v[1],
    `uEnter = ${wildDone.result?.uEnter}, vEnter = ${wildDone.result?.vEnter}`);

  // Ребёнок не пошевелился — просим повторить, но не запираем навсегда.
  const lazy = makeCalibration();
  const c3 = { t: 0 };
  feedUntilEvent(lazy, { x: 0.5 }, c3);
  const retry = feedUntilEvent(lazy, { x: 0.5 }, c3);
  check('неподвижность просит повторить', retry.retry === true, JSON.stringify(retry));
  feedUntilEvent(lazy, { x: 0.5 }, c3);
  const gaveUp = feedUntilEvent(lazy, { x: 0.5 }, c3);
  check('после трёх попыток идёт дальше, а не запирает',
    gaveUp.failed?.id === 'left' && lazy.stage?.id !== 'left',
    'застрять на экране, с которого нет выхода, хуже, чем неидеальный порог');
});

/* ───────────────── калибровка сдаётся ─────────────────

   Эта группа — регрессия на падение у ребёнка 6 октября. Ветка «три попытки и
   идём дальше» двигала стадию, но не отдавала ни `done`, ни `result`: на
   последней стадии следующий кадр получал { done: true, result: null },
   train.js читал `uEnter` у null и падал — 1478 раз подряд, 133 секунды
   замершего экрана, забег брошен. Поэтому здесь проверяется не наличие поля, а
   что калибровка ВСЕГДА заканчивается годными числами. */
group('калибровка сдаётся', () => {
  // Довести до приседа и не приседать: три попытки — и это конец калибровки.
  const cal = makeCalibration();
  const clock = { t: 0 };
  feedUntilEvent(cal, { x: 0.5 }, clock);
  feedUntilEvent(cal, { x: 0.5 + 0.09 }, clock);
  feedUntilEvent(cal, { x: 0.5 }, clock);
  feedUntilEvent(cal, { x: 0.5 - 0.09 }, clock);
  check('дошли до приседа', cal.stage?.id === 'crouch', `сейчас ${cal.stage?.id}`);

  let last = null;
  for (let i = 0; i < 3; i++) last = feedUntilEvent(cal, { crouch: 0 }, clock);

  check('сдавшийся присед завершает калибровку', last.done === true, JSON.stringify(last));
  check('и отдаёт РЕЗУЛЬТАТ, а не null', !!last.result,
    'именно отсутствие result роняло приложение каждый кадр');
  check('провал назван по провалившейся стадии', last.failed?.id === 'crouch',
    `failed = ${last.failed?.id}`);
  const got = last.result || {};
  for (const k of ['uEnter', 'uExit', 'vEnter', 'vExit', 'S0', 'panSpan']) {
    check(`${k} — годное число`, Number.isFinite(got[k]) && got[k] > 0, `${k} = ${got[k]}`);
  }
  check('повторный push после конца не ломается и отдаёт тот же результат',
    cal.push(pose({}), clock.t + 50).result === last.result);

  // Сдалась стадия ПОСЕРЕДИНЕ — следующая обязана получить свои три попытки.
  const mid = makeCalibration();
  const c4 = { t: 0 };
  feedUntilEvent(mid, { x: 0.5 }, c4);
  let step = null;
  for (let i = 0; i < 3; i++) step = feedUntilEvent(mid, { x: 0.5 }, c4); // не шагает
  check('провал середины сообщает о переходе', step.advanced === true, JSON.stringify(step));
  check('и называет следующую стадию', step.stage?.id === 'center', `stage = ${step.stage?.id}`);
  check('у следующей стадии снова три попытки, а не одна', mid.tries === 0,
    'без сброса tries следующая стадия сдавалась с первого раза — так в журнале и вышло');
  const after = feedUntilEvent(mid, { x: 0.95 }, c4); // в середину не возвращается
  check('следующая стадия действительно просит повторить, а не сдаётся сразу',
    after.retry === true, JSON.stringify(after));
});

/* ───────────────── нейтраль мерится стоянием ─────────────────

   Стадия нейтрали копила СУММУ и делила на число отсчётов, то есть считала
   среднее по всем пяти секундам — а первые из них игрок идёт от телефона, куда
   только что подходил нажать «Дальше». В журнале 9 октября эта дорога видна
   прямо: на стадии штатива торс растёт 0.18 → 0.27 → 0.33 → 0.46 → 0.60, и
   сразу за ней начинается нейтраль. Среднее дорогу впитывает, медиана — нет.

   ЧТО ИМЕННО ЭТИМ ПОЧИНЕНО, и это важнее самой правки.

   Починен `neutralX`, и вот у него запаса нет вовсе: он идёт прямо в воротца
   «вернись в середину» (допуск CENTER_TOL 0.20 длины торса) и в геометрию цели
   на экране. Смаз в 0.03 доли высоты кадра при торсе 0.30 — это 0.10 в длинах
   торса, половина допуска воротец. Отсюда и жалоба «зоны калибровки
   сместились», и перекос размаха left 2.1 / right 0.68: размах меряется от
   нейтрали.

   А вот непроходимый забег 9 октября медиана НЕ лечит, и делать вид, что
   лечит, нельзя. Потолок присутствия — это S0 × 1.80, то есть у него почти
   двукратный запас, и разницу между средним и медианой он проглатывает.
   Арифметика: потолок падает ниже игрока при `среднее < стояние / 1.80`, а
   среднее не меньше, чем доля стояния × стояние, — значит фатально только
   когда игрок простоял меньше 0.556 стадии. Медиана же равна стоянию ровно
   когда он простоял больше половины. Остаётся щель 0.50–0.556, да и в ней
   нужно, чтобы остальные отсчёты были почти нулевыми. В журнале было не это:
   игрок всю нейтраль стоял ДАЛЬШЕ, чем потом играл (0.20 против 0.37), и
   медиана такой выборки — та же 0.20. Непроходимость снял пол потолка, он
   один; проверено здесь же, последним блоком.

   Порога «пошевелился / стоит» не появилось намеренно: его пришлось бы
   подбирать под шум распознавания, а не простоявший своё игрок остался бы
   вообще без нейтрали. */
group('нейтраль мерится стоянием', () => {
  const WALK = 40;   // 2.0 с дороги при шаге 50 мс
  const STAND = 70;  // 3.5 с стояния — больше половины пятисекундной стадии

  /** Нейтраль с дорогой в начале: отходит от телефона и смещается к середине. */
  function walkThenStand() {
    const cal = makeCalibration();
    const clock = { t: 0 };
    const feed = (opts) => { cal.push(pose(opts), clock.t); clock.t += 50; };
    for (let i = 0; i < WALK; i++) {
      const k = i / (WALK - 1);
      feed({ scale: 0.60 - 0.30 * k, x: 0.35 + 0.15 * k });
    }
    for (let i = 0; i < STAND && cal.stage?.id === 'neutral'; i++) {
      feed({ scale: 0.30, x: 0.50 });
    }
    return { cal, clock };
  }

  const { cal, clock } = walkThenStand();
  check('нейтраль закончилась и калибровка пошла дальше', cal.stage?.id === 'left',
    `сейчас ${cal.stage?.id}`);

  /* Остальные стадии — обычным образом, чтобы добраться до результата. Шаг
     взят с запасом (±0.20 против нужных 0.25 длины торса при S 0.30): этой
     группе надо проверить нейтраль, а не достижимость боков, и до починки
     смазанная нейтраль сама делала одну из сторон недобираемой. */
  feedUntilEvent(cal, { scale: 0.30, x: 0.50 + 0.20 }, clock);
  feedUntilEvent(cal, { scale: 0.30, x: 0.50 }, clock);
  feedUntilEvent(cal, { scale: 0.30, x: 0.50 - 0.20 }, clock);
  const done = feedUntilEvent(cal, { scale: 0.30, x: 0.50, crouch: 0.6 }, clock);
  const r = done.result || {};

  check('калибровка с дорогой всё равно завершилась', done.done === true && !!done.result,
    JSON.stringify(done));
  /* Стоял игрок на 0.30, шёл с 0.60. Среднее по стадии даёт 0.36 — именно эти
     шесть сотых и отняли забег, потому что потолок от них в 1.8 раза дальше. */
  check('S0 — это стояние, а не среднее по дороге', Math.abs(r.S0 - 0.30) < 0.015,
    `S0 = ${r.S0}, стоял игрок на 0.30 (среднее по стадии дало бы 0.36)`);
  /* Нейтраль — то место, где эта правка и важна: 0.47 вместо 0.50 при торсе
     0.30 — это 0.10 в длинах торса, половина допуска воротец CENTER_TOL 0.20.
     У потолка присутствия запас почти двукратный, у воротец запаса нет. */
  check('нейтраль по X — тоже стояние', Math.abs(r.neutralX - 0.50) < 0.01,
    `neutralX = ${r.neutralX}, стоял игрок на 0.50 (среднее дало бы 0.47)`);

  /* Пол потолка из группы «короткая S0 не отнимает забег» — второй слой, а не
     замена этому: с честной S0 потолок обязан встать от неё, а не от пола. */
  check('честная S0 поднимает потолок выше пола', r.S0 * S.scaleRelMax > S.scaleCeilMin,
    `S0 ${r.S0} × ${S.scaleRelMax} против пола ${S.scaleCeilMin}`);

  /* А тот, кто не стоял вовсе, обязан получить годные числа: калибровка
     заканчивается результатом на ЛЮБОМ пути — на этом она уже падала у
     ребёнка 6 октября, 1478 ошибок подряд. */
  const never = makeCalibration();
  const c2 = { t: 0 };
  for (let i = 0; i < 400 && never.stage?.id === 'neutral'; i++) {
    never.push(pose({ scale: 0.25 + 0.3 * Math.abs(Math.sin(i / 7)), x: 0.3 + 0.3 * Math.abs(Math.sin(i / 5)) }), c2.t);
    c2.t += 50;
  }
  check('непрерывно двигавшийся игрок всё равно прошёл нейтраль',
    never.stage?.id !== 'neutral', `сейчас ${never.stage?.id}`);
  /* Проверка не лишняя: медиана по непостоянной выборке — всё равно число из
     этой выборки, а значит в хранилище попадёт неправдоподобная S0, и дальше
     за забег отвечает только пол потолка. */
  feedUntilEvent(never, { x: 0.5 + 0.30 }, c2);
  feedUntilEvent(never, { x: 0.5 }, c2);
  feedUntilEvent(never, { x: 0.5 - 0.30 }, c2);
  const wild = feedUntilEvent(never, { crouch: 0.9 }, c2);
  for (const k of ['S0', 'neutralX', 'neutralShoulderY', 'neutralHipY']) {
    check(`${k} у непостоявшего — годное число`,
      Number.isFinite(wild.result?.[k]) && wild.result[k] > 0, `${k} = ${wild.result?.[k]}`);
  }

  /* ─── а теперь прямо: журнал 9 октября медиана НЕ лечит ───

     Игрок всю нейтраль стоял на своём месте для калибровки — то есть ДАЛЬШЕ,
     чем потом играл. Выборка однородная, медиана равна среднему, S0 остаётся
     короткой, и забег спасает только пол потолка. Это и есть разделение труда
     между двумя слоями, и записано оно проверкой, а не комментарием: тот, кто
     однажды решит, что медианы достаточно, и снимет пол, увидит здесь провал. */
  const away = makeCalibration();
  const c3 = { t: 0 };
  while (away.stage?.id === 'neutral' && c3.t < 20000) {
    away.push(pose({ scale: 0.20, x: 0.5 }), c3.t);
    c3.t += 50;
  }
  feedUntilEvent(away, { scale: 0.20, x: 0.5 + 0.09 }, c3);
  feedUntilEvent(away, { scale: 0.20, x: 0.5 }, c3);
  feedUntilEvent(away, { scale: 0.20, x: 0.5 - 0.09 }, c3);
  const awayDone = feedUntilEvent(away, { scale: 0.20, x: 0.5, crouch: 0.6 }, c3);
  const S0away = awayDone.result?.S0;
  check('стоял далеко — медиана честно отдаёт короткую S0',
    Math.abs(S0away - 0.20) < 0.01, `S0 = ${S0away}`);
  check('и относительный потолок от неё ниже игрока', S0away * S.scaleRelMax < 0.37,
    `${S0away} × ${S.scaleRelMax} = ${(S0away * S.scaleRelMax).toFixed(2)}, а игрок стоя даёт 0.37`);

  const trAway = makeTracker(awayDone.result);
  run(trAway, steady({ scale: 0.20 }, 5));
  check('а забег всё равно проходим — это сделал ПОЛ, не медиана',
    run(trAway, steady({ scale: 0.37 }, 3)).pop().why === null,
    'снимешь scaleCeilMin — вернётся непроходимый забег 9 октября');
});

/* ───────────────── калибровка объясняет себя ─────────────────

   Цель в окошке камеры появилась потому, что калибровка не говорила, чего
   хочет: ни расстояния, ни того, куда шагнуть, ни насколько присесть.
   Семилетке это и не сказать словами — он смотрит на телевизор через комнату.
   Здесь проверяется арифметика цели, а не её вид. */
group('калибровка объясняет себя', () => {
  const NEED_U = 0.25;   // MIN_EXCURSION.u, см. js/calibrate.js
  const NEED_V = 0.20;

  /* ЕДИНИЦЫ КАДРА. Цель отдаётся в долях ШИРИНЫ, а считается из величин в
     долях ВЫСОТЫ. Проверяется на трёх формах кадра: ровно на этой подмене игра
     уже стояла однажды — отношение плеч к торсу считалось 0.48 вместо 0.86. */
  for (const aspect of [1, 16 / 9, 20 / 9]) {
    const a = aspect.toFixed(2);
    const cal = makeCalibration({ aspect });
    const clock = { t: 0 };
    feedUntilEvent(cal, { x: 0.5, scale: 0.2 }, clock);
    const r = cal.push(pose({ x: 0.5, scale: 0.2 }), clock.t);
    const t = r.target;
    check(`кадр ${a}: цель бокового шага есть`, t?.kind === 'side' && t.side === -1,
      JSON.stringify(t));
    // Обратный пересчёт: цель, переведённая назад в единицы высоты, обязана
    // стоять ровно на пороге размаха. Пропущенное деление на aspect здесь и
    // ловится — иначе требование растёт вместе с формой кадра.
    const u = S.mirrorX * (t.x * aspect - 0.5 * aspect) / 0.2;
    check(`кадр ${a}: цель стоит ровно на пороге размаха`,
      Math.abs(Math.abs(u) - NEED_U) < 1e-6, `получилось ${u}`);
    check(`кадр ${a}: цель влево после зеркала уходит влево`, (1 - t.x) < 0.5,
      `зеркальная цель ${(1 - t.x).toFixed(3)}`);

    // Ребёнок, вставший в зону, порог берёт; на полпути — не берёт.
    const d = t.x - 0.5;
    const inside = cal.push(pose({ x: 0.5 + d * 1.1, scale: 0.2 }), clock.t + 50);
    const halfway = makeCalibration({ aspect });
    const c5 = { t: 0 };
    feedUntilEvent(halfway, { x: 0.5, scale: 0.2 }, c5);
    const short = halfway.push(pose({ x: 0.5 + d * 0.5, scale: 0.2 }), c5.t);
    check(`кадр ${a}: в зоне порог взят`, inside.target.reached === true);
    check(`кадр ${a}: на полпути не взят`, short.target.reached === false);
  }

  // Цель приходит на КАЖДОМ кадре, включая кадры без позы: иначе зона мигает.
  const cal = makeCalibration({ aspect: 16 / 9 });
  const clock = { t: 0 };
  check('без позы цель всё равно есть', !!cal.push(null, 0).target,
    'иначе зона исчезает ровно тогда, когда ребёнок вышел её искать');
  feedUntilEvent(cal, { x: 0.5 }, clock);
  const early = cal.push(pose({ x: 0.5 }), clock.t);
  const later = cal.push(pose({ x: 0.5 }), clock.t + 1000);
  check('заливка цели растёт по мере выдержки', later.target.fill > early.target.fill,
    `${early.target.fill} → ${later.target.fill}`);

  // Присед: цель — линия ниже плеч, и уйти под неё означает взять порог.
  const low = makeCalibration({ aspect: 16 / 9 });
  const c3 = { t: 0 };
  feedUntilEvent(low, { x: 0.5 }, c3);
  feedUntilEvent(low, { x: 0.5 + 0.09 }, c3);
  feedUntilEvent(low, { x: 0.5 }, c3);
  feedUntilEvent(low, { x: 0.5 - 0.09 }, c3);
  const standing = low.push(pose({ x: 0.5 }), c3.t);
  check('цель приседа — линия по высоте', standing.target?.kind === 'crouch',
    JSON.stringify(standing.target));
  check('линия ниже плеч стоящего', standing.target.y > 0.45,
    `линия ${standing.target.y}, плечи стоящего 0.45`);
  check('линия ровно на пороге приседа',
    Math.abs((standing.target.y - 0.45) / 0.2 - NEED_V) < 1e-6, `${standing.target.y}`);
  check('стоя порог не взят', standing.target.reached === false);
  const squat = low.push(pose({ x: 0.5, crouch: 0.3 }), c3.t + 50);
  check('присев — взят', squat.target.reached === true);

  // Воротца «вернись в середину»: зона вокруг нейтрали, и порог обратный.
  const gate = makeCalibration({ aspect: 16 / 9 });
  const c6 = { t: 0 };
  feedUntilEvent(gate, { x: 0.5 }, c6);
  feedUntilEvent(gate, { x: 0.5 + 0.09 }, c6);
  const center = gate.push(pose({ x: 0.5 }), c6.t);
  check('цель середины — зона вокруг нейтрали',
    center.target?.side === 0 && center.target.half > 0, JSON.stringify(center.target));
  // Допуск 1e-6, а не ноль: точки приходят Float32Array — и от камеры тоже.
  check('середина центрирована на нейтрали', Math.abs(center.target.x - 0.5) < 1e-6,
    `середина оказалась на ${center.target.x}`);
  check('стоя в середине порог взят', center.target.reached === true);
  const away = makeCalibration({ aspect: 16 / 9 });
  const c7 = { t: 0 };
  feedUntilEvent(away, { x: 0.5 }, c7);
  feedUntilEvent(away, { x: 0.5 + 0.09 }, c7);
  check('стоя в стороне — не взят',
    away.push(pose({ x: 0.5 + 0.09 }), c7.t).target.reached === false,
    'иначе воротца пропускают того, кто остался сбоку, — и правый замер снова врёт');

  // Рамка «куда встать» судит расстояние той же функцией, что экран штатива.
  check('далёкого ребёнка рамка браковала бы',
    makeCalibration({ aspect: 16 / 9 }).push(pose({ scale: 0.1 }), 0).target.fit === false);
  check('стоящего как надо — принимает',
    makeCalibration({ aspect: 16 / 9 }).push(pose({ scale: 0.3 }), 0).target.fit === true);
});

/* ───────────────── ширина игрового поля ─────────────────

   Поле измеряется в размахе ИГРОКА, а не в длинах торса. По журналу первого
   забега ребёнка шаг взрослого даёт ≈0.48 единицы u, шаг ребёнка ≈0.34, и
   ребёнку нужно вдвое больше шагов на то же решение: уйти от препятствия за
   2 шага вместо 1, из края в край за 4–5 вместо 2–3. */
group('ширина поля', () => {
  check('без калибровки поле прежней ширины', panSpanOf(null) === 1,
    'иначе синтетика и первый запуск поедут иначе, чем проверено');
  check('размах взрослого поле не меняет',
    Math.abs(panSpanOf({ excursion: { left: 0.98, right: 1.00 } }) - 0.98) < 1e-9,
    'замерено 0.98 и 1.00 — сегодняшнее поведение обязано сохраниться точно');
  check('узкий размах усиливает не больше чем вдвое',
    panSpanOf({ excursion: { left: 0.40, right: 1.58 } }) === 0.5,
    'замер ребёнка 0.40; при большем усилении он жил бы у края поля');
  check('размах напоказ поле не расширяет',
    panSpanOf({ excursion: { left: 2.0, right: 2.5 } }) === 1.2);
  check('берётся слабая сторона, а не сильная',
    panSpanOf({ excursion: { left: 0.6, right: 1.5 } }) === 0.6,
    'иначе один удачный шаг решает за обе стороны');
  check('готовый panSpan берётся как есть', panSpanOf({ panSpan: 0.75 }) === 0.75);
  check('НЕизмеренный размах поле не трогает',
    panSpanOf({ excursion: { left: 0.02, right: 1.0 } }) === 1,
    'размах ниже порога — это сдавшаяся стадия, а не узкий размах: усиливать нечего');
  check('испорченная запись не становится делителем',
    panSpanOf({ panSpan: 0 }) === 1 && panSpanOf({ panSpan: NaN }) === 1,
    'ноль или NaN в делителе увёл бы панораму в Infinity навсегда и молча');
});

/* ───────────────── порядок маляра ─────────────────

   Кольцо просвечивало сквозь препятствие: кольца рисовались одним проходом
   после препятствий, а плита видна с 10 м при кольцах до 30 м. Заметил
   заказчик. Здесь проверяется и арифметика глубины, и настоящий порядок
   заливок — через поддельный контекст, потому что порядок и есть дефект. */
group('порядок маляра', () => {
  const ob = (at, extra = {}) => ({ at, kind: 'side', side: 1, ...extra });

  check('далёкое препятствие не рисуется', obstacleDepth(ob(10), 10 - O.signalS - 0.1) === null);
  check('пройденное не рисуется', obstacleDepth(ob(10, { passed: true }), 9) === null);
  check('уехавшее за спину не рисуется', obstacleDepth(ob(10), 10.5) === null,
    'у него отрицательная глубина, и проекция залила бы экран целиком');
  check('в окне телеграфа глубина — у самой дымки',
    Math.abs(obstacleDepth(ob(10), 10 - (O.signalS + O.visibleS) / 2) - VIEW.fogDistance * 0.92) < 1e-9);
  const close = obstacleDepth(ob(10), 10 - 1.5);
  check('ближе окна телеграфа глубина — это сама плита',
    Math.abs(close - 1.5 * VIEW.speed) < 1e-9, `глубина ${close}`);

  let prev = Infinity;
  let mono = true;
  for (let dt = O.visibleS; dt > 0.5; dt -= 0.1) {
    const d = obstacleDepth(ob(10), 10 - dt);
    if (d != null) { if (d > prev) mono = false; prev = d; }
  }
  check('глубина убывает по мере приближения', mono);

  check('разрез — по самому близкому', nearestObstacleDepth([ob(16), ob(10)], 9) === 2);
  check('без препятствий разреза нет', nearestObstacleDepth([], 9) === Infinity);

  // Настоящий порядок заливок. Контекст поддельный: нужен не рисунок, а
  // последовательность, в которой он кладётся.
  const recorder = painter;   // общий поддельный холст, см. выше

  const order = (starZ) => {
    const { canvas, fills } = recorder();
    const view = createView(canvas);
    view.render({
      u: 0, v: 0, travel: 0, elapsed: 0,
      obstacles: [ob(1.5)],            // плита на 3 м
      stars: [{ x: 0, z: starZ }],
    });
    return { ring: fills.indexOf(THEME.greenHill.star), plate: fills.indexOf(THEME.greenHill.block) };
  };

  const far = order(12);
  check('кольцо и плита вообще нарисованы', far.ring >= 0 && far.plate >= 0, JSON.stringify(far));
  check('кольцо ЗА плитой уходит под неё', far.ring < far.plate,
    `кольцо ${far.ring}, плита ${far.plate} — ровно этот дефект заметил заказчик`);

  const near = order(1.2);
  check('кольцо ПЕРЕД плитой остаётся поверх', near.ring > near.plate,
    `кольцо ${near.ring}, плита ${near.plate} — иначе кольцо теряется там, где важнее всего`);

  /* ─── пятно под кольцом ───

     Пятно лежит на полу и обязано ехать тем же проходом, что его кольцо.
     Нарисуй его вместе с полом — и препятствие, стоящее ДАЛЬШЕ ближнего
     кольца, накрыло бы пятно, которое должно быть перед ним. Это ровно тот
     класс дефекта, из-за которого проходов стало два. */
  const C = THEME.greenHill;
  const withShadow = (starZ, extra = {}) => {
    const { canvas, fills } = recorder();
    createView(canvas).render({
      u: 0, v: 0, travel: 0, elapsed: 0,
      obstacles: [ob(1.5)],
      stars: [{ x: 0, z: starZ, ...extra }],
    });
    return {
      fills,
      shadow: fills.indexOf(C.shadow),
      ring: fills.indexOf(C.star),
      plate: fills.indexOf(C.block),
    };
  };

  const sNear = withShadow(1.2);
  check('пятно под кольцом нарисовано', sNear.shadow >= 0, JSON.stringify(sNear.fills.length));
  check('пятно кладётся вплотную перед своим кольцом', sNear.ring - sNear.shadow === 1,
    `пятно ${sNear.shadow}, кольцо ${sNear.ring}`);
  check('у ближнего кольца пятно поверх плиты', sNear.shadow > sNear.plate,
    `пятно ${sNear.shadow}, плита ${sNear.plate}`);

  const sFar = withShadow(12);
  check('у дальнего кольца пятно уходит под плиту', sFar.shadow < sFar.plate,
    `пятно ${sFar.shadow}, плита ${sFar.plate}`);

  /* У собранного кольца пятна нет: оно подпрыгивает и исчезает, а пятно
     осталось бы висеть на полу сиротой. */
  const taken = withShadow(1.2, { taken: true, takenAtS: 0 });
  check('у собранного кольца пятна нет', taken.shadow === -1,
    'иначе на полу остаётся пятно без кольца');

  /* Светлота пятна проверяется не здесь, а в группе «тема»: она про палитру, а
     не про порядок, и обязана идти по КАЖДОЙ зоне. Здесь остаётся только
     порядок заливок. */

  /* Пятно — тень, а не площадка: заметно меньше того радиуса, в котором
     кольцо собирается. Иначе ребёнок станет вставать НА пятно вместо того,
     чтобы вести к кольцу взгляд. */
  check('пятно меньше радиуса сбора',
    VIEW.starShadowM < VIEW.starReach * VIEW.corridorWidth / 2,
    `${VIEW.starShadowM} против ${(VIEW.starReach * VIEW.corridorWidth / 2).toFixed(2)} м`);

  /* ─── три полосы глубины у пола ───

     Третья полоса не стоит ни одной лишней заливки: меняется только выбор
     цвета в том же цикле шахматки. Проверяется, что она действительно
     появляется в кадре и что светлота идёт лестницей — порядок тут важнее
     самих цветов, по нему и видно, что дальше. */
  check('средняя полоса пола в кадре есть', sFar.fills.includes(C.floorMid),
    'иначе полос по-прежнему две, и правка ничего не изменила');
  // Лестница светлоты — в группе «тема», по каждой зоне.
});

/* ───────────────── небо не красит невидимое ─────────────────

   Замерено на телефоне: до появления арта кадр шёл 46–47 fps, с артом — 38–39,
   обе полки ровные все 400 секунд. То есть арт стоит около 5 мс на кадр, а
   `draw50` при этом показывает 0 мс: он мерит время вызовов Canvas2D на CPU,
   то есть постановку работы в очередь, и растеризацию не видит вовсе.

   Куда уходили эти миллисекунды, видно из геометрии. Растр неба 1024×576 на
   кадре 1280×720 кладётся как dh = 720, dy = 0 — то есть РОВНО во весь кадр. А
   перед ним drawSky заливал весь кадр (1.00 экрана) и верхнюю полосу
   (0.30 экрана). Обе заливки растр закрывал целиком: 1.3 экранных заливки на
   каждом кадре красили пиксели, которых не видел никто.

   Поэтому заливка идёт по ФАКТИЧЕСКОЙ геометрии, а не по признаку «растр
   есть». Разница не косметическая: dy зависит от наклона взгляда, в приседе
   горизонт уезжает на pitchPx, и прореха там действительно появляется. */
/* ───────────────── кубок ─────────────────

   Уровень НЕ хранится: он вычисляется из копилки. Значит проверять надо ровно
   одно — что вычисление монотонно и на границах не врёт. Список открытого при
   большей копилке обязан ВКЛЮЧАТЬ список при меньшей: копилка растёт и отката
   не имеет, и приз, пропавший от прибавки колец, — худшее, что здесь может
   случиться с ребёнком. */
group('кубок', () => {
  check('двенадцать ступеней', TROPHY.length === TOP_LEVEL, `${TROPHY.length}`);
  check('шаг сотня', STEP_RINGS === 100, `${STEP_RINGS}`);

  // Порог ступени — её номер, умноженный на шаг. Проверяется формулой, а не
  // списком: список был бы второй копией таблицы.
  TROPHY.forEach((row, i) => {
    check(`ступень ${i + 1}: порог ${(i + 1) * STEP_RINGS}`,
      row.at === (i + 1) * STEP_RINGS, `${row.at}`);
    check(`ступень ${i + 1}: есть цвет`, /^#[0-9a-f]{6}$/.test(row.color || ''), row.color);
    check(`ступень ${i + 1}: есть имя`, prizeName(row).length > 0);
  });

  // Миры стоят на каждом третьем уровне, вершина — не мир.
  const миры = TROPHY.filter((r) => r.kind === 'world').map((r) => r.at);
  check('миры на 300, 600, 900', String(миры) === '300,600,900', String(миры));

  // Границы. Именно здесь живут все ошибки на единицу.
  for (const [bank, lv] of [[0, 0], [1, 0], [99, 0], [100, 1], [199, 1], [200, 2],
                            [1199, 11], [1200, 12], [5000, 12], [100000, 12]]) {
    check(`копилка ${bank} → уровень ${lv}`, levelAt(bank) === lv, `${levelAt(bank)}`);
  }
  /* Мусор вместо числа даёт нулевой уровень, а не NaN. Копилка читается из
     localStorage, и один испорченный профиль не вправе уронить кубок. */
  for (const bad of [NaN, Infinity, -5, null, undefined, '300', {}]) {
    check(`мусорная копилка ${String(bad)} → уровень 0`, levelAt(bad) === 0, `${levelAt(bad)}`);
  }

  /* Монотонность открытого — главная проверка этой группы. */
  let прошлый = unlockedAt(0);
  for (let bank = 50; bank <= 1500; bank += 50) {
    const нынешний = unlockedAt(bank);
    for (const [k, v] of Object.entries(прошлый)) {
      if (k === 'worlds') {
        for (const w of v) {
          check(`копилка ${bank}: мир ${w} не отобран`, нынешний.worlds.includes(w));
        }
      } else if (v) {
        check(`копилка ${bank}: приз ${k} не отобран`, нынешний[k] === true);
      }
    }
    прошлый = нынешний;
  }

  check('у нового игрока открыт только первый мир',
    String(worldsAt(0)) === 'hills', String(worldsAt(0)));
  check('и на 900 открыты все четыре', worldsAt(900).length === 4, String(worldsAt(900)));
  check('искры открываются ровно на сотне',
    unlockedAt(99).sparks === false && unlockedAt(100).sparks === true);

  check('на вершине следующего уровня нет', nextAt(1200) === null);
  check('и выше вершины тоже нет', nextAt(9999) === null);
  const n0 = nextAt(0);
  check('у нового игрока следующий — первый уровень',
    n0 && n0.level === 1 && n0.at === 100 && n0.left === 100, JSON.stringify(n0));
  check('остаток считается от копилки', nextAt(150)?.left === 50, `${nextAt(150)?.left}`);

  /* Имя приза-мира встаёт в ЧУЖУЮ строку, и строку эту читает ребёнок с
     дивана. «Следующий: Мир: Подводная долина» и «Открылось: Мир: Ледяные
     горы» — двоеточие в двоеточии; обе строки собираются подстановкой, и
     чинить их по отдельности значило бы завести второе правило именования. */
  check('приз-мир называется строчным словом и в кавычках',
    prizeName(TROPHY[2]) === 'мир «Ледяные горы»', prizeName(TROPHY[2]));
  check('и в строке «следующего» двоеточие не удваивается',
    !/Следующий: Мир:/.test(`Следующий: ${nextAt(250).name}`), nextAt(250).name);
  check('а косметика остаётся просто именем', prizeName(TROPHY[0]) === 'Искры',
    prizeName(TROPHY[0]));

  /* Светлота цветов кубка строго возрастает — кубок читается как
     «наливается» даже когда Miracast съел цветность. Проверяется той же
     функцией, что и палитра коридора, и с зазором: слипшиеся по светлоте
     полосы на телевизоре неразличимы, хотя формально «возрастают». */
  let прошлая = -1;
  for (const row of TROPHY) {
    const l = luminance(row.color);
    check(`${row.id}: светлее предыдущей полосы минимум на 0.04`, l - прошлая >= 0.04,
      `${l.toFixed(4)} после ${прошлая.toFixed(4)}`);
    прошлая = l;
  }

  /* Миры и зоны. Мир со СОБРАННЫМ артом обязан иметь ровно три существующие
     зоны; мир без арта честно говорит это полем zones: null, а не пустым
     списком — пустой список неотличим от забытого. */
  check('четыре мира', Object.keys(WORLDS).length === 4, String(Object.keys(WORLDS)));
  check('первый мир собран', worldReady('hills'));
  for (const [id, w] of Object.entries(WORLDS)) {
    check(`мир ${id}: есть имя`, typeof w.name === 'string' && w.name.length > 0);
    if (!worldReady(id)) continue;
    check(`мир ${id}: ровно три зоны`, w.zones.length === 3, String(w.zones));
    for (const z of w.zones) check(`мир ${id}: зона ${z} есть в THEME`, !!THEME[z]);
  }

  /* Обратная сторона: зона из THEME, не попавшая ни в один мир, не покажется
     ребёнку никогда, а палитру её при этом проверяет группа «тема» — то есть
     мёртвый код выглядел бы живым. Сличение двустороннее, как у документации. */
  const вМирах = new Set(Object.values(WORLDS).flatMap((w) => w.zones || []));
  for (const z of Object.keys(THEME)) {
    check(`зона ${z} принадлежит какому-то миру`, вМирах.has(z));
  }

  /* Несобранный и мусорный мир отдают зоны первого — молча. Экран выбора может
     и обязан показать «скоро», но отрисовка кадра не вправе получить undefined
     вместо имени зоны. */
  /* `'ice'` из этого списка УБРАН: мир собран с этапа 3, и его зоны теперь
     настоящие. Несобранные миры в проверке остались — их ещё два. */
  for (const bad of ['нет такого', '', null, undefined, 42]) {
    check(`мир ${String(bad)} отдаёт три зоны первого мира`,
      String(zonesOf(bad)) === String(WORLDS.hills.zones), String(zonesOf(bad)));
  }
  check('zoneAt без мира берёт первый', zoneAt(0, 300) === WORLDS.hills.zones[0]);
  check('zoneAt делит забег на три', zoneAt(299, 300, 'hills') === WORLDS.hills.zones[2]);

  /* Мир, который выбрали, но не открыли, — забег идёт в первый. Проверяется
     тут, а не в оболочке: правило чистое, и хранилища ему не нужно. */
  const доступен = (bank, world) => worldsAt(bank).includes(world) && worldReady(world);
  check('невзятый мир недоступен', !доступен(0, 'ice'),
    'копилки на него не хватило — значит и показывать его нечего');
  check('взятый И собранный мир доступен', доступен(300, 'ice'),
    'с этапа 3 ледяной мир собран, и на 300 кольцах в него можно побежать');
  check('взятый И собранный подводный мир доступен', доступен(600, 'deep'),
    'с этапа 5 он собран, и на 600 кольцах в него можно побежать');
  check('взятый И собранный звёздный мир доступен', доступен(900, 'stars'),
    'с этапа 5 собраны все четыре мира — несобранных больше нет');
  check('первый мир доступен всегда', доступен(0, 'hills'));

  /* Правило «куда пойдёт забег» живёт ОДНОЙ функцией, и это не уборка.
     Выражение `worldsAt(bank).includes(x) && worldReady(x) ? x : 'hills'`
     стояло в `startRun`, а экран выбора его не знал — и мир, выбранный когда-то
     при большей копилке, не был отмечен на экране ничем. Ребёнок видел четыре
     кнопки и ни одной выбранной, а забег молча уходил в холмы: игра не
     показала того, что сделала. */
  check('доступный выбор остаётся собой', activeWorld(900, 'stars') === 'stars');
  check('недоступный выбор уходит в первый мир',
    activeWorld(100, 'stars') === 'hills', activeWorld(100, 'stars'));
  check('несобранный мир тоже уходит в первый', (() => {
    const было = WORLDS.stars.zones;
    WORLDS.stars.zones = null;
    const r = activeWorld(900, 'stars');
    WORLDS.stars.zones = было;
    return r === 'hills';
  })());
  check('мусор уходит в первый мир',
    ['', null, undefined, 42, 'нет такого'].every((b) => activeWorld(900, b) === 'hills'));
  check('и startRun зовёт именно её, а не повторяет правило',
    /activeWorld\(/.test(readFileSync(join(ROOT, 'js/app.js'), 'utf8'))
    && !/worldsAt\([^)]*\)\.includes/.test(readFileSync(join(ROOT, 'js/app.js'), 'utf8')),
    'вторая копия правила разъехалась бы с первой молча');

  /* Искры рисуются только открытыми и только у СОБРАННОГО кольца, и живут те
     же 0.45 с, что подскок. Проверяется поддельным холстом: число заливок в
     кадре с собранным кольцом обязано вырасти ровно при открытом призе. */
  const кадрИскр = (prizes) => paintFrame({
    stars: [{ x: 0, z: 6, worth: 1, taken: true, takenAtS: 0.1 }],
    elapsed: 0.2, prizes,
  }).fills.length;
  check('без приза искр нет', кадрИскр({}) === кадрИскр({ sparks: false }));
  check('с призом заливок больше', кадрИскр({ sparks: true }) > кадрИскр({}),
    'искры обязаны что-то рисовать, иначе приз пустой');
  /* И не рисуются у несобранного кольца: искры — событие сбора, а не украшение
     кольца, иначе они горели бы всю дорогу и стоили бы кадру постоянно. */
  const кадрЦелого = (prizes) => paintFrame({
    stars: [{ x: 0, z: 6, worth: 1, taken: false }], elapsed: 0.2, prizes,
  }).fills.length;
  check('у несобранного кольца искр нет', кадрЦелого({ sparks: true }) === кадрЦелого({}),
    'иначе приз горит весь забег и платит за себя каждым кадром');

  /* ── Состав обочины: единственный владелец ──

     Виды обочины у зон свои, а приз «цветущая обочина» смещает веса. Второй
     список видов (отдельный «цветущий») разъехался бы с основным молча,
     поэтому владелец один — `kindsFor(zone, prizes)`, а приз правит ВЕС, а не
     состав. */
  check('без приза состав тот же, что в теме',
    kindsFor('greenHill').length === THEME.greenHill.decor.kinds.length);
  check('приз не добавляет и не убирает видов в зелёной зоне',
    kindsFor('greenHill', { bloom: true }).length === kindsFor('greenHill').length,
    'цветущая обочина — это ВЕСА, а не новые формы');

  /* Цветок и куст дешевле пальмы, поэтому цветущая обочина кадр не
     утяжеляет, а облегчает. Проверяется это не на глаз: суммарная «цена»
     состава при призе обязана быть не выше, чем без него.

     ЦЕНЫ СЧИТАЮТСЯ ОТРИСОВКОЙ, А НЕ ТАБЛИЦЕЙ. Здесь стояла таблица
     `{ palm: 3, cactus: 2, spruce: 2, … }` — третья копия числа заливок
     после кода и счётчика бюджета, — и она разошлась с кодом: настоящие
     цены 4, 3 и 3. Пропуск неизвестного вида (`?? 2`) прятал это тем
     надёжнее, чем больше видов появлялось. Теперь цена каждого вида
     МЕРИТСЯ поддельным холстом, ровно как у светлячка ниже, и разойтись ей
     не с чем. */
  const ЦЕНА_ВИДА = (() => {
    const пусто = paintFrame({ zone: 'nightHills' }).fills.length;
    const out = {};
    for (const z of ZONES_ALL) {
      for (const k of THEME[z].decor.kinds) {
        if (out[k.kind] != null) continue;
        const x = CORRIDOR_HALF + (k.out ?? DECOR.outM);
        out[k.kind] = paintFrame({
          zone: 'nightHills',
          decor: [{ kind: k.kind, zone: 'nightHills', side: 1, x, y: CLIFF_TOP,
                    h: k.height, z: 5, at: 2.5, phase: 0 }],
        }).fills.length - пусто;
      }
    }
    return out;
  })();
  for (const [k, n] of Object.entries(ЦЕНА_ВИДА)) {
    check(`вид «${k}» рисуется`, n > 0,
      'ноль заливок здесь значит «не нарисовался», а не «бесплатен»');
  }
  const средняя = (zone, prizes) => {
    const ks = kindsFor(zone, prizes);
    const сумма = ks.reduce((acc, k) => acc + k.weight, 0);
    return ks.reduce((acc, k) => acc + ЦЕНА_ВИДА[k.kind] * k.weight, 0) / сумма;
  };
  for (const z of ZONES_ALL) {
    check(`зона ${z}: цветущая обочина не дороже обычной`,
      средняя(z, { bloom: true }) <= средняя(z) + 1e-9,
      `${средняя(z, { bloom: true }).toFixed(3)} против ${средняя(z).toFixed(3)} заливок на вид`);
  }
  check('и в зелёной зоне она ощутимо дешевле',
    средняя('greenHill', { bloom: true }) < средняя('greenHill') - 0.05,
    'именно этим и платится ободок — приз пятого уровня');

  /* Пустой состав невозможен ни при каком наборе призов. `pickFrom` делит на
     сумму весов: при нуле выходит NaN, возвращается последний вид списка — то
     есть обочина не падает, а ВРЁТ, и поймать это глазами нечем. */
  for (const z of ZONES_ALL) {
    for (const prizes of [{}, { bloom: true }, unlockedAt(1200)]) {
      const ks = kindsFor(z, prizes);
      check(`зона ${z}: состав не пуст при наборе ${Object.keys(prizes).length} призов`,
        ks.length > 0 && ks.reduce((acc, k) => acc + k.weight, 0) > 0,
        'нулевая сумма весов даёт NaN в pickFrom и обочину из одного вида');
    }
  }

  /* Зона, у которой ВСЕ виды условны, состава не теряет.

     Здесь было написано (и в двух темах тоже), что пустой список даёт `NaN` в
     `pickFrom` и обочину из одного вида — «не падает, а врёт». Это перестало
     быть правдой, когда `kindsFor` начал отбрасывать нулевые веса: пустой
     список теперь роняет `makeDecor` с TypeError, то есть забег НЕ
     НАЧИНАЕТСЯ. Поймано ревью. Инвариант сторожит не только тест: у функции
     есть и запасной путь, и проверяется он здесь. */
  {
    const пробная = { decor: { kinds: [
      { kind: 'rock', needs: 'нет-такого-приза', weight: 0.5, height: 0.6, out: 0.10 },
    ] } };
    THEME['__проба'] = пробная;
    const ks = kindsFor('__проба', {});
    check('зона из одних условных видов не остаётся без состава',
      ks.length > 0 && ks.every((k) => k.weight > 0),
      'пустой состав роняет makeDecor, то есть забег не начинается вовсе');
    let упало = null;
    try {
      makeDecor({ durationS: 10, rng: seeded(3), world: 'hills', prizes: {} });
    } catch (e) { упало = String(e.message || e); }
    check('и makeDecor не падает', упало === null, упало || '');
    delete THEME['__проба'];
  }

  /* Светлячки принадлежат ОДНОЙ зоне: «приз открыт» не значит «везде».
     Светлячок в зелёной зоне днём — не украшение, а недоразумение. */
  const виды = (z, p) => kindsFor(z, p).map((k) => k.kind);
  check('без приза светлячков нет нигде',
    ZONES_ALL.every((z) => !виды(z, {}).includes('firefly')));
  check('с призом они есть в ночной зоне',
    виды('nightHills', { firefly: true }).includes('firefly'));
  check('и только в ней',
    !виды('greenHill', { firefly: true }).includes('firefly')
    && !виды('sunsetDunes', { firefly: true }).includes('firefly'),
    'светлячок в полдень — недоразумение, а не приз');

  /* Второй мир СОБРАН: у него три зоны, они есть в палитре, и мир перестал
     быть обещанием. Это единственная проверка, которая отличает «мир
     объявлен» от «в мир можно побежать». */
  check('ледяной мир собран', worldReady('ice'));
  check('и в нём три зоны', (WORLDS.ice.zones || []).length === 3,
    String(WORLDS.ice.zones));
  for (const z of WORLDS.ice.zones || []) {
    check(`зона ${z} есть в палитре`, !!THEME[z]);
    check(`у зоны ${z} назван файл неба`, typeof SKY_FILES[z] === 'string');
  }
  /* Ночь с сиянием — вторая тёмная зона проекта, и потолок растра у неё СВОЙ.
     Общий дневной потолок сделал бы её небо дырой. */
  check('у ночи с сиянием свой потолок растра',
    skyClamp('auroraNight') < skyClamp('iceMorning') - 0.2,
    `сияние ${skyClamp('auroraNight')}, утро ${skyClamp('iceMorning')}`);

  /* Подводный мир СОБРАН. Та же проверка, что у ледяного: она отличает «мир
     объявлен» от «в мир можно побежать». */
  check('подводный мир собран', worldReady('deep'));
  check('и в нём три зоны', (WORLDS.deep.zones || []).length === 3,
    String(WORLDS.deep.zones));
  for (const z of WORLDS.deep.zones || []) {
    check(`зона ${z} есть в палитре`, !!THEME[z]);
    check(`у зоны ${z} назван файл неба`, typeof SKY_FILES[z] === 'string');
  }
  check('у светящейся бездны свой потолок растра',
    skyClamp('abyssGlow') < skyClamp('reefShallow') - 0.2,
    `бездна ${skyClamp('abyssGlow')}, мелководье ${skyClamp('reefShallow')}`);

  /* Звёздный мир собран, и на нём лестница миров закрывается: все четыре. */
  check('звёздный мир собран', worldReady('stars'));
  check('и в нём три зоны', (WORLDS.stars.zones || []).length === 3,
    String(WORLDS.stars.zones));
  /* Отказ `worldReady` остался БЕЗ ПОКРЫТИЯ, когда собрались все четыре мира:
     проверять стало нечего, а механизм остался — и половина его про опечатку
     в имени зоны, то есть ровно про `undefined` в палитре, который Canvas
     глотает молча. Поэтому мир подделывается здесь, а не ищется среди
     настоящих. Поймано ревью. */
  {
    const сохранено = WORLDS.stars.zones;
    WORLDS.__проба = { id: '__проба', name: 'Проба', zones: null };
    check('мир без зон не собран', !worldReady('__проба'));
    WORLDS.__проба.zones = ['cloudTop', 'cometBelt'];
    check('мир из двух зон не собран', !worldReady('__проба'));
    WORLDS.__проба.zones = ['cloudTop', 'опечатка', 'nebula'];
    check('мир с опечаткой в имени зоны не собран', !worldReady('__проба'),
      'иначе undefined уйдёт в палитру кадра, а Canvas это глотает молча');
    check('и зоны такого мира подменяются первым миром',
      String(zonesOf('__проба')) === String(WORLDS.hills.zones));
    delete WORLDS.__проба;
    WORLDS.stars.zones = сохранено;
  }

  check('все четыре мира собраны',
    Object.keys(WORLDS).every((w) => worldReady(w)),
    Object.keys(WORLDS).filter((w) => !worldReady(w)).join(', ') || 'все');
  check('зон стало двенадцать', Object.keys(THEME).length === 12,
    `${Object.keys(THEME).length}`);

  /* Потолок растра пришпилен У КАЖДОЙ зоны, где он задан полем.

     Прежняя проверка требовала «не выше 0.45» у четырёх тёмных — и не держала
     ничего: пояс комет в список не входил вовсе, а две зоны с 0.30 прошли бы
     и при 0.45. Удали `skyClampTo: 0.45` — оба набора остались бы зелёными, а
     пояс комет молча унаследовал бы дневной потолок 0.704 при собственном
     небе 0.035: облака растра вышли бы впритык к проёму, и «иди сюда» в этой
     зоне перестало бы читаться. Поймано ревью.

     Шкала здесь НЕПРЕРЫВНА, и это вывод этапа 5: было «день или ночь», стало
     четыре значения. Поэтому и проверка пошла по значениям, а не по порогу. */
  for (const [z, потолок] of [['nightHills', 0.30], ['auroraNight', 0.30],
                              ['abyssGlow', 0.30], ['nebula', 0.30],
                              ['cometBelt', 0.45], ['kelpDeep', 0.45],
                              ['snowField', 0.62]]) {
    check(`у зоны ${z} потолок растра ровно ${потолок}`, skyClamp(z) === потолок,
      `${skyClamp(z)}`);
  }
  /* Заросли переехали сюда из выведенных 18 октября: их растр пересобран
     своим мотивом, и самое светлое в нём теперь лучи света, а не
     перекрашенные облака. Разбор — в `docs/sky-and-art.md`. */
  for (const z of ['greenHill', 'sunsetDunes', 'iceMorning', 'reefShallow',
                   'cloudTop']) {
    check(`у зоны ${z} потолок выводится из проёма`,
      Math.abs(skyClamp(z) - (luminance(THEME[z].gap) - GAP_GUARD)) < 1e-12,
      `${skyClamp(z)}`);
  }

  /* Светлячки — в ночных зонах, и ни в одной из ВОСЬМИ дневных. */
  for (const z of ['greenHill', 'sunsetDunes', 'iceMorning', 'snowField',
                   'reefShallow', 'kelpDeep', 'cloudTop', 'cometBelt']) {
    check(`светлячков нет в дневной зоне ${z}`,
      !kindsFor(z, { firefly: true }).some((k) => k.kind === 'firefly'),
      'светлячок в полдень — недоразумение, а не приз');
  }

  /* Светлячки теперь в ДВУХ ночных зонах, и правило не «одна зона», а «не
     везде»: механизм тот же `needs`, дневных зон он по-прежнему не касается. */
  /* Глаз бадника НЕ переопределяется в зонах: он единственный цвет вне обоих
     наборов ролей, то есть расхождение в нём не поймает ни одна проверка.
     Три ледяные зоны завели четвёртую копию цвета, неотличимую глазом
     (0.79 против 0.80), — то есть копию без выгоды. Поймано ревью. */
  for (const z of ZONES_ALL) {
    check(`${z}: глаз бадника берётся из общего набора`,
      THEME[z].badnikEye === THEME.greenHill.badnikEye,
      `${THEME[z].badnikEye} против ${THEME.greenHill.badnikEye}`);
  }

  check('светлячки есть в обеих ночных зонах',
    kindsFor('nightHills', { firefly: true }).some((k) => k.kind === 'firefly')
    && kindsFor('auroraNight', { firefly: true }).some((k) => k.kind === 'firefly'));
  for (const z of ['greenHill', 'sunsetDunes', 'iceMorning', 'snowField']) {
    check(`и нет в дневной зоне ${z}`,
      !kindsFor(z, { firefly: true }).some((k) => k.kind === 'firefly'),
      'светлячок в полдень — недоразумение, а не приз');
  }

  /* Зона, выпавшая из палитры, не должна отдавать undefined в кадр: такой мир
     считается несобранным и уступает первому — молча. */
  {
    const сохранено = WORLDS.ice.zones;
    WORLDS.ice.zones = ['iceMorning', 'нет-такой-зоны', 'auroraNight'];
    check('мир с несуществующей зоной отдаёт зоны первого мира',
      String(zonesOf('ice')) === String(WORLDS.hills.zones),
      String(zonesOf('ice')));
    WORLDS.ice.zones = сохранено;
  }

  /* Светлячок — ОДНА заливка, самая дешёвая форма в игре наравне с камнем, и
     вес он забирает у камня. Значит приз ничего не стоит кадру.

     Считается НАСТОЯЩЕЙ отрисовкой, а не таблицей цен: таблица была бы
     третьей копией числа заливок (первые две — код и счётчик бюджета). */
  const цена = (kind, h) => {
    const пусто = paintFrame({ zone: 'nightHills' }).fills.length;
    /* Элемент собирается ТЕМИ ЖЕ полями, что кладёт makeDecor: `y` — кромка
       обрыва (`CLIFF_TOP`, он же WALL), `h` — высота вида, `phase` — своя у
       элемента. С неверным `y` элемент уходит под маску обрыва и не рисуется
       вовсе, то есть «ноль заливок» читалось бы как «дёшево». */
    const сФигурой = paintFrame({
      zone: 'nightHills',
      decor: [{ kind, zone: 'nightHills', side: 1, x: 1.6, y: CLIFF_TOP, h, z: 5,
                at: 2.5, phase: 0 }],
    }).fills.length;
    return сФигурой - пусто;
  };
  /* Сначала — что элемент вообще нарисовался. Иначе срезанный маской элемент
     дал бы ноль, и проверка «не дороже камня» прошла бы на пустоте. */
  check('светлячок рисуется', цена('firefly', 1.4) > 0,
    'ноль заливок здесь значит «не нарисовался», а не «дёшев»');
  check('светлячок — одна заливка', цена('firefly', 1.4) === 1, `${цена('firefly', 1.4)}`);
  check('то есть не дороже камня', цена('firefly', 1.4) <= цена('rock', 0.6),
    `светлячок ${цена('firefly', 1.4)}, камень ${цена('rock', 0.6)}`);

  /* ── Плата за этап 4: пятно под кольцом ──

     Пятно сообщает, НАД КАКИМ местом пола висит кольцо, и вблизи это самая
     большая отдача на пиксель во всём уровне. Вдали оно вырождается: в худшем
     кадре пять из шести пятен были тоньше 2.5 пикселя по меньшей стороне, то
     есть платили заливкой за крапинку — и платили в глубине кадра, где колец
     больше всего.

     Порог берётся по ВЕРТИКАЛЬНОЙ полуоси кольца, а не по горизонтальной:
     горизонтальная сжимается вращением, и ворота на ней мигали бы полтора
     раза в секунду. Ровно на этом уже обжёгся ободок. */
  /* Считается ЦВЕТ пятна, а не общее число заливок: общее мигает и без всякой
     правки — у внутреннего отверстия кольца свой порог `w > 2.5`, и в профиль
     оно законно пропадает. Этой ошибкой я уже дважды мерил не то. */
  const пятен = (z, t = 0) => paintFrame({
    stars: [{ x: 0, z, worth: 1, taken: false }], elapsed: t, prizes: {},
    zone: 'greenHill',
  }).fills.filter((c) => c === THEME.greenHill.shadow).length;

  check('у ближнего кольца пятно есть', пятен(4) === 1, `${пятен(4)}`);
  check('у далёкого кольца пятна нет', пятен(26) === 0, `${пятен(26)}`);

  /* Порог обязан исполнять СВОЁ ЖЕ правило: «пятна тоньше 2.5 пикселя —
     снять». Первая версия (7) резала только дальше 19 метров, а пятна с 9 до
     19 метров продолжала рисовать при толщине 0.3–2.5 пикселя — ровно то, что
     абзац рядом и осуждает. Поймано ревью замером.

     Проверяется не само число, а правило: у любого НАРИСОВАННОГО пятна
     меньшая сторона не тоньше 2.5 пикселя. */
  {
    const ш = (z) => paintFrame({
      stars: [{ x: 0, z, worth: 1, taken: false }], elapsed: 0, prizes: {}, zone: 'greenHill',
    }).shapes.filter((f) => f.style === THEME.greenHill.shadow);
    for (const z of [4, 6, 8, 9, 10, 12, 14, 19]) {
      const пятна = ш(z);
      for (const ф of пятна) {
        check(`пятно на ${z} м не тоньше 2.5 px`, Math.min(ф.w, ф.h) >= 2.5,
          `${Math.min(ф.w, ф.h).toFixed(2)} px — ровно то, что правило велит снимать`);
      }
    }
  }

  for (const z of [4, 8, 14]) {
    const поФазам = new Set();
    for (let t = 0; t < 1.4; t += 0.05) поФазам.add(пятен(z, t));
    check(`на ${z} м пятно не мигает с вращением`, поФазам.size === 1,
      `пятен по фазам: ${[...поФазам].join(', ')}`);
  }

  /* Радуга вершины меняет ОТТЕНОК кольца, но не его светлоту: кольцо — цвет
     РЕШЕНИЯ, и контракт светлоты на него распространяется в любой фазе.
     Свободного цвета кольцу не положено ни в каком призе. */
  /* Перебор идёт по ВСЕМ четырём цветам кольца и по ПОЛНОМУ обороту радуги
     (период 1/rainbowHz = 4 с). Прежняя проверка брала один `star` и
     останавливалась на трёх секундах — четверть круга оттенков не
     проверялась вовсе, а `starDim` не проверялся никогда. Поймано ревью. */
  for (const ключ of ['star', 'starDim', 'starBig', 'starBigDim']) {
    const база = THEME.greenHill[ключ];
    for (let t = 0; t < 1 / MOTION.rainbowHz + 0.2; t += 0.1) {
      const c = rainbowOf(база, t);
      check(`радуга «${ключ}» на ${t.toFixed(1)} с держит светлоту`,
        Math.abs(luminance(c) - luminance(база)) < 0.02,
        `${luminance(c).toFixed(3)} против ${luminance(база).toFixed(3)}`);
      check(`радуга «${ключ}» на ${t.toFixed(1)} с даёт настоящий цвет`,
        /^#[0-9a-f]{6}$/i.test(c), c);
    }
  }
  /* Вырожденные входы не расходятся и не зацикливаются: чёрный, белый, серый
     без насыщенности. Поворот тона у серого — тождество, и это верно. */
  for (const база of ['#000000', '#ffffff', '#808080', '#010101']) {
    const c = rainbowOf(база, 1.3);
    check(`радуга не ломается на ${база}`, /^#[0-9a-f]{6}$/i.test(c)
      && Math.abs(luminance(c) - luminance(база)) < 0.02, c);
  }
  /* И она действительно КРАСИТ: за период оттенок обязан смениться заметно. */
  const оттенки = new Set();
  for (let t = 0; t < 4; t += 0.2) оттенки.add(rainbowOf(THEME.greenHill.star, t));
  check('радуга меняет цвет', оттенки.size > 8, `${оттенки.size} разных цветов`);

  /* Без приза кольцо красится ровно как прежде. */
  const кольцоЦвета = (prizes) => paintFrame({
    stars: [{ x: 0, z: 4, worth: 1, taken: false }], elapsed: 1.0, prizes,
    zone: 'greenHill',
  }).fills.filter((c) => c === THEME.greenHill.star).length;
  check('без приза кольцо прежнего цвета', кольцоЦвета({}) > 0);
  check('с призом — уже нет', кольцоЦвета({ gold: true }) === 0,
    'радуга обязана быть видна, иначе приза нет');

  /* Шлейф — полоса за кольцом, приз одиннадцатого уровня. Спек обещал «0,
     замена» — неверно, как было неверно у ободка: заменять у кольца нечего,
     тело и отверстие оба нужны. Порог у него СВОЙ и строже, чем у пятна. */
  const сШлейфом = (z, prizes, t = 0, taken = false) => paintFrame({
    stars: [{ x: 0, z, worth: 1, taken, takenAtS: 0.1 }], elapsed: t, prizes,
  }).fills.length;
  check('без приза шлейфа нет', сШлейфом(4, {}) === сШлейфом(4, { trail: false }));
  check('у ближнего кольца шлейф есть',
    сШлейфом(4, { trail: true }) === сШлейфом(4, {}) + 1,
    'шлейф — одна полоса, а не две');
  check('у среднего кольца шлейфа нет', сШлейфом(14, { trail: true }) === сШлейфом(14, {}),
    'там он тоньше пикселя и платит за невидимое');

  /* У СОБРАННОГО кольца шлейфа нет: кольцо подпрыгивает и исчезает за 0.45 с,
     а полоса пережила бы его и осталась висеть без владельца — ровно та беда,
     из-за которой у собранного кольца нет и пятна. */
  check('у собранного кольца шлейфа нет',
    сШлейфом(4, { trail: true }, 0.2, true) === сШлейфом(4, {}, 0.2, true),
    'полоса пережила бы кольцо и осталась висеть сиротой');

  /* А вот у БЛИЗКОГО кольца в профиль шлейф ЕСТЬ, и это решение, а не
     недосмотр.

     Прежняя проверка стояла на 26 метрах и мерила расстояние, а не профиль:
     там шлейфа нет из-за `trailMinR`, и профильный случай не проверялся
     вовсе — ровно та ошибка, которая записана про ободок («план считал иначе,
     и первая версия проверки искала не то»). Поймано ревью.

     Решение: шлейф следует за кольцом. Кольцо в профиль не исчезает — это
     цель, а не украшение, — и полоса за ним тоже остаётся, сжимаясь вместе с
     ним до минимальной ширины в пиксель. Исчезни она в профиль, шлейф мигал
     бы с вращением полтора раза в секунду. */
  {
    const вкладПрофиля = new Set();
    for (let t = 0; t < 1.4; t += 0.05) {
      вкладПрофиля.add(сШлейфом(4, { trail: true }, t) - сШлейфом(4, {}, t));
    }
    check('шлейф у близкого кольца не мигает с вращением', вкладПрофиля.size === 1,
      `вклад по фазам: ${[...вкладПрофиля].join(', ')}`);
  }
  check('у ДАЛЁКОГО кольца шлейфа нет ни в какой фазе',
    сШлейфом(26, { trail: true }, 0.2) === сШлейфом(26, {}, 0.2)
    && сШлейфом(26, { trail: true }, 0) === сШлейфом(26, {}, 0));

  /* Спутник — птица, летящая рядом. ДВЕ заливки: тело и крыло. Оплачен
     порогом у пятна, и порядок этот обязателен. */
  const сПтицей = (prizes) => paintFrame({ elapsed: 1.0, prizes }).fills.length;
  check('без приза спутника нет', сПтицей({}) === сПтицей({ buddy: false }));
  check('с призом ровно две заливки', сПтицей({ buddy: true }) === сПтицей({}) + 2,
    `${сПтицей({ buddy: true })} против ${сПтицей({})}`);

  /* Птица обязана лететь В ОТКРЫТОМ НЕБЕ, а не за обрывом.

     Поймано кадром в браузере: при `x = 0.78 W` спутник давал РОВНО НОЛЬ
     пикселей — обрыв закрывал его целиком, хотя счётчик исправно считал две
     заливки. Третий случай за прогон, когда счётчик видит приз, а экран нет.

     Небо открыто клином вокруг точки схода и тем шире, чем выше. Поэтому
     инвариант простой и проверяемый из node: птица держится у середины кадра
     по горизонтали и заметно выше горизонта. */
  /* Граница открытого неба выводится из ГЕОМЕТРИИ ОБРЫВА, а не задаётся
     числом. Первая версия этой проверки держала `0.12 W` от руки — вдвое выше
     настоящего предела, — и спутник снова резался обрывом: при полном уходе
     взгляда (`u = ±1.5`, кламп) он пропадал пятую часть времени. Поймано
     ревью; счётчик заливок всё это время показывал стабильные две.

     Клин неба сужается с уходом взгляда, поэтому берётся ХУДШИЙ случай по
     всем `u` и по обеим сторонам, и птица меряется вместе со своей
     полушириной. */
  {
    const полуширина = VIEW.width * 0.012;
    const краяНеба = (u, y) => {
      const cam = camera(u, 0);
      let слева = -Infinity; let справа = Infinity;
      for (let d = 1; d < 60; d += 0.25) {
        for (const сторона of [-1, 1]) {
          const p = project(сторона * CORRIDOR_HALF, CLIFF_TOP, d, cam);
          if (p.sy >= y) continue;          // ниже птицы — не загораживает
          if (сторона < 0) слева = Math.max(слева, p.sx);
          else справа = Math.min(справа, p.sx);
        }
      }
      return { слева, справа };
    };
    for (let t = 0; t < 4; t += 0.2) {
      const п = buddyPos(t);
      let тесно = Infinity;
      for (const u of [-1.5, -1, 0, 1, 1.5]) {
        const { слева, справа } = краяНеба(u, п.y);
        тесно = Math.min(тесно, п.x - полуширина - слева, справа - (п.x + полуширина));
      }
      check(`спутник на ${t.toFixed(1)} с не режется обрывом ни при каком взгляде`,
        тесно > 0, `зазор ${тесно.toFixed(1)} px при x ${п.x.toFixed(0)}, y ${п.y.toFixed(0)}`);
    }
  }

  /* И «меньше движения» жмёт не только крыло, но и сам ПОЛЁТ: размах по
     горизонтали больше взмаха, и оставить его недожатым значило бы исполнить
     правило наполовину. Поймано ревью. */
  {
    const размах = (scale) => {
      let min = Infinity; let max = -Infinity;
      for (let t = 0; t < 4; t += 0.05) {
        const п = buddyPos(t, scale);
        min = Math.min(min, п.x); max = Math.max(max, п.x);
      }
      return max - min;
    };
    check('при «меньше движения» полёт сжимается',
      размах(motionScale(true)) < размах(1) * 0.2,
      `${размах(motionScale(true)).toFixed(1)} против ${размах(1).toFixed(1)}`);
    check('но не в ноль', размах(motionScale(true)) > 0);
  }

  /* Он летит — то есть его положение меняется со временем, а число заливок
     НЕТ. Мерцающий спутник читался бы дефектом картинки. */
  const вкладПтицы = new Set();
  for (let t = 0; t < 2.0; t += 0.05) {
    вкладПтицы.add(paintFrame({ elapsed: t, prizes: { buddy: true } }).fills.length
                 - paintFrame({ elapsed: t, prizes: {} }).fills.length);
  }
  check('и не мигает', вкладПтицы.size === 1,
    `вклад по фазам: ${[...вкладПтицы].join(', ')}`);

  /* Ободок — третий контур кольца, и это ЕДИНСТВЕННЫЙ приз этапа, который
     добавляет заливку. Оплачен он цветущей обочиной (приз уровня 2), и
     порядок тут обязателен: сначала плата, потом покупка. */
  const кадрКольца = (prizes) => paintFrame({
    stars: [{ x: 0, z: 3, worth: 1, taken: false }], elapsed: 0, prizes,
  }).fills.length;
  check('без приза ободка нет', кадрКольца({}) === кадрКольца({ rim: false }));
  check('с призом заливок ровно на одну больше',
    кадрКольца({ rim: true }) === кадрКольца({}) + 1,
    `${кадрКольца({ rim: true })} против ${кадрКольца({})} — ободок это один контур`);

  /* У кольца В ПРОФИЛЬ ободка нет — под тем же порогом `w > 2.5`, что и
     внутреннее отверстие.

     Порог этот про ПРОФИЛЬ, а не про расстояние, и это стоит сказать прямо:
     план (и первая версия этой проверки) считали его сторожем далёкого
     кольца, но туман режет кольца на 30 метрах, где `w` всё ещё 4.45 — то
     есть по расстоянию порог не срабатывает никогда. Срабатывает он от
     вращения: `ringSquash` сжимает кольцо по горизонтали, и в профиль `w`
     падает до 0.6. Там третий контур слился бы с остальными в тёмное пятно.

     Фаза 0.2 с при z = 26 даёт w = 0.96 — измерено, не угадано. */
  const кадрПрофиля = (prizes) => paintFrame({
    stars: [{ x: 0, z: 26, worth: 1, taken: false }], elapsed: 0.2, prizes,
  }).fills.length;
  check('у кольца в профиль ободка нет',
    кадрПрофиля({ rim: true }) === кадрПрофиля({}),
    'в профиль контуры сливаются в пятно, а платить пришлось бы за каждое кольцо');

  /* И у СРЕДНЕГО кольца ободка тоже нет: порог у него свой и строже, чем у
     отверстия. Кайма занимает 0.18 радиуса, и ширина её замерена: на 6
     метрах 4.00 пикселя, на 8 — 3.00, на 10 — уже 2.40, на 14 — 1.72.
     Miracast съедает тонкое первым, то есть дальше порога ободок не виден, но
     платит заливкой за каждое кольцо в глубине кадра, где их больше всего. */
  const кадрНа = (z, prizes) => paintFrame({
    stars: [{ x: 0, z, worth: 1, taken: false }], elapsed: 0, prizes,
  }).fills.length;
  check('ободок есть у ближнего кольца', кадрНа(6, { rim: true }) === кадрНа(6, {}) + 1,
    'на 6 метрах кайма 4.00 пикселя — видна');
  check('и нет у среднего', кадрНа(14, { rim: true }) === кадрНа(14, {}),
    'на 14 метрах кайма 1.72 пикселя: Miracast её съест, а заливку мы заплатим');

  /* Ободок не МИГАЕТ. Кольцо вращается, и его горизонтальная полуось ходит от
     0.12 до 1.0 радиуса; ворота, поставленные на неё, открывались бы и
     закрывались по полтора раза в секунду. Поймано ревью замером по фазам: на
     шести метрах ободок был 0.38 с и исчезал на 0.33 с, а жёлтое тело в эти
     моменты скакало между полным размером и 0.82.

     Обе прежние проверки стояли при `elapsed: 0`, где косинус фазы ровно
     единица, то есть мерили самый выгодный момент. Поэтому здесь перебор по
     фазам: присутствие ободка обязано быть свойством РАССТОЯНИЯ. */
  for (const z of [4, 6, 8]) {
    /* Меряется ВКЛАД ободка, а не общее число заливок. Общее мигает и без
       приза: у внутреннего отверстия свой порог `w > 2.5`, и в профиль оно
       законно пропадает — кольцо там тонкий ломтик. Разница же «с призом
       минус без приза» обязана быть постоянной. */
    const вклад = new Set();
    for (let t = 0; t < 1.4; t += 0.05) {
      const кадр = (prizes) => paintFrame({
        stars: [{ x: 0, z, worth: 1, taken: false }], elapsed: t, prizes,
      }).fills.length;
      вклад.add(кадр({ rim: true }) - кадр({}));
    }
    check(`на ${z} м ободок не мигает с вращением`, вклад.size === 1,
      `вклад ободка по фазам: ${[...вклад].join(', ')}`);
  }
});

/* ───────────────── бюджет кадра ─────────────────

   «Потянет телефон» до сих пор было словами: число заливок считали в браузере
   руками — 44 при потолке 150, — и ни одна правда об этом не держалась. Теперь
   держится, и держится в node: поддельный контекст считает заливки, а стадия
   кадра собирается как настоящая, с декорациями, кольцами и препятствием.

   Потолок 150 замерен на телефоне, а не выбран: это та граница, за которой
   кадр перестаёт укладываться в 38–40 fps. Запас между 44 и 150 и есть
   единственное, чем оправданы новые украшения — поэтому и считается он, а не
   «на глаз красиво».

   Проверяется ХУДШИЙ кадр прогона, а не средний: именно он и роняет fps.
   Прежние «44 заливки» из CLAUDE.md, «Бюджет кадра» — это типичный кадр, посчитанный руками в
   браузере; худший вдвое тяжелее.

   Чего этот счётчик НЕ видит, и об этом надо помнить, читая его число.
   Во-первых, он считает ВЫЗОВЫ, а не площадь, — а на телефоне кадр роняет
   именно площадь: замерено, что арт стоит около 5 мс при `draw50 = 0`.
   Во-вторых, в node нет растра неба, поэтому drawSky идёт запасным путём и
   выдаёт около дюжины заливок на холмы и облака; на телефоне вместо них два
   drawImage — вызовов меньше, площади больше. То есть число годится для
   сравнения «до и после правки», а не как предсказание fps. */
group('бюджет кадра', () => {
  const CEILING = 150;

  const recorder = painter;   // общий поддельный холст, см. выше

  /* По нескольким посевам, а не по одному. Худший кадр зависит от того, как
     встали декорации и кольца, и разброс между посевами — десяток заливок:
     один посев дал бы случайное число и однажды пропустил бы перебор. */
  let worst = 0;
  let worstAt = 0;
  let worstSeed = 0;
  /* По посевам И по ступеням сложности: на верхней ступени плита уже, а
     приседов больше, то есть состав кадра другой. Считать бюджет по одной
     ступени значило бы мерить игру, в которую ребёнок будет играть не всегда. */
  let worstStep = 0;
  /* Набор призов — ПОЛНЫЙ: призы накопительны и остаются навсегда, значит
     мерить надо кадр ребёнка с собранной лестницей, а не пустой профиль.
     Пустой профиль не увидел бы ни одного нового приза вовсе, то есть счётчик
     мерил бы игру, в которую через месяц играть не будут. */
  const prizes = unlockedAt(1200);
  /* И по КАЖДОМУ собранному миру. Счётчик брал зоны первого мира умолчанием,
     то есть зоны нового мира в бюджет не попадали вовсе — перебор в них был
     бы не виден. Берутся только миры с собранным артом: у остальных зон нет,
     мерить нечего. */
  let worstWorld = WORLDS.hills.id;
  for (const мир of Object.keys(WORLDS).filter((w) => worldReady(w))) {
  for (const seed of [1, 7, 13, 29]) {
   /* По ВСЕМ пяти уровням. Прежде считались только края, и это годилось,
      пока уровни различались тремя числами. Теперь у трёх верхних своя
      скорость, своё чередование и свой ряд колец — то есть свой СОСТАВ
      кадра, — и мерить бюджет по краям значило бы не видеть середины. */
   for (let step = 0; step <= STEP_MAX; step++) {
    const rng = seeded(seed);
    const tune = tuneFor(step);
    /* МИР едет и в генератор препятствий: у каждого мира своя пара внешностей,
       и без этого параметра счётчик мерил бы четыре мира одними фигурами
       холмов — то есть новых фигур не видел бы вовсе. Ровно та же дыра, что
       была у зон обочины абзацем выше. */
    const obstacles = makeLevel({ durationS: 300, rng, tune, world: мир });
    const stars = makeStars({ durationS: 300, obstacles, rng, tune });
    /* Мир и ПРИЗЫ — как в игре. Без `prizes` счётчик мерил бы обочину без
       цветущего приза, то есть состав, в который ребёнок с полной копилкой
       уже не играет. Ровно эта дыра была у искр на этапе 1: бюджет считал
       приз, которого не видит. */
    const decor = makeDecor({ durationS: 300, rng, world: мир, prizes, speed: tune.speed });

    const { canvas, fills } = recorder();
    /* Скорость — та же, с которой построено расписание. Без неё вид считал
       бы глубины по базовой скорости, то есть мерил бы кадр, которого на
       быстром уровне не бывает. */
    const view = createView(canvas, { speed: tune.speed });

    // Шаг 0.25 с по всему забегу: кадры между ними отличаются сдвигом камеры,
    // а не составом, и на число заливок это не влияет.
    for (let t = 0; t < 300; t += 0.25) {
      fills.length = 0;
      /* Искры — ОЦЕНКА СВЕРХУ, а не воспроизведение сбора. В каждом кадре
         только что собранным помечается БЛИЖАЙШЕЕ кольцо: искр всегда четыре,
         какой бы ни была фаза, так что дороже этого они не бывают.

         Воспроизводить сбор по времени здесь нельзя по двум причинам, и обе
         проверены руками. Глубина сбора (`z < 1.2`) живёт в js/train.js, и
         копия её в тесте была бы вторым владельцем числа. А наивное «пометить
         все собранными» счётчик уронило со 113 до 95: собранное кольцо теряет
         тень, то есть такая метка убирает из кадра и те кольца, которые ещё
         впереди, — бюджет становится ЛЕГЧЕ правды. */
      let ближ = null;
      let ближZ = Infinity;
      for (const s of stars) {
        s.taken = false;
        const z = s.z - t * VIEW.speed;
        if (z > 0 && z < ближZ) { ближZ = z; ближ = s; }
      }
      if (ближ) { ближ.taken = true; ближ.takenAtS = t; }
      view.render({
        u: t % 2 < 1 ? 1 : -1, v: 0, travel: t * VIEW.speed, elapsed: t,
        obstacles, stars, decor, speed: 0.5, prizes,
        // Зона — та же, что была бы в игре: формы обочины у зон свои, и считать
        // бюджет по одной зоне значило бы не проверить остальные.
        zone: zoneAt(t, 300, мир),
        finishIn: 300 - t, safe: true, pulse: 0.5,
      });
      if (fills.length > worst) {
        worst = fills.length; worstAt = t; worstSeed = seed; worstStep = step; worstWorld = мир;
      }
    }
   }
  }
  }

  console.log(`  худший кадр: ${worst} заливок при потолке ${CEILING}`
    + ` (мир ${worstWorld}, посев ${worstSeed}, ступень ${worstStep}, ${worstAt.toFixed(1)} с)`);
  check(`худший кадр укладывается в потолок ${CEILING}`, worst <= CEILING,
    `${worst} заливок на ${worstAt.toFixed(1)} с`);
  check('и запас ещё остаётся', worst <= CEILING * 0.8,
    `${worst} из ${CEILING} — добавлять дальше уже нельзя без замера на телефоне`);

  /* Число, которое обещает корень, сверяется с посчитанным.

     Повод буквальный: корень обещал 117 заливок, комментарий у `DECOR.gapS`
     говорил 116, а счётчик давал 113 — три копии одного числа, две из них
     врут. Это ровно тот дефект, который корень называет самым частым в
     проекте, и завёлся он в описании механизма, который от него защищает.

     Сверяется ТОЧНЫМ равенством, а не допуском: счёт детерминирован (посевы
     заданы), поэтому разошлись числа — значит кадр действительно изменился, и
     корень обязан это сказать. Заодно проверяются потолок и мягкий рубеж:
     иначе `CEILING` можно поднять в тесте, не сознавшись в этом нигде. */
  const обещано = readFileSync(join(ROOT, 'CLAUDE.md'), 'utf8')
    .match(/[*][*]([0-9]+) при потолке ([0-9]+) и мягком рубеже ([0-9]+)[*][*]/);
  check('корень называет худший кадр в ожидаемой форме', обещано != null,
    'строка «Сейчас **N при потолке M и мягком рубеже K**» в CLAUDE.md не найдена');
  if (обещано) {
    const [, сказано, потолок, рубеж] = обещано.map(Number);
    check('корень называет тот же худший кадр, что считает тест', сказано === worst,
      `CLAUDE.md говорит ${сказано}, счётчик даёт ${worst}`);
    check('и тот же потолок', потолок === CEILING,
      `CLAUDE.md говорит ${потолок}, тест считает по ${CEILING}`);
    check('и тот же мягкий рубеж', рубеж === CEILING * 0.8,
      `CLAUDE.md говорит ${рубеж}, тест считает по ${CEILING * 0.8}`);
  }
  // Обратная сторона: кадр не должен внезапно опустеть. Ноль заливок означал
  // бы, что render упал молча или стадия собралась пустой.
  check('кадр не пустой', worst > 20, `${worst} заливок`);
});

group('небо не красит невидимое', () => {
  const W = VIEW.width;
  const H = VIEW.height;
  const hy0 = H * 0.46;                      // горизонт проекции при взгляде прямо
  const sky16 = { width: 1024, height: 576 };  // наш assets/sky.webp

  check('без растра прорех не существует', skyGaps(hy0, sky16 && null) === null,
     'запасной путь с холмами должен остаться ровно прежним');
  check('пустой растр тоже не считается растром',
    skyGaps(hy0, { width: 0, height: 0 }) === null);

  const прямо = skyGaps(hy0, sky16);
  check('растр 16:9 при взгляде прямо закрывает кадр целиком',
    прямо.top === 0 && прямо.bottom === 0, JSON.stringify(прямо));
  check('и ложится ровно во весь кадр',
    Math.abs(прямо.dy) < 1e-9 && Math.abs(прямо.dh - H) < 1e-9,
    `dy ${прямо.dy}, dh ${прямо.dh} при H ${H}`);

  /* Наклон. Ровно из-за него нельзя было написать «растр есть — заливки не
     нужны»: в приседе горизонт уезжает, и прореха настоящая. */
  const вниз = skyGaps(hy0 + 40, sky16);
  check('горизонт ушёл вниз — прореха сверху ровно по сдвигу',
    вниз.top === 40 && вниз.bottom === 0, JSON.stringify(вниз));
  const вверх = skyGaps(hy0 - 40, sky16);
  check('горизонт ушёл вверх — прореха снизу ровно по сдвигу',
    вверх.bottom === 40 && вверх.top === 0, JSON.stringify(вверх));
  const предел = skyGaps(hy0 + VIEW.pitchPx, sky16);
  check('прореха не больше предела наклона', предел.top === VIEW.pitchPx,
    `при pitchPx ${VIEW.pitchPx} вышло ${предел.top}`);

  /* Растр другой формы. Контракт обещает горизонт на 46%, но не отношение
     сторон: низкий растр оставляет прорехи с двух сторон сразу, высокий — ни
     одной, и заливать надо то, что есть, а не то, что ожидалось. */
  const низкий = skyGaps(hy0, { width: 1024, height: 200 });
  check('низкий растр оставляет прорехи с двух сторон',
    низкий.top > 0 && низкий.bottom > 0, JSON.stringify(низкий));
  check('и обе прорехи сходятся с кадром',
    Math.abs(низкий.top + низкий.dh + низкий.bottom - H) < 1e-9);
  const высокий = skyGaps(hy0, { width: 1024, height: 1400 });
  check('высокий растр прорех не оставляет',
    высокий.top === 0 && высокий.bottom === 0, JSON.stringify(высокий));

  // ── и то же самое на настоящей отрисовке ──
  function recorder() {
    const rects = [];
    const ops = [];
    let style = null;
    let images = 0;
    const ctx = {
      get fillStyle() { return style; },
      set fillStyle(v) { style = v; },
      beginPath() {}, closePath() {}, moveTo() {}, lineTo() {},
      ellipse() {}, quadraticCurveTo() {}, fill() {},
      /* Преобразования записываются, а не выбрасываются: вторая копия растра
         кладётся зеркально, и без этой записи проверить зеркало нечем. */
      save() { ops.push('save'); }, restore() { ops.push('restore'); },
      translate() { ops.push('translate'); },
      scale(sx) { ops.push('scale' + sx); },
      drawImage() { images += 1; ops.push('image'); },
      fillRect(x, y, w, h) { rects.push({ x, y, w, h }); },
    };
    return {
      canvas: { width: 0, height: 0, getContext: () => ctx },
      rects,
      ops,
      get images() { return images; },
    };
  }
  const кадр = (opts, backdrop) => {
    const r = recorder();
    /* Растр теперь приходит КАРТОЙ по зонам: небо меняется вместе с зоной.
       Здесь зона одна — умолчание `render`, то есть первая, — и карты из
       одной записи достаточно. */
    createView(r.canvas, backdrop ? { backdrops: { [ZONES[0]]: backdrop } } : {}).render({
      u: 0, v: 0, travel: 0, elapsed: 0, obstacles: [], stars: [], ...opts,
    });
    return r;
  };
  const площадь = (rects) => rects.reduce((a, q) => a + q.w * q.h, 0) / (W * H);

  const сРастром = кадр({}, sky16);
  check('с растром полноэкранных заливок не выдаётся ни одной',
    сРастром.rects.length === 0,
    'осталось: ' + JSON.stringify(сРастром.rects));
  check('а сам растр по-прежнему кладётся дважды', сРастром.images === 2,
    'при боковом уходе взгляда одной копии не хватает — оторвётся от края');

  /* ─── и вторая копия ЗЕРКАЛЬНАЯ ───

     Две копии подряд предполагают, что растр замощается по горизонтали. Ни
     одна наша картинка не замощается: у ночной невязка краёв 23.5 из 255 в
     среднем и 211 на строке горизонта. Снаружи это «холмы разного цвета с
     чёткой границей в месте наслоения» — так заказчик и сказал.

     Зеркало сводит на стыке два одинаковых края, и шов становится невозможным
     при любом содержимом. Проверять приходится ВЫЗОВЫ, а не пиксели: в node
     нет декодировщика картинок, и единственный способ поймать снятое зеркало —
     увидеть, что `scale(-1, …)` между двумя `drawImage` исчез. */
  const зеркало = сРастром.ops.join(' ');
  check('вторая копия растра кладётся зеркально',
    /image save translate scale-1 image restore/.test(зеркало),
    зеркало || '(вызовов нет)');

  const безРастра = кадр({}, null);
  check('без растра заливки остались прежними', безРастра.rects.length === 2,
    JSON.stringify(безРастра.rects));
  check('и экономия ровно та, что обещана геометрией',
    Math.abs(площадь(безРастра.rects) - площадь(сРастром.rects) - 1.30) < 0.01,
    `вышло ${(площадь(безРастра.rects) - площадь(сРастром.rects)).toFixed(3)} экрана`);

  /* Присед: заливка возвращается, но только размером с прореху. */
  const вПриседе = кадр({ v: 1 }, sky16);
  check('в приседе прореха заливается',
    вПриседе.rects.length === 1, JSON.stringify(вПриседе.rects));
  check('и заливается только она, а не весь кадр',
    вПриседе.rects[0].h < H * 0.2 && вПриседе.rects[0].w === W,
    JSON.stringify(вПриседе.rects[0]));
});

/* ───────────────── наводка штатива ───────────────── */
group('скелет лежит там же, где картинка', () => {
  /* Окошко камеры в вёрстке 16:9, а кадр этой формы НЕ обязан быть: 8 октября
     журнал поймал поворот вживую — полный экран сорвался, страница на миг
     стала портретной, и кадры пришли 360×640 (`cam.aspect` 1.78 → 0.56).
     Видео такой кадр `object-fit: cover` обрезает, показывая серединную треть
     по высоте, а скелет рисовался линейно во всю коробку. Фигурка и картинка
     расходятся — ноги выше пола, плечи не там, где плечи.

     Проверяется чистая укладка: перевод нормированных координат кадра в
     нормированные координаты окошка. */
  const тождество = coverFit(16 / 9, 16 / 9);
  check('совпали формы — ничего не меняется',
    тождество.sx === 1 && тождество.ox === 0 && тождество.sy === 1 && тождество.oy === 0);

  // Портретный кадр в широком окошке: обрезается сверху и снизу.
  const портрет = coverFit(360 / 640, 16 / 9);
  check('портретный кадр растягивается по вертикали', портрет.sy > 3,
    `sy = ${портрет.sy.toFixed(2)}`);
  check('и по горизонтали не трогается', портрет.sx === 1 && портрет.ox === 0);
  const yОкошка = (y) => y * портрет.sy + портрет.oy;
  check('середина кадра остаётся серединой окошка', Math.abs(yОкошка(0.5) - 0.5) < 1e-9,
    `вышло ${yОкошка(0.5)}`);
  check('а ноги у низа кадра уезжают НИЖЕ окошка, то есть за него', yОкошка(0.9) > 1,
    `вышло ${yОкошка(0.9).toFixed(2)} — без укладки они рисовались бы на 0.9, выше пола`);

  // Широкий кадр в узком окошке: обрезается по бокам. Обратный случай.
  const широкий = coverFit(20 / 9, 16 / 9);
  check('широкий кадр режется по бокам', широкий.sx > 1 && широкий.sy === 1,
    `sx = ${широкий.sx.toFixed(2)}`);
  check('и его середина тоже остаётся серединой',
    Math.abs(0.5 * широкий.sx + широкий.ox - 0.5) < 1e-9);

  // Мусор на входе не должен ломать отрисовку: окошко важнее точности.
  for (const [a, b, имя] of [[0, 1.78, 'нулевой кадр'], [1.78, 0, 'нулевое окошко'],
    [null, 1.78, 'нет кадра'], [NaN, 1.78, 'NaN']]) {
    const f = coverFit(a, b);
    check(`${имя} — тождество, а не NaN`,
      f.sx === 1 && f.ox === 0 && f.sy === 1 && f.oy === 0, JSON.stringify(f));
  }
});

group('наводка', () => {
  const at = (torso) => framing(null, { S: torso });

  check('подсказка зовёт ПОДОЙТИ, когда ребёнка в кадре мало', /ближе/.test(at(0.10).hint),
    'было наоборот, и заказчик с ребёнком подходили ближе, а телефон гнал их дальше');
  check('и зовёт ОТОЙТИ, когда он занял кадр целиком', /отойдите/i.test(at(0.80).hint));
  check('заполнение не зажато единицей', at(0.80).fill > 1,
    'зажим делал ветку «слишком близко» недостижимой вовсе');

  // Полоса привязана к тем же порогам, которыми игра судит присутствие.
  check('низ полосы выше порога потери', CAMERA.fillMin >= S.scaleMin * 3,
    `${CAMERA.fillMin} против ${S.scaleMin * 3}`);
  check('верх полосы ниже абсолютного потолка', CAMERA.fillMax <= S.scaleMax * 3,
    `${CAMERA.fillMax} против ${S.scaleMax * 3}`);
  check('наводка ребёнка из журнала проходит', at(0.37).ok === true, 'торс 0.37 — игра работала');
  check('наводка взрослого из журнала проходит', at(0.53).ok === true, 'торс 0.53 — игра работала');
  check('а на пороге потери — не проходит', at(S.scaleMin).ok === false,
    'иначе наводка зовёт туда, где игра теряет ребёнка');
  check('без позы судить нечего', framing(null, null).ok === false);
});

group('сдвиг штатива', () => {
  /* Калибровку переигрывать каждый раз незачем — двадцать секунд, а ребёнок
     хочет бежать. Прошлая принимается, если сцена та же. Эта проверка и
     решает, когда «та же». */
  const cal = { neutralX: 0.5, S0: 0.2 };
  check('та же сцена — калибровка годна', !isStale(cal, geometry(pose({ x: 0.5, scale: 0.2 }))));
  check('небольшая разница допустима', !isStale(cal, geometry(pose({ x: 0.52, scale: 0.21 }))),
    'иначе калибровка будет требоваться после каждого шага в сторону');
  check('ребёнок стал заметно крупнее — калибровка устарела',
    isStale(cal, geometry(pose({ x: 0.5, scale: 0.35 }))));
  check('штатив развернули — тоже устарела',
    isStale(cal, geometry(pose({ x: 0.72, scale: 0.2 }))));

  // Без калибровки и без позы решать нечего, и падать тоже не на чем.
  /* Числа из журнала 6 октября: на калибровке торс 0.53, в забеге 0.40.
     Расхождение 25% — ровно по прежнему допуску, и прошлая калибровка не
     переиспользовалась ни разу (`calib.reuse reuse:false had:true
     stale:true`), то есть двадцать секунд калибровки проходились каждый раз.
     Разница систематическая, а не шумовая: игрок возится у телефона, пока
     идёт установка штатива, и отходит только к старту. */
  const реальный = { neutralX: 0.5, S0: 0.53 };
  check('тот же игрок после отхода к старту — калибровка годна',
    !isStale(реальный, geometry(pose({ x: 0.5, scale: 0.40 }))),
    'иначе двадцать секунд калибровки будут проходиться перед каждым забегом');
  check('а развёрнутый штатив по-прежнему роняет калибровку',
    isStale(реальный, geometry(pose({ x: 0.78, scale: 0.53 }))),
    'допуск по нейтрали ослаблять нельзя — ради него проверка и существует');

  check('нет калибровки — не устарела', !isStale(null, geometry(pose({}))));
  check('нет позы — не устарела', !isStale(cal, null));
});

group('тема', () => {
  /* Эта группа существует из-за одного риска. Тема «зелёные холмы» делает мир
     светлым и зелёным, а до неё коридор был тёмно-синим, и контраст «плита /
     проём» получался сам. Теперь он сам не получается, а именно он сообщает
     ребёнку, куда уходить. Проверять его глазами нельзя: после Miracast кадр
     выглядит иначе, чем на машине разработки.

     Поэтому правило выражено числом: ФОРМА СООБЩАЕТ ТЕМУ, СВЕТЛОТА СООБЩАЕТ
     РЕШЕНИЕ.

     И проверяется оно по КАЖДОЙ теме, а не по первой. Раньше здесь стояло
     `const t = THEME.greenHill`, и перебора не было нигде: вторая зона не
     получила бы ни одной из этих проверок — то есть ровно так в палитру и
     попала бы белая декорация, спорящая с «иди сюда». Цикл поставлен ДО того,
     как появились зоны: с одной темой он не меняет ничего, а со второй он
     единственное, что держит читаемость. */
  const L = luminance;
  // Порог взят замером прежней палитры, а не выдуман: столько контраста уже
  // было, и терять его при покраске нельзя ни в каком случае.
  const baseline = L('#4fd6a0') - L('#c2415a');
  /* `skyStars` — не цвет, а свойство зоны, из того же ряда, что `decor`: чем
     набрано небо, звёздами или облаками. Поэтому стоит среди неокрашиваемых
     ключей, а не в наборах ролей — иначе проверка «цвет задан» потребовала бы
     от него вида `#rrggbb`. */
  /* `skyClampTo` — не цвет, а потолок светлоты РАСТРА этой зоны (число). В
     набор ролей он попадает по той же причине, что `skyStars`: роль «цвета» у
     него нет и быть не может, а молчаливый пропуск неотнесённого ключа — это
     ровно та дыра, ради которой проверка и стоит. */
  const classified = new Set([...DECISION_KEYS, ...BACKGROUND_KEYS, 'badnikEye',
    'id', 'name', 'decor', 'skyStars', 'skyMotif', 'skyClampTo']);

  check('темы вообще есть', Object.keys(THEME).length > 0);

  for (const t of Object.values(THEME)) {
    const z = t.id || '?';

    check(`${z}: контраст «плита / проём» не ниже прежнего`,
      L(t.gap) - L(t.block) >= baseline,
      `было ${baseline.toFixed(3)}, стало ${(L(t.gap) - L(t.block)).toFixed(3)}`);

    check(`${z}: проём светлее всего фона`,
      BACKGROUND_KEYS.every((k) => L(t[k]) < L(t.gap)),
      'иначе «куда идти» перестанет быть самым заметным местом кадра');

    for (const k of BACKGROUND_KEYS) {
      check(`${z}: фон «${k}» не лезет в канал решения`,
        Math.abs(L(t[k]) - L(t.gap)) >= GAP_GUARD,
        `${t[k]}: разница ${Math.abs(L(t[k]) - L(t.gap)).toFixed(3)} при пороге ${GAP_GUARD}`);
    }

    /* ─── то, что лежит НА лице плиты, обязано от него отличаться ───

       Правило старое, но до 11 октября держалось только на `blockDeep` у
       створки: шипы торчали выше `WALL`, где фоном было небо, и лица плиты не
       касались вовсе. После поворота на внутреннюю кромку зубья заняли треть
       ширины плиты по всей высоте, то есть стали такой же деталью лица, как
       поперечины, — и ночная палитра немедленно показала, чего стоило
       отсутствие проверки: 1.49 против лица, на кадре зубьев просто нет.

       Сторон у требования две, и нужны обе. Снизу — различимость: деталь,
       слившаяся с плитой, не сообщает ничего. Сверху — `GAP_GUARD`: светлая
       полоса вдоль кромки начинает спорить с проёмом, то есть обещать проход
       там, где приговор его не даёт. Темнее плиты (створка) или светлее
       (металл) — дело вкуса; «почти как плита» не годится никогда. */
    /* `badnik` попал в этот список по той же дороге и в тот же день, что
       `spike`: тело выросло с 46% ширины плиты до 92%, то есть из фигурки на
       плите стало деталью её лица. Сегодня отношения 3.78×, 5.35× и 9.21×
       проходят с запасом — но проходят по удаче, а не под охраной, и первая
       же правка палитры врага могла бы уронить их ниже двух, не сломав
       ничего другого. Поймано ревью. */
    for (const k of ['spike', 'blockDeep', 'badnik']) {
      const отношение = Math.max(L(t[k]), L(t.block)) / Math.min(L(t[k]), L(t.block));
      check(`${z}: деталь «${k}» отличима от лица плиты`, отношение >= 2,
        `${t[k]}: ${L(t[k]).toFixed(3)} против ${L(t.block).toFixed(3)} — `
        + `${отношение.toFixed(2)}×, под сжатием Miracast это одна заливка`);
      check(`${z}: и деталь «${k}» не спорит с проёмом`,
        L(t.gap) - L(t[k]) >= GAP_GUARD,
        `${(L(t.gap) - L(t[k])).toFixed(3)} при пороге ${GAP_GUARD}`);
    }

    /* Цвет, не отнесённый ни к решению, ни к фону, не проверяется ничем — и
       именно так в палитру и попадёт однажды белая декорация. Единственное
       исключение названо в theme.js: глаз бадника в несколько пикселей. */
    check(`${z}: каждый цвет палитры отнесён к роли`,
      Object.keys(t).every((k) => classified.has(k)),
      `без роли: ${Object.keys(t).filter((k) => !classified.has(k)).join(', ')}`);

    // И наоборот: в палитре зоны обязан быть КАЖДЫЙ ключ, который где-то
    // рисуется. Забытый ключ даёт `undefined` в fillStyle — Canvas молча
    // оставляет прежний цвет, то есть кадр красится цветом соседней фигуры.
    for (const k of [...DECISION_KEYS, ...BACKGROUND_KEYS, 'badnikEye']) {
      check(`${z}: цвет «${k}» задан`, typeof t[k] === 'string' && /^#[0-9a-f]{6}$/i.test(t[k]),
        `${k} = ${t[k]}`);
    }

    /* ── Две пары, которые контракт не видел, и обе поймало ревью ──

       Зверёк выскакивает из вскрытой створки и бежит по кромке обрыва — это
       награда за уклонение, и живёт она около 0.45 с. Рисуется он на траве
       кромки и на силуэте хребта, а проверялся до сих пор только против
       проёма. В ледяной ночи он давал 0.023 и 0.036 — тёмное пятно на тёмном,
       после сжатия Miracast не видно вовсе. Порог 0.05 взят по худшей из
       зон, которые читаются (зелёные холмы, 0.064). */
    for (const [k, фон] of [['critter', 'grass'], ['critter', 'hills']]) {
      check(`${z}: «${k}» отличим от «${фон}»`,
        Math.abs(L(t[k]) - L(t[фон])) >= 0.05,
        `${Math.abs(L(t[k]) - L(t[фон])).toFixed(3)} — после сжатия это одно пятно`);
    }

    /* Виды обочины стоят НАД кромкой обрыва, то есть на линии горизонта, где
       фоном служит силуэт хребта (`hills`) — и в растре, и на векторном пути.
       Слившись с ним, обочина перестаёт сообщать скорость, а в первом лице её
       сообщают только она и шахматка пола. В снежном поле камень давал 0.006
       при весе 0.40 — самый частый вид зоны был невидим. Порог 0.03 взят по
       худшей читаемой паре (ель в зелёных холмах, 0.038). */
    /* Карта «вид → его главный цвет» обязана покрывать ВСЕ виды, и пропуск
       здесь падает, а не продолжается молча. Раньше стояло `if (!цвет)
       continue;` — то есть новый вид обочины проходил эту проверку не
       пройдя её: семь форм подводного, ледяного и звёздного миров,
       добавленные 18 октября, не проверились бы ни разу. Ровно та же дыра,
       что у куста в бездне: проверка хороша настолько, насколько полон её
       список, и полноту списка должен сторожить не человек. */
    const ЦВЕТ_ВИДА = { palm: 'palmLeaf', bush: 'grassDark', flower: 'flower', post: 'post',
      totem: 'totem', cactus: 'cactus', rock: 'rock', spruce: 'spruce',
      firefly: 'firefly', kelp: 'kelp', coral: 'coral', anemone: 'anemone',
      spire: 'spire', drift: 'drift', crystal: 'crystal', shard: 'shard' };
    for (const k of new Set(t.decor.kinds.map((q) => q.kind))) {
      const цвет = ЦВЕТ_ВИДА[k];
      check(`${z}: у вида «${k}» назван главный цвет`, !!цвет,
        'вид без цвета в карте не проверяется на контраст с хребтом вовсе');
      if (!цвет) continue;
      check(`${z}: обочина «${k}» отличима от силуэта хребта`,
        Math.abs(L(t[цвет]) - L(t.hills)) >= 0.03,
        `${цвет} ${L(t[цвет]).toFixed(3)} против hills ${L(t.hills).toFixed(3)}`);
    }

    check(`${z}: левый и правый обрыв различаются по светлоте`,
      Math.abs(L(t.earthL) - L(t.earthR)) > 0.02,
      'разница светлоты подсказывает, в какую сторону уехал взгляд');

    check(`${z}: шахматка пола различима`,
      Math.abs(L(t.floorA) - L(t.floorB)) > 0.1,
      'без этого пол сливается и скорость перестаёт читаться');

    /* Эти три переехали сюда из группы «порядок маляра»: они про палитру, а не
       про порядок, и обязаны идти по каждой зоне. Пятно под кольцом зажато с
       двух сторон — темнее самой тёмной клетки пола (иначе не видно) и светлее
       глубины обрыва (иначе читается дыркой в полу); полосы пола идут
       лестницей, и порядок тут важнее самих цветов. */
    check(`${z}: пятно темнее самой тёмной клетки пола`, L(t.shadow) < L(t.floorB),
      `${L(t.shadow).toFixed(3)} против ${L(t.floorB).toFixed(3)}`);
    check(`${z}: но светлее глубины обрыва`, L(t.shadow) > L(t.earthDeep),
      'тень в цвет обрыва читается дыркой в полу');
    check(`${z}: светлота полос пола идёт лестницей вниз`,
      L(t.floorA) > L(t.floorMid) && L(t.floorMid) > L(t.floorFar),
      [t.floorA, t.floorMid, t.floorFar].map((h) => L(h).toFixed(3)).join(' → '));
  }
});

/* ───────────── зоны ─────────────

   Забег идёт пять минут, и всё это время он был одной сцены. Зоны — то, чем
   это лечится: для семилетки видимое продвижение и есть награда за долгий
   забег, а полоса прогресса в углу — нет.

   Цена замысла — ноль заливок: меняются цвета и виды обочины, а не состав
   кадра. Проверяется здесь именно это, а не красота.

   Решающие цвета (проём, плита, предупреждение, кольцо) в зонах ОБЩИЕ, и это
   главное правило: язык игры ребёнок выучивает в первые полминуты, и зона,
   перекрасившая проём, заставила бы учиться заново посреди забега. */
group('зоны', () => {
  const L = luminance;

  check('зон больше одной', ZONES_ALL.length > 1);
  check('все зоны первого мира есть в палитре', ZONES.every((z) => THEME[z]), ZONES.join(', '));
  /* «Лишних тем не осталось» раньше спрашивалось у длины: зон столько же,
     сколько тем. С миров этого мало — зоны лежат по мирам, и тема, не попавшая
     ни в один мир, не покажется ребёнку никогда, то есть не проверится ни
     глазами, ни забегом, зато будет выглядеть живой. Вопрос поэтому задаётся
     прямо, а сличение идёт в обе стороны — как у документации. */
  const вМирах = new Set(Object.values(WORLDS).flatMap((w) => w.zones || []));
  for (const z of ZONES_ALL) {
    check(`тема ${z} принадлежит какому-то миру`, вМирах.has(z),
      'тема вне миров не покажется никогда, то есть не проверится ничем');
  }

  /* ── Обочина отвечает своему миру ──

     Жалоба заказчика 18 октября: «во всех локациях есть ёлки по бокам, это не
     отвечает стилистике подводному миру». Ель стояла в семи зонах из
     двенадцати, в том числе в зарослях ламинарии, в светящейся бездне и в
     туманности. Проверка написана так, чтобы следующая зона не завела её
     обратно по привычке: вид называется поимённо вместе с миром, которому он
     запрещён. */
  const ВИДЫ = (z) => new Set(THEME[z].decor.kinds.map((k) => k.kind));
  for (const z of WORLDS.deep.zones) {
    for (const k of ['spruce', 'palm', 'cactus', 'bush', 'flower']) {
      check(`подводная зона ${z} обходится без «${k}»`, !ВИДЫ(z).has(k),
        'под водой не растёт ни ель, ни пальма, ни куст — там водоросль, коралл и актиния');
    }
  }
  for (const z of WORLDS.stars.zones) {
    check(`звёздная зона ${z} обходится без ели`, !ВИДЫ(z).has('spruce'),
      'на звёздной дороге ели быть неоткуда');
  }
  /* В ледяном мире ель остаётся ровно в одной зоне — на морозном утре, где
     она читается границей леса. Выше границы леса её нет. */
  check('ель ледяного мира стоит только на морозном утре',
    WORLDS.ice.zones.filter((z) => ВИДЫ(z).has('spruce')).join(',') === 'iceMorning',
    WORLDS.ice.zones.filter((z) => ВИДЫ(z).has('spruce')).join(',') || 'нет ни одной');
  /* И обратная сторона: каждая из семи новых форм обязана где-то стоять.
     Форма, заведённая в палитре и в отрисовке, но не попавшая ни в одну зону,
     — это мёртвый код, который выглядит живым. */
  for (const k of ['kelp', 'coral', 'anemone', 'spire', 'drift', 'crystal', 'shard']) {
    check(`форма «${k}» стоит хотя бы в одной зоне`,
      ZONES_ALL.some((z) => ВИДЫ(z).has(k)),
      'форма без зоны не покажется никогда, то есть не проверится ничем');
  }

  /* Решающие цвета совпадают во всех зонах — побайтово. Это не стиль, а
     запрет: ребёнок читает «куда идти» светлотой проёма, и менять её посреди
     забега нельзя. */
  for (const k of DECISION_KEYS) {
    const значения = new Set(ZONES_ALL.map((z) => THEME[z][k]));
    check(`цвет решения «${k}» одинаков во всех зонах`, значения.size === 1,
      [...значения].join(' / '));
  }

  /* А фон обязан различаться, иначе зоны не зоны. Проверяется по небу и полу:
     это самые большие площади кадра, и если они совпали, смену зоны не
     увидит никто. */
  for (const k of ['sky', 'floorA']) {
    check(`фоновый «${k}» различается между зонами`,
      new Set(ZONES_ALL.map((z) => THEME[z][k])).size === ZONES_ALL.length,
      ZONES_ALL.map((z) => THEME[z][k]).join(' / '));
  }

  /* Границы по долям забега. Отладочный забег на минуту обязан показать все
     три зоны: иначе та единственная проверка, которой зоны смотрят глазами,
     перестала бы работать. */
  for (const durationS of [60, 180, 300]) {
    const увиденные = new Set();
    for (let t = 0; t < durationS; t += 0.25) увиденные.add(zoneAt(t, durationS));
    check(`за забег ${durationS} с видны все зоны`, увиденные.size === ZONES.length,
      [...увиденные].join(', '));
  }
  check('забег начинается первой зоной', zoneAt(0, 300) === ZONES[0]);
  check('и кончается последней', zoneAt(299.9, 300) === ZONES[ZONES.length - 1]);
  check('зоны идут по порядку, без возвратов', (() => {
    let i = 0;
    for (let t = 0; t < 300; t += 0.25) {
      const j = ZONES.indexOf(zoneAt(t, 300));
      if (j < i) return false;
      i = j;
    }
    return true;
  })(), 'возврат в прошлую зону читался бы как «забег пошёл назад»');

  /* Вырожденные входы. `zoneAt` зовётся и из расстановки декораций, и из кадра:
     вернуть `undefined` она не имеет права нигде — это `THEME[undefined]`, то
     есть кадр без палитры. */
  for (const [e, d] of [[0, 0], [10, 0], [-5, 300], [1e9, 300], [NaN, 300], [10, NaN]]) {
    check(`zoneAt(${e}, ${d}) отдаёт существующую зону`, ZONES.includes(zoneAt(e, d)),
      String(zoneAt(e, d)));
  }

  // ── палитра кадра действительно меняется ──
  const recorder = painter;   // общий поддельный холст, см. выше
  const кадр = (zone) => {
    const { canvas, fills } = recorder();
    createView(canvas).render({ u: 0, v: 0, travel: 0, elapsed: 0, zone });
    return fills;
  };

  for (const z of ZONES_ALL) {
    const f = кадр(z);
    check(`кадр зоны ${z} красится её полом`, f.includes(THEME[z].floorA),
      'иначе зона пришла полем, но до заливок не дошла');
  }
  check('кадр другой зоны не красится полом первой',
    !кадр(ZONES[1]).includes(THEME[ZONES[0]].floorA),
    'палитра защёлкнулась один раз, и смена зоны не работает');
  /* Неизвестная зона не обнуляет палитру: лучше цвета соседней зоны, чем
     `undefined` в fillStyle — на него Canvas молча оставляет прежний цвет, и
     кадр красится цветом соседней фигуры. */
  check('неизвестная зона не ломает кадр', кадр('нет такой').length > 20);

  /* Новый цвет обязан быть отнесён к набору и задан во ВСЕХ зонах, включая
     те, где формы нет: забытый ключ даёт undefined в fillStyle, а Canvas на
     это молча не рисует. */
  check('спутник отнесён к фоновым цветам', BACKGROUND_KEYS.includes('buddy'));
  for (const z of ZONES_ALL) {
    check(`${z}: цвет спутника задан`, typeof THEME[z].buddy === 'string');
    if (typeof THEME[z].buddy !== 'string') continue;
    check(`${z}: спутник отличим от неба`,
      Math.abs(L(THEME[z].buddy) - L(THEME[z].sky)) >= 0.05,
      `${L(THEME[z].buddy).toFixed(3)} против неба ${L(THEME[z].sky).toFixed(3)}`);
    /* И от силуэта ХРЕБТА — пару обещал план, а в контракт она не попала:
       в дюнах она давала 0.030. Геометрически птица до хребта не достаёт
       (она выше), но полагаться на это нельзя: растр неба рисует свои горы
       где угодно, а проверить растр из node нечем. Поймано ревью. */
    check(`${z}: спутник отличим от силуэта хребта`,
      Math.abs(L(THEME[z].buddy) - L(THEME[z].hills)) >= 0.05,
      `${L(THEME[z].buddy).toFixed(3)} против хребта ${L(THEME[z].hills).toFixed(3)}`);
    check(`${z}: и спутник не спорит с проёмом`,
      L(THEME[z].gap) - L(THEME[z].buddy) >= GAP_GUARD,
      'птица — украшение, и светлее «иди сюда» она быть не вправе');
  }

  check('светлячок отнесён к фоновым цветам', BACKGROUND_KEYS.includes('firefly'));
  for (const z of ZONES_ALL) {
    check(`${z}: цвет светлячка задан`, typeof THEME[z].firefly === 'string',
      'зона определяет и те цвета форм, которых в ней нет');
  }
  /* И он обязан быть ТЕМНЕЕ проёма на GAP_GUARD, как любой фон. Это главный
     риск этого приза: «светящийся» и «темнее проёма» надо совместить, иначе
     светлячок начнёт спорить с «иди сюда» — ровно та белая декорация, от
     которой предостерегает корень. */
  check('и светлячок не ярче проёма',
    L(THEME.nightHills.firefly) <= L(THEME.nightHills.gap) - GAP_GUARD,
    `${L(THEME.nightHills.firefly).toFixed(3)} против проёма `
    + `${L(THEME.nightHills.gap).toFixed(3)} при зазоре ${GAP_GUARD}`);

  // ── формы обочины: не дороже пальмы ──
  /* Бюджет кадра — 150 заливок при худших 108, и декорации уже самая большая
     статья. Поэтому зона имеет право на свои формы, но не на более дорогие:
     одновременно активна одна зона, и если каждая её форма не дороже пальмы,
     кадр не может стать тяжелее сегодняшнего. Проверяется, а не обещается. */
  const формы = new Map();
  for (const z of ZONES_ALL) {
    for (const k of THEME[z].decor.kinds) {
      if (!формы.has(k.kind)) формы.set(k.kind, { zone: z, height: k.height, out: k.out ?? DECOR.outM });
    }
  }
  const заливок = (zone, kind, height, out = DECOR.outM) => {
    const { canvas, fills } = recorder();
    createView(canvas).render({
      u: 0, v: 0, travel: 0, elapsed: 0, zone,
      /* Отступ от кромки — тот, что у ВИДА, а не общий: обрыв скрывает низ
         декорации, и при чужом отступе низкий вид не нарисовался бы вовсе.
         Разбор — у `decorYMask` и в группе «что чем перекрыто». */
      decor: [{ kind, zone, side: 1, x: CORRIDOR_HALF + out, y: CLIFF_TOP, h: height, z: 4, at: 1, phase: 0.3 }],
    });
    const пусто = кадр(zone).length;
    return fills.length - пусто;
  };
  const пальма = заливок('greenHill', 'palm', 2.2);
  check('пальма вообще рисуется', пальма > 0, `${пальма} заливок`);
  for (const [kind, { zone, height, out }] of формы) {
    const n = заливок(zone, kind, height, out);
    check(`форма «${kind}» рисуется`, n > 0, `${n} заливок`);
    check(`форма «${kind}» не дороже пальмы`, n <= пальма,
      `${n} против ${пальма} у пальмы — кадр станет тяжелее сегодняшнего`);
  }

  /* Незнакомый вид не рисуется НИЧЕМ. Раньше последняя ветка drawDecor была
     `else`, то есть любой новый вид молча становился тотемом с подмигивающим
     глазом; с зонами это ловушка под ногами. */
  check('незнакомый вид не рисуется вовсе',
    заливок('greenHill', 'нетакого', 1.5) === 0,
    'молчаливая подмена вида — дефект, который виден только на телефоне');
});

group('декорации', () => {
  /* Потолок отрисовки повторён здесь числом: DECOR_MAX — модульная константа
     js/view.js и наружу не отдаётся, а вывозить её туда только ради теста
     значило бы расширить API ради проверки. Расхождение поймает проверка ниже:
     она требует запаса, то есть сработает и если потолок в коде опустят. */
  const DECOR_MAX_ОЖИДАЕМЫЙ = 18;
  const decor = makeDecor({ durationS: 60, rng: seeded(1) });

  check('декорации расставлены', decor.length > 10);

  /* Главное свойство: декорация не участвует в игре. Проверяется не доверием
     к отрисовке, а положением — всё стоит строго за пределами коридора. */
  check('ни одна декорация не стоит в игровой полосе',
    decor.every((d) => Math.abs(d.x) > CORRIDOR_HALF),
    'иначе пальма закроет проём, и ребёнок проиграет из-за украшения');

  check('все декорации выше кромки обрыва',
    decor.every((d) => d.y >= CLIFF_TOP),
    'стены рисуются сплошными до тумана и всё за собой закрывают');

  check('порядок по глубине не нарушен',
    decor.every((d, i) => i === 0 || d.z >= decor[i - 1].z),
    'по возрастанию глубины отбираются ближние — на них бюджет кадра, — '
    + 'а рисуются они потом в обратную сторону, от дальних к ближним');

  check('расставлены по обе стороны',
    decor.some((d) => d.x < 0) && decor.some((d) => d.x > 0));

  const kinds = new Set(decor.map((d) => d.kind));
  check('виды не выродились в один', kinds.size >= 3, [...kinds].join(', '));
  /* Виды теперь берутся из ЗОНЫ, и проверка это повторяет: каждый элемент
     обязан быть видом той зоны, в которую он попал по времени. Иначе кактус
     однажды окажется на зелёных холмах, а заметить это можно будет только
     глазами на телефоне. */
  check('у каждого элемента есть зона',
    decor.every((d) => ZONES.includes(d.zone)), [...new Set(decor.map((d) => d.zone))].join(', '));
  check('вид взят из таблицы СВОЕЙ зоны',
    decor.every((d) => THEME[d.zone].decor.kinds.some((k) => k.kind === d.kind)),
    decor.filter((d) => !THEME[d.zone].decor.kinds.some((k) => k.kind === d.kind))
      .map((d) => `${d.zone}/${d.kind}`).join(', '));
  check('зона элемента совпадает с зоной его времени',
    decor.every((d) => d.zone === zoneAt(d.at, 60)),
    'два источника расписания зон разошлись бы — ровно то, из-за чего zoneAt один');
  check('за забег встречаются все зоны',
    new Set(decor.map((d) => d.zone)).size === ZONES.length,
    [...new Set(decor.map((d) => d.zone))].join(', '));

  /* Детерминированность. Иначе в истории правок не видно, что изменилось: при
     каждом прогоне уровень выглядит иначе, и сравнить два снимка нельзя. */
  const again = makeDecor({ durationS: 60, rng: seeded(1) });
  check('один и тот же посев даёт тот же уровень',
    JSON.stringify(decor) === JSON.stringify(again));
  const other = makeDecor({ durationS: 60, rng: seeded(2) });
  check('другой посев даёт другой уровень',
    JSON.stringify(decor) !== JSON.stringify(other));

  // Плотность задана временем, а не метрами: при смене скорости бега уровень
  // должен выглядеть так же густо.
  const expected = 60 / DECOR.gapS;
  check('плотность примерно та, что заказана',
    Math.abs(decor.length - expected) < expected * 0.5,
    `${decor.length} против ожидаемых ~${expected.toFixed(0)}`);

  /* Сколько декораций РЕАЛЬНО попадает в окно отрисовки. Число пригодилось не
     ради оптимизации: поднимая DECOR_MAX с 12 до 18, я написал в комментарии,
     что прежний потолок обрезал обочину на середине коридора. Замер это
     опроверг — в окно влезает самое большее одиннадцать. Теперь замер стоит
     проверкой: если плотность вырастет и упрётся в потолок, обочина начнёт
     молча обрываться, и узнать об этом надо здесь, а не на телевизоре. */
  const вОкне = (() => {
    let пик = 0;
    for (const seed of [1, 7, 13, 29]) {
      const d = makeDecor({ durationS: 300, rng: seeded(seed) });
      for (let t = 0; t < 300; t += 0.25) {
        const travel = t * VIEW.speed;
        let n = 0;
        for (const x of d) {
          const z = x.z - travel;
          if (z >= 0.7 && z <= VIEW.fogDistance * 0.75) n++;
        }
        пик = Math.max(пик, n);
      }
    }
    return пик;
  })();
  check('декорации укладываются в потолок кадра с запасом', вОкне <= DECOR_MAX_ОЖИДАЕМЫЙ - 4,
    `в окне до ${вОкне} при потолке ${DECOR_MAX_ОЖИДАЕМЫЙ}: меньший запас — и обочина начнёт обрываться`);

  check('длинный забег не выродился', makeDecor({ durationS: 300, rng: seeded(3) }).length > 100);
  check('нулевая длительность не ломает', makeDecor({ durationS: 0, rng: seeded(4) }).length === 0);
});

group('анимации', () => {
  /* Взмах крыла спутника. Функция времени с фазой, состояния не копит.
     Амплитуда жмётся `motionScale`, но НЕ в ноль: нулевой путь, который никто
     не исполняет, отдельно гниёт, а приз, исчезающий от системной настройки
     «меньше движения», — отказ, которого никто с настройкой не свяжет. */
  {
    const взмахи = [];
    for (let t = 0; t < 2; t += 0.05) взмахи.push(buddyFlap(t, 1));
    const размах = Math.max(...взмахи) - Math.min(...взмахи);
    check('взмах спутника колеблется', размах > 0.5, `размах ${размах.toFixed(3)}`);
    check('и не копит состояние',
      Math.abs(buddyFlap(0, 1) - buddyFlap(10 / MOTION.buddyHz, 1)) < 1e-9,
      'через целое число периодов значение обязано повториться');
    const сжатые = [];
    for (let t = 0; t < 2; t += 0.05) сжатые.push(buddyFlap(t, motionScale(true)));
    const размахСжатый = Math.max(...сжатые) - Math.min(...сжатые);
    check('при «меньше движения» взмах сжимается', размахСжатый < размах * 0.2,
      `${размахСжатый.toFixed(3)} против ${размах.toFixed(3)}`);
    check('но не в ноль', размахСжатый > 0,
      'неисполняемый путь гниёт отдельно — это правило проекта, а не придирка');
  }

  /* Все анимации — функции времени. Это проверяемо в node ровно потому, что
     ни одна не копит состояние: при 20 Гц источника поз и просадках кадра
     накопительная анимация расходится с картинкой, а функция — нет. */
  check('кольцо: один и тот же момент даёт один и тот же вид',
    ringSquash(3.25, 0.4) === ringSquash(3.25, 0.4));

  const squashes = [];
  for (let travel = 0; travel < 4; travel += 0.05) squashes.push(ringSquash(travel, 0));
  check('кольцо не выворачивается наизнанку', squashes.every((s) => s > 0 && s <= 1),
    'отрицательная ширина нарисует кольцо зеркально');
  check('кольцо действительно крутится', Math.max(...squashes) - Math.min(...squashes) > 0.5);
  check('кольцо не исчезает совсем', Math.min(...squashes) > 0.05,
    'в профиль кольцо должно оставаться видимым: это цель, а не украшение');

  check('пальма качается вокруг своего места',
    Math.abs(palmSway(0, 0) + palmSway(2 / MOTION.palmSwayHz / 2, 0)) < 1e-9,
    'иначе крона уедет от ствола');
  const sway = [];
  for (let travel = 0; travel < 8; travel += 0.1) sway.push(palmSway(travel, 0.3));
  check('качание в заданных пределах',
    sway.every((s) => Math.abs(s) <= MOTION.palmSwayM + 1e-9));

  /* «Меньше движения» сжимает амплитуду, а не выключает код: нулевой путь,
     который никто не видит, отдельно гниёт. Ребёнок на укачивание уже
     жаловался — из-за этого в игре нет поворота взгляда. */
  check('обычный режим — полная амплитуда', motionScale(false) === 1);
  check('«меньше движения» сжимает, но не до нуля',
    motionScale(true) > 0 && motionScale(true) < 0.2);
  check('сжатие действует на качание',
    Math.abs(palmSway(1.7, 0, motionScale(true))) < Math.abs(palmSway(1.7, 0, 1)));
  check('сжатие действует на кольцо',
    1 - ringSquash(1.7, 0, motionScale(true)) < 1 - ringSquash(1.7, 0, 1));

  /* Мерцание далёкого предупреждения. Устроено наоборот остальных: сжатие
     амплитуды прижимает его к ЕДИНИЦЕ, то есть метка остаётся ровно яркой.
     Это сообщение о решении, и системная настройка не имеет права его
     погасить — не по аккуратности, а по построению. */
  check('мерцание: один и тот же момент даёт один и тот же вид',
    warnBlink(2.75, 0.4) === warnBlink(2.75, 0.4));
  const blink = [];
  for (let t = 0; t < 4; t += 0.02) blink.push(warnBlink(t, 0));
  check('мерцание в пределах 0..1', blink.every((b) => b >= -1e-9 && b <= 1 + 1e-9));
  check('метка действительно мерцает', Math.max(...blink) - Math.min(...blink) > 0.9);
  check('за две секунды окна успевают два цикла', MOTION.warnBlinkHz * 2 >= 2,
    `при ${MOTION.warnBlinkHz} Гц мерцание не прочитается как мерцание`);
  const quiet = [];
  for (let t = 0; t < 4; t += 0.02) quiet.push(warnBlink(t, 0, motionScale(true)));
  check('«меньше движения» оставляет метку яркой', Math.min(...quiet) > 0.5,
    `минимум ${Math.min(...quiet).toFixed(2)} — ниже половины метка гаснет`);
});

// ──────────────────────── стены до края кадра ────────────────────────

group('стены', () => {
  /* Щель, которую видно только на телевизоре и только в крайнем положении.

     Обрыв и пол — плоскости при постоянном x, а точка схода стоит на месте
     (yawPx = 0): панорама их не растягивает, а двигает. Поэтому ближний угол
     правого обрыва при полном смещении вправо уезжал ВНУТРЬ кадра, и справа
     от него оставалась полоса 68 px сплошного неба — буфер залит им перед
     всем остальным. Выглядело дыркой в мире; пожаловался заказчик.

     Числом это ловится сразу, глазами — почти никогда: нужно одновременно
     уйти в самый край и посмотреть не туда, куда смотрит игра. */
  for (const u of [-1.5, -1, -0.5, 0, 0.5, 1, 1.5]) {
    const left = wallNearEdgeX(u, -1);
    const right = wallNearEdgeX(u, 1);
    check(`при u=${u} левый обрыв доходит до края кадра`, left <= 0,
      `ближний угол на ${left.toFixed(0)} px — слева видно небо`);
    check(`при u=${u} правый обрыв доходит до края кадра`, right >= VIEW.width,
      `ближний угол на ${right.toFixed(0)} px при ширине ${VIEW.width} — справа видно небо`);
  }

  /* ─── и та же дырка с ДАЛЬНЕГО конца ───

     Пол и обрывы кончались на `fogDistance` (30 м), а горизонт — на
     бесконечности. Между дальним краем пола и горизонтом оставался клин
     чистого неба шириной ровно в коридор на 30 метрах (65 px) и высотой до
     32 px. Он был там ВСЕГДА, при любом смещении, — но в середине кадра
     читается как даль, а при крайнем уезжает вбок от точки схода и становится
     виден как пустота сбоку от дальнего плана. Заметил заказчик; найдено
     пересчётом пикселей в браузере, потому что глазами это спорно.

     Чинится тем же приёмом, что ближний край: отрисовка идёт до `FAR_DRAW`, а
     не до `far`. Заливок это не добавляет — меняется только дальняя кромка
     тех же четырёхугольников, — а площади добавляет на тот самый клин,
     который и был дыркой.

     Проверяется не константа, а РИСУНОК: поддельный контекст ловит самую
     верхнюю точку пола, и она обязана подойти к горизонту ближе пикселя.
     Проверять константу значило бы поверить, что ею кто-то пользуется. */
  {
    const floorKeys = ['floorA', 'floorB', 'floorMid', 'floorFar'];
    const C = THEME.greenHill;
    const floors = new Set(floorKeys.map((k) => C[k]));
    for (const u of [-1.5, 0, 1.5]) {
      for (const v of [0, 0.6]) {
        const { shapes } = paintFrame({ u, v, travel: 30, elapsed: 30 });
        const tops = shapes.filter((f) => floors.has(f.style)).map((f) => f.minY);
        const top = Math.min(...tops);
        const hy = horizonY(camera(u, v));
        check(`при u=${u}, v=${v} пол доходит до горизонта`, top - hy < 1,
          `верх пола на ${top.toFixed(1)}, горизонт на ${hy.toFixed(1)} — `
          + `клин неба в ${(top - hy).toFixed(1)} px ниже горизонта`);
      }
    }
  }
});

// ─────────────────── звёзды и препятствия вместе ───────────────────

group('звёзды и препятствия', () => {
  /* Расписания колец и препятствий строились независимо, и это давало
     кольца, которые нельзя собрать, не ударившись. По журналу первого полного
     забега: одиннадцать колец ближе 0.35 с к препятствию, пять — ближе 0.1 с.
     Худший случай — кольцо на u = −0.89 в 0.07 с от приседа: присед и боковой
     наклон одновременно физически невозможны. */

  check('сдвиг кольца всегда сходится за один шаг', O.minGapS > 2 * VIEW.starGuardS,
    `minGapS ${O.minGapS} против удвоенного окна ${2 * VIEW.starGuardS}: `
    + 'при меньшем кольцо вытолкнется в следующее окно и ряд выродится');

  /* По ступеням: на верхней приседов больше, а значит больше и запретных
     окон (под приседом не висит ничего). Ряд колец от этого не вправе
     выродиться — иначе сложность молча отняла бы награду. */
  /* Замер прежнего правила: 101 кольцо за 300 секунд. Заморожен числом, а не
     вычислен из конфига, — иначе он поедет вместе с правкой и перестанет быть
     эталоном. */
  const ПОТОЛОК_КОЛЕЦ = 101;
  const счёт = [];
  /* По ВСЕМ пяти уровням, а не по краям. Прежде перебирались только нижний
     и верхний: с тремя средними, у каждого из которых теперь свой ряд колец
     и своя скорость, это значило бы не проверять три пятых игры. */
  for (let step = 0; step <= STEP_MAX; step++) {
  for (const crouch of [true, false]) {
    let bad = 0;
    let total = 0;
    let worst = null;
    for (let seed = 1; seed <= 100; seed++) {
      /* Разные сиды у препятствий и колец — не придирка. С одним сидом обе
         раскладки берут одну и ту же последовательность чисел, стороны колец
         оказываются связаны с видами препятствий, и перебор на сотне уровней
         обходит заметно меньше случаев, чем кажется. Дефект размещения,
         который виден только когда две случайности расходятся, такой перебор
         пропустил бы. */
      const obstacles = makeLevel({ durationS: 300, crouch, rng: seeded(seed * 7919), tune: tuneFor(step) });
      /* `tune` обязателен и ЗДЕСЬ. Без него ряд строился умолчаниями `VIEW`,
         то есть компенсатор `starGapS` своего уровня не применялся вовсе, и
         проверка «колец столько же» сравнивала два ряда, построенных по
         одним и тем же числам, — то есть не проверяла ничего. Поймано
         18 октября, когда у каждого уровня появился свой компенсатор. */
      const stars = makeStars({ durationS: 300, obstacles, rng: seeded(seed * 104729),
        tune: tuneFor(step) });
      total += stars.length;
      for (const s of stars) {
        if (starAllowed(s.at, s.side, obstacles)) continue;
        bad++;
        worst ??= `сид ${seed}: кольцо на ${s.at.toFixed(2)} с, сторона ${s.side}`;
      }
    }
    check(`ступень ${step}, ${crouch ? 'с приседами' : 'без приседов'}: ни одно кольцо не спорит с препятствием`,
      bad === 0, `${bad} нарушений, первое — ${worst}`);
    /* Сравнение идёт с ЗАМЕРЕННЫМ потолком, а не с рядом без препятствий.
       Прежде здесь стояло `> free * 0.7`, где `free` — ряд на пустом уровне, и
       это сломалось ровно тогда, когда шаг ряда пришлось уменьшить ради
       сохранения потолка: `free` вырос вместе с плотностью, порог уехал за ним,
       и проверка стала строже без всякой причины. Потолок же неподвижен — это
       замер прежнего правила, 101 кольцо за 300 секунд (см. группу «фразы
       колец», где он тоже заморожен числами). */
    счёт.push({ step, crouch, колец: total / 100 });
    check(`ступень ${step}, ${crouch ? 'с приседами' : 'без приседов'}: ряд колец не выродился`,
      total / 100 > ПОТОЛОК_КОЛЕЦ * 0.9,
      `осталось ${(total / 100).toFixed(1)} при замеренном потолке ${ПОТОЛОК_КОЛЕЦ}`);
  }
  }

  /* И колец на всех ступенях СТОЛЬКО ЖЕ. Таблица рекордов бьётся по длине
     забега, а не по ступени: разное число колец сделало бы забеги несравнимыми
     ровно по тому полю, ради которого таблица ведётся, а у ребёнка в ней уже
     лежит 88 колец за три минуты — упавший потолок сделал бы этот рекорд
     недостижимым навсегда. Держится это компенсатором `starGapS` в строке
     ступени, и подобран он замером, а не на глаз.

     Сравниваются ступени ПРИ ОДИНАКОВОМ наборе препятствий. Уровень без
     приседов — отладочный режим, и колец на нём меньше по построению: все
     препятствия боковые, то есть запретных окон закрытой стороны вдвое больше.
     Смешивать его со штатным значило бы выдавать разницу режимов за разницу
     ступеней. */
  for (const crouch of [true, false]) {
    const р = счёт.filter((x) => x.crouch === crouch).map((x) => x.колец);
    const мин = Math.min(...р);
    const макс = Math.max(...р);
    check(`колец на всех ступенях столько же (${crouch ? 'с приседами' : 'без приседов'})`,
      (макс - мин) / мин < 0.05,
      счёт.filter((x) => x.crouch === crouch).map((x) => `ст.${x.step} ${x.колец.toFixed(1)}`).join(', '));
  }

  // Само правило, поштучно: оно важнее числа прогонов.
  const duck = [{ at: 20, kind: 'duck', side: 0 }];
  check('под приседом не висит ничего', !starAllowed(20, 0, duck)
    && !starAllowed(20, 1, duck) && !starAllowed(19.5, -1, duck),
    'присед не совмещается ни с наклоном, ни с возвратом в центр');
  check('за окном приседа кольцо снова можно',
    starAllowed(20 + VIEW.starGuardS + 0.01, 1, duck));

  const right = [{ at: 30, kind: 'side', side: 1 }];
  check('у бокового препятствия кольцо есть только на открытой стороне',
    starAllowed(30, -1, right) && !starAllowed(30, 1, right) && !starAllowed(30, 0, right),
    'isSafe: side > 0 закрывает +x, значит открыта −1');

  /* ─── закрытой стороне нужно ВРЕМЯ ПЕРЕХОДА, а не окно уклонения ───

     Заказчик 11 октября: «препятствия по бокам снова стали накладываться на
     призовые предметы… физически времени может не хватить, чтобы собрать
     кольцо и не врезаться». Подтверждено журналом: из 145 колец сессии 21
     требовало перехода быстрее измеренного, и ровно это дало оба задетых
     препятствия — за первым стояло кольцо закрытой стороны в 1.04–1.64 с, и
     ребёнок шёл за ним, когда получил удар.

     Причина: окно `starGuardS` защищало УКЛОНЕНИЕ, а сдвиг ставил кольцо ровно
     на его кромку — 1.65 с. Препятствие согнало ребёнка на дорожку −1, кольцо
     закрытой стороны висит на +2, это три дорожки. А между двумя кольцами на
     разных боках тот же генератор отводит `starSwitchS` 3.0 с на четыре
     дорожки, то есть знает настоящую цену шага. Одно число было вдвое меньше
     другого в одном файле. */
  check('кольцо на закрытой стороне ждёт времени перехода',
    !starAllowed(30 + VIEW.starGuardS + 0.01, 1, right)
    && starAllowed(30 + VIEW.starSwitchS + 0.01, 1, right),
    'кромка окна уклонения — 1.65 с, а переход стоит 3.0 с');
  check('и зеркально, ДО препятствия',
    !starAllowed(30 - 2.0, 1, right) && starAllowed(30 - VIEW.starSwitchS - 0.01, 1, right),
    'уйти с закрытой стороны к приходу — тот же переход, только заранее');
  check('а открытой стороне переход не нужен вовсе',
    starAllowed(30, -1, right) && starAllowed(30 + 1.0, -1, right),
    'там уклонение и сбор совпадают — кольцо и есть награда за правильный уход');

  /* ─── ступень 0: спокойный ряд колец ───

     Требование заказчика от 11 октября, дословно: «на первом уровне сложности
     не должно быть резких перемещений из одного края в другой за кольцами и
     резких обходов препятствий, совмещённых со сбором кольца до препятствия
     или сразу после него».

     Переводится в три проверяемых утверждения. Рядом с препятствием на нулевой
     ступени тихо со ВСЕХ сторон, включая открытую. Переход стоит дороже
     измеренного впритык. И внутри серии препятствий боковых колец нет вовсе —
     там им попросту негде встать. */
  const ст0 = tuneFor(0);
  const ст1 = tuneFor(1);
  /* Спокойный ряд держится теперь на ДВУХ нижних уровнях, а не на одном:
     второй отличается от первого размахом и ценой перехода, но кольцо у
     препятствия на нём по-прежнему не ставится. Второй язык (кольца)
     добавляется к первому (уклонение) отдельным шагом — так и задумано. */
  const ст2 = tuneFor(2);
  check('ступень 0: у препятствия тихо и на открытой стороне',
    !starAllowed(30, -1, right, ст0) && !starAllowed(30, 1, right, ст0)
    && !starAllowed(30, 0, right, ст0),
    'сбор в уклонении — это два дела разом, а ступень 0 первая игра ребёнка');
  check('и на втором уровне тоже тихо',
    !starAllowed(30, -1, right, ст1),
    'второй уровень отличается размахом и ценой перехода, а не кольцом у препятствия');
  check('а на третьем открытая сторона снова награда',
    starAllowed(30, -1, right, ст2),
    'кольцо за правильный уход — хорошая мысль, её отменять только на двух нижних');
  check('переход дешевеет ступенями, но не ниже измеренного',
    ст0.starSwitchScale > ст1.starSwitchScale && ст1.starSwitchScale > ст2.starSwitchScale
    && ст2.starSwitchScale === 1,
    `${ст0.starSwitchScale} → ${ст1.starSwitchScale} → ${ст2.starSwitchScale}`);
  check('и шаг ряда у каждого уровня свой — это компенсатор потолка колец',
    new Set([ст0, ст1, ст2].map((t) => t.starGapS)).size === 3,
    'без него спокойный ряд стоил бы ребёнку колец, а значит и рекорда');

  /* Главное из трёх — и проверяется оно на РАССТАВЛЕННОМ ряде, а не на
     правиле: правило разрешает боковое кольцо вдали от препятствий, а «вдали»
     внутри серии почти не существует. Считаем по сотне сеяных уровней. */
  {
    let вСерииБоковых = 0;
    let вСерииВсего = 0;
    let переходовРезких = 0;
    for (let seed = 1; seed <= 100; seed++) {
      const ob = makeLevel({ durationS: 300, crouch: true, rng: seeded(seed * 7919), tune: ст0 });
      const st = makeStars({ durationS: 300, obstacles: ob, rng: seeded(seed * 104729), tune: ст0 });
      const вПередышке = (t) => {
        let prev = null;
        for (const o of ob) { if (o.at > t) return prev === null ? true : o.at - prev >= ст0.breatherS; prev = o.at; }
        return true;
      };
      for (let i = 0; i < st.length; i++) {
        if (!вПередышке(st[i].at)) { вСерииВсего++; if (st[i].side !== 0) вСерииБоковых++; }
        if (i === 0) continue;
        const смена = st[i].side !== 0 && st[i - 1].side !== 0 && st[i].side !== st[i - 1].side;
        if (смена && st[i].at - st[i - 1].at < VIEW.starSwitchS * ст0.starSwitchScale - 1e-9) переходовРезких++;
      }
    }
    check('ступень 0: в серии препятствий боковых колец почти нет',
      вСерииБоковых / вСерииВсего < 0.05,
      `${(вСерииБоковых / вСерииВсего * 100).toFixed(1)}% из ${вСерииВсего} колец серии`);
    check('ступень 0: ни одного резкого перехода из края в край',
      переходовРезких === 0,
      `${переходовРезких} переходов быстрее ${(VIEW.starSwitchS * ст0.starSwitchScale).toFixed(2)} с`);
  }

  /* И окно не вправе быть короче того, что требует ГЕОМЕТРИЯ — на любой
     ступени. Иначе правка `blockFrac` или `starX` однажды молча вернёт дефект:
     порог ухода растёт со ступенью, то есть переход становится длиннее.

     `starCentreU` — смещение, на котором кольцо приходится ровно под руку;
     `starSwitchS` измерен как переход от кольца до кольца, то есть на двойное
     это смещение. Порог ухода в тех же единицах равен `blockFrac` — ход камеры
     линеен по u, и доля хода это та же доля u. */
  const starCentreU = (() => {
    const x = VIEW.starX * CORRIDOR_HALF;
    let best = Infinity; let at = 0;
    for (let u = 0; u <= 2.0001; u += 0.001) {
      const d = Math.abs(x - cameraX(u));
      if (d < best) { best = d; at = u; }
    }
    return at;
  })();
  const скоростьU = (2 * starCentreU) / VIEW.starSwitchS; // размах колец за измеренное время
  for (const step of [0, STEP_MAX]) {
    const нужно = (tuneFor(step).blockFrac + starCentreU) / скоростьU;
    check(`ступень ${step}: окна закрытой стороны хватает на переход`,
      VIEW.starSwitchS >= нужно,
      `нужно ${нужно.toFixed(2)} с от дорожки ухода до кольца, дано ${VIEW.starSwitchS}`);
  }

  /* Дотягивание. Четыре неравенства, и важны они все четыре сразу: смысл игры
     в том, что ребёнок двигается. Числа пересчитаны по журналу — прежние
     требовали u ≥ 0.643 при центре кольца на u = 1.58, то есть за пределами
     полного размаха, и взрослый добирал боковые кольца, вываливаясь из кадра
     (три паузы «ты у самого края»). */
  const starX = VIEW.starX * CORRIDOR_HALF;
  check('боковое кольцо стоя не собрать', !canReach(starX, 0),
    `кольцо на ${starX.toFixed(3)} м при допуске ${VIEW.starReach}`);
  check('центральное кольцо в наклоне не собрать', !canReach(0, 1),
    `ход камеры ${cameraX(1).toFixed(3)} м`);
  check('боковое кольцо в наклоне собирается', canReach(starX, 0.85));

  let minU = null;
  let centre = 0;
  let best = Infinity;
  for (let u = 0; u <= 2.0001; u += 0.001) {
    if (canReach(starX, u) && minU === null) minU = u;
    const d = Math.abs(starX - cameraX(u));
    if (d < best) { best = d; centre = u; }
  }
  check('дотянуться хватает трети размаха', minU > 0.25 && minU < 0.45,
    `требуется u ≥ ${minU?.toFixed(3)}`);
  check('за край кадра тянуться не надо', centre < 1,
    `центр кольца приходится на u = ${centre.toFixed(3)}, а у кадра край около 1.41`);
});

// ──────────────────────── игроки и рекорды ────────────────────────

/* Кольца и очки — два разных числа, и один счётчик на оба врал.

   В журнале 7 октября 90 событий сбора кольца, а в результате и в рекорде
   88: `score = Math.max(0, score - starsLost)` вычитал два кольца за задетое
   препятствие из того же счётчика, которым считается собранное. Экран
   результата говорил «88 колец из 100», то есть называл кольцами очки, и из
   ста колец недобранными выглядели двенадцать вместо десяти. Рекорды разных
   забегов становились несравнимы ровно по тому полю, ради которого таблица и
   ведётся. Забег взрослого (102 из 130, два задетых) занижен так же, на 4.

   Отнимание кольца за удар — решение заказчика, оно остаётся: счётчик в HUD
   уходит вниз, и это обратная связь. Врала не она, а то, что собранное и
   очки назывались одним словом. */
group('кольца и очки', () => {
  const t = makeTally({ starsLost: 2 });
  check('пустой счёт', t.collected === 0 && t.score === 0 && t.hits === 0);

  for (let i = 0; i < 5; i++) t.star();
  check('кольцо растит оба числа', t.collected === 5 && t.score === 5);

  t.hit();
  check('удар отнимает очки', t.score === 3);
  check('а собранного не отнимает', t.collected === 5,
    'иначе «X из Y» снова начнёт называть кольцами очки');
  check('удар посчитан', t.hits === 1);

  /* Нижний зажим очков — тоже обратная связь, а не арифметика: ниже нуля
     счётчик в HUD опускаться не должен. Собранное зажимать нечем и незачем. */
  const z = makeTally({ starsLost: 2 });
  z.star();
  z.hit();
  check('очки не уходят ниже нуля', z.score === 0);
  check('а собранное цело и при нулевых очках', z.collected === 1);

  /* Числа ровно из журнала: 90 собранных, одно задетое, HUD показал 88. */
  const real = makeTally({ starsLost: 2 });
  for (let i = 0; i < 90; i++) real.star();
  real.hit();
  check('журнал 7 октября сходится', real.collected === 90 && real.score === 88,
    `получилось ${real.collected} и ${real.score}`);

  /* Прощённые — ЧЕТВЁРТОЕ число, и оно ничего не трогает в первых трёх.

     Для ребёнка прощённое препятствие пройдено: очки целы, вспышки нет. Для
     ступени сложности это единственный датчик того, что запас времени
     кончился, и перепутать его с ударом значило бы наказывать дважды. */
  const пр = makeTally({ starsLost: 2 });
  пр.star();
  пр.forgive();
  check('прощённое не трогает ни очки, ни собранное',
    пр.score === 1 && пр.collected === 1);
  check('и задетым не считается', пр.hits === 0);
  check('но считается отдельно', пр.grace === 1);

  const r = makeTally({ starsLost: 2 });
  for (let i = 0; i < 3; i++) r.star();
  r.hit();
  r.forgive();
  r.reset();
  check('сброс обнуляет все четыре числа',
    r.collected === 0 && r.score === 0 && r.hits === 0 && r.grace === 0);
  /* ─── большое кольцо ───

     Вес уходит в ОЧКИ, а собранное считается штуками, и это не мелочь:
     `collected` идёт в «X из Y колец» на экране результата и в рекорд, а
     знаменателем там `stars.length` — тоже штуки. Прибавь вес к собранному, и
     строка начнёт говорить «102 из 100». Ровно этот класс ошибки — один
     счётчик на два смысла — здесь уже случался 7 октября. */
  const веса = makeTally({ starsLost: 2 });
  веса.star();
  веса.star(VIEW.bigStarWorth);
  check('большое кольцо — одна штука', веса.collected === 2, `${веса.collected}`);
  check('а очков за него больше', веса.score === 1 + VIEW.bigStarWorth, `${веса.score}`);
  check('большое кольцо стоит дороже обычного', VIEW.bigStarWorth > 1);
  check('и выглядит крупнее', VIEW.bigStarScale > 1,
    'иначе о его ценности ребёнок узнаёт только ПОСЛЕ сбора, из звука');
  /* Но не крупнее ОКНА СБОРА. При множителе 1.7 нарисованный рим выходил за
     него на 12 миллиметров: ребёнок видел, что задевает кольцо, а оно не
     собиралось. Это то же расхождение отрисовки и правила, из-за которого
     край препятствия берётся из одного места, — только наоборот. */
  check('большое кольцо не выходит за окно сбора',
    VIEW.starDrawR * VIEW.bigStarScale < VIEW.starReach,
    `рим ${(VIEW.starDrawR * VIEW.bigStarScale).toFixed(3)} против окна ${VIEW.starReach}`);
  check('а обычное тем более', VIEW.starDrawR < VIEW.starReach,
    'у обычного окно шире нарисованного, и это запас на промах');
  const без = makeTally({});
  без.star();
  check('вызов без веса остался прежним', без.collected === 1 && без.score === 1,
    'старый вызов обязан значить ровно то же, что значил');

  check('сброс обнуляет всё три числа',
    r.collected === 0 && r.score === 0 && r.hits === 0,
    'иначе следующий забег начнётся с чужого счёта');
});

group('игроки', () => {
  /* Калибровка и рекорды принадлежат игроку, а не телефону: взрослый 173 см и
     ребёнок 100–130 см затирали её друг другу, и второй проходил двадцать
     секунд калибровки заново при каждом забеге. */

  check('имя сжимает пробелы', normalizeName('  Богдан   И. ') === 'Богдан И.');
  check('имя обрезается по потолку', normalizeName('а'.repeat(40)).length === NAME_MAX);
  check('обрезка не оставляет пробел на конце',
    normalizeName('Богдан Иван Петров') === 'Богдан Иван',
    `получилось «${normalizeName('Богдан Иван Петров')}»`);
  check('пустое имя не имя', normalizeName('   ') === '');
  check('имя из пробелов не создаёт игрока', players.add('   ') === null);

  const a = players.add('Богдан');
  check('новый игрок создан', a?.created === true && a.name === 'Богдан');
  const again = players.add('богдан');
  check('то же имя в другом регистре — тот же игрок', again?.created === false && again.id === a.id,
    'иначе «Богдан» и «богдан» разойдутся двумя таблицами и двумя калибровками');

  const b = players.add('Рома');
  check('второй игрок создан и выбран', players.current()?.id === b.id);

  /* Подпись под результатом — не смена игрока. Экран на финише спрашивает
     «чей это результат», и если он заодно переключит игрока, то у ребёнка
     следующий забег начнётся с двадцати секунд калибровки по пустому профилю
     гостя — ровно то, ради устранения чего профили и заводились. */
  const гость = players.add('Гость', { select: false });
  check('подпись не переключает игрока', players.current()?.id === b.id,
    `играет ${players.name()}, а должен Рома`);
  check('подписанный игрок всё равно создан', !!гость && гость.created === true);
  players.addRecord({ playerId: гость.id, durationS: 60, stars: 7, starsTotal: 9, hits: 1 });
  check('запись ушла подписанному, а не текущему',
    players.records(60)[0]?.name === 'Гость');

  /* Калибровка не должна течь между игроками — это и есть причина, по которой
     профили появились. */
  players.saveCalibration({ neutralX: 0.5, S0: 0.28 });
  players.select(a.id);
  check('калибровка одного игрока не видна другому', players.loadCalibration() === null);
  players.select(b.id);
  check('своя калибровка на месте', players.loadCalibration()?.S0 === 0.28);

  check('последнего игрока удалить нельзя', (() => {
    const ids = players.all().map((p) => p.id);
    for (const id of ids) players.remove(id);
    return players.all().length === 1;
  })(), 'пустой список заставил бы перенос создать «Игрок 1» с чужой калибровкой');

  // ── порядок в таблице ──
  const rows = [
    { at: 10, stars: 5, hits: 1 },
    { at: 20, stars: 5, hits: 0 },
    { at: 30, stars: 9, hits: 3 },
    { at: 40, stars: 5, hits: 0 },
  ];
  const ranked = rankRecords(rows);
  check('больше колец — выше', ranked[0].stars === 9);
  check('при равных кольцах выше меньше задетых', ranked[1].hits === 0);
  check('при полном равенстве свежее выше', ranked[1].at === 40);
  check('сортировка не портит исходный массив', rows[0].at === 10);

  /* Вытесняется ХУДШАЯ запись, а не самая старая: иначе десяток рутинных
     забегов вынес бы собственно рекорд, ради которого таблица и существует. */
  const many = Array.from({ length: 60 }, (_, i) => ({ at: i, stars: i, hits: 0, durationS: 300 }));
  const capped = capRecords(many, 10);
  check('потолок соблюдён', capped.length === 10);
  check('рекорд выживает при переполнении', rankRecords(capped)[0].stars === 59);
  check('вытесняется худшее, а не старейшее', capped.every((r) => r.stars >= 50),
    `в обрезке осталось ${capped.map((r) => r.stars).join(',')}`);

  /* И потолок действует ВНУТРИ длины, а не поперёк. Иначе пятьдесят
     пятиминутных забегов по сотне колец вытеснили бы первый же трёхминутный с
     шестьюдесятью — молча, в момент записи, и таблица трёх минут осталась бы
     пустой навсегда. Это та же ошибка, от которой уберегает rankRecords. */
  const смешанные = capRecords(
    [...many, { at: 99, stars: 60, hits: 0, durationS: 180 }], 10,
  );
  check('короткий забег не вытесняется длинными',
    смешанные.some((r) => r.durationS === 180),
    'потолок применён поперёк длин — запись пропала в момент записи');
  check('потолок считается по каждой длине отдельно',
    смешанные.filter((r) => r.durationS === 300).length === 10);

  // ── таблицы на длину забега ──
  const me = players.current().id;
  players.addRecord({ durationS: 300, stars: 102, starsTotal: 130, hits: 2 });
  players.addRecord({ durationS: 180, stars: 70, starsTotal: 80, hits: 0 });
  const five = players.records(300);
  check('в таблице только своя длина', five.length === 1 && five[0].stars === 102,
    'сырые кольца за пять минут и за три несравнимы');
  check('имя приклеивается при чтении, а не хранится в записи',
    five[0].name === players.name() && five[0].playerId === me,
    'иначе переименование игрока не переименует его прошлые рекорды');
  const длины = players.lengths();
  check('длины перечислены и упорядочены',
    длины.includes(180) && длины.includes(300)
    && длины.every((v, i) => i === 0 || длины[i - 1] < v),
    'получилось ' + длины.join(','));
  check('без колец запись не создаётся', players.addRecord({ durationS: 300 }) === null);

  /* Записи, сделанные до разделения колец и очков, обязаны стать сравнимыми с
     новыми, а не остаться заниженными.

     В старой записи одно поле значило очки, то есть собранное минус отнятое за
     удары; число задетых лежит там же. Значит собранное восстанавливается
     точно: `очки + задетые × 2`. Это не догадка — проверено на всех трёх
     дошедших до финиша забегах в журналах: 102+2×2 = 106, 84+2×2 = 88,
     88+1×2 = 90, и каждое совпало с настоящим числом событий сбора кольца.

     Не восстанови — и таблица начнёт мешать две разные величины через границу
     правки: забег ребёнка 7 октября навсегда остался бы «88 из 100», а
     точно такой же новый написал бы «90 из 100» и обошёл бы его в рекордах.
     Это ровно та несравнимость, ради устранения которой всё и делалось. */
  for (const [очки, задето, собрано] of [[102, 2, 106], [84, 2, 88], [88, 1, 90]]) {
    const m = migrateRecord({ durationS: 300, stars: очки, starsTotal: 130, hits: задето });
    check(`старая запись ${очки} при ${задето} задетых — это ${собрано} колец`,
      m.stars === собрано && m.score === очки,
      `получилось кольца ${m.stars}, очки ${m.score}`);
  }
  check('запись без задетых не меняется вовсе',
    (() => {
      const m = migrateRecord({ durationS: 300, stars: 70, starsTotal: 80, hits: 0 });
      return m.stars === 70 && m.score === 70;
    })(),
    'при нуле задетых очки и кольца совпадают по построению');
  check('новая запись не переписывается второй раз',
    (() => {
      const m = migrateRecord({ durationS: 300, stars: 90, score: 88, starsTotal: 100, hits: 1 });
      return m.stars === 90 && m.score === 88;
    })(),
    'повторная миграция накручивала бы кольца при каждом чтении');

  /* В рекорде живут ОБА числа. Кольца — то, по чему таблица сравнивает забеги;
     очки — то, что ребёнок видел в HUD на финише, и без них журнал не может
     объяснить ту цифру. Числа из журнала 7 октября: собрано 90, задето одно,
     на экране было 88. */
  const оба = players.addRecord({
    durationS: 300, stars: 90, score: 88, starsTotal: 100, hits: 1,
  });
  check('рекорд помнит собранные кольца', оба?.stars === 90);
  check('и очки отдельным полем', оба?.score === 88,
    'иначе цифру с экрана ребёнка потом нечем объяснить');
  check('старая запись без очков не ломается',
    players.addRecord({ durationS: 300, stars: 70, starsTotal: 80, hits: 0 })?.score === 70,
    'забеги до этой правки хранили очки в поле колец — это и есть их очки');

  /* ── копилка ──

     Копилка — СОБСТВЕННОЕ число игрока, а не сумма по таблице рекордов, и
     проверяется здесь именно это. Сумма по таблице занижала бы: в таблицу
     попадает только забег, который нажали «Записать», а `capRecords`
     вытесняет из неё худшие записи. Число, которое врёт, на экране результата
     хуже отсутствующего. */
  {
    const было = players.bank();
    players.addToBank(12);
    players.addToBank(7);
    check('копилка складывает забеги', players.bank() === было + 19,
      `было ${было}, стало ${players.bank()}`);
    const после = players.bank();
    players.addToBank(0);
    players.addToBank(-5);
    players.addToBank(NaN);
    players.addToBank(undefined);
    check('и не принимает мусор', players.bank() === после,
      'ноль, минус и NaN обязаны оставить копилку как есть, а не обнулить её');

    /* У каждого своя. За один телефон играют двое, и общий счёт не сказал бы
       ничего ни одному из них — та же причина, по которой у игрока своя
       калибровка и своя таблица. */
    const другой = players.add('Копилка-2');
    check('у нового игрока копилка пустая', players.bank() === 0);
    players.addToBank(5);
    players.select(me);
    check('и копилка соседа не видна', players.bank() === после);
    players.select(другой.id);
    check('а своя на месте', players.bank() === 5);

    check('копилка видна в карточке игрока',
      players.all().every((p) => Number.isFinite(p.bank)),
      'экран «кто играет» показывает её рядом с числом забегов');

    /* ── ступень сложности у игрока ──

       У каждого своя, как калибровка и рекорды, и по той же причине: взрослый
       173 см проходит забег чисто, ребёнок учится. Общая ступень означала бы,
       что один вечер игры взрослого делает игру ребёнка труднее. */
    check('у нового игрока ступень нулевая', players.step() === 0);
    players.setStep(2);
    check('ступень сохраняется', players.step() === 2);
    players.setStep(-1);
    players.setStep(1.5);
    players.setStep('три');
    check('и не принимает мусор', players.step() === 2,
      'отрицательное, дробное и строка обязаны оставить ступень как есть');
    players.select(me);
    check('ступень соседа не видна', players.step() === 0);
    /* Потолка хранилище не знает нарочно: длина таблицы ступеней — дело
       js/difficulty.js, и зажим живёт там. Здесь проверяется только, что
       хранилище не выдумывает своего. */
    players.setStep(99);
    check('хранилище своего потолка не выдумывает', players.step() === 99);
    check('а зажимает его difficulty.js', clampStep(99) === STEP_MAX);
    players.setStep(0);

    /* Запись рекорда помнит ступень, а старая запись НЕ получает нуль:
       отсутствие поля значит «сделана до тихой адаптации», и нулём это
       значило бы, что прошлые рекорды поставлены на самой лёгкой. */
    const сступенью = players.addRecord({ durationS: 300, stars: 10, starsTotal: 20, hits: 0, step: 3 });
    check('рекорд помнит ступень', сступенью?.step === 3);
    const без = players.addRecord({ durationS: 300, stars: 10, starsTotal: 20, hits: 0 });
    check('а запись без ступени не получает нуль', без && без.step === undefined,
      'ноль значил бы «поставлен на лёгкой», а он поставлен неизвестно на какой');
    /* А что копилка переживает ПЕРЕЧИТЫВАНИЕ хранилища, отсюда проверить
       нечем: в node хранилища нет вовсе, и `reload()` там честно возвращает
       пустое состояние. Профиль в `read()` собирается полями поимённо, и
       забытое поле теряется молча — поэтому сторож на это стоит текстом, в
       группе «копилка» набора оболочки. */
  }
});

// ─────────────────── разбор журнала с телефона ───────────────────

/* Журнал — единственный свидетель забега с ребёнком, и глазами его не прочесть:
   565 КБ и до двадцати сессий в одном файле. Разбор проверяется на
   СИНТЕТИЧЕСКИХ журналах, собранных здесь же: настоящие лежат вне репозитория
   по той же причине, по которой они в .gitignore — это запись о ребёнке. */

function сессия(log, id = 1759772363000) {
  return { id, startedAt: '2026-10-06T18:19:23.000Z', ua: 'Android', events: log.length, bytes: 0, log };
}

/* Полный забег: два окна здоровья с разными квантилями, 44 препятствия,
   четыре паузы и финиш. Числа взяты из журнала второго детского сеанса. */
function забегДоФиниша() {
  const log = [
    { t: 0, type: 'run.start', durationS: 300, obstacles: 44, stars: 103 },
    { t: 1000, type: 'pose.ready', pipeline: 'stream', delegate: 'GPU', initMs: 3300, warmupP50: 18 },
    { t: 2000, type: 'health', stage: 'run', fps: 38, hz: 11, drop: 0, ok: 0.9, vis: 0.8,
      S: 0.4, p50: 88, p95: 104, draw50: 0, draw95: 1, u: 0.2, v: 0, panSpan: 0.42 },
    { t: 4000, type: 'health', stage: 'run', fps: 36, hz: 10, drop: 2, ok: 0.88, vis: 0.78,
      S: 0.41, p50: 104, p95: 120, draw50: 1, draw95: 11, u: 0.3, v: 0, panSpan: 0.42 },
    { t: 10050, type: 'samples', n: 40, rows: [[1, 0.2, 0, 0.4, 0.9], [2, 0.3, 0.1, 0.4, 0.9]] },
  ];
  // Препятствия: 40 пройдено чисто, 2 прощено, 2 задето — всего 44.
  let t = 11000;
  for (let i = 0; i < 40; i++) log.push({ t: (t += 100), type: 'obstacle', kind: 'low', side: 1, result: 'clear', camX: 0.3 });
  for (let i = 0; i < 2; i++) log.push({ t: (t += 100), type: 'obstacle', kind: 'low', side: 1, result: 'grace', camX: 0.1 });
  for (let i = 0; i < 2; i++) log.push({ t: (t += 100), type: 'obstacle', kind: 'side', side: -1, result: 'hit', camX: 0 });
  // Паузы: scale 4 с, scale 2 с, edge 3 с, manual 1 с — всего 10 с.
  log.push({ t: 100000, type: 'pause', why: 'scale', vis: 0.3, S: 0.2, cx: 0.5, lostMs: 700 });
  log.push({ t: 104000, type: 'resume' });
  log.push({ t: 120000, type: 'pause', why: 'scale', vis: 0.3, S: 0.2, cx: 0.4, lostMs: 700 });
  log.push({ t: 122000, type: 'resume' });
  log.push({ t: 130000, type: 'pause', why: 'edge', vis: 0.9, S: 0.4, cx: 0.9, lostMs: 700 });
  log.push({ t: 133000, type: 'resume' });
  log.push({ t: 140000, type: 'pause', why: 'manual', elapsed: 140 });
  log.push({ t: 141000, type: 'resume' });
  log.push({ t: 300000, type: 'run.finish', stars: 84, starsTotal: 103, hits: 2, durationS: 300 });
  return сессия(log);
}

/* Первый детский сеанс: калибровка упала потоком одинаковых ошибок, забег
   брошен, журнал снят со сборки до нормировки игрового поля. */
function забегБрошен() {
  return сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 44, stars: 103 },
    { t: 1200, type: 'error', where: 'frame', message: 'uEnter of null', _n: 1478, _lastT: 134200 },
    { t: 2000, type: 'health', stage: 'calibrate', fps: 30, hz: 11, drop: 0, ok: 0.9,
      vis: 0.8, S: 0.53, p50: 90, p95: 110, draw50: 0, draw95: 1, u: 0.1, v: 0 },
    { t: 5000, type: 'pause', why: 'scale', vis: 0.2, S: 0.1, cx: 0.5, lostMs: 700 },
  ], 1759700000000);
}

group('разбор журнала', () => {
  /* Кольца и очки разведены с 7 октября, и разбор обязан их различать: без
     этого сводка снова называла бы кольцами очки, а замеры делаются как раз
     по сводке. У журналов, снятых раньше, поля очков нет вовсе — и тогда
     печатать «колец» нельзя, потому что при задетых препятствиях это очки. */
  const сОчками = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 43, stars: 100 },
    { t: 300000, type: 'run.finish', stars: 90, score: 88, starsTotal: 100, hits: 1, durationS: 300 },
  ]));
  check('собранные кольца берутся из stars', сОчками.run.stars === 90);
  check('очки читаются отдельно', сОчками.run.score === 88);
  check('доля считается по кольцам, а не по очкам', сОчками.run.ringPct === 90,
    'иначе удар занижал бы собираемость, которой он не касается');
  check('сводка печатает оба числа',
    /90 колец из 100 \(90%\)/.test(format(сОчками)) && /88 очк/.test(format(сОчками)),
    format(сОчками).split('\n').filter((l) => l.includes('забег')).join(''));

  const безОчков = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 43, stars: 100 },
    { t: 300000, type: 'run.finish', stars: 88, starsTotal: 100, hits: 1, durationS: 300 },
  ]));
  check('у старого журнала очков нет', безОчков.run.score === null);
  check('и сводка предупреждает, что кольца там — очки',
    безОчков.notes.some((n) => /очк/.test(n)),
    'получилось: ' + безОчков.notes.join(' | '));

  /* Политика экрана телефона едет в run.start, иначе два забега одной сессии
     в журнале неразличимы — а замер в том и состоит, чтобы сравнить их между
     собой внутри одной сессии: разброс устройства ±8 fps живёт как раз между
     сессиями. */
  const гаснет = report(сессия([
    { t: 0, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, screenRun: 'sleep' },
    { t: 60000, type: 'run.finish', stars: 18, score: 18, starsTotal: 20, hits: 0, durationS: 60 },
  ]));
  check('политика экрана прочитана', гаснет.run.screenRun === 'sleep');
  /* Названа именно ПРОСЬБОЙ. Прежнее «экран не гаснет» читалось как
     наблюдение, и 8 октября сводка этим словом соврала: экран гас в обоих
     забегах, включая тот, где просили не гаснуть. */
  check('и названа в сводке как просьба, а не как факт',
    /просили гаснуть/.test(format(гаснет)),
    format(гаснет).split(String.fromCharCode(10)).filter((l) => /просил/.test(l)).join('') || '(строки нет)');

  /* А факт — отдельно, из событий блокировки. Иначе «настройка не работает»
     нечем отличить от «система отбирает блокировку сразу после выдачи»: ровно
     на этом разборе 8 октября журнал и кончился догадками. */
  const отобрали = report(сессия([
    { t: 0, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, screenRun: 'awake' },
    { t: 1000, type: 'wakelock', got: false, released: true, why: 'system' },
    { t: 6000, type: 'wakelock', got: true, why: 'regain' },
    { t: 7000, type: 'wakelock', got: false, released: true, why: 'system' },
    { t: 60000, type: 'run.finish', stars: 18, score: 18, starsTotal: 20, hits: 0, durationS: 60 },
  ]));
  check('потеря блокировки посчитана', отобрали.runs[0].wakeLost === 2,
    JSON.stringify(отобрали.runs[0]));
  check('и возврат тоже', отобрали.runs[0].wakeRegained === 1);
  check('сводка говорит о потере вслух', /блокировка: потеряна 2, взята заново 1/.test(format(отобрали)),
    format(отобрали).split(String.fromCharCode(10)).filter((l) => /блокировк/.test(l)).join('') || '(строки нет)');
  check('а когда не теряли — молчит', !/блокировка/.test(format(гаснет)));

  /* Зоны и большие кольца — проверка замысла, а не украшение сводки: зоны
     обязаны смениться все, большие кольца обязаны встречаться. У журналов до
     этих правок полей нет, и строк быть не должно — «0 больших» читался бы как
     «ни одного не собрал», а не «их в игре ещё не было». */
  const путешествие = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 40, stars: 100 },
    { t: 1000, type: 'zone', zone: 'greenHill', at: 1 },
    { t: 100000, type: 'zone', zone: 'sunsetDunes', at: 100 },
    { t: 200000, type: 'zone', zone: 'nightHills', at: 200 },
    { t: 50000, type: 'star', side: 1, u: 0.5, worth: 3 },
    { t: 60000, type: 'star', side: -1, u: 0.5, worth: 1 },
    { t: 70000, type: 'star', side: 1, u: 0.5, worth: 3 },
    { t: 300000, type: 'run.finish', stars: 90, score: 94, starsTotal: 100, hits: 0, durationS: 300 },
  ]));
  check('зоны собраны в том порядке, в каком их видели',
    путешествие.zones.join(' ') === 'greenHill sunsetDunes nightHills',
    путешествие.zones.join(' '));
  check('и сводка печатает цепочку',
    /зоны: greenHill → sunsetDunes → nightHills/.test(format(путешествие)));
  check('большие кольца посчитаны', путешествие.bigStars === 2, `${путешествие.bigStars}`);
  check('и напечатаны рядом с кольцами',
    /из них больших: 2/.test(format(путешествие)));
  check('у журнала без зон строки про зоны нет', !/зоны:/.test(format(гаснет)));
  check('и без больших колец — строки про большие',
    !/из них больших/.test(format(гаснет)),
    '«0 больших» читался бы как «ни одного не собрал»');

  /* ─── хранилище ───

     Повод: игрок и рекорды сбрасывались между сеансами. Наш код их не чистит,
     а хранилище, не помеченное постоянным, браузер вправе вытеснить ЦЕЛИКОМ —
     одним origin, вместе с офлайн-кэшем и localStorage. Приложение занимает
     порядка 42 МБ, поводов у него достаточно. Разбор обязан показать три числа
     вместе: вытесняемы ли мы, сколько занято и какая это доля квоты. */
  const вытесняемое = report(сессия([
    { t: 100, type: 'storage', usageMb: 41, quotaMb: 120, pct: 34 },
    { t: 110, type: 'storage.state', persisted: false },
    { t: 2000, type: 'storage.persist', granted: false },
  ]));
  check('состояние хранилища собрано', вытесняемое.storage?.persisted === false
    && вытесняемое.storage?.usageMb === 41 && вытесняемое.storage?.pct === 34,
    JSON.stringify(вытесняемое.storage));
  check('и сводка называет вытесняемое вытесняемым',
    /хранилище: ВЫТЕСНЯЕМОЕ.*занято 41 МБ из 120 \(34%\).*отказали/.test(format(вытесняемое)),
    format(вытесняемое).split(String.fromCharCode(10)).filter((l) => /хранилище/.test(l)).join('') || '(строки нет)');

  const постоянное = report(сессия([
    { t: 100, type: 'storage', usageMb: 41, quotaMb: 120, pct: 34 },
    { t: 110, type: 'storage.state', persisted: true },
    { t: 2000, type: 'storage.persist', granted: true },
  ]));
  check('постоянное названо постоянным',
    /хранилище: постоянное/.test(format(постоянное))
    && !/ВЫТЕСНЯЕМОЕ/.test(format(постоянное)));

  /* Перечитанный ноль надо НАЗЫВАТЬ. 11 октября замер на 11-й миллисекунде
     сказал «занято 0 МБ», и сводка повторила это как факт — хотя кэш был цел.
     Замер теперь перечитывает такой ноль и пишет, сколько попыток ушло; если
     сводка об этом молчит, починка неотличима от «получилось сразу», и
     следующий такой ноль опять уедет в разбор как вытеснение. */
  const переcпросили = report(сессия([
    { t: 300, type: 'storage', usageMb: 19, quotaMb: 10259, pct: 0, tries: 3 },
    { t: 110, type: 'storage.state', persisted: true },
  ]));
  check('сводка говорит, что занятое перечитывали',
    /занято 19 МБ из 10259 \(0%\), с 3-й попытки/.test(format(переcпросили)),
    format(переcпросили).split(String.fromCharCode(10)).filter((l) => /хранилище/.test(l)).join('') || '(строки нет)');
  check('а с первой попытки про попытки молчит',
    !/попытк/.test(format(постоянное)),
    'обычный случай не должен обрастать словами');
  check('у журнала без поля tries попыток тоже нет',
    !/попытк/.test(format(вытесняемое)),
    'журналы до правки поля не несут, и выдумывать «с 1-й попытки» нельзя');

  /* У журналов до этой правки полей нет, и строки быть не должно: «вытесняемое,
     занято 0 МБ» читалось бы как замеренный факт. Та же осторожность, из-за
     которой разбор однажды соврал, напечатав просьбу «экран не гаснет» вместо
     того, что случилось с экраном. */
  check('у старого журнала строки про хранилище нет',
    !/хранилище/.test(format(гаснет)) && report(сессия([])).storage === null);

  /* ── офлайн-комплект: пропажа, починка и сборка ──

     10 октября журнал четыре сессии подряд писал `ok: true` при отсутствующем
     комплекте: «кэш ещё не создан» значило и первый запуск, и вытеснение.
     Разбор обязан называть эти два состояния РАЗНЫМИ словами, иначе следующая
     такая сессия снова прочитается как «всё хорошо». */
  const пропал = report(сессия([
    { t: 90, type: 'build', version: 'run-v99', builtAt: '2026-10-11 09:00', controlled: true },
    { t: 4000, type: 'offline.check', ok: false, gone: true, caches: [], missing: [] },
    { t: 9000, type: 'offline.repair', asked: true, ok: true, missing: [], ms: 21000 },
  ]));
  check('пропажа комплекта собрана', пропал.offline?.gone === true
    && пропал.offline?.repaired === true, JSON.stringify(пропал.offline));
  check('и сводка называет пропажу пропажей',
    /офлайн-комплект: ПРОПАЛ.*добран за 21000 мс/.test(format(пропал)),
    format(пропал).split(String.fromCharCode(10)).filter((l) => /офлайн/.test(l)).join('') || '(строки нет)');
  check('сборка печатается', /сборка run-v99 от 2026-10-11 09:00.*ведёт воркер/.test(format(пропал)),
    'без неё журнал не отнести к коду');

  const неДобрали = report(сессия([
    { t: 4000, type: 'offline.check', ok: false, gone: true, caches: [], missing: [] },
    { t: 9000, type: 'offline.repair', asked: true, ok: false, missing: ['vendor/x.task'], ms: 60000 },
  ]));
  check('неудавшийся добор назван неудавшимся',
    /ПРОПАЛ.*добрать не удалось/.test(format(неДобрали)),
    'иначе «попросили» неотличимо от «починили»');

  check('у старого журнала строк про комплект и сборку нет',
    report(сессия([])).offline === null && report(сессия([])).build === null);

  /* Отношение плеч к торсу у пауз «profile». Три журнала подряд эта причина
     была главной — 7, 8 и ещё 8 эпизодов, — и разбор каждый раз упирался в
     догадку: по видимости, торсу и центру понять, повернулся ребёнок или врёт
     форма кадра, нельзя. Порог сравнивается с одним числом, и его в журнале
     не было вовсе. */
  const боком = report(сессия([
    { t: 0, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, screenRun: 'awake' },
    { t: 10000, type: 'pause', why: 'profile', vis: 1, S: 0.34, cx: 0.5, lostMs: 730, ratio: 0.27, shW: 0.09, aspect: 0.56 },
    { t: 12000, type: 'resume' },
    { t: 20000, type: 'pause', why: 'profile', vis: 1, S: 0.36, cx: 0.5, lostMs: 710, ratio: 0.41, shW: 0.15, aspect: 1.78 },
    { t: 22000, type: 'resume' },
    { t: 60000, type: 'run.finish', stars: 18, score: 18, starsTotal: 20, hits: 0, durationS: 60 },
  ]));
  check('отношение плеч к торсу собрано с пауз profile',
    боком.pauses.profileRatio.lo === 0.27 && боком.pauses.profileRatio.hi === 0.41,
    JSON.stringify(боком.pauses.profileRatio));
  check('и сводка печатает его полосой',
    /плечи к торсу у «profile»: 0\.27–0\.41/.test(format(боком)),
    format(боком).split(String.fromCharCode(10)).filter((l) => /плечи/.test(l)).join('') || '(строки нет)');

  /* У журналов до этой правки числа нет, и печатать «—» нельзя: молчание
     честнее, чем выдуманное значение. */
  const безЧисла = report(сессия([
    { t: 0, type: 'run.start', durationS: 60, obstacles: 8, stars: 20 },
    { t: 10000, type: 'pause', why: 'profile', vis: 1, S: 0.34, cx: 0.5, lostMs: 730 },
    { t: 60000, type: 'run.finish', stars: 18, score: 18, starsTotal: 20, hits: 0, durationS: 60 },
  ]));
  check('у старого журнала строки про плечи нет', !/плечи к торсу/.test(format(безЧисла)));

  /* Торс и полоса присутствия у пауз «scale» — то же, но по журналу 9 октября.
     Восемь таких пауз за 72 секунды разбирались вручную: длина торса в записи
     была, а полоса, с которой её сравнили, — нет, и доставать её приходилось
     из `calib.done.S0` домножением. Теперь так уже не выйдет вовсе: у потолка
     появился пол, и одним умножением он не выводится. */
  const близко = report(сессия([
    { t: 0, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, screenRun: 'awake' },
    { t: 10000, type: 'pause', why: 'scale', vis: 1, S: 0.37, cx: 0.5, lostMs: 707, sLo: 0.1, sHi: 0.5 },
    { t: 12000, type: 'resume' },
    { t: 20000, type: 'pause', why: 'scale', vis: 1, S: 0.43, cx: 0.5, lostMs: 757, sLo: 0.1, sHi: 0.5 },
    { t: 22000, type: 'resume' },
    { t: 60000, type: 'run.finish', stars: 18, score: 18, starsTotal: 20, hits: 0, durationS: 60 },
  ]));
  check('торс у пауз scale собран полосой',
    близко.pauses.scaleBand.lo === 0.37 && близко.pauses.scaleBand.hi === 0.43,
    JSON.stringify(близко.pauses.scaleBand));
  check('и сводка печатает его вместе с полосой присутствия',
    /торс у «scale»: 0\.37–0\.43 при полосе 0\.1–0\.5/.test(format(близко)),
    format(близко).split(String.fromCharCode(10)).filter((l) => /«scale»/.test(l)).join('') || '(строки нет)');

  /* А у журнала до этой правки полосы нет, и разбор обязан сказать это прямо, а
     не промолчать: без полосы «торс 0.37» не отличает подошедшего игрока от
     короткой S0, то есть именно того дефекта, ради которого строка и появилась. */
  const безПолосы = report(сессия([
    { t: 0, type: 'run.start', durationS: 60, obstacles: 8, stars: 20 },
    { t: 10000, type: 'pause', why: 'scale', vis: 1, S: 0.37, cx: 0.5, lostMs: 707 },
    { t: 60000, type: 'run.finish', stars: 18, score: 18, starsTotal: 20, hits: 0, durationS: 60 },
  ]));
  /* Разбивка задетых по ВНЕШНОСТИ препятствия. Перекраска не меняет ни
     действия, ни приговора, но может читаться хуже — и отличить это от
     усталости ребёнка можно только сравнив две внешности одного действия. */
  const внешности = report(сессия([
    { t: 0, type: 'run.start', durationS: 60, obstacles: 4, stars: 10 },
    { t: 10000, type: 'obstacle', kind: 'side', look: 'plate', side: 1, result: 'clear' },
    { t: 20000, type: 'obstacle', kind: 'side', look: 'gate', side: -1, result: 'hit' },
    { t: 30000, type: 'obstacle', kind: 'side', look: 'gate', side: 1, result: 'hit' },
    { t: 40000, type: 'obstacle', kind: 'duck', look: 'ceiling', side: 0, result: 'clear' },
    { t: 60000, type: 'run.finish', stars: 8, score: 8, starsTotal: 10, hits: 2, durationS: 60 },
  ]));
  check('задетые разложены по внешностям',
    внешности.run.obstacles.byLook['side/gate']?.hit === 2
    && внешности.run.obstacles.byLook['side/plate']?.hit === 0,
    JSON.stringify(внешности.run.obstacles.byLook));
  check('и сводка печатает разбивку',
    /по внешности:.*side\/gate 0\/2/.test(format(внешности)),
    format(внешности).split(String.fromCharCode(10)).filter((l) => /внешности/.test(l)).join('') || '(строки нет)');
  check('у журнала без внешностей разбивки нет',
    !/по внешности/.test(format(близко)),
    'перекраски появились позже журналов, и «неизвестно/0» читалось бы как замеренный ноль');

  check('у старого журнала отсутствие полосы названо вслух',
    /торс у «scale»: 0\.37–0\.37 \(полосы в журнале нет/.test(format(безПолосы)),
    format(безПолосы).split(String.fromCharCode(10)).filter((l) => /«scale»/.test(l)).join('') || '(строки нет)');

  /* Соврамшая форма кадра — то, из-за чего второй забег 8 октября был
     непроходим вовсе. Разбор обязан называть её сам: «он меня не видел, как я
     ни ходил» в журнале выглядит одной цифрой, и найти её глазами нельзя. */
  const соврала = report(сессия([
    { t: 0, type: 'cam.aspect', aspect: 1.78, said: 0.56, w: 640, h: 360, saidW: 360, saidH: 640 },
    { t: 1000, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, screenRun: 'awake' },
  ]));
  check('расхождение отчёта камеры с кадром названо',
    соврала.notes.some((n) => /отчёт камеры и кадр расходятся/.test(n)),
    'получилось: ' + соврала.notes.join(' | '));
  const совпало = report(сессия([
    { t: 0, type: 'cam.aspect', aspect: 1.78, said: 1.78, w: 640, h: 360 },
    { t: 1000, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, screenRun: 'awake' },
  ]));
  check('а когда не врала — молчит',
    !совпало.notes.some((n) => /форме кадра/.test(n)), совпало.notes.join(' | '));
  const переучили = report(сессия([
    { t: 0, type: 'cam.aspect', aspect: 1.78, was: 0.56, w: 640, h: 360 },
    { t: 1000, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, screenRun: 'awake' },
  ]));
  check('переучивание на ходу тоже видно',
    переучили.notes.some((n) => /переучена на ходу/.test(n)), переучили.notes.join(' | '));

  /* Два забега в одной сессии — это и есть замер. Сводка обязана разложить их
     по забегам: общая медиана fps смешала бы обе политики в одно число, то
     есть ответила бы на вопрос замера средним по вопросу. */
  const замер = report(сессия([
    { t: 1000, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, screenRun: 'awake' },
    { t: 2000, type: 'health', stage: 'free', fps: 38, hz: 11, drop: 0, ok: 1, vis: 1, S: 0.3, p50: 87, p95: 100, draw50: 0, draw95: 1, u: 0, v: 0, panSpan: 0.93 },
    { t: 3000, type: 'health', stage: 'free', fps: 39, hz: 11, drop: 0, ok: 1, vis: 1, S: 0.3, p50: 88, p95: 101, draw50: 0, draw95: 1, u: 0, v: 0, panSpan: 0.93 },
    { t: 61000, type: 'run.finish', stars: 18, score: 18, starsTotal: 20, hits: 0, durationS: 60 },
    { t: 70000, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, screenRun: 'sleep' },
    { t: 71000, type: 'health', stage: 'free', fps: 47, hz: 11, drop: 0, ok: 1, vis: 1, S: 0.3, p50: 86, p95: 99, draw50: 0, draw95: 1, u: 0, v: 0, panSpan: 0.93 },
    { t: 72000, type: 'health', stage: 'free', fps: 48, hz: 11, drop: 0, ok: 1, vis: 1, S: 0.3, p50: 87, p95: 100, draw50: 0, draw95: 1, u: 0, v: 0, panSpan: 0.93 },
    { t: 130000, type: 'run.finish', stars: 19, score: 19, starsTotal: 20, hits: 0, durationS: 60 },
  ]));
  check('забеги сессии перечислены по одному', замер.runs.length === 2,
    JSON.stringify(замер.runs));
  check('у каждого своя политика экрана',
    замер.runs[0].screenRun === 'awake' && замер.runs[1].screenRun === 'sleep');
  check('и своя медиана кадров, а не общая на двоих',
    замер.runs[0].fps === 38.5 && замер.runs[1].fps === 47.5,
    JSON.stringify(замер.runs.map((r) => r.fps)));
  /* И главное: ни одна из них не равна сессионной. Та считается по всем окнам
     сразу и даёт 43 — число, которого не было ни в одном забеге. Ровно на этом
     замер и рассыпался бы. */
  check('сессионная медиана обеим чужая',
    замер.perf.fps.med === 43
    && замер.runs.every((r) => r.fps !== замер.perf.fps.med),
    `сессионная ${замер.perf.fps.med}, по забегам ${JSON.stringify(замер.runs.map((r) => r.fps))}`);
  const сводка = format(замер);
  check('сводка печатает оба забега с их просьбой',
    /просили не гаснуть/.test(сводка) && /просили гаснуть/.test(сводка),
    сводка.split(String.fromCharCode(10)).filter((l) => /просил|забег/.test(l)).join(' | '));
  check('и частота поз у забегов тоже своя', замер.runs[0].hz === 11);

  /* Окна здоровья второго забега не имеют права попасть в первый: именно на
     этом замер и рассыпался бы — обе политики в одной медиане. */
  check('окна поделены по забегам',
    замер.runs[0].windows === 2 && замер.runs[1].windows === 2,
    JSON.stringify(замер.runs.map((r) => r.windows)));

  const безПолитики = report(сессия([
    { t: 0, type: 'run.start', durationS: 60, obstacles: 8, stars: 20 },
    { t: 60000, type: 'run.finish', stars: 18, score: 18, starsTotal: 20, hits: 0, durationS: 60 },
  ]));
  check('у журнала до замера политики нет', безПолитики.run.screenRun === null);
  check('и сводка о ней молчит', !/экран/.test(format(безПолитики)),
    'печатать «экран: null» значит предлагать принять это за наблюдение');

  /* Мир и уровень кубка. Забег их называет с этапа 5, а разбор о них молчал:
     миров четыре, и первый же журнал с ребёнком оказался бы неразборчивым по
     мирам — числа двух забегов в разных мирах легли бы рядом без подписи. */
  const миры = report(сессия([
    { t: 1000, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, screenRun: 'awake', world: 'hills', level: 3 },
    { t: 61000, type: 'run.finish', stars: 18, score: 18, starsTotal: 20, hits: 0, durationS: 60 },
    { t: 70000, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, screenRun: 'awake', world: 'deep', level: 7 },
    { t: 130000, type: 'run.finish', stars: 19, score: 19, starsTotal: 20, hits: 0, durationS: 60 },
  ]));
  check('мир забега прочитан', миры.runs[0].world === 'hills' && миры.runs[1].world === 'deep',
    JSON.stringify(миры.runs.map((r) => r.world)));
  check('и уровень кубка тоже', миры.runs[0].level === 3 && миры.runs[1].level === 7,
    JSON.stringify(миры.runs.map((r) => r.level)));
  /* Финишу принадлежит ПОСЛЕДНИЙ запуск до него — то же правило, что у
     политики экрана: иначе разбор приписал бы второму забегу мир первого. */
  check('у забега с финишем мир свой, а не первый попавшийся',
    миры.run.world === 'deep' && миры.run.level === 7,
    JSON.stringify([миры.run.world, миры.run.level]));
  const сМирами = format(миры);
  /* Печатается ИМЯ из реестра, а не ключ: ключ читается кодом, а сводку
     читают глазами, и `deep` рядом с `hills` ничего не говорит о том, где
     ребёнок бежал. */
  check('сводка называет мир по имени', /^ {2}мир «Подводная долина», уровень кубка 7$/m.test(сМирами),
    сМирами.split(String.fromCharCode(10)).filter((l) => /мир/.test(l)).join(' | ') || '(строки нет)');
  check('и оба забега подписаны своим миром',
    /мир «Холмы»/.test(сМирами) && /мир «Подводная долина»/.test(сМирами),
    сМирами.split(String.fromCharCode(10)).filter((l) => /мир/.test(l)).join(' | ') || '(строки нет)');

  /* Один забег — разбивки по забегам нет, а мир назвать всё равно надо: без
     него журнал неразборчив ровно так же. */
  const одинМир = report(сессия([
    { t: 0, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, world: 'stars', level: 12 },
    { t: 60000, type: 'run.finish', stars: 18, score: 18, starsTotal: 20, hits: 0, durationS: 60 },
  ]));
  check('мир назван и у единственного забега',
    /^ {2}мир «Звёздная дорога», уровень кубка 12$/m.test(format(одинМир)),
    format(одинМир).split(String.fromCharCode(10)).filter((l) => /мир/.test(l)).join(' | ') || '(строки нет)');

  /* Незнакомый ключ печатается как есть. Реестр миров переписывают, а журнал
     снят однажды: молчание о мире выглядело бы как журнал до миров, то есть
     соврало бы о другом. */
  const чужойМир = report(сессия([
    { t: 0, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, world: 'лес', level: 2 },
    { t: 60000, type: 'run.finish', stars: 18, score: 18, starsTotal: 20, hits: 0, durationS: 60 },
  ]));
  check('незнакомый мир назван ключом, а не замолчан',
    /мир «лес»/.test(format(чужойМир)),
    format(чужойМир).split(String.fromCharCode(10)).filter((l) => /мир/.test(l)).join(' | ') || '(строки нет)');

  /* То же правило, что у политики экрана и у ступени: отсутствие поля — это
     «журнал снят до миров», а не «мир по умолчанию». */
  check('у журнала до миров мира нет',
    безПолитики.run.world === null && безПолитики.run.level === null,
    JSON.stringify([безПолитики.run.world, безПолитики.run.level]));
  check('и сводка о нём молчит', !/мир «/.test(format(безПолитики)),
    'печатать «мир: Холмы» по умолчанию значит выдать догадку за запись');

  /* Взятый уровень кубка — ИСХОД, и журнал его пишет с этапа 1. Читателя у
     записи не было: лестница в двенадцать уровней — главное, ради чего
     ребёнок возвращается, а по журналу нельзя было сказать, брал ли он
     что-нибудь вообще. Тот же дефект, что был у мира: запись есть, читателя
     нет. */
  const лестница = report(сессия([
    { t: 0, type: 'run.start', durationS: 60, obstacles: 8, stars: 20, world: 'hills', level: 2 },
    { t: 60000, type: 'run.finish', stars: 60, score: 60, starsTotal: 60, hits: 0, durationS: 60 },
    { t: 60500, type: 'bank', added: 60, bank: 310, player: 'Ребёнок' },
    { t: 60600, type: 'trophy.level', level: 3, at: 300, id: 'world-ice', bank: 310 },
  ]));
  check('взятый уровень прочитан', лестница.levels.length === 1,
    JSON.stringify(лестница.levels));
  check('и у него есть номер, порог и приз',
    лестница.levels[0].level === 3 && лестница.levels[0].at === 300
    && лестница.levels[0].id === 'world-ice',
    JSON.stringify(лестница.levels[0]));
  check('сводка называет взятый уровень и приз',
    /уровень 3 взят.*Ледяные горы/.test(format(лестница)),
    format(лестница).split(String.fromCharCode(10)).filter((l) => /уровень/.test(l)).join(' | ') || '(строки нет)');

  /* Забег может взять ДВА уровня сразу (собрал 220 при копилке 90), и журнал
     пишет по событию на каждый. Разбор обязан показать оба: «взял уровень»
     и «взял два» — разные новости. */
  const двойной = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 40, stars: 100, world: 'hills', level: 0 },
    { t: 300000, type: 'run.finish', stars: 220, score: 220, starsTotal: 240, hits: 0, durationS: 300 },
    { t: 300500, type: 'trophy.level', level: 1, at: 100, id: 'sparks', bank: 310 },
    { t: 300600, type: 'trophy.level', level: 2, at: 200, id: 'bloom', bank: 310 },
  ]));
  check('оба взятых уровня видны', двойной.levels.length === 2,
    JSON.stringify(двойной.levels.map((l) => l.level)));
  check('и оба названы в сводке',
    /уровень 1 взят/.test(format(двойной)) && /уровень 2 взят/.test(format(двойной)),
    format(двойной).split(String.fromCharCode(10)).filter((l) => /уровень/.test(l)).join(' | ') || '(строки нет)');

  /* Ничего не взято — строки нет. Та же осторожность, что у политики экрана:
     «взято 0 уровней» читалось бы как наблюдение, а это отсутствие события. */
  check('без взятых уровней разбор молчит',
    безПолитики.levels.length === 0 && !/уровень \d+ взят/.test(format(безПолитики)),
    'строка про уровни у журнала без них была бы выдумкой');

  const безУдаров = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 43, stars: 100 },
    { t: 300000, type: 'run.finish', stars: 88, starsTotal: 100, hits: 0, durationS: 300 },
  ]));
  check('а без задетых предупреждать не о чем',
    !безУдаров.notes.some((n) => /очк/.test(n)),
    'при нуле задетых очки и кольца совпадают по построению');

  const полный = report(забегДоФиниша());
  const брошен = report(забегБрошен());

  // ── склейка повторов разворачивается в счёт ──
  check('повтор со счётчиком считается за все свои разы',
    брошен.errors.total === 1478,
    'получилось ' + брошен.errors.total + '; одна запись с _n=1478 — это 1478 событий, '
    + 'и считать записи значит занизить поток ошибок в тысячу раз');
  check('длительность потока берётся из _lastT',
    Math.round(брошен.errors.spanS) === 133,
    'получилось ' + брошен.errors.spanS + ' с; без _lastT «упало 1478 раз» неотличимо '
    + 'от «падает до сих пор»');

  /* Склейка повторов появилась позже самих журналов: все снятые с телефона
     файлы несут поток отдельных записей, а не одну со счётчиком. Разброс
     потока поэтому считается по ГРУППЕ одинаковых событий, от первого `t` до
     последнего, — иначе на настоящем журнале выходило «1478 ошибок за 0 с».
     Поймано ровно так: на журнале второго детского сеанса. */
  const безСклейки = сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 44, stars: 103 },
    ...Array.from({ length: 1478 }, (_, i) => ({
      t: 116551 + Math.round((i * 133026) / 1477),
      type: 'error', where: 'frame', message: 'uEnter of null',
    })),
  ]);
  const старый = report(безСклейки);
  check('поток отдельных записей считается так же, как склеенный',
    старый.errors.total === 1478,
    'получилось ' + старый.errors.total);
  check('и его разброс берётся по группе, а не внутри записи',
    Math.round(старый.errors.spanS) === 133,
    'получилось ' + старый.errors.spanS + ' с; у отдельных записей нет _lastT, '
    + 'и разброс внутри каждой равен нулю — считать надо от первой до последней');

  // ── квантили окон не усредняются ──
  check('медиана инференса — медиана окон', полный.perf.infer.med === 96,
    'получилось ' + полный.perf.infer.med + ' при окнах p50 88 и 104');
  check('худшее окно показано отдельно и берётся по p95', полный.perf.infer.worst === 120,
    'получилось ' + полный.perf.infer.worst + ' при окнах p95 104 и 120');
  check('число окон названо', полный.perf.windows === 2,
    'без него непонятно, по какому объёму считана медиана');
  check('отрисовка рядом с инференсом',
    полный.perf.draw.med === 0.5 && полный.perf.draw.worst === 11,
    'по этой паре видно, кто кого ждёт');
  check('частота поз и кадров по окнам',
    полный.perf.hz.med === 10.5 && полный.perf.fps.med === 37,
    'получилось hz ' + полный.perf.hz.med + ', fps ' + полный.perf.fps.med);

  // ── чего в журнале нет, о том отчёт говорит ──
  check('нет panSpan — не ноль, а «неизвестно»', брошен.panSpan === null,
    'ноль здесь означал бы нулевое игровое поле, а не журнал до нормировки');
  check('и об этом сказано словами',
    брошен.notes.some((s) => /нормировк/i.test(s)),
    'заметки: ' + брошен.notes.join(' | '));
  check('panSpan полного забега прочитан', полный.panSpan === 0.42);

  // ── брошенный забег не считается дошедшим ──
  check('без run.finish забег брошен', брошен.finished === false && брошен.run === null,
    'иначе брошенный забег выглядит забегом с нулём колец — ровно та ошибка, '
    + 'от которой в рекордах стоит отсутствие вызова');
  check('и помечен словами', брошен.notes.some((s) => /брошен/i.test(s)),
    'заметки: ' + брошен.notes.join(' | '));

  // ── итоги забега ──
  check('кольца и доля', полный.run.stars === 84 && полный.run.starsTotal === 103
    && полный.run.ringPct === 82, 'получилось ' + полный.run.ringPct + '%');
  /* Старые журналы не писали `starsTotal`. Доли тогда не существует, и
     печатать «null%» значит предлагать принять это за число — на журнале
     взрослого забега именно так и вышло. */
  const безИтога = report(сессия([
    { t: 0, type: 'run.start', durationS: 300 },
    { t: 300000, type: 'run.finish', stars: 102, hits: 2, durationS: 300 },
  ]));
  check('нет starsTotal — нет и доли, а не ноль',
    безИтога.run.ringPct === null && !/null/.test(format(безИтога)),
    'доля без знаменателя не существует, и в отчёт она попасть не должна');
  check('препятствия разложены на три исхода',
    полный.run.obstacles.clear === 40 && полный.run.obstacles.grace === 2
    && полный.run.obstacles.hit === 2 && полный.run.obstacles.total === 44,
    'прощённое — не задетое и не чистое, и сливать их значит потерять '
    + 'ровно то, чем мерится щадящесть');
  check('задетое берётся из run.finish, а не пересчитывается',
    полный.run.hits === 2,
    'две копии числа разошлись бы, а run.finish здесь — источник');

  // ── паузы ──
  check('эпизоды пауз и разбивка по причине',
    полный.pauses.episodes === 4 && полный.pauses.byWhy.scale === 2
    && полный.pauses.byWhy.edge === 1 && полный.pauses.byWhy.manual === 1,
    JSON.stringify(полный.pauses.byWhy));
  check('длительность паузы — до resume',
    полный.pauses.totalS === 10, 'получилось ' + полный.pauses.totalS + ' с');
  check('доля пауз от забега', полный.pauses.pctOfRun === 3.3,
    'получилось ' + полный.pauses.pctOfRun + '%');
  check('незакрытая пауза считается до конца журнала',
    брошен.pauses.totalS === 129.2,
    'получилось ' + брошен.pauses.totalS + ' с; пауза в конце журнала означает, '
    + 'что из неё так и не вышли');
  /* Незакрытая пауза называется отдельно: её длительность — не время в паузе
     посреди игры, а «сеанс кончился на ней». Без оговорки доля пауз выглядит
     вдвое хуже, чем была: у взрослого забега так и вышло — 44 с против
     записанных в документации 28.5 с. */
  check('незакрытые паузы посчитаны отдельно',
    брошен.pauses.unclosed === 1 && полный.pauses.unclosed === 0,
    'получилось ' + брошен.pauses.unclosed + ' и ' + полный.pauses.unclosed);

  /* В одной сессии забегов несколько. Пауза брошенного забега не имеет права
     спариваться с `resume` СЛЕДУЮЩЕГО: так она проглатывала всё между ними и
     при этом считалась закрытой — то есть оговорка про «сеанс кончился на
     паузе» не печаталась, а завышенная доля уезжала в measurements/. */
  const двеПопытки = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 44, stars: 103 },
    { t: 10000, type: 'pause', why: 'scale', vis: 0.2, S: 0.1, cx: 0.5, lostMs: 700 },
    { t: 20000, type: 'run.abort' },
    { t: 30000, type: 'run.start', durationS: 300, obstacles: 44, stars: 103 },
    { t: 40000, type: 'pause', why: 'edge', vis: 0.9, S: 0.4, cx: 0.9, lostMs: 700 },
    { t: 43000, type: 'resume' },
    { t: 330000, type: 'run.finish', stars: 90, starsTotal: 103, hits: 1, durationS: 300 },
  ]));
  check('пауза не спаривается с resume следующего забега',
    двеПопытки.pauses.unclosed === 1 && двеПопытки.pauses.totalS === 13,
    'получилось незакрытых ' + двеПопытки.pauses.unclosed + ', всего '
    + двеПопытки.pauses.totalS + ' с; брошенная пауза длилась 10 с до run.abort, '
    + 'вторая — 3 с до resume');
  /* Доля — от пауз внутри забега, а не за сессию: иначе в неё попадают
     калибровка и прошлые попытки, и процент перестаёт быть процентом чего-либо. */
  check('доля пауз считается от пауз внутри забега',
    двеПопытки.pauses.inRunS === 3 && двеПопытки.pauses.pctOfRun === 1,
    'получилось ' + двеПопытки.pauses.inRunS + ' с и ' + двеПопытки.pauses.pctOfRun
    + '%; за сессию пауз 13 с, но к забегу относятся только 3');

  /* Склеенное окно здоровья — это несколько окон. Вес обязан быть одинаковым
     у всех чисел: здесь `drop` учитывал `_n`, а медианы и счёт окон — нет. */
  const склеенныеОкна = report(сессия([
    { t: 0, type: 'health', stage: 'run', fps: 30, hz: 10, drop: 1, ok: 1, vis: 1,
      S: 0.4, p50: 200, p95: 200, draw50: 0, draw95: 0, u: 0, v: 0, panSpan: 0.42,
      _n: 3, _lastT: 6000 },
    { t: 8000, type: 'health', stage: 'run', fps: 40, hz: 20, drop: 0, ok: 1, vis: 1,
      S: 0.4, p50: 50, p95: 50, draw50: 0, draw95: 0, u: 0, v: 0, panSpan: 0.42 },
  ]));
  check('склеенное окно весит как несколько',
    склеенныеОкна.perf.windows === 4 && склеенныеОкна.perf.infer.med === 200,
    'получилось окон ' + склеенныеОкна.perf.windows + ', медиана '
    + склеенныеОкна.perf.infer.med + '; три окна по 200 мс и одно по 50 дают '
    + 'медиану 200, а не 125');

  // ── источник поз ──
  check('делегат и прогрев прочитаны',
    полный.pose.delegate === 'GPU' && полный.pose.warmupP50 === 18
    && полный.pose.initMs === 3300,
    'заявленный делегат умеет врать, честный ответ даёт только время');

  // ── весь файл, а не первая сессия ──
  const обе = reportAll({
    exportedAt: '2026-10-06T21:25:00.000Z', limits: {},
    sessions: [забегДоФиниша(), забегБрошен()],
  });
  check('разбираются все сессии файла', обе.length === 2,
    'выгрузка несёт до двадцати сессий, и нужная — не обязательно первая');

  /* ── расход окна прощения ──

     Раньше «прощено» в сводке считало удары, поглощённые неуязвимостью от
     предыдущего удара, — случай, невозможный при `invulnMs` 1500 мс и
     `minGapS` 5500. Настоящий расход окна (ушёл уже после прихода, в те
     350 мс, что ему прощают) не мерился вовсе. Теперь мерится, и печатается
     только когда случался: ноль двусмыслен — он значит и «журнал снят до
     того, как это стали мерить». */
  const сПрощением = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 3, stars: 10 },
    { t: 1000, type: 'obstacle', kind: 'side', side: 1, result: 'clear', camX: 0.3 },
    { t: 2000, type: 'obstacle', kind: 'side', side: 1, result: 'clear', camX: 0.3, forgiven: true },
    { t: 3000, type: 'obstacle', kind: 'duck', side: 0, result: 'hit', camX: 0 },
    { t: 300000, type: 'run.finish', stars: 9, score: 9, starsTotal: 10, hits: 1, durationS: 300 },
  ]));
  check('проход в окне прощения считается отдельно',
    сПрощением.run.obstacles.forgiven === 1
    && сПрощением.run.obstacles.clear === 2,
    'для ребёнка это пройденное препятствие, для ступени — «запаса не осталось»');
  check('и печатается',
    /в окне прощения: 1/.test(format(сПрощением)));
  check('а при нуле не печатается', !/в окне прощения/.test(format(полный)),
    'ноль здесь значит и «тогда это не мерили», и «успевал всегда»');

  /* ── проход, доставшийся незнанием ──

     Боковое препятствие, пришедшее в защёлкнутый присед, с 14 октября
     приговора не выносит: пока ребёнок сложен, боковое положение не
     обновляется, и судить по нему значит давать приговор за то, чего он не мог
     исполнить. Но такой проход не заработан, и в сводке он обязан быть виден
     отдельно — иначе «чисто» однажды будет значить «пролежал на полу». */
  const сНезнанием = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 3, stars: 10 },
    { t: 1000, type: 'obstacle', kind: 'side', side: 1, result: 'clear', camX: -0.5 },
    {
      t: 2000, type: 'obstacle', kind: 'side', side: 1, result: 'clear',
      camX: 0.1, lateralUnknown: true,
    },
    { t: 3000, type: 'obstacle', kind: 'duck', side: 0, result: 'clear', camX: 0 },
    { t: 300000, type: 'run.finish', stars: 10, score: 10, starsTotal: 10, hits: 0, durationS: 300 },
  ]));
  check('проход незнанием считается отдельно',
    сНезнанием.run.obstacles.unknown === 1
    && сНезнанием.run.obstacles.clear === 3,
    'в «чисто» он входит — для ребёнка это проход, — но и виден отдельно');
  check('и печатается',
    /прошли незнанием: 1/.test(format(сНезнанием)));
  check('а при нуле не печатается', !/незнанием/.test(format(полный)),
    'тот же довод, что у окна прощения: ноль двусмыслен');

  /* ── ступень сложности в журнале ──

     Событие `difficulty` пишется ВСЕГДА, в том числе когда ступень осталась
     на месте: отсутствие события неотличимо от «код не выполнился», и это
     ровно то различие, ради которого разбор существует. */
  const соСтупенью = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 43, stars: 100, step: 2,
      tune: { blockFrac: 0.48, duckShare: 0.34, seriesMin: 3, seriesMax: 5, breatherS: 8.8 } },
    { t: 300000, type: 'run.finish', stars: 95, score: 95, starsTotal: 100, hits: 0, durationS: 300 },
    { t: 300100, type: 'difficulty', from: 2, to: 3, why: 'easy', finished: true,
      faced: 43, late: 0, hits: 0, grace: 0, pauses: 0, ringPct: 95 },
  ]));
  check('ступень забега прочитана', соСтупенью.runs[0].step === 2);
  check('и её числа тоже', соСтупенью.runs[0].tune?.blockFrac === 0.48,
    'номер без чисел бесполезен: таблицу ступеней однажды перепишут');
  check('переход прочитан', соСтупенью.steps.length === 1
    && соСтупенью.steps[0].to === 3 && соСтупенью.steps[0].why === 'easy');
  const текстСтупени = format(соСтупенью);
  check('ступень напечатана с числами',
    /ступень 2 \(размах 0\.48/.test(текстСтупени),
    текстСтупени.split('\n').filter((l) => /ступень/.test(l)).join(' // '));
  check('и переход напечатан', /ступень: 2 → 3 \(легко\)/.test(текстСтупени));

  const держится = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 43, stars: 100, step: 1, tune: null },
    { t: 300000, type: 'run.finish', stars: 80, score: 80, starsTotal: 100, hits: 0, durationS: 300 },
    { t: 300100, type: 'difficulty', from: 1, to: 1, why: 'held', finished: true,
      faced: 43, late: 0, hits: 0, grace: 0, pauses: 0, ringPct: 80 },
  ]));
  check('«держится» тоже печатается', /ступень: 1 держится/.test(format(держится)),
    'молчание здесь означало бы, что код не выполнился');

  /* ── словарь читателя шире словаря писателя ──

     Автоматический переход отменён 18 октября, и игра пишет теперь только
     `chosen` и `fake`. Но `easy`, `hard` и `held` стоят во ВСЕХ журналах,
     снятых до того дня, включая тот, которым отмена и обоснована: три
     проверки выше читают ровно их. Перестать понимать старые слова значило
     бы потерять сравнимость там, где она доказывает необходимость правки, —
     поэтому разбор понимает пять слов, а пишутся два. */
  const выбран = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 43, stars: 100, step: 3,
      tune: { blockFrac: 0.455, duckShare: 0.34, seriesMin: 4, seriesMax: 6, breatherS: 9.9,
              speed: 2.3 } },
    { t: 300000, type: 'run.finish', stars: 95, score: 95, starsTotal: 100, hits: 0, durationS: 300 },
    { t: 300100, type: 'difficulty', from: 3, to: 3, why: 'chosen', finished: true,
      faced: 43, late: 0, hits: 0, grace: 0, pauses: 0, ringPct: 95 },
  ]));
  check('скорость уровня напечатана, когда она в журнале есть',
    /скорость 2\.3/.test(format(выбран)),
    'уровни различаются и ею, значит два журнала без неё неразличимы');
  check('а у журнала без неё не выдумывается',
    !/скорость/.test(format(держится)),
    'подставить базовые 2.0 значило бы соврать числом: та сборка о ней не знала');
  check('выбранный рукой уровень назван своим словом',
    /ступень: 3 — выбран вручную/.test(format(выбран)),
    '`from === to` без слова через месяц прочитается как «автоматика сломалась»');
  const синтетика = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 43, stars: 100, step: 0, tune: null },
    { t: 300000, type: 'run.finish', stars: 10, score: 10, starsTotal: 100, hits: 9, durationS: 300 },
    { t: 300100, type: 'difficulty', from: 0, to: 0, why: 'fake', finished: true,
      faced: 43, late: 9, hits: 9, grace: 0, pauses: 0, ringPct: 10 },
  ]));
  check('синтетика названа синтетикой',
    /ступень: 0 — синтетика/.test(format(синтетика)),
    'забег, в котором никто не двигался, не должен выглядеть забегом ребёнка');

  /* ── совет вместо правила ──

     Пороги те же, что двигали ступень, и асимметрия та же: «трудно» по трём
     «не успел», «перерос» — только по безупречному забегу. Адресат другой:
     решение принимает взрослый, и числа печатаются ему. */
  const трудно = report(сессия([
    { t: 0, type: 'run.start', durationS: 300, obstacles: 43, stars: 100, step: 2, tune: null },
    { t: 300000, type: 'run.finish', stars: 70, score: 70, starsTotal: 100, hits: 3, durationS: 300 },
    { t: 300100, type: 'difficulty', from: 2, to: 2, why: 'chosen', finished: true,
      faced: 43, late: 3, hits: 3, grace: 0, pauses: 0, ringPct: 70 },
  ]));
  check('разбор советует уровень ниже', /ребёнку трудно: не успел 3 раза из 43/.test(format(трудно)),
    'это и есть то, во что превратилось правило понижения');
  check('и советует уровень выше по безупречному забегу',
    /перерос эту сложность/.test(format(выбран)),
    'пороги взяты из DIFFICULTY, а не переписаны литералами');
  check('а по забегу с паузой — не советует',
    !/перерос/.test(format(report(сессия([
      { t: 0, type: 'run.start', durationS: 300, obstacles: 43, stars: 100, step: 3, tune: null },
      { t: 300000, type: 'run.finish', stars: 95, score: 95, starsTotal: 100, hits: 0, durationS: 300 },
      { t: 300100, type: 'difficulty', from: 3, to: 3, why: 'chosen', finished: true,
        faced: 43, late: 0, hits: 0, grace: 0, pauses: 2, ringPct: 95 },
    ])))),
    'усложнять по журналу с дефектами нельзя — это правило пережило саму автоматику');

  /* А журнал ДО тихой адаптации не получает ступень нулевой: это выдумка про
     игру, которой тогда не было. То же правило, что у panSpan и очков. */
  check('журнал без ступени называет это отсутствием',
    полный.runs[0].step === null && /ступени в журнале нет/.test(format(полный)),
    'ноль значил бы «забег шёл на лёгкой», а он шёл до того, как ступени завелись');

  // ── отчёт не выносит наружу записи о ребёнке ──
  const текст = format(полный);
  check('единицы u подписаны', /доли поля/.test(текст),
    'в health это доли игрового поля, в gesture — длины торса, и перепутать их легко');
  check('сырые точки в отчёт не попадают',
    !/rows/.test(текст) && !/\[\[/.test(текст),
    'measurements/ уезжает в публичный репозиторий, а samples и skeleton — это движения ребёнка');
});


/* ───────────────── что чем перекрыто ─────────────────

   Две жалобы заказчика после забега 10 октября, и обе — об одном: кадр
   собирается в правильном порядке по ГЛУБИНЕ, но внутри слоя порядка нет.

   1. «Тени дальних колец видны сквозь ближние предметы». Проходов по кольцам
      два, и разрез между ними честный, — но внутри прохода список шёл по
      ВОЗРАСТАНИЮ z, то есть дальнее кольцо и его пятно красились поверх
      ближнего. У декораций этот же дефект уже ловили и уже починили обратным
      обходом; у колец он остался.

   2. «Объекты фона по бокам видны полностью, хотя должны перекрываться
      стенами». Декорации стоят ЗА плоскостью обрыва (x = ±(HALF + out)), а
      рисуются одним проходом после него — то есть перекрытия не было ни у
      одной, и обочина висела в воздухе поверх стены.

   Перекрытие здесь считается точно и даром, без clip и без второго прохода
   обрыва. Причина — в самой проекции: `sy` не зависит от `x` вовсе, поэтому
   кромка обрыва (y = WALL на плоскости x = ±HALF) проецируется в ПРЯМУЮ,
   проходящую через точку схода. Условие «точка за обрывом» сводится к
   неравенству, из которого z сокращается:

       видно  ⇔  y > cam.y + (WALL − cam.y) · |x − cam.x| / |±HALF − cam.x|

   Отсюда три следствия, и каждое проверяется ниже: доля скрытого НЕ зависит от
   глубины; уход взгляда в сторону перекрывает свою обочину сильнее, а
   противоположную слабее; а скрыто при нейтрали ровно `1.1667 × out` метра —
   поэтому у низких видов обочины свой, меньший отступ от кромки, иначе цветы и
   камни исчезли бы из игры целиком. */
group('что чем перекрыто', () => {
  const C = THEME.greenHill;

  const frame = (patch = {}) => paintFrame(patch).shapes;

  /* ─── кольца внутри прохода: от дальнего к ближнему ───

     Дальнее кольцо стоит на ВОСЬМИ метрах, а не на двенадцати: с порогом
     видимости у пятна (`MOTION.shadowMinR`) на двенадцати пятна больше нет, и
     проверка порядка маляра мерила бы одно пятно вместо двух. Порядок она
     проверяет по-прежнему — просто на расстоянии, где оба пятна существуют. */
  const two = frame({ stars: [{ x: 0, z: 3 }, { x: 0, z: 8 }] });
  const rings = two.filter((s) => s.style === C.star);
  const spots = two.filter((s) => s.style === C.shadow);
  check('оба кольца нарисованы', rings.length === 2, `нашлось ${rings.length}`);
  check('оба пятна нарисованы', spots.length === 2, `нашлось ${spots.length}`);
  check('дальнее кольцо кладётся раньше ближнего',
    rings.length === 2 && rings[0].h < rings[1].h,
    rings.map((r) => r.h.toFixed(1)).join(' затем '));
  check('и пятно дальнего кольца — тоже раньше',
    spots.length === 2 && spots[0].h < spots[1].h,
    `ровно это заказчик и увидел: тень дальнего кольца поверх ближнего предмета`);

  // ─── декорация обрезана кромкой обрыва ───
  const post = (z, side = 1, out = DECOR.outM, h = 2.6) => ({
    kind: 'post', zone: 'greenHill', side, x: side * (CORRIDOR_HALF + out),
    y: CLIFF_TOP, h, z, at: 0, phase: 0,
  });

  const far = frame({ decor: [post(12)] }).filter((s) => s.style === C.post);
  const cam0 = camera(0, 0);
  const rawBase = project(CORRIDOR_HALF + DECOR.outM, CLIFF_TOP, 12, cam0).sy;
  check('столб обочины нарисован', far.length > 0);
  check('его основание обрезано кромкой обрыва', far.length > 0 && far[0].maxY < rawBase - 1,
    `низ на ${far[0]?.maxY?.toFixed(1)}, непокрытое основание на ${rawBase.toFixed(1)}`);

  // Доля скрытого не зависит от глубины: и обрыв, и обочина — плоскости
  // x = const, поэтому z в неравенстве сокращается. Проверяется отношением
  // видимой высоты к полной на двух глубинах.
  const seen = (z) => {
    const s = frame({ decor: [post(z)] }).filter((f) => f.style === C.post)[0];
    const full = project(CORRIDOR_HALF + DECOR.outM, CLIFF_TOP, z, cam0).sy
      - project(CORRIDOR_HALF + DECOR.outM, CLIFF_TOP + 2.6, z, cam0).sy;
    return s.h / full;
  };
  check('доля видимого одна и та же на 6 и на 18 метрах',
    Math.abs(seen(6) - seen(18)) < 0.02, `${seen(6).toFixed(3)} против ${seen(18).toFixed(3)}`);

  // ─── маска и уход взгляда ───
  const mask = (x, cam, side) => decorYMask(x, cam, side);
  const atRest = mask(CORRIDOR_HALF + DECOR.outM, cam0, 1);
  check('при нейтрали скрыто ровно 1.1667 × out',
    Math.abs((atRest - CLIFF_TOP) - (CLIFF_TOP - camera(0, 0).y) / CORRIDOR_HALF * DECOR.outM) < 1e-9,
    `скрыто ${(atRest - CLIFF_TOP).toFixed(3)} м`);

  const right = camera(1.5, 0);
  check('уход вправо перекрывает правую обочину сильнее',
    mask(CORRIDOR_HALF + DECOR.outM, right, 1) > atRest,
    'взгляд ушёл к правому обрыву, и он поднялся в кадре');
  check('а левую — слабее',
    mask(-(CORRIDOR_HALF + DECOR.outM), right, -1) < atRest,
    'от левого обрыва взгляд отошёл, и из-за него стало видно больше');

  /* ─── обочина обязана остаться видимой ───

     Это не про красоту, а про то, что правка не имеет права вычесть из игры
     половину обочины. Скрыто при нейтрали `1.1667 × out`, то есть 0.64 м при
     общем отступе 0.55 — а куст высотой 0.7 и цветок 0.45 после такого просто
     исчезли бы, и заметить это в node было бы нечем. Поэтому у низких видов
     свой отступ, и порог здесь — треть высоты. */
  for (const z of ZONES_ALL) {
    for (const k of THEME[z].decor.kinds) {
      const out = k.out ?? DECOR.outM;
      const m = mask(CORRIDOR_HALF + out, cam0, 1);
      const visible = CLIFF_TOP + k.height - m;
      check(`${z}/${k.kind}: при нейтрали видно хотя бы треть`,
        visible > k.height / 3,
        `видно ${visible.toFixed(2)} из ${k.height} м при out ${out}`);
    }
  }

  /* ─── и обочина не залезает в коридор ───

     Отступы у низких видов пришлось уменьшить, чтобы обрыв не скрывал их
     целиком, — и цветок на этом попался: лепесток шириной 0.28 сам по себе
     шире отступа 0.08, а поворот вслед бегущему добавлял ещё 0.18 внутрь.
     У самого глаза лепесток оказывался НАД игровой полосой, и спрятать его
     там нечем: внутри коридора маска обрыва не работает по построению.

     Проверяется не якорь элемента, а НАРИСОВАННАЯ фигура: якорь был снаружи
     всё это время, в коридор заезжала геометрия. Сравнивать можно прямо по
     экрану — `sx` не зависит от `y`, поэтому кромка коридора на нужной
     глубине это одно число. */
  for (const s of [-1, 1]) {
    for (const z of [0.9, 1.5, 3, 6]) {
      const el = {
        kind: 'flower', zone: 'greenHill', side: s,
        x: s * (CORRIDOR_HALF + 0.22), y: CLIFF_TOP, h: 0.45, z, at: 0, phase: 0,
      };
      const нарисовано = frame({ decor: [el] }).filter((f) => f.style === C.flower);
      const край = project(s * CORRIDOR_HALF, 0, z, cam0).sx;
      const внутрь = нарисовано.some((f) => (s > 0 ? f.minX < край - 0.5 : f.maxX > край + 0.5));
      check(`цветок на ${s > 0 ? 'правой' : 'левой'} обочине, z=${z}: не залезает в коридор`,
        !внутрь, 'лепесток повис бы над игровой полосой, и скрыть его нечем');
    }
  }

  // Декорация, целиком ушедшая за обрыв, не рисуется вовсе: вырожденные
  // четырёхугольники нулевой площади — это заливки в пользу никому.
  const buried = frame({ decor: [post(12, 1, DECOR.outM, 0.2)] });
  check('полностью скрытая декорация не рисуется',
    !buried.some((s) => s.style === C.post),
    'иначе кадр платит заливками за то, чего не видно');
});


/* ───────────── время реакции ─────────────

   Главный незакрытый вопрос проекта: все числа телеграфа и скоростей в
   `js/config.js` — ОЦЕНКИ. Так и написано там с самого начала, и пересчитать
   их можно было только по забегу с ребёнком. Забег 10 октября дал первый
   журнал без единого дефекта, то есть первые данные, которым можно верить.

   Считается две разные вещи, и путать их нельзя.

   «Думал» — от отметки телеграфа до жеста. Это и есть время ответа ребёнка, с
   ним сравнивается `OBSTACLES.signalS`: окно решения не вправе быть короче.

   «Запас» — от жеста до прохода препятствия. Это то, что осталось, и оно
   показывает, насколько близко к краю ребёнок играет.

   Жест ищется ПОСЛЕ отметки телеграфа и ДО прохода, и ищется нужный: уход в
   сторону, противоположную закрытой, либо вход в присед. Последний такой, а не
   первый, — ребёнок может качнуться и вернуться, а решает последнее движение.

   Препятствие без подходящего жеста в счёт не идёт вовсе. Это не потеря: ребёнок
   мог уже стоять на безопасной стороне с прошлого препятствия, и приписать ему
   нулевое время реакции значило бы занизить медиану выдумкой. */
group('время реакции', () => {
  const log = [
    { t: 0, type: 'run.start' },
    // Боковое справа: телеграф, уход влево, проход.
    { t: 1000, type: 'telegraph', kind: 'side', side: 1, at: 6 },
    { t: 3000, type: 'gesture', kind: 'left' },
    { t: 6000, type: 'obstacle', kind: 'side', look: 'plate', side: 1, result: 'clear' },
    // Боковое слева: ребёнок сперва качнулся не туда, решает последний жест.
    { t: 8000, type: 'telegraph', kind: 'side', side: -1, at: 13 },
    { t: 9000, type: 'gesture', kind: 'left' },
    { t: 11000, type: 'gesture', kind: 'right' },
    { t: 13000, type: 'obstacle', kind: 'side', look: 'gate', side: -1, result: 'clear' },
    // Присед.
    { t: 15000, type: 'telegraph', kind: 'duck', side: 0, at: 20 },
    { t: 18500, type: 'gesture', kind: 'crouchIn' },
    { t: 20000, type: 'obstacle', kind: 'duck', look: 'beam', side: 0, result: 'clear' },
    // Препятствие без жеста: ребёнок уже стоял где надо. В счёт не идёт.
    { t: 22000, type: 'telegraph', kind: 'side', side: 1, at: 27 },
    { t: 27000, type: 'obstacle', kind: 'side', look: 'plate', side: 1, result: 'clear' },
    { t: 27500, type: 'run.finish', stars: 1, score: 1, starsTotal: 1, hits: 0, durationS: 27 },
  ];
  const r = report({ startedAt: '2026-10-10T08:29:52.908Z', log });
  const t = r.reaction;

  check('раздел реакции есть', !!t, 'без него телеграф остаётся оценкой навсегда');
  check('считаны только препятствия с жестом', t.n === 3,
    `${t.n} из 4: четвёртое без жеста, и выдумывать ему нулевую реакцию нельзя`);

  // Думал: 2.0 / 3.0 (последний жест, не первый) / 3.5 → медиана 3.0
  check('«думал» считается от телеграфа', t.thinkMed === 3,
    `медиана ${t.thinkMed} с, ожидалось 3`);
  check('и берётся ПОСЛЕДНИЙ жест, а не первый', t.thinkMax === 3.5,
    `${t.thinkMax} с: с первым жестом второго случая вышло бы 1.0`);

  // Запас: 3.0 / 2.0 / 1.5 → минимум 1.5
  check('«запас» считается до прохода', t.leadMin === 1.5,
    `минимум ${t.leadMin} с, ожидалось 1.5`);
  check('запас и ответ дают полное окно телеграфа',
    Math.abs((t.thinkMed + 2) - 5) < 1e-9,
    'иначе одно из двух чисел меряет не то, что названо');

  /* Присед отдельно: он по построению делается позже бокового шага — его
     держат недолго, — и смешивать их в одну медиану значит прятать оба. */
  check('присед считается отдельно', t.duckLeadMed === 1.5,
    `${t.duckLeadMed} с`);

  // Жест ДО телеграфа не считается: это не реакция на него.
  const рано = report({
    startedAt: '2026-10-10T08:29:52.908Z',
    log: [
      { t: 0, type: 'run.start' },
      { t: 500, type: 'gesture', kind: 'left' },
      { t: 1000, type: 'telegraph', kind: 'side', side: 1, at: 6 },
      { t: 6000, type: 'obstacle', kind: 'side', look: 'plate', side: 1, result: 'clear' },
      { t: 6500, type: 'run.finish', stars: 0, score: 0, starsTotal: 1, hits: 0, durationS: 6 },
    ],
  });
  check('жест до телеграфа реакцией не считается', рано.reaction.n === 0,
    'иначе ребёнок, стоящий слева с прошлого раза, даёт отрицательное время ответа');

  /* Отметка старше окна телеграфа к препятствию не относится.

     Журнал 9 октября половину забега простоял на ложных паузах, часть отметок
     в него не попала, и «последняя перед» подобралась от ПРЕДЫДУЩЕГО
     препятствия: вышло «думал 9.52 с» при окне 5.0 — число, невозможное по
     построению, но с виду правдоподобное. Такое уехало бы в measurements/ как
     измерение. */
  const потеряна = report({
    startedAt: '2026-10-10T08:29:52.908Z',
    log: [
      { t: 0, type: 'run.start' },
      { t: 1000, type: 'telegraph', kind: 'side', side: 1, at: 6 },
      { t: 3000, type: 'gesture', kind: 'left' },
      { t: 6000, type: 'obstacle', kind: 'side', look: 'plate', side: 1, result: 'clear' },
      // У этого препятствия отметки в журнале НЕТ, а жест есть.
      { t: 14000, type: 'gesture', kind: 'left' },
      { t: 16000, type: 'obstacle', kind: 'side', look: 'plate', side: 1, result: 'clear' },
      { t: 16500, type: 'run.finish', stars: 0, score: 0, starsTotal: 1, hits: 0, durationS: 16 },
    ],
  });
  check('препятствие без своей отметки в счёт не идёт', потеряна.reaction.n === 1,
    `${потеряна.reaction.n}: со старой отметкой вышло бы «думал 13 с» при окне ${O.signalS}`);
  check('и невозможного времени ответа не возникает',
    потеряна.reaction.thinkMax <= O.signalS * 1.25,
    `${потеряна.reaction.thinkMax} с при окне ${O.signalS} с`);

  // Журнал без телеграфа (до перекрасок и до этого раздела) не врёт нулями.
  const старый = report({
    startedAt: '2026-10-06T18:19:23.000Z',
    log: [
      { t: 0, type: 'run.start' },
      { t: 6000, type: 'obstacle', kind: 'side', side: 1, result: 'clear' },
      { t: 6500, type: 'run.finish', stars: 0, score: 0, starsTotal: 1, hits: 0, durationS: 6 },
    ],
  });
  check('старый журнал не даёт выдуманных чисел', старый.reaction.n === 0
    && старый.reaction.thinkMed === null,
    'ноль здесь означал бы мгновенную реакцию, а не отсутствие данных');

  // И в тексте отчёта это видно.
  const текст = format(r);
  check('реакция попадает в сводку', /реакция/.test(текст), текст.slice(0, 200));
  check('а у журнала без данных строки нет', !/реакция/.test(format(старый)),
    '«реакция —» читалась бы как замеренный прочерк');
});

/* ───────────────── ожидание сообщает исход ─────────────────

   `withTimeout` возвращает `undefined` и когда обещание не успело, и когда
   оно отказало. Для вызывающего это сознательно одно и то же, а для журнала
   — нет: срок чинится сроком, отказ чинится кодом. Проверяется именно
   различение, потому что раньше его не было вовсе.

   Группа асинхронная: объявлена через `await group`, как и те, что
   подтягивают модули динамически. */
await group('ожидание сообщает исход', async () => {
  const сказано = [];
  reportWaits((...a) => сказано.push(a));

  check('значение проходит насквозь', await withTimeout(Promise.resolve(7), 50, 'ок') === 7);
  check('удача молчит', сказано.length === 0, JSON.stringify(сказано));

  check('по отказу возвращается undefined',
    await withTimeout(Promise.reject(new Error('бум')), 50, 'отказ') === undefined);
  check('и отказ назван отказом', сказано.at(-1)?.[1] === 'fail', JSON.stringify(сказано.at(-1)));
  check('вместе с причиной', сказано.at(-1)?.[2] === 'бум', JSON.stringify(сказано.at(-1)));

  check('по сроку тоже undefined',
    await withTimeout(new Promise(() => {}), 20, 'срок') === undefined);
  check('и срок назван сроком', сказано.at(-1)?.[1] === 'timeout', JSON.stringify(сказано.at(-1)));
  check('имя ожидания доезжает', сказано.at(-1)?.[0] === 'срок', JSON.stringify(сказано.at(-1)));

  /* Отказ ПОСЛЕ срока. Случай не выдуманный: камера отвечает отказом позже
     своего срока, и две записи об одном ожидании читались бы в журнале как
     две разные неудачи. */
  const было = сказано.length;
  await withTimeout(new Promise((_, rej) => setTimeout(() => rej(new Error('поздно')), 40)),
    15, 'поздний');
  await new Promise((r) => setTimeout(r, 80));
  check('поздний отказ не даёт второй записи', сказано.length === было + 1,
    JSON.stringify(сказано.slice(было)));

  /* Без имени не пишется ничего: так размечаются вызывающие по одному, и
     так молчат тесты и инструменты, где приёмника нет вовсе. */
  const доБезымянного = сказано.length;
  await withTimeout(Promise.reject(new Error('тихо')), 50);
  check('без имени ожидание молчит', сказано.length === доБезымянного);

  reportWaits(null);
  await withTimeout(Promise.reject(new Error('некому')), 50, 'без приёмника');
  check('без приёмника тоже молчит и не бросает', true);
});

/* ───────────────── повторный прогон записи ─────────────────

   `tools/replay.mjs` гонит записанный скелет через нынешний `makeTracker` —
   тот самый, что работает в забеге. Проверяется на синтетических сессиях, как
   и разбор журнала: настоящая запись сюда не попадёт никогда (репозиторий
   публичный, а это движения ребёнка в его комнате), и привязывать проверку к
   ней значило бы не иметь её вовсе.

   Инструмент уже сверен с настоящим прогоном: на записи из браузера он дал
   24 смены дорожки при 24 в журнале той же сессии. Числа совпали ТОЛЬКО
   после окна забега — см. ниже. */
group('повторный прогон записи', () => {
  /* Сессия из синтетики: формат тот же, что выгружает телефон. */
  const сессия = ({ script = 'walk', n = 200, hz = 20, стадии = true } = {}) => {
    const log = [];
    if (стадии) log.push({ t: 0, type: 'train.stage', from: 'setup', to: 'free' });
    log.push({ t: 0, type: 'cam.aspect', aspect: 1.78 });
    let rows = [];
    for (let i = 0; i < n; i++) {
      const t = Math.round((i * 1000) / hz);
      const lm = fakeLandmarks(SCRIPTS[script](t / 1000));
      rows.push([t, ...lm]);
      if (rows.length === 20) { log.push({ t, type: 'skeleton', n: 20, rows }); rows = []; }
    }
    if (rows.length) log.push({ t: rows[0][0], type: 'skeleton', n: rows.length, rows });
    log.push({ t: Math.round(((n - 1) * 1000) / hz), type: 'run.finish', stars: 0, hits: 0 });
    return { startedAt: '2026-10-14T00:00:00.000Z', log };
  };

  const r = replay(сессия());
  check('отсчёты дошли все', r.n === 200, `${r.n}`);
  check('частота восстановлена', r.hz === 20, `${r.hz}`);
  check('отношение сторон взято из журнала', r.aspect === 1.78, `${r.aspect}`);
  check('калибровка названа умолчаниями', r.from === 'умолчания', r.from);
  check('окно забега найдено', r.whole === false);
  check('качающийся ребёнок меняет дорожку', r.lanes > 0, `${r.lanes} смен`);
  check('и остаётся в кадре', r.notPresent === 0, JSON.stringify(r.why));

  const стоит = replay(сессия({ script: 'still' }));
  check('неподвижный дорожку не меняет', стоит.lanes === 0, `${стоит.lanes}`);

  /* ОКНО ЗАБЕГА. Главная ловушка инструмента: запись идёт со всех стадий, а
     трекер на телефоне ведётся только в забеге. Без окна прогон дал 42 смены
     против 24 в журнале — разница методик, которую легко принять за
     расхождение кода. Проверяется именно отсечение. */
  const сЗаписьюДоЗабега = сессия();
  сЗаписьюДоЗабега.log[0] = { t: 5000, type: 'train.stage', from: 'setup', to: 'free' };
  const окно = replay(сЗаписьюДоЗабега);
  check('строки до входа в забег отсечены', окно.n < 200 && окно.n > 0, `${окно.n}`);
  check('и отсечены ровно по отметке', окно.n === 100, `${окно.n} при 20 Гц и 5 с`);

  /* ПРЕРВАННАЯ ЗАПИСЬ. Случай не выдуманный: настройка «Запись движений»
     читается живо, и включить её можно посреди забега. Размах тогда врёт —
     двести отсчётов двумя кусками с перерывом в минуту дали бы 2.5 Гц, число
     правдоподобное и неверное. Медиана промежутка не врёт, а сам перерыв
     считается отдельно, чтобы его было видно. */
  const сДырой = сессия({ n: 100 });
  for (const e of сДырой.log) {
    if (e.type !== 'skeleton') continue;
    for (const row of e.rows) if (row[0] > 2000) row[0] += 60000;
  }
  /* Финиш надо отодвинуть вместе с записью, иначе окно забега отрежет всё
     сдвинутое и дыры не останется вовсе. На этом тест и поймал сам себя:
     перерыв не считался, потому что второго куска уже не было. */
  сДырой.log.find((e) => e.type === 'run.finish').t = 70000;
  const дыра = replay(сДырой);
  check('частота считается по медиане, а не по размаху', дыра.hz === 20, `${дыра.hz} Гц`);
  check('и перерыв посчитан', дыра.перерывы === 1, `${дыра.перерывы}`);
  check('перерыв виден в отчёте', formatReplay(дыра).includes('всплесками'),
    formatReplay(дыра).split('\n')[0]);
  check('ровная запись перерывов не выдумывает', replay(сессия()).перерывы === 0);
  check('покрытое время считается по кускам, а не по отрезку',
    дыра.покрытоС < дыра.spanS / 2, `покрыто ${дыра.покрытоС} из ${дыра.spanS}`);

  /* СВЕРКА ОГРАНИЧЕНА ПОКРЫТЫМ ВРЕМЕНЕМ. Всплеск вокруг происшествия — это
     две секунды из сорока, и ставить найденное в них рядом с числами за весь
     забег значит выдать разницу методик за расхождение кода. Живой прогон
     давал «9 смен против 48», пока сверка шла по всему журналу. */
  const сЖестомВне = сессия({ n: 40 });
  сЖестомВне.log.find((e) => e.type === 'run.finish').t = 70000;
  for (const e of сЖестомВне.log) {
    if (e.type !== 'skeleton') continue;
    for (const row of e.rows) if (row[0] > 500) row[0] += 60000;
  }
  // Жест в дыре между кусками: записи о нём нет, значит и в сверку он не идёт.
  сЖестомВне.log.push({ t: 30000, type: 'gesture', kind: 'left' });
  // А этот — внутри первого куска.
  сЖестомВне.log.push({ t: 200, type: 'gesture', kind: 'right' });
  const вне = replay(сЖестомВне);
  check('жест в покрытом куске считается', вне.журнал.lanes === 1,
    `${вне.журнал.lanes} — должен быть ровно тот, что внутри куска`);

  const безСтадий = replay(сессия({ стадии: false }));
  check('без отметки стадии берутся все строки', безСтадий.n === 200, `${безСтадий.n}`);
  check('и отчёт об этом говорит', безСтадий.whole === true
    && formatReplay(безСтадий).includes('взяты все строки'));

  /* Строка не той длины — признак сменившегося формата записи. Молча
     пропустить её нельзя: прогон тогда считал бы по части отсчётов и выдавал
     бы правдоподобные числа. */
  const битая = сессия({ n: 40 });
  битая.log.find((e) => e.type === 'skeleton').rows[0] = [0, 1, 2, 3];
  const всёОкно = [{ from: -Infinity, to: Infinity }];
  check('строка не той длины не считается', rowsOf(битая, всёОкно).length === 39,
    `${rowsOf(битая, всёОкно).length}`);

  /* ПОВОД ВСПЛЕСКА. Происшествие случается ПОСЛЕ своих двух секунд, поэтому
     в покрытое время не попадает: «паузы тогда 0» при трёх паузах читается
     как «пауз не было» — ровно наоборот. Поводы берутся с самого события и
     угадывать ничего не требуют. Поймано живым прогоном с ?fake=leave-frame. */
  const сПоводами = сессия({ n: 40 });
  for (const e of сПоводами.log) if (e.type === 'skeleton') e.why = 'pause';
  const пв = replay(сПоводами);
  check('повод всплеска посчитан', пв.поводы.pause === 2, JSON.stringify(пв.поводы));
  check('и показан вместо пауз журнала', formatReplay(пв).includes('всплески      pause 2'),
    formatReplay(пв));
  check('у сплошной записи поводов нет', Object.keys(replay(сессия()).поводы).length === 0);
  check('и тогда показываются паузы журнала',
    formatReplay(replay(сессия())).includes('паузы тогда'));

  /* НЕСКОЛЬКО ЗАБЕГОВ В ОДНОЙ СЕССИИ. Сессия журнала — это один запуск
     приложения, а не один забег: «Ещё раз» заводит новый createTraining без
     перезагрузки, и в живой сессии забегов два-пять. Разбор брал первый вход
     и первый финиш, всё после первого финиша молча отбрасывалось, а отчёт
     описывал один забег как всю сессию. Поймано ревью. */
  const дваЗабега = () => {
    const log = [{ t: 0, type: 'cam.aspect', aspect: 1.78 }];
    const строки = (t0, n) => {
      const rows = [];
      for (let i = 0; i < n; i++) {
        const t = t0 + i * 50;
        rows.push([t, ...fakeLandmarks(SCRIPTS.walk(t / 1000))]);
      }
      return rows;
    };
    log.push({ t: 1000, type: 'train.stage', from: 'setup', to: 'free' });
    log.push({ t: 1000, type: 'skeleton', n: 40, rows: строки(1000, 40) });
    log.push({ t: 3000, type: 'run.finish', stars: 0, hits: 0 });
    // Второй забег — после возврата «Ещё раз», без перезагрузки страницы.
    log.push({ t: 9000, type: 'train.stage', from: 'result', to: 'free' });
    log.push({ t: 9000, type: 'skeleton', n: 40, rows: строки(9000, 40) });
    log.push({ t: 11000, type: 'run.finish', stars: 0, hits: 0 });
    return { startedAt: '2026-10-14T00:00:00.000Z', log };
  };

  const два = replay(дваЗабега());
  check('оба забега попали в разбор', два.забегов === 2, `${два.забегов}`);
  check('и строки обоих посчитаны', два.n === 80, `${два.n}`);
  check('частота не испорчена перерывом между забегами', два.hz === 20, `${два.hz} Гц`);
  check('перерыв между забегами не считается дырой в записи', два.перерывы === 0,
    `${два.перерывы} — это перерыв в игре, а не в записи`);

  /* Брошенный забег (вышли через паузу, финиша нет) закрывается следующим
     входом: иначе его окно поглотило бы все последующие и разбор снова
     схлопнулся бы в один. */
  const брошенный = дваЗабега();
  брошенный.log = брошенный.log.filter((e, i) => !(e.type === 'run.finish' && i < 4));
  const бр = replay(брошенный);
  check('брошенный забег закрывается следующим входом', бр.забегов === 2, `${бр.забегов}`);
  check('и лишних строк не набирает', бр.n === 80, `${бр.n}`);

  /* Поводы всплесков считаются по окнам забегов, а не по покрытым кускам:
     отметка самого события лежит на миг позже последней своей строки, и
     проверка по кускам обнулила бы их целиком. */
  const сПоводомПослеСтрок = дваЗабега();
  const ск = сПоводомПослеСтрок.log.find((e) => e.type === 'skeleton');
  ск.why = 'hit';
  ск.t = ск.rows[ск.rows.length - 1][0] + 7;   // событие позже последней строки
  const пп = replay(сПоводомПослеСтрок);
  check('повод считается, хотя событие позже своих строк', пп.поводы.hit === 1,
    JSON.stringify(пп.поводы));

  const пустая = replay({ log: [{ t: 0, type: 'run.start' }] });
  check('сессия без записи даёт ноль, а не выдумку', пустая.n === 0);
  /* Проверяется, что отчёт ГОВОРИТ об отсутствии записи, а не печатает нули:
     ноль смен дорожки при пустой записи читался бы как «ребёнок не двигался».
     Раньше здесь требовался текст «?record=1» — ручка, которой в
     установленном приложении не существует; поймано ревью. */
  check('и говорит, чего не хватает',
    /записей скелета .* нет/.test(formatReplay(пустая)), formatReplay(пустая));
  check('и не печатает при этом выдуманных чисел',
    !/Гц|смен/.test(formatReplay(пустая)), formatReplay(пустая));

  /* Сверка с журналом. Числа рядом — то, что код решил тогда; расхождение и
     есть повод смотреть. Здесь журнал синтетический и жестов в нём нет, так
     что проверяется сама подстановка, а не совпадение. */
  const сЖестами = сессия();
  сЖестами.log.push({ t: 100, type: 'gesture', kind: 'left', _n: 3 });
  сЖестами.log.push({ t: 200, type: 'gesture', kind: 'crouchIn' });
  сЖестами.log.push({ t: 300, type: 'pause', why: 'edge', _n: 2 });
  const сж = replay(сЖестами);
  check('склеенные жесты считаются по _n', сж.журнал.lanes === 3, `${сж.журнал.lanes}`);
  check('приседы журнала считаются отдельно', сж.журнал.crouches === 1);
  check('причины пауз журнала доезжают', сж.журнал.why.edge === 2, JSON.stringify(сж.журнал.why));
});

// ─────────────────────────── итог ───────────────────────────

if (failed) {
  console.error(`\n${failed} провал(ов) из ${passed + failed} проверок`);
  process.exit(1);
}
console.log(`\nвсё сошлось: ${passed} проверок`);
